INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92053, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "非凡", "is_correct": true, "explanation": "正确。非凡与平凡意思相对，指不平常、与众不同。"}, {"text": "繁忙", "is_correct": false, "explanation": "“繁忙”指事情多、忙碌，与“平凡”没有反义关系。"}, {"text": "巨大", "is_correct": false, "explanation": "“巨大”指体积、数量或力量很大，与“平凡”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”的反义词是吵闹，与“平凡”没有反义关系。"}], "correct_answer": "非凡", "explanations": {"非凡": "正确。非凡与平凡意思相对，指不平常、与众不同。", "繁忙": "“繁忙”指事情多、忙碌，与“平凡”没有反义关系。", "巨大": "“巨大”指体积、数量或力量很大，与“平凡”没有反义关系。", "安静": "“安静”的反义词是吵闹，与“平凡”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b2bf2e-59d7-411a-9869-74a291039784') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92053, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不凡", "is_correct": true, "explanation": "正确。不凡与平凡意思相对，指与众不同、不普通。"}, {"text": "严肃", "is_correct": false, "explanation": "“严肃”形容态度庄重或不轻松，与“平凡”没有反义关系。"}, {"text": "迅速", "is_correct": false, "explanation": "“迅速”形容速度快，与“平凡”没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线充足或颜色鲜亮，与“平凡”没有反义关系。"}], "correct_answer": "不凡", "explanations": {"不凡": "正确。不凡与平凡意思相对，指与众不同、不普通。", "严肃": "“严肃”形容态度庄重或不轻松，与“平凡”没有反义关系。", "迅速": "“迅速”形容速度快，与“平凡”没有反义关系。", "明亮": "“明亮”形容光线充足或颜色鲜亮，与“平凡”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b2bf2e-59d7-411a-9869-74a291039784') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92053, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "平凡是很普通，没有什么特别。", "primary_collocate": null, "pronunciation": "píng fán", "ipa": "pʰɪŋ˧˥ fan˧˥", "syllable_count": 2, "sentences": [{"text": "他是一个很平凡的人。", "target_word": "平凡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的生活平凡而安静。", "target_word": "平凡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她过着平凡的生活，很幸福。", "target_word": "平凡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份工作很平凡，但是很重要。", "target_word": "平凡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他长得很平凡，没人注意他。", "target_word": "平凡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "平凡的人也可以做大事。", "target_word": "平凡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只是一个平凡的学生。", "target_word": "平凡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小镇很平凡，几乎没有人知道它。", "target_word": "平凡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的一生很平凡，却很伟大。", "target_word": "平凡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想一辈子都这么平凡。", "target_word": "平凡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "平平凡凡", "label": "重叠"}], "register": "中性", "sense_fingerprint": "形容人、生活或工作很普通，没有特别的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91424016-136b-4dbb-8616-3939a22b04a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92053, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "平凡", "is_correct": true, "explanation": "正确答案：平凡 píng fán，意思是很普通，没有什么特别。"}, {"text": "平方", "is_correct": false, "explanation": "fāng（第一声）与 fán（第二声）声调不同，韵母也由 an 变为 ang，意思是平方（乘方）。"}, {"text": "平房", "is_correct": false, "explanation": "fáng 与 fán 韵母不同（ang 与 an），声调相同，意思是单层的房屋。"}, {"text": "平反", "is_correct": false, "explanation": "fǎn（第三声）与 fán（第二声）声调不同，意思是为受冤的人恢复名誉。"}], "explanations": {"平凡": "正确答案：平凡 píng fán，意思是很普通，没有什么特别。", "平方": "fāng（第一声）与 fán（第二声）声调不同，韵母也由 an 变为 ang，意思是平方（乘方）。", "平房": "fáng 与 fán 韵母不同（ang 与 an），声调相同，意思是单层的房屋。", "平反": "fǎn（第三声）与 fán（第二声）声调不同，意思是为受冤的人恢复名誉。"}, "sentence_index": null, "correct_answer": "平凡"}, "level_3": {"options": [{"text": "平凡", "is_correct": true, "explanation": "正确。平凡形容人很普通，没有什么特别之处，符合“很……的人”的语境。"}, {"text": "辽阔", "is_correct": false, "explanation": "搭配：“辽阔”形容地域广大，不能用来形容人。"}, {"text": "繁华", "is_correct": false, "explanation": "搭配：“繁华”形容城市或地方热闹，不能用来形容人。"}, {"text": "湛蓝", "is_correct": false, "explanation": "语义：“湛蓝”指颜色，不能用来描述一个人的特点。"}], "explanations": {"平凡": "正确。平凡形容人很普通，没有什么特别之处，符合“很……的人”的语境。", "辽阔": "搭配：“辽阔”形容地域广大，不能用来形容人。", "繁华": "搭配：“繁华”形容城市或地方热闹，不能用来形容人。", "湛蓝": "语义：“湛蓝”指颜色，不能用来描述一个人的特点。"}, "sentence_index": 0, "correct_answer": "平凡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位运动员的成绩很平凡，还打破了世界纪录。", "explanation": "这里应该用〈出色〉。平凡指普通、没有特别之处，不能用来形容打破纪录的成绩。"}, {"text": "听到这个消息，我的心情很平凡。", "explanation": "这里应该用〈平静〉。平凡形容人、事物或生活的普通，不能用来形容心情。"}, {"text": "这场演讲很平凡，全场观众都被深深打动了。", "explanation": "这里应该用〈精彩〉。平凡指没有特别之处，与“被深深打动”的效果互相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b2bf2e-59d7-411a-9869-74a291039784') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92053, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平凡", "is_correct": true, "explanation": "正确。平凡形容人很普通，与“我只是一个……的学生”的语境相符。"}, {"text": "雄伟", "is_correct": false, "explanation": "搭配：“雄伟”多形容山河、建筑，不能用来形容学生。"}, {"text": "悠久", "is_correct": false, "explanation": "搭配：“悠久”多形容历史、传统，不能用来形容学生。"}, {"text": "清澈", "is_correct": false, "explanation": "语义：“清澈”指水或眼神清亮，与“我只是一个……的学生”这一身份描述不合。"}], "explanations": {"平凡": "正确。平凡形容人很普通，与“我只是一个……的学生”的语境相符。", "雄伟": "搭配：“雄伟”多形容山河、建筑，不能用来形容学生。", "悠久": "搭配：“悠久”多形容历史、传统，不能用来形容学生。", "清澈": "语义：“清澈”指水或眼神清亮，与“我只是一个……的学生”这一身份描述不合。"}, "sentence_index": 6, "correct_answer": "平凡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "战士平凡地冲上了阵地。", "explanation": "这里应该用〈英勇〉。平凡指普通、没有特别之处，不能用来形容冲上阵地这种英勇的行动。"}, {"text": "这座宫殿十分平凡，让人印象深刻。", "explanation": "这里应该用〈宏伟〉。平凡指普通，不能用来形容让人印象深刻的宫殿。"}, {"text": "这间屋子很平凡，家具全都是用黄金做的。", "explanation": "这里应该用〈豪华〉。平凡指普通、没有特别之处，与“家具全都是用黄金做的”的描述矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b2bf2e-59d7-411a-9869-74a291039784') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92053, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一个平凡地老师，但学生都很喜欢他。", "corrected_sentence": "他是一个平凡的老师，但学生都很喜欢他。", "error_description": "“平凡”修饰名词“老师”时应用“的”，不能用“地”。“地”用于动词前作状语，这里应说“平凡的老师”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b2bf2e-59d7-411a-9869-74a291039784') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92053, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的衣服很平凡地，但是很干净。", "corrected_sentence": "他的衣服很平凡，但是很干净。", "error_description": "“平凡”作谓语时后面不加“地”，“地”只用在动词前作状语；这里应去掉“地”，说“很平凡”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b2bf2e-59d7-411a-9869-74a291039784') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
