INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92055, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "伊是书上用的字，意思是她或者他。", "primary_collocate": null, "pronunciation": "yī", "ipa": "i˥", "syllable_count": 1, "sentences": [{"text": "小说里写道：少女坐在窗前，伊一直没有说话。", "target_word": "伊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书中的女孩走进屋里，伊轻轻关上了门。", "target_word": "伊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人望着远方，伊想起了过去的事。", "target_word": "伊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文章里的女孩很爱读书，伊每天都读到很晚。", "target_word": "伊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小梅站在雨中，伊没有带伞。", "target_word": "伊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母亲看了我一眼，伊什么也没说。", "target_word": "伊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个好老师，学生都很想念伊。", "target_word": "伊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位姑娘笑了笑，伊的声音很轻。", "target_word": "伊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说中的少年低着头，伊不敢看父亲。", "target_word": "伊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，那位姑娘还在河边，伊在等人。", "target_word": "伊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "书面语中指她或他的第三人称代词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2bbdfe-45ed-43d8-ab7a-6e76fe728753') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92055, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "伊", "is_correct": true, "explanation": "正确。伊（第一声）是书面语中指她或他的第三人称代词。"}, {"text": "移", "is_correct": false, "explanation": "移（第二声）与伊（第一声）声调不同，意思是移动，不是代词。"}, {"text": "以", "is_correct": false, "explanation": "以（第三声）与伊（第一声）声调不同，意思是用、把，不是代词。"}, {"text": "意", "is_correct": false, "explanation": "意（第四声）与伊（第一声）声调不同，意思是意思、心意。"}, {"text": "音", "is_correct": false, "explanation": "音（yīn）与伊（yī）韵母不同，多了鼻音 n，意思是声音。"}], "explanations": {"伊": "正确。伊（第一声）是书面语中指她或他的第三人称代词。", "移": "移（第二声）与伊（第一声）声调不同，意思是移动，不是代词。", "以": "以（第三声）与伊（第一声）声调不同，意思是用、把，不是代词。", "意": "意（第四声）与伊（第一声）声调不同，意思是意思、心意。", "音": "音（yīn）与伊（yī）韵母不同，多了鼻音 n，意思是声音。"}, "sentence_index": null, "correct_answer": "伊"}, "level_3": {"options": [{"text": "它", "is_correct": false, "explanation": "语义：“它”指事物或动物，而句中坐在窗前、不说话的是人物。"}, {"text": "伊", "is_correct": true, "explanation": "正确。伊是书面语第三人称代词，指小说里的人物，与“小说里写道”的书面语境相符。"}, {"text": "您", "is_correct": false, "explanation": "语域：“您”是对听话人的敬称，小说里的第三人称叙述中不用。"}, {"text": "它们", "is_correct": false, "explanation": "语义：“它们”指多个事物，而句中是一个人坐在窗前。"}], "explanations": {"它": "语义：“它”指事物或动物，而句中坐在窗前、不说话的是人物。", "伊": "正确。伊是书面语第三人称代词，指小说里的人物，与“小说里写道”的书面语境相符。", "您": "语域：“您”是对听话人的敬称，小说里的第三人称叙述中不用。", "它们": "语义：“它们”指多个事物，而句中是一个人坐在窗前。"}, "sentence_index": 0, "correct_answer": "伊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书很好看，伊每天都有人借。", "explanation": "这里应该用〈它〉。伊只指人（她或他），不能指书这类事物。"}, {"text": "我家的猫很可爱，伊每天都睡在我床上。", "explanation": "这里应该用〈它〉。伊只指人（她或他），不能指猫这类动物。"}, {"text": "这盏灯很亮，伊每天都陪着他工作。", "explanation": "这里应该用〈它〉。伊只指人（她或他），不能指灯这类事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63908539-1f36-4f60-943a-1d355515d7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92055, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "伊", "is_correct": true, "explanation": "正确。伊（第一声）是书面语中指她或他的第三人称代词。"}, {"text": "遗", "is_correct": false, "explanation": "遗（第二声）与伊（第一声）声调不同，意思是遗忘、遗留。"}, {"text": "椅", "is_correct": false, "explanation": "椅（第三声）与伊（第一声）声调不同，意思是椅子。"}, {"text": "亿", "is_correct": false, "explanation": "亿（第四声）与伊（第一声）声调不同，意思是数量单位“亿”。"}, {"text": "阴", "is_correct": false, "explanation": "阴（yīn）与伊（yī）韵母不同，多了鼻音 n，意思是阴天、阴暗。"}], "explanations": {"伊": "正确。伊（第一声）是书面语中指她或他的第三人称代词。", "遗": "遗（第二声）与伊（第一声）声调不同，意思是遗忘、遗留。", "椅": "椅（第三声）与伊（第一声）声调不同，意思是椅子。", "亿": "亿（第四声）与伊（第一声）声调不同，意思是数量单位“亿”。", "阴": "阴（yīn）与伊（yī）韵母不同，多了鼻音 n，意思是阴天、阴暗。"}, "sentence_index": null, "correct_answer": "伊"}, "level_3": {"options": [{"text": "他们", "is_correct": false, "explanation": "语义：“他们”指多人，而句中只有一位老师（他）。"}, {"text": "她们", "is_correct": false, "explanation": "语义：“她们”指多位女性，与句中单数的“他”不符。"}, {"text": "自己", "is_correct": false, "explanation": "搭配：“想念自己”不合句意，句中是学生想念老师。"}, {"text": "伊", "is_correct": true, "explanation": "正确。伊指前文的“他”（老师），书面语中作宾语。"}], "explanations": {"他们": "语义：“他们”指多人，而句中只有一位老师（他）。", "她们": "语义：“她们”指多位女性，与句中单数的“他”不符。", "自己": "搭配：“想念自己”不合句意，句中是学生想念老师。", "伊": "正确。伊指前文的“他”（老师），书面语中作宾语。"}, "sentence_index": 6, "correct_answer": "伊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那只小狗很乖，伊总是跟着我。", "explanation": "这里应该用〈它〉。伊只指人（她或他），不能指狗这类动物。"}, {"text": "这棵树很高，伊已经一百岁了。", "explanation": "这里应该用〈它〉。伊只指人（她或他），不能指树这类事物。"}, {"text": "这些书很旧，伊都是爷爷留下的。", "explanation": "这里应该用〈它们〉。伊只指人，不能指书这类事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63908539-1f36-4f60-943a-1d355515d7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92055, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "伊书放在桌子上。", "corrected_sentence": "伊的书放在桌子上。", "error_description": "“伊书”漏了结构助词“的”。代词作定语修饰名词时要说“伊的书”，表示“她（他）的书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63908539-1f36-4f60-943a-1d355515d7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92055, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人很孤单，伊们一直坐在门口。", "corrected_sentence": "老人很孤单，伊一直坐在门口。", "error_description": "“伊们”不能指单数的“老人”，“们”是复数词尾，应去掉，说“伊一直坐在门口”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63908539-1f36-4f60-943a-1d355515d7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
