INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92056, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "文言和书面语中的第三人称代词，多指“她”，也指“他”。", "primary_collocate": null, "pronunciation": "yī", "ipa": "i˥", "syllable_count": 1, "sentences": [{"text": "他的妻子很温柔，伊总是笑着说话。", "target_word": "伊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "女主人打开门，伊请客人坐下。", "target_word": "伊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家已经去世，人们常常读伊的书。", "target_word": "伊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张说伊明天不来了。", "target_word": "伊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的老同学是位姑娘，我很久没有见到伊了。", "target_word": "伊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说里的女子很勇敢，伊独自走了很远的路。", "target_word": "伊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有个妹妹，伊今年刚上大学。", "target_word": "伊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少女看着镜子，伊笑了。", "target_word": "伊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位老人很孤单，没有人陪伊说话。", "target_word": "伊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母亲病了，儿子一直守在伊身边。", "target_word": "伊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "文言书面语第三人称代词，多指她", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab2bbdfe-45ed-43d8-ab7a-6e76fe728753') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92056, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "伊", "is_correct": true, "explanation": "正确。伊（第一声）是文言和书面语中的第三人称代词，多指她。"}, {"text": "遗", "is_correct": false, "explanation": "遗（第二声）与伊（第一声）声调不同，意思是遗忘、遗留。"}, {"text": "椅", "is_correct": false, "explanation": "椅（第三声）与伊（第一声）声调不同，意思是椅子。"}, {"text": "亿", "is_correct": false, "explanation": "亿（第四声）与伊（第一声）声调不同，意思是数量单位“亿”。"}, {"text": "阴", "is_correct": false, "explanation": "阴（yīn）与伊（yī）韵母不同，多了鼻音 n，意思是阴天、阴暗。"}], "explanations": {"伊": "正确。伊（第一声）是文言和书面语中的第三人称代词，多指她。", "遗": "遗（第二声）与伊（第一声）声调不同，意思是遗忘、遗留。", "椅": "椅（第三声）与伊（第一声）声调不同，意思是椅子。", "亿": "亿（第四声）与伊（第一声）声调不同，意思是数量单位“亿”。", "阴": "阴（yīn）与伊（yī）韵母不同，多了鼻音 n，意思是阴天、阴暗。"}, "sentence_index": null, "correct_answer": "伊"}, "level_3": {"options": [{"text": "它", "is_correct": false, "explanation": "语义：“它”指事物或动物，而这里说的是人。"}, {"text": "咱们", "is_correct": false, "explanation": "语义：“咱们”包括说话人在内，与这里的第三人称叙述不合。"}, {"text": "伊", "is_correct": true, "explanation": "正确。伊是文言和书面语第三人称代词，多指她，这里指“他的妻子”。"}, {"text": "您", "is_correct": false, "explanation": "语域：“您”是敬称，用于对话，叙述中不用。"}], "explanations": {"它": "语义：“它”指事物或动物，而这里说的是人。", "咱们": "语义：“咱们”包括说话人在内，与这里的第三人称叙述不合。", "伊": "正确。伊是文言和书面语第三人称代词，多指她，这里指“他的妻子”。", "您": "语域：“您”是敬称，用于对话，叙述中不用。"}, "sentence_index": 0, "correct_answer": "伊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些花很美，伊每天都开得很好。", "explanation": "这里应该用〈它们〉。伊只指人，不能指花这类事物。"}, {"text": "他很爱这盏灯，伊每天都亮着。", "explanation": "这里应该用〈它〉。伊只指人（她或他），不能指灯这类事物。"}, {"text": "我家的猫很可爱，伊每天都睡在我床上。", "explanation": "这里应该用〈它〉。伊只指人（她或他），不能指猫这类动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63908539-1f36-4f60-943a-1d355515d7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92056, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "伊", "is_correct": true, "explanation": "正确。伊（第一声）是文言和书面语中的第三人称代词，多指她。"}, {"text": "移", "is_correct": false, "explanation": "移（第二声）与伊（第一声）声调不同，意思是移动。"}, {"text": "以", "is_correct": false, "explanation": "以（第三声）与伊（第一声）声调不同，意思是用、把。"}, {"text": "意", "is_correct": false, "explanation": "意（第四声）与伊（第一声）声调不同，意思是意思、心意。"}, {"text": "音", "is_correct": false, "explanation": "音（yīn）与伊（yī）韵母不同，多了鼻音 n，意思是声音。"}], "explanations": {"伊": "正确。伊（第一声）是文言和书面语中的第三人称代词，多指她。", "移": "移（第二声）与伊（第一声）声调不同，意思是移动。", "以": "以（第三声）与伊（第一声）声调不同，意思是用、把。", "意": "意（第四声）与伊（第一声）声调不同，意思是意思、心意。", "音": "音（yīn）与伊（yī）韵母不同，多了鼻音 n，意思是声音。"}, "sentence_index": null, "correct_answer": "伊"}, "level_3": {"options": [{"text": "它", "is_correct": false, "explanation": "语义：“它”指事物或动物，而这里指人（妹妹）。"}, {"text": "它们", "is_correct": false, "explanation": "语义：“它们”指多个事物，与一位妹妹不合。"}, {"text": "我们", "is_correct": false, "explanation": "语义：“我们”包括说话人，而这里说的是“他”的妹妹一个人。"}, {"text": "伊", "is_correct": true, "explanation": "正确。伊指前文的妹妹，书面语第三人称代词，作主语。"}], "explanations": {"它": "语义：“它”指事物或动物，而这里指人（妹妹）。", "它们": "语义：“它们”指多个事物，与一位妹妹不合。", "我们": "语义：“我们”包括说话人，而这里说的是“他”的妹妹一个人。", "伊": "正确。伊指前文的妹妹，书面语第三人称代词，作主语。"}, "sentence_index": 6, "correct_answer": "伊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只鸟很漂亮，伊每天都在树上唱歌。", "explanation": "这里应该用〈它〉。伊只指人（她或他），不能指鸟这类动物。"}, {"text": "那辆车很旧，伊已经开了十年。", "explanation": "这里应该用〈它〉。伊只指人（她或他），不能指车这类事物。"}, {"text": "这些小鱼很可爱，伊在水里游来游去。", "explanation": "这里应该用〈它们〉。伊只指人，不能指鱼这类动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63908539-1f36-4f60-943a-1d355515d7b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_val