INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92057, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "开始吃东西。", "primary_collocate": null, "pronunciation": "kāi chī", "ipa": "kʰaɪ̯˥ ʈʂʰɻ̩˥", "syllable_count": 2, "sentences": [{"text": "菜都上齐了，我们开吃吧。", "target_word": "开吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭做好了，大家快洗手，准备开吃。", "target_word": "开吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说完话，同学们就开吃了。", "target_word": "开吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈一说开吃，孩子们就拿起了筷子。", "target_word": "开吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭菜都热了，我们可以开吃了。", "target_word": "开吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他饿坏了，一坐下就开吃。", "target_word": "开吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等客人到齐了再开吃。", "target_word": "开吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋糕切好了，大家唱完歌就开吃。", "target_word": "开吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷还没动筷子，谁也不能开吃。", "target_word": "开吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "烤肉的香味太好闻了，我们马上开吃。", "target_word": "开吃", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开吃了", "label": "体标"}], "register": "口语", "sense_fingerprint": "众人准备好后开始吃东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c8724db-93b5-4991-96c7-55399deeca21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92057, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "开吃", "is_correct": true, "explanation": "正确。“开吃”是词目，意思是开始吃东西。"}, {"text": "开车", "is_correct": false, "explanation": "kāichē 与 kāichī 只有韵母不同（ē 与 ī），意思是驾驶车辆，与吃无关。"}, {"text": "开出", "is_correct": false, "explanation": "kāichū 与 kāichī 只有韵母不同（ū 与 ī），意思是开出去或签发，与吃无关。"}, {"text": "开支", "is_correct": false, "explanation": "kāizhī 与 kāichī 只有声母不同（zh 与 ch），意思是支出费用。"}], "explanations": {"开吃": "正确。“开吃”是词目，意思是开始吃东西。", "开车": "kāichē 与 kāichī 只有韵母不同（ē 与 ī），意思是驾驶车辆，与吃无关。", "开出": "kāichū 与 kāichī 只有韵母不同（ū 与 ī），意思是开出去或签发，与吃无关。", "开支": "kāizhī 与 kāichī 只有声母不同（zh 与 ch），意思是支出费用。"}, "sentence_index": null, "correct_answer": "开吃"}, "level_3": {"options": [{"text": "开吃", "is_correct": true, "explanation": "正确。“菜都上齐了”之后说“我们开吃吧”，符合语境。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：菜已经上齐，说“我们洗澡吧”与吃饭的语境不符。"}, {"text": "出发", "is_correct": false, "explanation": "语义：“我们出发吧”表示离开，与“菜都上齐了”的语境矛盾。"}, {"text": "开会", "is_correct": false, "explanation": "语义：菜都上齐了，说“我们开会吧”与吃饭的语境完全不符。"}], "explanations": {"开吃": "正确。“菜都上齐了”之后说“我们开吃吧”，符合语境。", "洗澡": "语义：菜已经上齐，说“我们洗澡吧”与吃饭的语境不符。", "出发": "语义：“我们出发吧”表示离开，与“菜都上齐了”的语境矛盾。", "开会": "语义：菜都上齐了，说“我们开会吧”与吃饭的语境完全不符。"}, "sentence_index": 0, "correct_answer": "开吃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "足球赛下午三点开吃，球迷们早早入场。", "explanation": "这里应该用〈开赛〉。开赛指比赛开始，开吃只表示开始吃东西，不能用于比赛。"}, {"text": "会议十点开吃，请大家准时到场。", "explanation": "这里应该用〈开始〉。开吃只表示开始吃东西，不能用于会议。"}, {"text": "电影七点开吃，请大家入场。", "explanation": "这里应该用〈开演〉。开演指电影、演出开始，开吃只表示开始吃东西，不能用于电影。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b39e582-744c-4c39-a343-7e0484b564a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92057, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开吃", "is_correct": true, "explanation": "正确。“等客人到齐了再开吃”，先到齐、后开吃，顺序合理。"}, {"text": "上班", "is_correct": false, "explanation": "语义：客人到齐后说“再上班”，与等待开饭的语境不符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：客人还没到齐，说“再睡觉”与语境矛盾。"}, {"text": "散席", "is_correct": false, "explanation": "搭配：“散席”指宴席结束，要在吃完以后说，不能用于客人到齐之前。"}], "explanations": {"开吃": "正确。“等客人到齐了再开吃”，先到齐、后开吃，顺序合理。", "上班": "语义：客人到齐后说“再上班”，与等待开饭的语境不符。", "睡觉": "语义：客人还没到齐，说“再睡觉”与语境矛盾。", "散席": "搭配：“散席”指宴席结束，要在吃完以后说，不能用于客人到齐之前。"}, "sentence_index": 6, "correct_answer": "开吃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台打印机一通电就开吃。", "explanation": "词义不符：“开吃”的主语须是能吃东西的人或动物，打印机不能吃东西，句子不通。"}, {"text": "这辆汽车一加满油就开吃。", "explanation": "词义不符：“开吃”的主语须是能吃东西的人或动物，汽车不能吃东西，句子不通。"}, {"text": "空调一打开就开吃。", "explanation": "词义不符：“开吃”的主语须是能吃东西的人或动物，空调不能吃东西，句子不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b39e582-744c-4c39-a343-7e0484b564a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92057, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "饭都好了，我们开吃吃吧。", "corrected_sentence": "饭都好了，我们开吃吧。", "error_description": "错误：“开吃吃吧”把“吃”重复了。“开吃”是一个词，不能重叠成“开吃吃”，正确的是“开吃吧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b39e582-744c-4c39-a343-7e0484b564a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92057, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家都坐好了，开吃着吧。", "corrected_sentence": "大家都坐好了，开吃吧。", "error_description": "错误：“开吃”后面加了“着”。“着”表示动作持续的状态，而“开吃”表示开始的动作，不能持续，应说“开吃吧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b39e582-744c-4c39-a343-7e0484b564a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
