INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92058, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "开吃", "is_correct": true, "explanation": "正确。“开吃”是词目，意思是开始吃东西。"}, {"text": "开车", "is_correct": false, "explanation": "kāichē 与 kāichī 只有韵母不同（ē 与 ī），意思是驾驶车辆，与吃无关。"}, {"text": "开出", "is_correct": false, "explanation": "kāichū 与 kāichī 只有韵母不同（ū 与 ī），意思是开出去或签发，与吃无关。"}, {"text": "开支", "is_correct": false, "explanation": "kāizhī 与 kāichī 只有声母不同（zh 与 ch），意思是支出费用。"}], "explanations": {"开吃": "正确。“开吃”是词目，意思是开始吃东西。", "开车": "kāichē 与 kāichī 只有韵母不同（ē 与 ī），意思是驾驶车辆，与吃无关。", "开出": "kāichū 与 kāichī 只有韵母不同（ū 与 ī），意思是开出去或签发，与吃无关。", "开支": "kāizhī 与 kāichī 只有声母不同（zh 与 ch），意思是支出费用。"}, "sentence_index": null, "correct_answer": "开吃"}, "level_3": {"options": [{"text": "开吃", "is_correct": true, "explanation": "正确。“十二点整，选手一起开吃”，符合同时开始吃东西的语境。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：十二点整选手一起睡觉，与吃东西的语境不符。"}, {"text": "上课", "is_correct": false, "explanation": "语义：“上课”是学习活动，与选手一起吃东西的语境不符。"}, {"text": "开学", "is_correct": false, "explanation": "搭配：“开学”指学校新学期开始，不能用于大赛选手。"}], "explanations": {"开吃": "正确。“十二点整，选手一起开吃”，符合同时开始吃东西的语境。", "睡觉": "语义：十二点整选手一起睡觉，与吃东西的语境不符。", "上课": "语义：“上课”是学习活动，与选手一起吃东西的语境不符。", "开学": "搭配：“开学”指学校新学期开始，不能用于大赛选手。"}, "sentence_index": 0, "correct_answer": "开吃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "比赛十点开吃，请选手们准时到场。", "explanation": "这里应该用〈开始〉。开吃只表示开始吃东西，不能用于比赛。"}, {"text": "餐馆十一点开吃，欢迎大家光临。", "explanation": "这里应该用〈开饭〉。开饭指店家开始供应饭菜，开吃是食客开始吃，主语不能是餐馆。"}, {"text": "音乐会八点开吃，请观众入座。", "explanation": "这里应该用〈开演〉。开演指演出开始，开吃只表示开始吃东西，不能用于音乐会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b39e582-744c-4c39-a343-7e0484b564a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92058, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开吃", "is_correct": true, "explanation": "正确。“拍完照片再开吃，菜就凉了”，先拍照后吃，语境吻合。"}, {"text": "上班", "is_correct": false, "explanation": "语义：“上班”与拍照、吃饭的语境无关，句子不通。"}, {"text": "散席", "is_correct": false, "explanation": "搭配：“散席”指宴席结束，不能在拍完照片、还没开吃时说。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”与拍照、吃饭的语境无关，句子不通。"}], "explanations": {"开吃": "正确。“拍完照片再开吃，菜就凉了”，先拍照后吃，语境吻合。", "上班": "语义：“上班”与拍照、吃饭的语境无关，句子不通。", "散席": "搭配：“散席”指宴席结束，不能在拍完照片、还没开吃时说。", "考试": "语义：“考试”与拍照、吃饭的语境无关，句子不通。"}, "sentence_index": 6, "correct_answer": "开吃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "无人机一起飞就开吃。", "explanation": "词义不符：“开吃”的主语须是能吃东西的人或动物，无人机不能吃东西，句子不通。"}, {"text": "电梯一到楼层就开吃。", "explanation": "词义不符：“开吃”的主语须是能吃东西的人或动物，电梯不能吃东西，句子不通。"}, {"text": "水龙头一拧开就开吃。", "explanation": "词义不符：“开吃”的主语须是能吃东西的人或动物，水龙头不能吃东西，句子不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b39e582-744c-4c39-a343-7e0484b564a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92058, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "汤端上来了，大家开吃着吧。", "corrected_sentence": "汤端上来了，大家开吃吧。", "error_description": "错误：“开吃着吧”，正确：“开吃吧”。“着”表示动作持续，而“开吃”表示开始吃，是瞬间动作，不能加“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b39e582-744c-4c39-a343-7e0484b564a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92058, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一进门就开吃过，一点也不客气。", "corrected_sentence": "他一进门就开吃，一点也不客气。", "error_description": "错误：“开吃”后面加了“过”。“过”表示经历，这里说的是刚进门就开始吃，不能加“过”，应说“开吃”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b39e582-744c-4c39-a343-7e0484b564a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
