INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92059, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "几何是数学里学点、线、图形的那一科。", "primary_collocate": null, "pronunciation": "jǐ hé", "ipa": "tɕi˨˩˦ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "明天要考几何，我得好好复习。", "target_word": "几何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的几何成绩比代数好。", "target_word": "几何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师今天在黑板上讲了几何。", "target_word": "几何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最怕几何，因为总是画不好图。", "target_word": "几何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "初中生要学代数，也要学几何。", "target_word": "几何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的数学很好，尤其是几何。", "target_word": "几何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这周的几何很难，我听不懂。", "target_word": "几何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同桌教我怎么学几何，我进步了很多。", "target_word": "几何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢数学，可是不喜欢几何。", "target_word": "几何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说几何要多画图，少背公式。", "target_word": "几何", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "幾何", "label": "繁体"}, {"form": "几何学", "label": "复合"}, {"form": "几何图形", "label": "复合"}], "register": "中性", "sense_fingerprint": "数学里学点、线、图形的一门课", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5a5e0a7-1931-406f-8fa8-4b6b6a09a7b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92059, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：“考”针对的是考试科目，天气不能作为考试的内容。"}, {"text": "几何", "is_correct": true, "explanation": "“几何”是可以考的数学科目，“考几何”搭配正确。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“考”不能接“心情”，心情不是考试的对象。"}, {"text": "早餐", "is_correct": false, "explanation": "搭配：“考”不能接“早餐”，早餐不能作为考试科目。"}], "explanations": {"天气": "语义：“考”针对的是考试科目，天气不能作为考试的内容。", "几何": "“几何”是可以考的数学科目，“考几何”搭配正确。", "心情": "搭配：“考”不能接“心情”，心情不是考试的对象。", "早餐": "搭配：“考”不能接“早餐”，早餐不能作为考试科目。"}, "sentence_index": 0, "correct_answer": "几何"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "几何课讲的是古代的事。", "explanation": "这里应该用〈历史〉。历史讲过去发生的事；几何是讲图形的课程，不讲古代的事。"}, {"text": "几何课要背很多古诗。", "explanation": "这里应该用〈语文〉。语文要背古诗和学写作文；几何是数学课，不背古诗。"}, {"text": "作业要求我们画出几何。", "explanation": "这里应该用〈几何图形〉。“几何”是学科，不能画出来；要画的是几何图形。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c1d2f4-427e-4755-b2ed-f9413a9d3608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92059, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "味道", "is_correct": false, "explanation": "语义：味道不能用“很难，我听不懂”来形容，句子说的是学科内容。"}, {"text": "几何", "is_correct": true, "explanation": "“几何”指这周在学的课程，说它难、听不懂，语意通顺。"}, {"text": "饭菜", "is_correct": false, "explanation": "搭配：“听不懂”不能用来形容饭菜，饭菜没有可以“听”的内容。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：脚步不能被说成“很难”或“听不懂”，句子说的是课程内容。"}], "explanations": {"味道": "语义：味道不能用“很难，我听不懂”来形容，句子说的是学科内容。", "几何": "“几何”指这周在学的课程，说它难、听不懂，语意通顺。", "饭菜": "搭配：“听不懂”不能用来形容饭菜，饭菜没有可以“听”的内容。", "脚步": "语义：脚步不能被说成“很难”或“听不懂”，句子说的是课程内容。"}, "sentence_index": 6, "correct_answer": "几何"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "几何课教我们怎么唱歌。", "explanation": "这里应该用〈音乐〉。音乐课教唱歌；几何讲图形，不教唱歌。"}, {"text": "老师在几何课上讲水彩画。", "explanation": "这里应该用〈美术〉。美术讲绘画和色彩；几何讲图形的形状、大小和位置，不讲水彩画。"}, {"text": "老师说要多画几何，少背公式。", "explanation": "这里应该用〈图形〉。几何是学科，不能画出来，要画的是图形。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c1d2f4-427e-4755-b2ed-f9413a9d3608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92059, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我已经把几何完学了。", "corrected_sentence": "我已经把几何学完了。", "error_description": "补语位置用错：结果补语“完”应紧跟动词，说“学完”，不能说“完学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c1d2f4-427e-4755-b2ed-f9413a9d3608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92059, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我学了一座几何。", "corrected_sentence": "我学了一门几何。", "error_description": "量词用错：作为课程的“几何”应该用量词“门”，说“一门几何”；“座”用于山、桥、房屋等大型物体，不能用来数课程。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c1d2f4-427e-4755-b2ed-f9413a9d3608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
