INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92060, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "研究空间图形的形状、大小和位置关系的数学分支。", "primary_collocate": null, "pronunciation": "jǐ hé", "ipa": "tɕi˨˩˦ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "几何研究图形的形状和大小。", "target_word": "几何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "欧几里得是古希腊研究几何的数学家。", "target_word": "几何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对几何很感兴趣，常常画各种图形。", "target_word": "几何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几何里的三角形和圆都很有意思。", "target_word": "几何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学几何的时候，要先看懂图。", "target_word": "几何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位数学家在几何上有新发现。", "target_word": "几何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几何和代数是数学的两个分支。", "target_word": "几何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "建筑师需要用几何来设计房子。", "target_word": "几何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几何告诉我们两点之间直线最短。", "target_word": "几何", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的埃及人已经懂得一些几何了。", "target_word": "几何", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "幾何", "label": "繁体"}, {"form": "几何学", "label": "复合"}, {"form": "几何图形", "label": "复合"}], "register": "中性", "sense_fingerprint": "研究图形形状、大小和位置关系的数学分支", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5a5e0a7-1931-406f-8fa8-4b6b6a09a7b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92060, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "历史", "is_correct": false, "explanation": "语义：历史研究的是过去的事件，不研究图形的形状和大小。"}, {"text": "几何", "is_correct": true, "explanation": "“几何”是研究空间图形形状、大小和位置的数学分支，句意正确。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“研究”的对象应是学科或事物，“天气”不能作“研究图形的形状”的主语。"}, {"text": "代数", "is_correct": false, "explanation": "语义：代数研究数与式的运算和关系，不研究图形的形状和大小。"}], "explanations": {"历史": "语义：历史研究的是过去的事件，不研究图形的形状和大小。", "几何": "“几何”是研究空间图形形状、大小和位置的数学分支，句意正确。", "天气": "搭配：“研究”的对象应是学科或事物，“天气”不能作“研究图形的形状”的主语。", "代数": "语义：代数研究数与式的运算和关系，不研究图形的形状和大小。"}, "sentence_index": 0, "correct_answer": "几何"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我画了一个几何，三角形和圆都在上面。", "explanation": "这里应该用〈几何图形〉。“几何”指研究图形的学科，不能指一个画出来的图形。"}, {"text": "几何研究力和运动的规律。", "explanation": "这里应该用〈物理〉。几何研究图形的形状、大小和位置；研究力和运动规律的是物理。"}, {"text": "几何研究的是数与式之间的关系。", "explanation": "这里应该用〈代数〉。几何研究图形的形状、大小和位置，研究数与式关系的是代数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c1d2f4-427e-4755-b2ed-f9413a9d3608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92060, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诗歌", "is_correct": false, "explanation": "语义：诗歌属于文学，不是数学的分支，与“代数”并列不成立。"}, {"text": "几何", "is_correct": true, "explanation": "“几何”是数学的分支，与“代数”并列，搭配正确。"}, {"text": "音乐", "is_correct": false, "explanation": "搭配：“数学的两个分支”要求两者都是数学学科，“音乐”与“代数”并列搭配不通。"}, {"text": "语文", "is_correct": false, "explanation": "语义：语文是学校的学科，但不是数学的分支，与“代数”并列不成立。"}], "explanations": {"诗歌": "语义：诗歌属于文学，不是数学的分支，与“代数”并列不成立。", "几何": "“几何”是数学的分支，与“代数”并列，搭配正确。", "音乐": "搭配：“数学的两个分支”要求两者都是数学学科，“音乐”与“代数”并列搭配不通。", "语文": "语义：语文是学校的学科，但不是数学的分支，与“代数”并列不成立。"}, "sentence_index": 6, "correct_answer": "几何"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "几何的内角和是一百八十度。", "explanation": "这里应该用〈三角形〉。几何是研究图形的学科，不能说“几何的内角和”；内角和是具体图形三角形的性质。"}, {"text": "几何研究的是山川河流的分布。", "explanation": "这里应该用〈地理〉。几何研究图形的形状、大小和位置；研究山川河流分布的是地理。"}, {"text": "几何研究星星和行星的运动。", "explanation": "这里应该用〈天文学〉。几何研究的是图形的形状、大小和位置，研究星星和行星运动的是天文学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c1d2f4-427e-4755-b2ed-f9413a9d3608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92060, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我学过一个几何，还记得一些定理。", "corrected_sentence": "我学过一门几何，还记得一些定理。", "error_description": "量词用错：作为学科的“几何”应用量词“门”，说“学过一门几何”，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c1d2f4-427e-4755-b2ed-f9413a9d3608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92060, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我和几何很感兴趣。", "corrected_sentence": "我对几何很感兴趣。", "error_description": "介词用错：表示兴趣的对象要用“对”，说“对几何很感兴趣”，不能用“和”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4c1d2f4-427e-4755-b2ed-f9413a9d3608') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
