INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92063, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把车开着离开。", "primary_collocate": null, "pronunciation": "kāi zǒu", "ipa": "kʰaɪ̯˥ tsoʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "他把我的车开走了。", "target_word": "开走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小偷把车开走了。", "target_word": "开走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把车开走，这里不能停。", "target_word": "开走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥开走了爸爸的车。", "target_word": "开走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把车开走，送去修理。", "target_word": "开走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板把门口的车开走了。", "target_word": "开走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察开走了那辆旧车。", "target_word": "开走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能把车开走吗？", "target_word": "开走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把卡车开走了。", "target_word": "开走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友借车，下午就把车开走了。", "target_word": "开走", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开走了", "label": "完成体"}, {"form": "开走过", "label": "经历体"}, {"form": "开不走", "label": "可能补语"}, {"form": "開走", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把某辆车驾驶着带离某处，带车作宾语或用把字句", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20ba2caa-c9bc-48ff-8965-0af456cf76bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92063, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开走", "is_correct": true, "explanation": "开走：正确。「他把我的车开走了」指驾车把车带离。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「吃」的对象是食物，不能用于「我的车」。"}, {"text": "咬", "is_correct": false, "explanation": "语义：「咬」要用牙齿，车不能被咬。"}, {"text": "唱", "is_correct": false, "explanation": "语义：「唱」的对象是歌曲，不能用于「我的车」。"}], "explanations": {"开走": "开走：正确。「他把我的车开走了」指驾车把车带离。", "吃": "语义：「吃」的对象是食物，不能用于「我的车」。", "咬": "语义：「咬」要用牙齿，车不能被咬。", "唱": "语义：「唱」的对象是歌曲，不能用于「我的车」。"}, "sentence_index": 0, "correct_answer": "开走"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小偷开走了我的钱包。", "explanation": "这里应该用〈偷走〉。开走的对象必须是车辆，钱包不是车辆，要用偷走。"}, {"text": "工人开走了那张桌子。", "explanation": "这里应该用〈搬走〉。开走的对象必须是车辆，桌子不是车辆，要用搬走。"}, {"text": "他开走了我的书。", "explanation": "这里应该用〈拿走〉。开走的对象必须是车辆，书不是车辆，要用拿走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92063, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开走", "is_correct": true, "explanation": "开走：正确。「警察开走了那辆旧车」指警察驾车把车带离。"}, {"text": "喝", "is_correct": false, "explanation": "语义：「喝」的对象是饮品，不能用于「旧车」。"}, {"text": "读", "is_correct": false, "explanation": "搭配：「读」的对象是文字，不能说「读那辆旧车」。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：「喂」的对象是人或动物，不能用于「旧车」。"}], "explanations": {"开走": "开走：正确。「警察开走了那辆旧车」指警察驾车把车带离。", "喝": "语义：「喝」的对象是饮品，不能用于「旧车」。", "读": "搭配：「读」的对象是文字，不能说「读那辆旧车」。", "喂": "搭配：「喂」的对象是人或动物，不能用于「旧车」。"}, "sentence_index": 6, "correct_answer": "开走"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大风开走了他的帽子。", "explanation": "这里应该用〈吹走〉。开走要有人驾驶车辆，帽子不是车辆，风也不会开车，要用吹走。"}, {"text": "那只大象开走了那辆车。", "explanation": "这里应该用〈拖走〉。开走要求驾驶者会开车，大象不能驾驶车辆，要用拖走。"}, {"text": "洪水开走了那辆车。", "explanation": "这里应该用〈冲走〉。开走要求驾驶者会开车，洪水不能驾驶车辆，要用冲走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92063, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把我的小车开走着。", "corrected_sentence": "他把我的小车开走了。", "error_description": "错误：「着」表示持续状态，「开走」是完成的动作，应该用「了」。正确说法是「他把我的小车开走了。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92063, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同事借车，中午就把车开走着。", "corrected_sentence": "同事借车，中午就把车开走了。", "error_description": "错误：「着」表示持续状态，「开走」是完成的动作，应该用「了」。正确说法是「同事借车，中午就把车开走了。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
