INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92064, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "驾驶车辆离开。", "primary_collocate": null, "pronunciation": "kāi zǒu", "ipa": "kʰaɪ̯˥ tsoʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "他上了车，很快就开走了。", "target_word": "开走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察还没到，小偷已经开走了。", "target_word": "开走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先上车，我马上开走。", "target_word": "开走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机等了十分钟，然后开走了。", "target_word": "开走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说完话就开走了。", "target_word": "开走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没说再见就开走了。", "target_word": "开走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我下楼的时候，他已经开走了。", "target_word": "开走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王把东西放好，就开走了。", "target_word": "开走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停了，她上车开走了。", "target_word": "开走", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张吃完饭，上车开走了。", "target_word": "开走", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开走了", "label": "完成体"}, {"form": "开走过", "label": "经历体"}, {"form": "开不走", "label": "可能补语"}, {"form": "開走", "label": "繁体"}], "register": "中性", "sense_fingerprint": "驾驶人开着车自己离开某处，不带宾语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20ba2caa-c9bc-48ff-8965-0af456cf76bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92064, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开走", "is_correct": true, "explanation": "开走：正确。「很快就开走了」指驾车离开。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：「吃饭」与「上了车」之后很快发生的事情不衔接。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：「结婚」与「上了车，很快就」的情境无关。"}, {"text": "书包", "is_correct": false, "explanation": "词性：「书包」是名词，不能放在「很快就……了」中作谓语。"}], "explanations": {"开走": "开走：正确。「很快就开走了」指驾车离开。", "吃饭": "语义：「吃饭」与「上了车」之后很快发生的事情不衔接。", "结婚": "语义：「结婚」与「上了车，很快就」的情境无关。", "书包": "词性：「书包」是名词，不能放在「很快就……了」中作谓语。"}, "sentence_index": 0, "correct_answer": "开走"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小鸟开走了。", "explanation": "这里应该用〈飞走〉。开走指驾驶车辆离开，小鸟不能驾驶车辆，要用飞走。"}, {"text": "鱼开走了。", "explanation": "这里应该用〈游走〉。开走指驾驶车辆离开，鱼不能驾驶车辆，要用游走。"}, {"text": "雾气开走了。", "explanation": "这里应该用〈消失〉。开走指驾驶车辆离开，雾气不能驾驶车辆，要用消失。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92064, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开走", "is_correct": true, "explanation": "开走：正确。「他已经开走了」指他驾车离开。"}, {"text": "桌子", "is_correct": false, "explanation": "词性：「桌子」是名词，不能放在「他已经……了」中作谓语。"}, {"text": "亲吻", "is_correct": false, "explanation": "配价：「亲吻」需要宾语（亲吻某人），句中「他已经亲吻了」缺少宾语。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：「下雨」的主语应是天气，不能用「他」作主语。"}], "explanations": {"开走": "开走：正确。「他已经开走了」指他驾车离开。", "桌子": "词性：「桌子」是名词，不能放在「他已经……了」中作谓语。", "亲吻": "配价：「亲吻」需要宾语（亲吻某人），句中「他已经亲吻了」缺少宾语。", "下雨": "语义：「下雨」的主语应是天气，不能用「他」作主语。"}, "sentence_index": 6, "correct_answer": "开走"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那只猫开走了。", "explanation": "这里应该用〈跑走〉。开走指驾驶车辆离开，猫不能开车，要用跑走。"}, {"text": "孩子手里的气球开走了。", "explanation": "这里应该用〈飞走〉。开走指驾驶车辆离开，气球不能开车，要用飞走。"}, {"text": "树上的叶子被风吹得开走了。", "explanation": "这里应该用〈飘走〉。开走指驾驶车辆离开，叶子不能开车，要用飘走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92064, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我刚下车，那辆车就开走了了。", "corrected_sentence": "我刚下车，那辆车就开走了。", "error_description": "错误：「开走了」后面已经有「了」，不应重复加「了」。正确说法是「我刚下车，那辆车就开走了。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92064, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老王关好门，上车就开走着。", "corrected_sentence": "老王关好门，上车就开走了。", "error_description": "错误：「着」表示动作持续，而「开走」是一次性完成的动作，应该用「了」。正确说法是「老王关好门，上车就开走了。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
