INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92065, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "引爆是让炸弹爆炸。", "primary_collocate": null, "pronunciation": "yǐn bào", "ipa": "in˨˩ pau˥˩", "syllable_count": 2, "sentences": [{"text": "士兵远远地引爆了炸弹。", "target_word": "引爆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察用机器人引爆了可疑的炸弹。", "target_word": "引爆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他按下按钮，引爆了炸弹。", "target_word": "引爆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人躲到山后，引爆了炸药。", "target_word": "引爆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏人想引爆车里的炸弹。", "target_word": "引爆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家正在想办法引爆这颗旧炸弹。", "target_word": "引爆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里，他用手机引爆了桥下的炸弹。", "target_word": "引爆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军人在河边引爆过一颗炸弹。", "target_word": "引爆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请离远一点，我们要引爆炸弹了。", "target_word": "引爆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把炸弹放好，准备引爆。", "target_word": "引爆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "引爆了", "label": "完成体"}, {"form": "引爆过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "让炸弹等爆炸物爆炸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106b6cc5-ef4e-4494-9883-9314d895a3e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92065, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "引爆", "is_correct": true, "explanation": "正确答案。引爆：让炸弹爆炸，此处指士兵在远处引爆炸弹。"}, {"text": "摸", "is_correct": false, "explanation": "语义：“远远地”表示距离远，“摸”需要接触，士兵在远处摸不到炸弹。"}, {"text": "驯养", "is_correct": false, "explanation": "搭配：“驯养”的宾语须是动物，不能说驯养炸弹。"}, {"text": "救", "is_correct": false, "explanation": "语义：“救”的对象须是有生命的人或动物，炸弹不能被救。"}], "explanations": {"引爆": "正确答案。引爆：让炸弹爆炸，此处指士兵在远处引爆炸弹。", "摸": "语义：“远远地”表示距离远，“摸”需要接触，士兵在远处摸不到炸弹。", "驯养": "搭配：“驯养”的宾语须是动物，不能说驯养炸弹。", "救": "语义：“救”的对象须是有生命的人或动物，炸弹不能被救。"}, "sentence_index": 0, "correct_answer": "引爆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈引爆了灶台上的蜡烛。", "explanation": "这里应该用〈点燃〉。引爆用于炸药、炸弹等爆炸物，蜡烛只能说点燃。"}, {"text": "洪水引爆了那座小村庄。", "explanation": "这里应该用〈摧毁〉。引爆的对象是爆炸物，洪水冲毁村庄应说摧毁。"}, {"text": "学校引爆了一批新设备。", "explanation": "这里应该用〈引进〉。引爆指使爆炸物爆炸，学校引入新设备应说引进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92065, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "引爆", "is_correct": true, "explanation": "正确答案。引爆：让炸弹爆炸，此处指用手机引爆桥下的炸弹。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”的对象是食物，炸弹不能被煮。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”的对象是食物，炸弹不能被烤。"}, {"text": "放牧", "is_correct": false, "explanation": "搭配：“放牧”的对象是牛羊等牲畜，不能说放牧炸弹。"}], "explanations": {"引爆": "正确答案。引爆：让炸弹爆炸，此处指用手机引爆桥下的炸弹。", "煮": "语义：“煮”的对象是食物，炸弹不能被煮。", "烤": "语义：“烤”的对象是食物，炸弹不能被烤。", "放牧": "搭配：“放牧”的对象是牛羊等牲畜，不能说放牧炸弹。"}, "sentence_index": 6, "correct_answer": "引爆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爷爷引爆了那只小鸡。", "explanation": "这里把〈引爆〉用成了〈杀死〉的意思。引爆只能用于炸药、炸弹等爆炸物，小鸡是生物，不能被引爆。"}, {"text": "姐姐引爆了生日蛋糕。", "explanation": "这里把〈引爆〉用成了〈切开〉的意思。引爆只能用于炸药、炸弹等爆炸物，生日蛋糕不是爆炸物。"}, {"text": "弟弟引爆了那张旧照片。", "explanation": "这里应该用〈撕毁〉。引爆的对象只能是炸弹、炸药等爆炸物，照片不能被引爆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92065, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工兵引爆了过那堆旧炸药。", "corrected_sentence": "工兵引爆了那堆旧炸药。", "error_description": "错误：“引爆了过”；正确：“引爆了”。“了”和“过”都表示完成或经历，不能同时用，这里只用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92065, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人引爆了过一颗废弃的炸弹。", "corrected_sentence": "工人引爆过一颗废弃的炸弹。", "error_description": "错误：“引爆了过”；正确：“引爆过”。表示经历只用“过”，动词后不能同时加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
