INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92067, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "两岸是河或海两边的地方。", "primary_collocate": null, "pronunciation": "liǎng àn", "ipa": "ljɑŋ˨˩˦ an˥˩", "syllable_count": 2, "sentences": [{"text": "河的两岸都是绿色的树。", "target_word": "两岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河很宽，两岸的人要坐船过河。", "target_word": "两岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天，两岸开满了花。", "target_word": "两岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桥把河的两岸连在一起了。", "target_word": "两岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐船在江上，两岸的山很美。", "target_word": "两岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大河两岸住着很多人家。", "target_word": "两岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河两岸的路很安静。", "target_word": "两岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船走得很慢，两岸的风景一直在变。", "target_word": "两岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水很深，两岸的孩子不能自己过河。", "target_word": "两岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，河两岸的灯都亮了。", "target_word": "两岸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "河两岸", "label": "复合"}, {"form": "兩岸", "label": "繁体"}], "register": "中性", "sense_fingerprint": "河流两边的岸边土地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f82317-b64b-4c72-a0db-f7ebe4e148f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92067, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "两岸", "is_correct": true, "explanation": "正确：“两岸”指河的两边，与“河的”搭配，句意通顺。"}, {"text": "海边", "is_correct": false, "explanation": "语义：“海边”指海的岸边，与句中的“河”冲突。"}, {"text": "山顶", "is_correct": false, "explanation": "语义：“山顶”与“河的”不搭，句中指河的两边，不能是山顶。"}, {"text": "河床", "is_correct": false, "explanation": "搭配：“河床”指河底，与“都是绿色的树”搭配不当，河底通常不长树。"}], "explanations": {"两岸": "正确：“两岸”指河的两边，与“河的”搭配，句意通顺。", "海边": "语义：“海边”指海的岸边，与句中的“河”冲突。", "山顶": "语义：“山顶”与“河的”不搭，句中指河的两边，不能是山顶。", "河床": "搭配：“河床”指河底，与“都是绿色的树”搭配不当，河底通常不长树。"}, "sentence_index": 0, "correct_answer": "两岸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把书的两岸都涂成了红色。", "explanation": "这里应该用〈两边〉。“两岸”只指江河或海峡两边的陆地，不能指书本的两侧。"}, {"text": "他一个人站在两岸上钓鱼。", "explanation": "这里应该用〈河岸〉。“两岸”指河的两边，一个人只站在一边时应说河岸。"}, {"text": "我家的两岸有三个房间。", "explanation": "这里应该用〈两侧〉。“两岸”只指江河或海峡两边的陆地，不能指房屋的两侧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92067, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "两岸", "is_correct": true, "explanation": "正确：“两岸”指河的两边，与“这条河”搭配，句意通顺。"}, {"text": "草原", "is_correct": false, "explanation": "语义：“草原”是大片草地，不在河的两边，“这条河草原的路”句意不通。"}, {"text": "山区", "is_correct": false, "explanation": "语义：“山区”指山地地区，与“这条河”所指的河边位置不符，句意矛盾。"}, {"text": "城市", "is_correct": false, "explanation": "语义：“城市”与“这条河”所指的河边位置不符，“这条河城市的路”句意不通。"}], "explanations": {"两岸": "正确：“两岸”指河的两边，与“这条河”搭配，句意通顺。", "草原": "语义：“草原”是大片草地，不在河的两边，“这条河草原的路”句意不通。", "山区": "语义：“山区”指山地地区，与“这条河”所指的河边位置不符，句意矛盾。", "城市": "语义：“城市”与“这条河”所指的河边位置不符，“这条河城市的路”句意不通。"}, "sentence_index": 6, "correct_answer": "两岸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "船到了河的两岸。", "explanation": "这里应该用〈对岸〉。“两岸”指河的两边，船只能到达一边，不能说到了两岸。"}, {"text": "天黑了，马路两岸的灯都亮了。", "explanation": "这里应该用〈两边〉。“两岸”只指江河或海两边的陆地，马路两侧应说“两边”。"}, {"text": "这盘菜的两岸都放了葱。", "explanation": "这里应该用〈两边〉。“两岸”只指江河或海峡两边的陆地，不能指菜盘的两侧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92067, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "河的两个两岸种满了柳树。", "corrected_sentence": "河的两岸种满了柳树。", "error_description": "错误：“两个两岸”，“两岸”本身已表示河的两边，前面不能再加数量词“两个”。正确：“河的两岸”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92067, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条河两岸们的小路很安静。", "corrected_sentence": "这条河两岸的小路很安静。", "error_description": "错误：“两岸们”，“们”只能用于指人的名词，“两岸”后不能加“们”。正确：“这条河两岸的小路很安静”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
