INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92068, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "江河或海峡两边的陆地；也特指台湾海峡两边。", "primary_collocate": null, "pronunciation": "liǎng àn", "ipa": "ljɑŋ˨˩˦ an˥˩", "syllable_count": 2, "sentences": [{"text": "两岸的朋友今天在北京见面了。", "target_word": "两岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海峡两岸的人都说中文。", "target_word": "两岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他常常坐飞机往来于两岸之间。", "target_word": "两岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两岸的学生一起参加了这次比赛。", "target_word": "两岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节时，两岸的家人都想团聚。", "target_word": "两岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两岸的商人常常一起做生意。", "target_word": "两岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两岸的年轻人都喜欢这首歌。", "target_word": "两岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台湾海峡把两岸分开，但亲人心里很近。", "target_word": "两岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两岸的电视台一起做了这个节目。", "target_word": "两岸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两岸的老人都希望家人能经常见面。", "target_word": "两岸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "海峡两岸", "label": "复合"}, {"form": "两岸关系", "label": "复合"}, {"form": "兩岸", "label": "繁体"}], "register": "中性", "sense_fingerprint": "江河海峡两边的陆地，特指台湾海峡两边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f82317-b64b-4c72-a0db-f7ebe4e148f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92068, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "两岸", "is_correct": true, "explanation": "正确：“两岸”指台湾海峡两岸，与“朋友”和“北京见面”的语境相符。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：“黑板”是物体，不能有“朋友”，句意不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”是物体，不能有“朋友”，句意不通。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空的朋友”不成立，句中指人，句意矛盾。"}], "explanations": {"两岸": "正确：“两岸”指台湾海峡两岸，与“朋友”和“北京见面”的语境相符。", "黑板": "语义：“黑板”是物体，不能有“朋友”，句意不通。", "窗户": "语义：“窗户”是物体，不能有“朋友”，句意不通。", "天空": "语义：“天空的朋友”不成立，句中指人，句意矛盾。"}, "sentence_index": 0, "correct_answer": "两岸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "北京和上海两岸的学生一起参加了比赛。", "explanation": "这里应该用〈两地〉。“两岸”指江河两边的陆地或台湾海峡两边，北京和上海并不隔河或隔海相望，应说“两地”。"}, {"text": "这所学校两岸的学生一起参加了比赛。", "explanation": "这里应该用〈两个校区〉。“两岸”只指江河或海峡两边的陆地，学校没有两岸，应说“两个校区”。"}, {"text": "这三岸的学生一起参加了比赛。", "explanation": "“两岸”只有两方，不能说“三岸”，这里数量用错了。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92068, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "两岸", "is_correct": true, "explanation": "正确：“两岸”指台湾海峡两边，“两岸的年轻人”句意通顺。"}, {"text": "铅笔", "is_correct": false, "explanation": "语义：“铅笔”是文具，“铅笔的年轻人”句意不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”是家具，“桌子的年轻人”句意不通。"}, {"text": "杯子", "is_correct": false, "explanation": "语义：“杯子”是器物，“杯子的年轻人”句意不通。"}], "explanations": {"两岸": "正确：“两岸”指台湾海峡两边，“两岸的年轻人”句意通顺。", "铅笔": "语义：“铅笔”是文具，“铅笔的年轻人”句意不通。", "桌子": "语义：“桌子”是家具，“桌子的年轻人”句意不通。", "杯子": "语义：“杯子”是器物，“杯子的年轻人”句意不通。"}, "sentence_index": 6, "correct_answer": "两岸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这一对两岸的老人都希望家人能经常见面。", "explanation": "这里不能用量词〈一对〉修饰“两岸”。“两岸”本身已指两方，前面不能再加表示成对的量词。"}, {"text": "我和妹妹住在两岸，一个住在楼上，一个住在楼下。", "explanation": "这里应该用〈楼上楼下〉。“两岸”指台湾海峡两边，不能指同一栋楼的上下两层。"}, {"text": "这张桌子的两岸都放着书。", "explanation": "这里应该用〈两边〉。“两岸”只指江河或海峡两边的陆地，不能指桌子的两侧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92068, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两岸们的记者今天在北京见面了。", "corrected_sentence": "两岸的记者今天在北京见面了。", "error_description": "错误：“两岸们”。正确：“两岸”。“两岸”本身已是复数，不能再加“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92068, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她每年都坐船往来于两岸之中。", "corrected_sentence": "她每年都坐船往来于两岸之间。", "error_description": "错误：“两岸之中”。正确：“两岸之间”。“往来于……”指在两地之间来回，应说“两岸之间”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
