INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92069, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有想好，随便来的。", "primary_collocate": null, "pronunciation": "suí jī", "ipa": "sweɪ̯˧˥ tɕi˥", "syllable_count": 2, "sentences": [{"text": "他的选择很随机，没有什么原因。", "target_word": "随机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个答案是随机的，不是我想好的。", "target_word": "随机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天去哪儿吃饭，完全是随机的。", "target_word": "随机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次聊天很随机，我们没有准备话题。", "target_word": "随机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说话很随机，想到什么说什么。", "target_word": "随机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些数字是随机的，没有规律。", "target_word": "随机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做事太随机了，从来不做计划。", "target_word": "随机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的安排看起来很随机。", "target_word": "随机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的菜单很随机，老板想做什么就做什么。", "target_word": "随机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的旅行很随机，走到哪儿算哪儿。", "target_word": "随机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "随机的", "label": "定语形式"}, {"form": "隨機", "label": "繁体"}], "register": "口语", "sense_fingerprint": "形容词，没有计划、随便决定的，如“很随机”“是随机的”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '923791ca-0690-495c-bb48-7710886093fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92069, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "随机", "is_correct": true, "explanation": "正确。随机形容选择没有事先想好、随便来的，与“没有什么原因”相合。"}, {"text": "理性", "is_correct": false, "explanation": "语义：理性指有道理、有依据，与“没有什么原因”矛盾。"}, {"text": "紧张", "is_correct": false, "explanation": "搭配：紧张形容人的心理状态，不能用来形容选择，句意不通。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：聪明指有头脑、做得巧妙，与“没有什么原因”矛盾。"}], "explanations": {"随机": "正确。随机形容选择没有事先想好、随便来的，与“没有什么原因”相合。", "理性": "语义：理性指有道理、有依据，与“没有什么原因”矛盾。", "紧张": "搭配：紧张形容人的心理状态，不能用来形容选择，句意不通。", "聪明": "语义：聪明指有头脑、做得巧妙，与“没有什么原因”矛盾。"}, "sentence_index": 0, "correct_answer": "随机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他做实验很随机，每一步都有记录。", "explanation": "这里应该用〈严谨〉。随机强调没有计划、随便，做实验要用“严谨”。"}, {"text": "这份计划很随机，每一步都安排得很清楚。", "explanation": "这里应该用〈周密〉。随机说的是没有预先设计，计划的完备程度要用“周密”。"}, {"text": "这件工艺品很随机。", "explanation": "这里应该用〈精细〉。随机说的是没有预先设计，形容工艺品的做工要用“精细”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92069, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "随机", "is_correct": true, "explanation": "正确。随机形容做事没有计划、随便，与“从来不做计划”相合。"}, {"text": "认真", "is_correct": false, "explanation": "语义：认真表示尽心、重视，与“从来不做计划”矛盾。"}, {"text": "谨慎", "is_correct": false, "explanation": "语义：谨慎表示小心、考虑周到，与“从来不做计划”矛盾。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“高”不能用来形容做事的方式，应说“做事很随便”之类。"}], "explanations": {"随机": "正确。随机形容做事没有计划、随便，与“从来不做计划”相合。", "认真": "语义：认真表示尽心、重视，与“从来不做计划”矛盾。", "谨慎": "语义：谨慎表示小心、考虑周到，与“从来不做计划”矛盾。", "高": "搭配：“高”不能用来形容做事的方式，应说“做事很随便”之类。"}, "sentence_index": 6, "correct_answer": "随机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "火车很随机，每天都按时发车。", "explanation": "这里应该用〈准时〉。随机指没有计划，形容火车运行要用“准时”。"}, {"text": "老师的要求很随机，大家都要按时交作业。", "explanation": "这里应该用〈严格〉。随机指随便、没有标准，形容要求的严厉程度要用“严格”。"}, {"text": "房间收拾得很随机，东西摆得一丝不乱。", "explanation": "这里应该用〈整齐〉。随机指没有规律，形容收拾的样子要用“整齐”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92069, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她有一个很随机想法。", "corrected_sentence": "她有一个很随机的想法。", "error_description": "“很”加形容词修饰名词时，中间要加“的”，应说“很随机的想法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92069, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次出游得随机，大家都没准备。", "corrected_sentence": "这次出游很随机，大家都没准备。", "error_description": "错误：“很”误作“得”。“随机”作谓语需用程度副词“很”修饰，不能用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
