INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92070, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "不预先设定，任意地；随意。", "primary_collocate": null, "pronunciation": "suí jī", "ipa": "sweɪ̯˧˥ tɕi˥", "syllable_count": 2, "sentences": [{"text": "电脑会随机选一个名字。", "target_word": "随机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师随机叫了一个同学回答。", "target_word": "随机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请随机抽三张卡片。", "target_word": "随机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机会随机播放你喜欢的歌。", "target_word": "随机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前，我们随机分成了两组。", "target_word": "随机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生随机问了十个人。", "target_word": "随机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游戏里的礼物是随机给的。", "target_word": "随机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他闭上眼睛，随机翻开一本书。", "target_word": "随机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店会随机送客人一份小礼物。", "target_word": "随机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板随机请了三位客人喝茶。", "target_word": "随机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "隨機", "label": "繁体"}], "register": "中性", "sense_fingerprint": "副词，不事先设定、任意地做某事，放在动词前，如“随机抽取”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '923791ca-0690-495c-bb48-7710886093fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92070, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "随机", "is_correct": true, "explanation": "正确。随机是副词，表示任意、不预先设定，放在动词“选”前。"}, {"text": "故意", "is_correct": false, "explanation": "语义：故意表示有意图，电脑没有意图，与“任意地选”不合。"}, {"text": "亲自", "is_correct": false, "explanation": "配价：亲自要求动作者是人，电脑不能亲自去选。"}, {"text": "特意", "is_correct": false, "explanation": "语义：特意是为某个目的专门去做，与句中任意选择的意思相反。"}], "explanations": {"随机": "正确。随机是副词，表示任意、不预先设定，放在动词“选”前。", "故意": "语义：故意表示有意图，电脑没有意图，与“任意地选”不合。", "亲自": "配价：亲自要求动作者是人，电脑不能亲自去选。", "特意": "语义：特意是为某个目的专门去做，与句中任意选择的意思相反。"}, "sentence_index": 0, "correct_answer": "随机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他随机准备出发。", "explanation": "这里应该用〈随时〉。随机表示任意、不预先设定，表示任何时候都可以要用“随时”。"}, {"text": "他随机离开了房间。", "explanation": "这里应该用〈随即〉。随即表示紧接着就，随机表示任意地，不表示时间上的接续。"}, {"text": "请大家随机，不要客气。", "explanation": "这里应该用〈随意〉。随机是副词，必须放在动词前，不能单独作谓语；表示请人自由、不拘束要说“请大家随意”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92070, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "随机", "is_correct": true, "explanation": "正确。随机是副词，表示任意、不预先设定，修饰动词“给”。"}, {"text": "亲手", "is_correct": false, "explanation": "配价：亲手要求动作者用自己的手去做，游戏系统不能亲手给礼物。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：偏偏表示故意或恰好，与礼物的任意给予不合。"}, {"text": "亲笔", "is_correct": false, "explanation": "配价：亲笔指亲自书写，要求动作是书写，不能用于“给”。"}], "explanations": {"随机": "正确。随机是副词，表示任意、不预先设定，修饰动词“给”。", "亲手": "配价：亲手要求动作者用自己的手去做，游戏系统不能亲手给礼物。", "偏偏": "语义：偏偏表示故意或恰好，与礼物的任意给予不合。", "亲笔": "配价：亲笔指亲自书写，要求动作是书写，不能用于“给”。"}, "sentence_index": 6, "correct_answer": "随机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他随机关上了门。", "explanation": "这里应该用〈随手〉。随机表示任意、不预先设定，表示顺手、顺便做事要用“随手”。"}, {"text": "会议随机开始了。", "explanation": "这里应该用〈随后〉。随机表示任意、不预先设定，表示之后接着发生要用“随后”。"}, {"text": "这种花随机可见。", "explanation": "这里应该用〈随处〉。随处表示到处都有，随机不表示地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92070, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个程序会随机的抽取一位同学。", "corrected_sentence": "这个程序会随机抽取一位同学。", "error_description": "错误：副词“随机”后面不能加“的”，应去掉“的”，说“会随机抽取”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92070, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很随机抽出一张卡片。", "corrected_sentence": "他随机抽出一张卡片。", "error_description": "错误：“很随机”；正确：“随机”。“随机”是副词，不能受程度副词“很”修饰，应直接放在动词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '487d859d-09f5-4a2a-86d7-5c4dbf595fdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
