INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92071, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "刀是用来切东西的、很锋利的工具。", "primary_collocate": null, "pronunciation": "dāo", "ipa": "taʊ˥", "syllable_count": 1, "sentences": [{"text": "这把刀很锋利，小心手。", "target_word": "刀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用刀切肉。", "target_word": "刀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里有一把新刀。", "target_word": "刀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一把切菜的刀。", "target_word": "刀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把刀不快，切不开苹果。", "target_word": "刀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着刀在切西瓜。", "target_word": "刀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刀太钝了，要磨一磨。", "target_word": "刀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩不能玩刀，很危险。", "target_word": "刀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把刀放在桌子上。", "target_word": "刀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸每天用同一把刀做饭。", "target_word": "刀", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "把", "label": "量词"}, {"form": "菜刀", "label": "复合"}, {"form": "刀子", "label": "复合"}], "register": "中性", "sense_fingerprint": "厨房等处用来切东西的锋利工具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b94b613-bc01-4765-9f44-061a986e4dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92071, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "刀", "is_correct": true, "explanation": "刀 dāo（第一声），指切东西的工具，正确答案。"}, {"text": "到", "is_correct": false, "explanation": "dào（第四声）与 dāo（第一声）声调不同，意思是到达。"}, {"text": "倒", "is_correct": false, "explanation": "dǎo（第三声）与 dāo（第一声）声调不同，意思是倒下、倒掉。"}, {"text": "掏", "is_correct": false, "explanation": "tāo（第一声）与 dāo 声母不同（t 与 d），意思是掏出、掏取。"}, {"text": "包", "is_correct": false, "explanation": "bāo（第一声）与 dāo 声母不同（b 与 d），意思是包裹。"}], "explanations": {"刀": "刀 dāo（第一声），指切东西的工具，正确答案。", "到": "dào（第四声）与 dāo（第一声）声调不同，意思是到达。", "倒": "dǎo（第三声）与 dāo（第一声）声调不同，意思是倒下、倒掉。", "掏": "tāo（第一声）与 dāo 声母不同（t 与 d），意思是掏出、掏取。", "包": "bāo（第一声）与 dāo 声母不同（b 与 d），意思是包裹。"}, "sentence_index": null, "correct_answer": "刀"}, "level_3": {"options": [{"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞没有刃口，不能说“锋利”，也不会小心伤手。"}, {"text": "刀", "is_correct": true, "explanation": "正确：“刀”指有刃口的切割工具，可以说“锋利”，也会伤手。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不会锋利，也不会伤手，与后半句的提示冲突。"}, {"text": "镜子", "is_correct": false, "explanation": "搭配：“锋利”用于刀刃、剑锋等，不说镜子锋利。"}], "explanations": {"雨伞": "语义：雨伞没有刃口，不能说“锋利”，也不会小心伤手。", "刀": "正确：“刀”指有刃口的切割工具，可以说“锋利”，也会伤手。", "椅子": "语义：椅子不会锋利，也不会伤手，与后半句的提示冲突。", "镜子": "搭配：“锋利”用于刀刃、剑锋等，不说镜子锋利。"}, "sentence_index": 0, "correct_answer": "刀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用刀把钉子敲进了木板。", "explanation": "这里应该用〈锤子〉。敲钉子要用锤子，刀刃薄，不能用来敲击钉子。"}, {"text": "他用刀把头发梳得很整齐。", "explanation": "这里应该用〈梳子〉。梳头发要用梳子，刀是切东西的，不能用来梳头。"}, {"text": "妈妈用刀缝好了衣服的破洞。", "explanation": "这里应该用〈针〉。缝衣服要用针线，刀只能切割、砍削，不能用来缝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92071, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "刀", "is_correct": true, "explanation": "刀 dāo（第一声），指切东西的工具，正确答案。"}, {"text": "道", "is_correct": false, "explanation": "dào（第四声）与 dāo（第一声）声调不同，意思是道路。"}, {"text": "岛", "is_correct": false, "explanation": "dǎo（第三声）与 dāo（第一声）声调不同，意思是小岛。"}, {"text": "雕", "is_correct": false, "explanation": "diāo（第一声）比 dāo 多一个介音 i，意思是雕刻。"}], "explanations": {"刀": "刀 dāo（第一声），指切东西的工具，正确答案。", "道": "dào（第四声）与 dāo（第一声）声调不同，意思是道路。", "岛": "dǎo（第三声）与 dāo（第一声）声调不同，意思是小岛。", "雕": "diāo（第一声）比 dāo 多一个介音 i，意思是雕刻。"}, "sentence_index": null, "correct_answer": "刀"}, "level_3": {"options": [{"text": "手机", "is_correct": false, "explanation": "语义：手机没有刃口，不会“钝”，也不用“磨”。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“钝”和“磨”多用于刀具，不说桌子太钝。"}, {"text": "刀", "is_correct": true, "explanation": "正确：“刀”有刃口，钝了要磨，与后半句完全吻合。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：苹果不能说“钝”，也不用“磨一磨”，与后半句冲突。"}], "explanations": {"手机": "语义：手机没有刃口，不会“钝”，也不用“磨”。", "桌子": "搭配：“钝”和“磨”多用于刀具，不说桌子太钝。", "刀": "正确：“刀”有刃口，钝了要磨，与后半句完全吻合。", "苹果": "语义：苹果不能说“钝”，也不用“磨一磨”，与后半句冲突。"}, "sentence_index": 6, "correct_answer": "刀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人用刀锯断了木头。", "explanation": "这里应该用〈锯子〉。锯木头要用有齿的锯子，普通刀刃不能这样锯。"}, {"text": "他用刀把汤舀到碗里。", "explanation": "这里应该用〈勺子〉。舀汤要用勺子，刀是切东西的，不能用来舀。"}, {"text": "他用刀凿开了石头。", "explanation": "这里应该用〈凿子〉。凿石头要用凿子，刀刃薄，不能靠敲击凿开石头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92071, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我用这只刀切了一个西红柿。", "corrected_sentence": "我用这把刀切了一个西红柿。", "error_description": "“刀”有柄，量词应用“把”，不用“只”。错误形式“这只刀”，正确形式“这把刀”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92071, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用一个刀切了一条鱼。", "corrected_sentence": "他用一把刀切了一条鱼。", "error_description": "“刀”有柄，量词用“把”，不用“个”。错误形式“一个刀”，正确形式“一把刀”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
