INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92072, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有锋利刃口、用来切割或砍削的工具。", "primary_collocate": null, "pronunciation": "dāo", "ipa": "taʊ˥", "syllable_count": 1, "sentences": [{"text": "农民用刀砍树枝。", "target_word": "刀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用刀削苹果皮。", "target_word": "刀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把刀很钝，砍不断木头。", "target_word": "刀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用刀割开了纸箱。", "target_word": "刀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷有一把用了很多年的老刀。", "target_word": "刀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把刀的刃很薄，很容易切开纸。", "target_word": "刀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把刀磨得很快。", "target_word": "刀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里人带着刀去砍竹子。", "target_word": "刀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把刀是铁做的，很重。", "target_word": "刀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用刀割断了绳子。", "target_word": "刀", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "把", "label": "量词"}, {"form": "菜刀", "label": "复合"}, {"form": "刀子", "label": "复合"}], "register": "中性", "sense_fingerprint": "有刃口、用来切割或砍削的工具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b94b613-bc01-4765-9f44-061a986e4dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92072, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "刀", "is_correct": true, "explanation": "刀 dāo（第一声），指有刃口的切割或砍削工具，正确答案。"}, {"text": "到", "is_correct": false, "explanation": "dào（第四声）与 dāo（第一声）声调不同，意思是到达。"}, {"text": "倒", "is_correct": false, "explanation": "dǎo（第三声）与 dāo（第一声）声调不同，意思是倒下、倒掉。"}, {"text": "掏", "is_correct": false, "explanation": "tāo（第一声）与 dāo 声母不同（t 与 d），意思是掏出、掏取。"}, {"text": "包", "is_correct": false, "explanation": "bāo（第一声）与 dāo 声母不同（b 与 d），意思是包裹。"}], "explanations": {"刀": "刀 dāo（第一声），指有刃口的切割或砍削工具，正确答案。", "到": "dào（第四声）与 dāo（第一声）声调不同，意思是到达。", "倒": "dǎo（第三声）与 dāo（第一声）声调不同，意思是倒下、倒掉。", "掏": "tāo（第一声）与 dāo 声母不同（t 与 d），意思是掏出、掏取。", "包": "bāo（第一声）与 dāo 声母不同（b 与 d），意思是包裹。"}, "sentence_index": null, "correct_answer": "刀"}, "level_3": {"options": [{"text": "绳子", "is_correct": false, "explanation": "语义：绳子不能用来砍树枝，与“砍”的动作不合。"}, {"text": "刀", "is_correct": true, "explanation": "正确：“刀”有刃口，农民用它砍树枝，符合句意。"}, {"text": "水", "is_correct": false, "explanation": "语义：水没有刃口，不能用来砍树枝。"}, {"text": "纸", "is_correct": false, "explanation": "搭配：“砍”需要有刃口的工具，纸不能用来砍树枝。"}], "explanations": {"绳子": "语义：绳子不能用来砍树枝，与“砍”的动作不合。", "刀": "正确：“刀”有刃口，农民用它砍树枝，符合句意。", "水": "语义：水没有刃口，不能用来砍树枝。", "纸": "搭配：“砍”需要有刃口的工具，纸不能用来砍树枝。"}, "sentence_index": 0, "correct_answer": "刀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人用刀锯开了木板。", "explanation": "这里应该用〈锯子〉。锯木板要用有齿的锯子，普通刀刃不能这样锯。"}, {"text": "他用刀把地扫干净了。", "explanation": "这里应该用〈扫帚〉。扫地要用扫帚，刀是切割、砍削的工具，不能用来扫地。"}, {"text": "奶奶用刀织好了一件毛衣。", "explanation": "这里应该用〈毛衣针〉。织毛衣要用毛衣针，刀只能切割、砍削，不能用来织。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92072, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "刀", "is_correct": true, "explanation": "刀 dāo（第一声），指有刃口的切割或砍削工具，正确答案。"}, {"text": "道", "is_correct": false, "explanation": "dào（第四声）与 dāo（第一声）声调不同，意思是道路。"}, {"text": "岛", "is_correct": false, "explanation": "dǎo（第三声）与 dāo（第一声）声调不同，意思是小岛。"}, {"text": "雕", "is_correct": false, "explanation": "diāo（第一声）比 dāo 多一个介音 i，意思是雕刻。"}], "explanations": {"刀": "刀 dāo（第一声），指有刃口的切割或砍削工具，正确答案。", "道": "dào（第四声）与 dāo（第一声）声调不同，意思是道路。", "岛": "dǎo（第三声）与 dāo（第一声）声调不同，意思是小岛。", "雕": "diāo（第一声）比 dāo 多一个介音 i，意思是雕刻。"}, "sentence_index": null, "correct_answer": "刀"}, "level_3": {"options": [{"text": "衣服", "is_correct": false, "explanation": "语义：衣服不能磨得很快，与“磨得很快”的说法冲突。"}, {"text": "刀", "is_correct": true, "explanation": "正确：“把刀磨得很快”指磨利刀刃，符合句意。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能磨得很快，这里的“快”指锋利。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“磨得很快”多用于刀具，不说窗户磨得很快。"}], "explanations": {"衣服": "语义：衣服不能磨得很快，与“磨得很快”的说法冲突。", "刀": "正确：“把刀磨得很快”指磨利刀刃，符合句意。", "桌子": "语义：桌子不能磨得很快，这里的“快”指锋利。", "窗户": "搭配：“磨得很快”多用于刀具，不说窗户磨得很快。"}, "sentence_index": 6, "correct_answer": "刀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用刀钻了一个孔。", "explanation": "这里应该用〈钻头〉。钻孔要靠钻头旋转，“刀”靠切割、砍削，不能用来钻孔。"}, {"text": "他用刀焊接了两根铁管。", "explanation": "这里应该用〈焊枪〉。焊接铁管要用焊枪，刀不能把金属熔合连接。"}, {"text": "他用刀凿出了一个石洞。", "explanation": "这里应该用〈凿子〉。凿石洞要用凿子，刀不能靠敲击凿出石洞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92072, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我用一只刀切了一块面包。", "corrected_sentence": "我用一把刀切了一块面包。", "error_description": "“刀”有柄，量词应用“把”，不用“只”。错误形式“一只刀”，正确形式“一把刀”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92072, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用一个刀剁碎了一块排骨。", "corrected_sentence": "他用一把刀剁碎了一块排骨。", "error_description": "“刀”有柄，量词用“把”，不用“个”。错误形式“一个刀”，正确形式“一把刀”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
