INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92073, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92073, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "见面问你问题，看你合不合适。", "primary_collocate": null, "pronunciation": "miàn shì", "ipa": "mjɛn˥˩ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "我明天上午要去面试。", "target_word": "面试", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我今天去那家公司面试了。", "target_word": "面试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次面试，经理问了很多问题。", "target_word": "面试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很紧张，因为下午要面试。", "target_word": "面试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司让我下周二去面试。", "target_word": "面试", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我以前面试过很多次，都没有成功。", "target_word": "面试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你面试的时候，不要太紧张。", "target_word": "面试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我面试了两家公司，都不太合适。", "target_word": "面试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他穿着新衣服去公司面试。", "target_word": "面试", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面试结束以后，我松了一口气。", "target_word": "面试", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "面试了", "label": "体标"}, {"form": "面试过", "label": "体标"}, {"form": "面试官", "label": "复合"}], "register": "中性", "sense_fingerprint": "找工作时和公司的人见面，回答问题，看是否合适", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20ba2caa-c9bc-48ff-8965-0af456cf76bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92073, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "面试", "is_correct": true, "explanation": "面试（miàn shì）：正确答案，指应聘者接受公司的当面考察。"}, {"text": "免试", "is_correct": false, "explanation": "免试（miǎn shì）与面试（miàn shì）的第一音节声调不同：免为第三声，面为第四声。意思是免除考试。"}, {"text": "面食", "is_correct": false, "explanation": "面食（miàn shí）与面试（miàn shì）的第二音节声调不同：食为第二声，试为第四声。意思是用面粉做的食品。"}, {"text": "电视", "is_correct": false, "explanation": "电视（diàn shì）与面试（miàn shì）的第一音节声母不同：d 与 m 不同。意思是电视机。"}, {"text": "变式", "is_correct": false, "explanation": "变式（biàn shì）与面试（miàn shì）的第一音节声母不同：b 与 m 不同。意思是变化的样式。"}], "explanations": {"面试": "面试（miàn shì）：正确答案，指应聘者接受公司的当面考察。", "免试": "免试（miǎn shì）与面试（miàn shì）的第一音节声调不同：免为第三声，面为第四声。意思是免除考试。", "面食": "面食（miàn shí）与面试（miàn shì）的第二音节声调不同：食为第二声，试为第四声。意思是用面粉做的食品。", "电视": "电视（diàn shì）与面试（miàn shì）的第一音节声母不同：d 与 m 不同。意思是电视机。", "变式": "变式（biàn shì）与面试（miàn shì）的第一音节声母不同：b 与 m 不同。意思是变化的样式。"}, "sentence_index": null, "correct_answer": "面试"}, "level_3": {"options": [{"text": "面试", "is_correct": true, "explanation": "面试：正确。「去面试」指去接受面试，与「明天上午」搭配自然。"}, {"text": "录取", "is_correct": false, "explanation": "配价：「录取」需要带宾语（录取某人），句中「去录取」缺少宾语。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：「迟到」指到得晚，不能作为「去」的目的。"}, {"text": "放假", "is_correct": false, "explanation": "搭配：「放假」指自己停止工作或学习，不能说「要去放假」。"}], "explanations": {"面试": "面试：正确。「去面试」指去接受面试，与「明天上午」搭配自然。", "录取": "配价：「录取」需要带宾语（录取某人），句中「去录取」缺少宾语。", "迟到": "语义：「迟到」指到得晚，不能作为「去」的目的。", "放假": "搭配：「放假」指自己停止工作或学习，不能说「要去放假」。"}, "sentence_index": 0, "correct_answer": "面试"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "记者面试了那位明星。", "explanation": "这里应该用〈采访〉。面试指考察应试者的能力和素质，记者向明星提问要用采访。"}, {"text": "医生面试了病人的心脏。", "explanation": "这里应该用〈检查〉。面试的对象是应试者，检查身体器官要用检查，不能说面试。"}, {"text": "总统面试了外国代表团。", "explanation": "这里应该用〈接见〉。面试是考察应试者，会见来访的代表团要用接见。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92073, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "面试", "is_correct": true, "explanation": "面试：正确。「你面试的时候」指应试者接受面试时，语境完整。"}, {"text": "出生", "is_correct": false, "explanation": "语义：「出生」指婴儿来到世上，与应试时的紧张情绪无关。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：「睡觉」与应试时的紧张情绪无关，不能用于「你……的时候，不要太紧张」的应试语境。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：「洗澡」与应试场合无关，不能用于「你……的时候，不要太紧张」的应试语境。"}], "explanations": {"面试": "面试：正确。「你面试的时候」指应试者接受面试时，语境完整。", "出生": "语义：「出生」指婴儿来到世上，与应试时的紧张情绪无关。", "睡觉": "语义：「睡觉」与应试时的紧张情绪无关，不能用于「你……的时候，不要太紧张」的应试语境。", "洗澡": "语义：「洗澡」与应试场合无关，不能用于「你……的时候，不要太紧张」的应试语境。"}, "sentence_index": 6, "correct_answer": "面试"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校每学期都要面试学生的成绩。", "explanation": "这里应该用〈考核〉。面试考察的是应试者，学生的成绩要用考核。"}, {"text": "警察面试了这起案件。", "explanation": "这里应该用〈调查〉。面试的对象是应试者，案件要用调查。"}, {"text": "市长面试了这份计划。", "explanation": "这里应该用〈审批〉。面试针对应试者，计划书要用审批。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92073, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天去公司面试着。", "corrected_sentence": "我昨天去公司面试了。", "error_description": "错误：「着」表示动作持续，「昨天」的面试已经完成，应该用「了」。正确说法是「我昨天去公司面试了。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92073, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他面试着三家公司，都没成功。", "corrected_sentence": "他面试了三家公司，都没成功。", "error_description": "错误：「着」表示动作正在持续，这里说的是已经完成的经历，应该用「了」。正确说法是「他面试了三家公司，都没成功。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
