INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92074, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "当面考察应试者的能力和素质。", "primary_collocate": null, "pronunciation": "miàn shì", "ipa": "mjɛn˥˩ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "学校面试考生的口语和表达能力。", "target_word": "面试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校面试新生，看他们会不会说汉语。", "target_word": "面试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司面试时会看你的经验和能力。", "target_word": "面试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面试的时候，他们更看重你的想法。", "target_word": "面试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "评委面试了三个小时，才选出最好的人。", "target_word": "面试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们面试我，是想知道我会什么。", "target_word": "面试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院用两天面试了二十个护士。", "target_word": "面试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校请专家来面试这些学生。", "target_word": "面试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们会面试每个人，了解他们的能力。", "target_word": "面试", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面试的老师把每个学生都问了一遍。", "target_word": "面试", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "面试了", "label": "体标"}, {"form": "面试过", "label": "体标"}, {"form": "面试官", "label": "复合"}], "register": "中性", "sense_fingerprint": "招聘或招生时当面考察应试者的能力和素质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20ba2caa-c9bc-48ff-8965-0af456cf76bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92074, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "面试", "is_correct": true, "explanation": "面试（miàn shì）：正确答案，指当面考察应试者的能力和素质。"}, {"text": "免试", "is_correct": false, "explanation": "免试（miǎn shì）与面试（miàn shì）的第一音节声调不同：免为第三声，面为第四声。意思是免除考试。"}, {"text": "面食", "is_correct": false, "explanation": "面食（miàn shí）与面试（miàn shì）的第二音节声调不同：食为第二声，试为第四声。意思是用面粉做的食品。"}, {"text": "电视", "is_correct": false, "explanation": "电视（diàn shì）与面试（miàn shì）的第一音节声母不同：d 与 m 不同。意思是电视机。"}, {"text": "变式", "is_correct": false, "explanation": "变式（biàn shì）与面试（miàn shì）的第一音节声母不同：b 与 m 不同。意思是变化的样式。"}], "explanations": {"面试": "面试（miàn shì）：正确答案，指当面考察应试者的能力和素质。", "免试": "免试（miǎn shì）与面试（miàn shì）的第一音节声调不同：免为第三声，面为第四声。意思是免除考试。", "面食": "面食（miàn shí）与面试（miàn shì）的第二音节声调不同：食为第二声，试为第四声。意思是用面粉做的食品。", "电视": "电视（diàn shì）与面试（miàn shì）的第一音节声母不同：d 与 m 不同。意思是电视机。", "变式": "变式（biàn shì）与面试（miàn shì）的第一音节声母不同：b 与 m 不同。意思是变化的样式。"}, "sentence_index": null, "correct_answer": "面试"}, "level_3": {"options": [{"text": "面试", "is_correct": true, "explanation": "面试：正确。「学校面试考生」指学校当面考察考生的能力。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：「打扫」的对象是场地或物品，不能用于「口语和表达能力」。"}, {"text": "录取", "is_correct": false, "explanation": "搭配：「录取」的对象是人，不能说「录取……的口语和表达能力」。"}, {"text": "出售", "is_correct": false, "explanation": "语义：「出售」指卖商品，能力和口语不能被出售。"}], "explanations": {"面试": "面试：正确。「学校面试考生」指学校当面考察考生的能力。", "打扫": "语义：「打扫」的对象是场地或物品，不能用于「口语和表达能力」。", "录取": "搭配：「录取」的对象是人，不能说「录取……的口语和表达能力」。", "出售": "语义：「出售」指卖商品，能力和口语不能被出售。"}, "sentence_index": 0, "correct_answer": "面试"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "领导面试了那个地区的发展。", "explanation": "这里应该用〈考察〉。考察指实地了解情况，地区的发展要用考察，不能说面试。"}, {"text": "医院给员工面试身体。", "explanation": "这里应该用〈体检〉。面试考察的是人的能力素质，检查身体要用体检。"}, {"text": "编辑面试了这篇稿件。", "explanation": "这里应该用〈审核〉。面试针对应试者，稿件要用审核。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92074, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "面试", "is_correct": true, "explanation": "面试：正确。「面试了二十个护士」指当面考察这些护士。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：「驾驶」的对象是车辆，不能用于护士。"}, {"text": "煮", "is_correct": false, "explanation": "语义：「煮」的对象是食物，与「二十个护士」不符。"}, {"text": "洗", "is_correct": false, "explanation": "语义：「洗」指清洗物品，用在「二十个护士」上语义不通。"}], "explanations": {"面试": "面试：正确。「面试了二十个护士」指当面考察这些护士。", "驾驶": "搭配：「驾驶」的对象是车辆，不能用于护士。", "煮": "语义：「煮」的对象是食物，与「二十个护士」不符。", "洗": "语义：「洗」指清洗物品，用在「二十个护士」上语义不通。"}, "sentence_index": 6, "correct_answer": "面试"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板面试了账目。", "explanation": "这里应该用〈查看〉。面试针对应试者，账目要用查看。"}, {"text": "将军面试了部队。", "explanation": "这里应该用〈检阅〉。面试是考察应试者，检阅部队要用检阅。"}, {"text": "工人面试了那台机器。", "explanation": "这里应该用〈查验〉。面试的对象是人，机器要用查验。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92074, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校明年要面试了考生。", "corrected_sentence": "学校明年要面试考生。", "error_description": "错误：「明年」是将来时间，「面试」后不能加「了」。正确说法是「学校明年要面试考生。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92074, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医院用三天面试着十个护士。", "corrected_sentence": "医院用三天面试了十个护士。", "error_description": "错误：「着」表示持续状态，这里说的是已经完成的事情，应该用「了」。正确说法是「医院用三天面试了十个护士。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
