INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92075, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "千万是告诉你这件事一定要记住。", "primary_collocate": null, "pronunciation": "qiān wàn", "ipa": "tɕʰjɛn˥ wan˥˩", "syllable_count": 2, "sentences": [{"text": "过马路时千万要看车。", "target_word": "千万", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你千万不要忘了带钱包。", "target_word": "千万", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天千万别开快车。", "target_word": "千万", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事千万不能告诉别人。", "target_word": "千万", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门前千万记得关火。", "target_word": "千万", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试的时候千万别紧张。", "target_word": "千万", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上很冷，你千万要多穿衣服。", "target_word": "千万", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说：“千万别玩手机玩到太晚。”", "target_word": "千万", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个药很苦，但你千万要吃完。", "target_word": "千万", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上有雪，千万要小心。", "target_word": "千万", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "提醒对方一定要记住，常接要、别、不要、不能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f82317-b64b-4c72-a0db-f7ebe4e148f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92075, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "千万", "is_correct": true, "explanation": "千万：副词，表示恳切叮嘱，此句提醒过马路时一定要看车。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：“已经”表示动作已经完成，与叮嘱对方今后要做的“要”不相容。"}, {"text": "终于", "is_correct": false, "explanation": "语义：“终于”表示经过较长过程后最后出现，过马路时看车是每次都要做的常规，不能用“终于”。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：“竟然”表示出乎意料，过马路时看车是常规要求，句中不该用。"}], "explanations": {"千万": "千万：副词，表示恳切叮嘱，此句提醒过马路时一定要看车。", "已经": "体貌：“已经”表示动作已经完成，与叮嘱对方今后要做的“要”不相容。", "终于": "语义：“终于”表示经过较长过程后最后出现，过马路时看车是每次都要做的常规，不能用“终于”。", "竟然": "语义：“竟然”表示出乎意料，过马路时看车是常规要求，句中不该用。"}, "sentence_index": 0, "correct_answer": "千万"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他千万会来。", "explanation": "这里应该用〈一定〉。千万只用于叮嘱对方，后面接“要、别、不要、不能”，不用来推测将要发生的事。"}, {"text": "这次改革千万会带来变化。", "explanation": "这里应该用〈必定〉。千万只用于叮嘱对方，不用来对将要发生的结果作判断；表示事情必然发生要用“必定”。"}, {"text": "明天的比赛我们千万会赢。", "explanation": "这里应该用〈肯定〉。千万用于叮嘱，不用来对结果作判断。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92075, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "千万", "is_correct": true, "explanation": "千万：副词，表示恳切叮嘱，此句提醒对方多穿衣服。"}, {"text": "果然", "is_correct": false, "explanation": "语义：“果然”表示与预料相符，是对结果的确认，不表示叮嘱，与“要”的劝告语气不合。"}, {"text": "终于", "is_correct": false, "explanation": "语义：“终于”表示经过较长过程后最后出现，与“山上很冷”需要即刻添衣的叮嘱语境不合。"}, {"text": "曾", "is_correct": false, "explanation": "体貌：“曾”表示过去经历过，与这里当下的叮嘱不符。"}], "explanations": {"千万": "千万：副词，表示恳切叮嘱，此句提醒对方多穿衣服。", "果然": "语义：“果然”表示与预料相符，是对结果的确认，不表示叮嘱，与“要”的劝告语气不合。", "终于": "语义：“终于”表示经过较长过程后最后出现，与“山上很冷”需要即刻添衣的叮嘱语境不合。", "曾": "体貌：“曾”表示过去经历过，与这里当下的叮嘱不符。"}, "sentence_index": 6, "correct_answer": "千万"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这里的风景千万美。", "explanation": "这里应该用〈非常〉。千万只用于叮嘱，不表示程度，不能用来修饰“美”。"}, {"text": "这个菜千万好吃。", "explanation": "这里应该用〈特别〉。千万只用于叮嘱，不表示形容词的程度。"}, {"text": "我千万去了北京。", "explanation": "这里应该用〈已经〉。千万表示叮嘱，不能与表示完成的“了”连用，也不用来陈述已经发生的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92075, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天黑以后千万不别一个人出去。", "corrected_sentence": "天黑以后千万别一个人出去。", "error_description": "错误：“千万不别”，“别”本身已是否定的叮嘱词，其前不能再加“不”。正确：“千万别”，“千万”是叮嘱副词，直接修饰否定叮嘱词“别”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92075, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "千万别要忘了锁门。", "corrected_sentence": "千万别忘了锁门。", "error_description": "错误：“别”本身已表示否定的叮嘱，其后不能再加“要”。正确：“千万别忘了锁门”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
