INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92076, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示恳切叮嘱，务必、一定。", "primary_collocate": null, "pronunciation": "qiān wàn", "ipa": "tɕʰjɛn˥ wan˥˩", "syllable_count": 2, "sentences": [{"text": "明天开会，你千万别迟到。", "target_word": "千万", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了那里，千万要给我打电话。", "target_word": "千万", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是秘密，千万不能说出去。", "target_word": "千万", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你一个人在外面，千万要照顾好自己。", "target_word": "千万", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水很深，孩子们千万不要下去玩。", "target_word": "千万", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事很重要，千万别忘了。", "target_word": "千万", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "您千万别客气，就当是自己家。", "target_word": "千万", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车的时候千万不要喝酒。", "target_word": "千万", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "千万记住，不要把门打开。", "target_word": "千万", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机丢了的话千万别着急，我们一起找。", "target_word": "千万", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "恳切叮嘱，务必、一定，多用于否定劝阻或郑重要求", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f82317-b64b-4c72-a0db-f7ebe4e148f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92076, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "千万", "is_correct": true, "explanation": "千万：副词，表示恳切叮嘱，此句提醒对方明天开会一定不要迟到。"}, {"text": "曾经", "is_correct": false, "explanation": "体貌：“曾经”表示过去发生过，与“明天”这一将来时间冲突。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：“竟然”表示出乎意料，开会不迟到是正常要求，不该用“竟然”。"}, {"text": "不断", "is_correct": false, "explanation": "语义：“不断”表示持续进行，与只发生一次的开会时间不合。"}], "explanations": {"千万": "千万：副词，表示恳切叮嘱，此句提醒对方明天开会一定不要迟到。", "曾经": "体貌：“曾经”表示过去发生过，与“明天”这一将来时间冲突。", "竟然": "语义：“竟然”表示出乎意料，开会不迟到是正常要求，不该用“竟然”。", "不断": "语义：“不断”表示持续进行，与只发生一次的开会时间不合。"}, "sentence_index": 0, "correct_answer": "千万"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个节目千万有趣。", "explanation": "这里应该用〈非常〉。千万只用于叮嘱，不表示程度，不能修饰“有趣”。"}, {"text": "这家店的东西千万便宜。", "explanation": "这里应该用〈特别〉。千万只用于叮嘱，不表示形容词的程度。"}, {"text": "这件事我千万解决了。", "explanation": "这里应该用〈已经〉。千万表示叮嘱，不能与表示完成的“了”连用，也不用来陈述已经发生的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92076, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "千万", "is_correct": true, "explanation": "千万：副词，表示恳切叮嘱，此句劝对方不要客气。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：“偏偏”表示故意与事理相反，与“就当是自己家”的劝慰语境不合。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：“已经”表示动作已经完成，与叮嘱对方不要客气的语气不合。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”用于陈述一贯的情况，不与表示劝阻的“别”搭配。"}], "explanations": {"千万": "千万：副词，表示恳切叮嘱，此句劝对方不要客气。", "偏偏": "语义：“偏偏”表示故意与事理相反，与“就当是自己家”的劝慰语境不合。", "已经": "体貌：“已经”表示动作已经完成，与叮嘱对方不要客气的语气不合。", "从来": "搭配：“从来”用于陈述一贯的情况，不与表示劝阻的“别”搭配。"}, "sentence_index": 6, "correct_answer": "千万"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛我们千万会赢。", "explanation": "这里应该用〈必定〉。千万表示叮嘱，不用来对结果作判断。"}, {"text": "明天千万会下雨。", "explanation": "这里应该用〈肯定〉。千万只用于叮嘱对方，不用于预测天气。"}, {"text": "他千万能通过考试。", "explanation": "这里应该用〈一定〉。千万不用来陈述或推测某人将要做到的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92076, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "千万了不要靠近那条河。", "corrected_sentence": "千万不要靠近那条河。", "error_description": "错误：“千万”后多加了“了”。“千万”是副词，不能与表示完成的“了”连用。正确：“千万不要靠近那条河”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92076, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这段路很滑，你很千万要慢点走。", "corrected_sentence": "这段路很滑，你千万要慢点走。", "error_description": "错误：“千万”是副词，前面不能再加副词“很”。正确：“你千万要慢点走”，“很”只用在“很滑”里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
