INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92078, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "超出规定或正常数量地。", "primary_collocate": null, "pronunciation": "é wài", "ipa": "ɤ˧˥ wai˥˩", "syllable_count": 2, "sentences": [{"text": "在这家酒店住，不用额外付钱。", "target_word": "额外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板额外给了他一千块钱奖金。", "target_word": "额外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个活动要额外收费吗？", "target_word": "额外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我常常额外加班。", "target_word": "额外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为他工作努力，公司额外奖励了他。", "target_word": "额外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "寄大箱子要额外交十块钱。", "target_word": "额外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈额外给了我一些零花钱。", "target_word": "额外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超过一百斤的行李要额外收钱。", "target_word": "额外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道菜加肉的话，需要额外花钱。", "target_word": "额外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天额外练习半小时。", "target_word": "额外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "額外", "label": "繁体"}], "register": "中性", "sense_fingerprint": "超出规定或正常数量地（修饰动词，如额外收费）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a182e01-4fd0-41b9-afec-41667e58b233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92078, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "额外", "is_correct": true, "explanation": "正确：副词“额外”表示超出正常的收费，“不用额外付钱”即不用多付。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”表示事情忽然发生，与“不用付钱”的预先安排不合。"}, {"text": "极力", "is_correct": false, "explanation": "搭配：“极力”修饰争取、阻止之类的行为，不修饰付钱。"}, {"text": "偷偷", "is_correct": false, "explanation": "语义：“偷偷”表示暗中做，与酒店公开收费的语境不合。"}], "explanations": {"额外": "正确：副词“额外”表示超出正常的收费，“不用额外付钱”即不用多付。", "突然": "语义：“突然”表示事情忽然发生，与“不用付钱”的预先安排不合。", "极力": "搭配：“极力”修饰争取、阻止之类的行为，不修饰付钱。", "偷偷": "语义：“偷偷”表示暗中做，与酒店公开收费的语境不合。"}, "sentence_index": 0, "correct_answer": "额外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台发动机的额外功率是五千瓦。", "explanation": "这里应该用〈额定〉。“额定”指机器规定的标准数值，“额外”表示超出的部分，不能说“额外功率”。"}, {"text": "我们换个额外的地方聚会。", "explanation": "这里应该用〈另外〉。此处“额外的”是形容词，表示“另外多出来的”，不是本题的副词义“超出正常数量地”；换地方应说“另外”。"}, {"text": "我们先额外住在这儿。", "explanation": "这里应该用〈暂时〉。“额外”表示超出规定或正常的数量，不表示短期、临时，“额外住”不是这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '170d71e0-dc2a-4314-bfe2-fb919f6a46ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92078, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "额外", "is_correct": true, "explanation": "正确：副词“额外”表示超出正常的数量，与“给了我”相合。"}, {"text": "将", "is_correct": false, "explanation": "语义：“将”表示将来，与“给了”的已然事件相矛盾。"}, {"text": "极力", "is_correct": false, "explanation": "搭配：“极力”修饰努力、争取类的行为，不修饰给予。"}, {"text": "兀自", "is_correct": false, "explanation": "语域：“兀自”是书面语，口语中说妈妈给我钱不用此词。"}], "explanations": {"额外": "正确：副词“额外”表示超出正常的数量，与“给了我”相合。", "将": "语义：“将”表示将来，与“给了”的已然事件相矛盾。", "极力": "搭配：“极力”修饰努力、争取类的行为，不修饰给予。", "兀自": "语域：“兀自”是书面语，口语中说妈妈给我钱不用此词。"}, "sentence_index": 6, "correct_answer": "额外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道题额外难。", "explanation": "这里应该用〈特别〉。“额外”表示超出正常的量，不表示程度，不能说“额外难”。"}, {"text": "他收到礼物后额外地高兴。", "explanation": "这里应该用〈非常〉。“额外”表示超出规定或正常的数量，不用来形容心理状态，应说“非常高兴”。"}, {"text": "他额外迟到了。", "explanation": "这里应该用〈总是〉。“额外”表示超出正常的量，不表示经常、每次都发生，不能说“额外迟到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '170d71e0-dc2a-4314-bfe2-fb919f6a46ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92078, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司额外的支付了三天的工资。", "corrected_sentence": "公司额外支付了三天的工资。", "error_description": "“额外”作状语修饰动词时后面不加“的”，应为“额外支付”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '170d71e0-dc2a-4314-bfe2-fb919f6a46ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92078, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很额外买了两本书。", "corrected_sentence": "他额外买了两本书。", "error_description": "“额外”作状语表示超出正常的数量，修饰动词时不能受“很”修饰，应删去“很”。正确的说法是“他额外买了两本书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '170d71e0-dc2a-4314-bfe2-fb919f6a46ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
