INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92081, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "放在菜里，吃起来咸咸的白色小颗粒。", "primary_collocate": null, "pronunciation": "yán", "ipa": "jɛn˧˥", "syllable_count": 1, "sentences": [{"text": "菜里没有放盐，不好吃。", "target_word": "盐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把盐递给我。", "target_word": "盐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在汤里放了一勺盐。", "target_word": "盐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的盐快用完了。", "target_word": "盐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道菜的盐放多了，太咸了。", "target_word": "盐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有盐，也有糖。", "target_word": "盐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天早上在鸡蛋上放一点盐。", "target_word": "盐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里的盐很便宜。", "target_word": "盐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去买一包盐回来。", "target_word": "盐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盐放得太少，菜没有味道。", "target_word": "盐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "勺", "label": "量词"}, {"form": "包", "label": "量词"}, {"form": "食盐", "label": "复合"}, {"form": "海盐", "label": "复合"}, {"form": "盐水", "label": "复合"}, {"form": "鹽", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做菜时放的调味品，咸味的白色小颗粒", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cddba94b-849b-43a8-83ea-95234c1a7ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92081, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "盐", "is_correct": true, "explanation": "正确答案。盐（yán）指放在菜里、吃起来咸咸的白色小颗粒。"}, {"text": "眼", "is_correct": false, "explanation": "yǎn（第三声）与 yán（第二声）声调不同，意思是眼睛。"}, {"text": "烟", "is_correct": false, "explanation": "yān（第一声）与 yán（第二声）声调不同，意思是烟雾。"}, {"text": "羊", "is_correct": false, "explanation": "yáng 与 yán 韵母不同（-ang 与 -an），意思是羊。"}, {"text": "圆", "is_correct": false, "explanation": "yuán 与 yán 韵母不同（-uan 与 -an），意思是圆。"}, {"text": "宴", "is_correct": false, "explanation": "yàn（第四声）与 yán（第二声）声调不同，意思是宴会。"}], "explanations": {"盐": "正确答案。盐（yán）指放在菜里、吃起来咸咸的白色小颗粒。", "眼": "yǎn（第三声）与 yán（第二声）声调不同，意思是眼睛。", "烟": "yān（第一声）与 yán（第二声）声调不同，意思是烟雾。", "羊": "yáng 与 yán 韵母不同（-ang 与 -an），意思是羊。", "圆": "yuán 与 yán 韵母不同（-uan 与 -an），意思是圆。", "宴": "yàn（第四声）与 yán（第二声）声调不同，意思是宴会。"}, "sentence_index": null, "correct_answer": "盐"}, "level_3": {"options": [{"text": "盐", "is_correct": true, "explanation": "正确答案。“菜里没有放盐”指菜里缺少调味料，所以不好吃。"}, {"text": "肥皂", "is_correct": false, "explanation": "语义：肥皂不能放进菜里调味，与“不好吃”的语境不合。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不是调料，放进菜里不合理。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“放”后面接的应是可以放进菜里的东西，“雨”不能被“放”进菜里。"}], "explanations": {"盐": "正确答案。“菜里没有放盐”指菜里缺少调味料，所以不好吃。", "肥皂": "语义：肥皂不能放进菜里调味，与“不好吃”的语境不合。", "书": "语义：书不是调料，放进菜里不合理。", "雨": "搭配：“放”后面接的应是可以放进菜里的东西，“雨”不能被“放”进菜里。"}, "sentence_index": 0, "correct_answer": "盐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯咖啡要放两勺盐。", "explanation": "这里应该用〈糖〉。咖啡要加的是甜味，盐是咸的，不能用来给咖啡调甜味。"}, {"text": "这道鱼要放两勺盐，才够酸。", "explanation": "这里应该用〈醋〉。盐只带来咸味，要让菜变酸应该用醋。"}, {"text": "我口渴了，想喝一杯盐。", "explanation": "这里应该用〈水〉。盐是调味的颗粒，不能直接喝一杯，口渴要喝水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92081, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "盐", "is_correct": true, "explanation": "正确答案。盐（yán）指放在菜里、吃起来咸咸的白色小颗粒。"}, {"text": "演", "is_correct": false, "explanation": "yǎn（第三声）与 yán（第二声）声调不同，意思是表演。"}, {"text": "洋", "is_correct": false, "explanation": "yáng 与 yán 韵母不同（-ang 与 -an），意思是海洋。"}, {"text": "元", "is_correct": false, "explanation": "yuán 与 yán 韵母不同（-uan 与 -an），意思是货币单位“元”。"}, {"text": "燕", "is_correct": false, "explanation": "yàn（第四声）与 yán（第二声）声调不同，意思是燕子。"}], "explanations": {"盐": "正确答案。盐（yán）指放在菜里、吃起来咸咸的白色小颗粒。", "演": "yǎn（第三声）与 yán（第二声）声调不同，意思是表演。", "洋": "yáng 与 yán 韵母不同（-ang 与 -an），意思是海洋。", "元": "yuán 与 yán 韵母不同（-uan 与 -an），意思是货币单位“元”。", "燕": "yàn（第四声）与 yán（第二声）声调不同，意思是燕子。"}, "sentence_index": null, "correct_answer": "盐"}, "level_3": {"options": [{"text": "盐", "is_correct": true, "explanation": "正确答案。“在鸡蛋上放一点盐”是常见的调味做法。"}, {"text": "钉子", "is_correct": false, "explanation": "搭配：“放一点”后接的应是调味料或食材，“钉子”不能用“一点”来计量着放在食物上。"}, {"text": "布", "is_correct": false, "explanation": "语义：布不能放在鸡蛋上吃，与早上吃鸡蛋的语境不合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能放在鸡蛋上吃，与“早上”吃早饭的场景不合。"}], "explanations": {"盐": "正确答案。“在鸡蛋上放一点盐”是常见的调味做法。", "钉子": "搭配：“放一点”后接的应是调味料或食材，“钉子”不能用“一点”来计量着放在食物上。", "布": "语义：布不能放在鸡蛋上吃，与早上吃鸡蛋的语境不合。", "石头": "语义：石头不能放在鸡蛋上吃，与“早上”吃早饭的场景不合。"}, "sentence_index": 6, "correct_answer": "盐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我洗手的时候，用了一点盐，手很干净。", "explanation": "这里应该用〈肥皂〉。盐是做菜用的调味品，洗手要用肥皂。"}, {"text": "炒肉的时候，加一勺盐，颜色会更深。", "explanation": "这里应该用〈酱油〉。盐是白色的，不能让菜的颜色变深，酱油才可以。"}, {"text": "这种盐每天喝两杯，对身体好。", "explanation": "这里应该用〈饮料〉。盐是调味品，要放进菜里，不能当饮料来“喝”；“喝两杯”的对象应是饮料，不是盐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92081, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了三只盐。", "corrected_sentence": "我买了三包盐。", "error_description": "量词错误：盐要用“包”计量，“只”用于动物或单件物品。错误形式是“三只盐”，正确形式是“三包盐”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92081, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在超市买了两条盐。", "corrected_sentence": "我在超市买了两包盐。", "error_description": "量词错误：盐要用“包”计量，“条”用于细长的东西。错误形式是“两条盐”，正确形式是“两包盐”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
