INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92082, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有咸味的白色晶体，用来调味和腌制食物。", "primary_collocate": null, "pronunciation": "yán", "ipa": "jɛn˧˥", "syllable_count": 1, "sentences": [{"text": "奶奶用盐腌了很多鱼。", "target_word": "盐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海水晒干以后就能得到盐。", "target_word": "盐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盐可以让肉放得更久。", "target_word": "盐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的盐是从大海里来的。", "target_word": "盐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天要用盐腌菜。", "target_word": "盐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盐是白色的，像小小的石头。", "target_word": "盐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在海边晒盐。", "target_word": "盐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用盐腌肉，也用盐做菜。", "target_word": "盐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种盐很细，用来调味最好。", "target_word": "盐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "腌肉的时候，盐不能放得太少。", "target_word": "盐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "勺", "label": "量词"}, {"form": "包", "label": "量词"}, {"form": "食盐", "label": "复合"}, {"form": "海盐", "label": "复合"}, {"form": "盐水", "label": "复合"}, {"form": "鹽", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有咸味的白色晶体，来自海水或盐湖，可调味、腌制", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cddba94b-849b-43a8-83ea-95234c1a7ee5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92082, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "盐", "is_correct": true, "explanation": "正确答案。盐（yán）指有咸味、可调味和腌制食物的白色晶体。"}, {"text": "眼", "is_correct": false, "explanation": "yǎn（第三声）与 yán（第二声）声调不同，意思是眼睛。"}, {"text": "烟", "is_correct": false, "explanation": "yān（第一声）与 yán（第二声）声调不同，意思是烟雾。"}, {"text": "羊", "is_correct": false, "explanation": "yáng 与 yán 韵母不同（-ang 与 -an），意思是羊。"}, {"text": "圆", "is_correct": false, "explanation": "yuán 与 yán 韵母不同（-uan 与 -an），意思是圆。"}, {"text": "宴", "is_correct": false, "explanation": "yàn（第四声）与 yán（第二声）声调不同，意思是宴会。"}], "explanations": {"盐": "正确答案。盐（yán）指有咸味、可调味和腌制食物的白色晶体。", "眼": "yǎn（第三声）与 yán（第二声）声调不同，意思是眼睛。", "烟": "yān（第一声）与 yán（第二声）声调不同，意思是烟雾。", "羊": "yáng 与 yán 韵母不同（-ang 与 -an），意思是羊。", "圆": "yuán 与 yán 韵母不同（-uan 与 -an），意思是圆。", "宴": "yàn（第四声）与 yán（第二声）声调不同，意思是宴会。"}, "sentence_index": null, "correct_answer": "盐"}, "level_3": {"options": [{"text": "盐", "is_correct": true, "explanation": "正确答案。腌鱼要用盐，“奶奶用盐腌了很多鱼”是常见的说法。"}, {"text": "纸", "is_correct": false, "explanation": "语义：纸不能用来腌鱼，腌制需要调味料。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能用来腌鱼，与“腌了很多鱼”的语境不合。"}, {"text": "汽油", "is_correct": false, "explanation": "搭配：“腌”用的材料应是可食用的盐、糖等，汽油不能用于腌制。"}], "explanations": {"盐": "正确答案。腌鱼要用盐，“奶奶用盐腌了很多鱼”是常见的说法。", "纸": "语义：纸不能用来腌鱼，腌制需要调味料。", "石头": "语义：石头不能用来腌鱼，与“腌了很多鱼”的语境不合。", "汽油": "搭配：“腌”用的材料应是可食用的盐、糖等，汽油不能用于腌制。"}, "sentence_index": 0, "correct_answer": "盐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天黑了，请把盐打开。", "explanation": "这里应该用〈灯〉。盐是调味和腌制用的白色晶体，不能“打开”来照明，应该开灯。"}, {"text": "这碗汤的盐太酸了。", "explanation": "这里应该用〈醋〉。盐是咸的，不会酸，形容酸味要用“醋”。"}, {"text": "这个蛋糕放了很多盐，甜极了。", "explanation": "这里应该用〈糖〉。盐是咸的，不能使食物变甜，甜味要用糖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92082, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "盐", "is_correct": true, "explanation": "正确答案。盐（yán）指有咸味、可调味和腌制食物的白色晶体。"}, {"text": "演", "is_correct": false, "explanation": "yǎn（第三声）与 yán（第二声）声调不同，意思是表演。"}, {"text": "洋", "is_correct": false, "explanation": "yáng 与 yán 韵母不同（-ang 与 -an），意思是海洋。"}, {"text": "元", "is_correct": false, "explanation": "yuán 与 yán 韵母不同（-uan 与 -an），意思是货币单位“元”。"}, {"text": "燕", "is_correct": false, "explanation": "yàn（第四声）与 yán（第二声）声调不同，意思是燕子。"}], "explanations": {"盐": "正确答案。盐（yán）指有咸味、可调味和腌制食物的白色晶体。", "演": "yǎn（第三声）与 yán（第二声）声调不同，意思是表演。", "洋": "yáng 与 yán 韵母不同（-ang 与 -an），意思是海洋。", "元": "yuán 与 yán 韵母不同（-uan 与 -an），意思是货币单位“元”。", "燕": "yàn（第四声）与 yán（第二声）声调不同，意思是燕子。"}, "sentence_index": null, "correct_answer": "盐"}, "level_3": {"options": [{"text": "盐", "is_correct": true, "explanation": "正确答案。海边的晒盐场景中，人们晒的是盐。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不能在海边晒，与“晒盐”的场景不合。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不是晒在海边的东西，与“晒”的语境不合。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“晒”一般用于可以摊开的东西，“冰箱”不能拿来晒。"}], "explanations": {"盐": "正确答案。海边的晒盐场景中，人们晒的是盐。", "钥匙": "语义：钥匙不能在海边晒，与“晒盐”的场景不合。", "电脑": "语义：电脑不是晒在海边的东西，与“晒”的语境不合。", "冰箱": "搭配：“晒”一般用于可以摊开的东西，“冰箱”不能拿来晒。"}, "sentence_index": 6, "correct_answer": "盐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个汤的盐很鲜，放一点就行。", "explanation": "这里应该用〈味精〉。盐只有咸味，没有鲜味，鲜味要用味精。"}, {"text": "这锅肉的盐放多了，肉吃起来又辣又麻。", "explanation": "这里应该用〈辣椒〉。盐只有咸味，不会让菜变辣或变麻，辣味要用辣椒。"}, {"text": "这种盐每天要喝两杯。", "explanation": "这里应该用〈饮料〉。盐是调味品，要放进菜里，不能当饮料来“喝”；“喝两杯”的对象应是饮料，不是盐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92082, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只盐白白的，很像小石头。", "corrected_sentence": "这块盐白白的，很像小石头。", "error_description": "量词错误：成块的盐应用“块”，“只”用于动物或单件物品。错误形式是“这只盐”，正确形式是“这块盐”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92082, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈每年都盐来腌咸菜。", "corrected_sentence": "妈妈每年都用盐来腌咸菜。", "error_description": "缺少介词“用”：“盐”作工具时前面要加“用”，应说“用盐来腌咸菜”，不能说“盐来腌咸菜”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7361ef9-72db-4a51-8312-f52136ad4158') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92083, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "服从", "is_correct": true, "explanation": "服从：听从、不对抗，与“反抗”的意思相对。"}, {"text": "欣赏", "is_correct": false, "explanation": "欣赏：表示认为好而喜爱，与“反抗”没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "思考：表示用脑子考虑问题，与“反抗”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步：表示随意走动，与“反抗”没有反义关系。"}], "correct_answer": "服从", "explanations": {"服从": "服从：听从、不对抗，与“反抗”的意思相对。", "欣赏": "欣赏：表示认为好而喜爱，与“反抗”没有反义关系。", "思考": "思考：表示用脑子考虑问题，与“反抗”没有反义关系。", "散步": "散步：表示随意走动，与“反抗”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92083, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "服从", "is_correct": true, "explanation": "服从：听从、不对抗，与“反抗”的意思相对。"}, {"text": "学习", "is_correct": false, "explanation": "学习：表示获得知识或技能，与“反抗”没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行：表示到外地游览，与“反抗”没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌：表示用声音表达曲调，与“反抗”没有反义关系。"}], "correct_answer": "服从", "explanations": {"服从": "服从：听从、不对抗，与“反抗”的意思相对。", "学习": "学习：表示获得知识或技能，与“反抗”没有反义关系。", "旅行": "旅行：表示到外地游览，与“反抗”没有反义关系。", "唱歌": "唱歌：表示用声音表达曲调，与“反抗”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92083, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "反抗是别人欺负你，你不听，还要对着干。", "primary_collocate": null, "pronunciation": "fǎn kàng", "ipa": "fan˨˩ kʰɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "同学总欺负他，他不再忍了，开始反抗。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥打我，我大声反抗。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板总是骂他，他终于反抗了。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人欺负你，你要敢于反抗。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟太小，不会反抗大孩子。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从来不反抗，所以总有人欺负她。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们欺负新同学，新同学反抗过。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起反抗，坏人就不敢欺负了。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人抢他的书包，他用力反抗。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直忍着，没有反抗。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反抗了", "label": "体标"}, {"form": "反抗过", "label": "体标"}, {"form": "反抗着", "label": "体标"}], "register": "中性", "sense_fingerprint": "被人欺负时不服从并对着干", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b94b613-bc01-4765-9f44-061a986e4dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92083, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反抗", "is_correct": true, "explanation": "句中“欺负他”的人让他“不再忍了”，“反抗”指对欺负进行对抗，符合语境。"}, {"text": "忍耐", "is_correct": false, "explanation": "语义：“忍耐”是克制、不发作，与“他不再忍了”的句意相矛盾。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”表示谢意，被人欺负时不会去感谢，与语境不符。"}, {"text": "妥协", "is_correct": false, "explanation": "语义：“妥协”是让步，与“他不再忍了”的态度相矛盾。"}], "explanations": {"反抗": "句中“欺负他”的人让他“不再忍了”，“反抗”指对欺负进行对抗，符合语境。", "忍耐": "语义：“忍耐”是克制、不发作，与“他不再忍了”的句意相矛盾。", "感谢": "语义：“感谢”表示谢意，被人欺负时不会去感谢，与语境不符。", "妥协": "语义：“妥协”是让步，与“他不再忍了”的态度相矛盾。"}, "sentence_index": 0, "correct_answer": "反抗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用力反抗寒冷。", "explanation": "这里应该用〈抵抗〉。反抗针对压迫或欺凌的人和事，抵御寒冷、疾病等要用抵抗。"}, {"text": "他反抗了老师的邀请。", "explanation": "这里应该用〈拒绝〉。反抗指用行动对抗压迫，对邀请表示不接受要用拒绝。"}, {"text": "他反抗了我的观点。", "explanation": "这里应该用〈反驳〉。反抗指对压迫或欺凌进行对抗，对别人的观点提出不同意见要用反驳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92083, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反抗", "is_correct": true, "explanation": "句中“他们欺负新同学”，“新同学反抗过”指新同学对欺负进行过对抗，符合语境。"}, {"text": "关心", "is_correct": false, "explanation": "语义：“关心”是照顾、挂念，与“他们欺负新同学”的语境相反。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：“迟到”指未按时到达，与“他们欺负新同学”的语境无关，不能表示新同学的反应。"}, {"text": "感激", "is_correct": false, "explanation": "语义：“感激”表示感谢，与被欺负的语境不符，不能表示新同学的反应。"}], "explanations": {"反抗": "句中“他们欺负新同学”，“新同学反抗过”指新同学对欺负进行过对抗，符合语境。", "关心": "语义：“关心”是照顾、挂念，与“他们欺负新同学”的语境相反。", "迟到": "语义：“迟到”指未按时到达，与“他们欺负新同学”的语境无关，不能表示新同学的反应。", "感激": "语义：“感激”表示感谢，与被欺负的语境不符，不能表示新同学的反应。"}, "sentence_index": 6, "correct_answer": "反抗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他反抗了朋友送的生日礼物。", "explanation": "这里应该用〈收下〉。反抗针对压迫或欺凌，对朋友的好意表示接受要用收下，不能说反抗。"}, {"text": "他每天都反抗工作的辛苦。", "explanation": "这里应该用〈抱怨〉。反抗指对压迫进行对抗，对工作辛苦表示不满要用抱怨。"}, {"text": "他深刻地反抗了自己的错误。", "explanation": "这里应该用〈反省〉。反抗的对象是压迫或不公平的事，检查自己的错误要用反省。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92083, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他反抗地很勇敢，大家都佩服他。", "corrected_sentence": "他反抗得很勇敢，大家都佩服他。", "error_description": "错误：“反抗地很勇敢”。正确：“反抗得很勇敢”。补语标记应用“得”，不能用“地”，“地”只用于动词前的修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92083, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新同学以前常常受欺负，却从来没有反抗过了。", "corrected_sentence": "新同学以前常常受欺负，却从来没有反抗过。", "error_description": "错误：“没有反抗过了”。正确：“没有反抗过”。表示否定经历时，“过”后不加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92084, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "服从", "is_correct": true, "explanation": "服从：听从、不对抗，与“反抗”的意思相对。"}, {"text": "写作", "is_correct": false, "explanation": "写作：表示写文章，与“反抗”没有反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳：表示在水中运动，与“反抗”没有反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "观察：表示仔细看、研究，与“反抗”没有反义关系。"}], "correct_answer": "服从", "explanations": {"服从": "服从：听从、不对抗，与“反抗”的意思相对。", "写作": "写作：表示写文章，与“反抗”没有反义关系。", "游泳": "游泳：表示在水中运动，与“反抗”没有反义关系。", "观察": "观察：表示仔细看、研究，与“反抗”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92084, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "服从", "is_correct": true, "explanation": "服从：听从、不对抗，与“反抗”的意思相对。"}, {"text": "拍照", "is_correct": false, "explanation": "拍照：表示用相机记录影像，与“反抗”没有反义关系。"}, {"text": "跳舞", "is_correct": false, "explanation": "跳舞：表示随音乐做动作，与“反抗”没有反义关系。"}, {"text": "收集", "is_correct": false, "explanation": "收集：表示把分散的东西聚在一起，与“反抗”没有反义关系。"}], "correct_answer": "服从", "explanations": {"服从": "服从：听从、不对抗，与“反抗”的意思相对。", "拍照": "拍照：表示用相机记录影像，与“反抗”没有反义关系。", "跳舞": "跳舞：表示随音乐做动作，与“反抗”没有反义关系。", "收集": "收集：表示把分散的东西聚在一起，与“反抗”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92084, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用行动抵抗压迫、欺凌或不合理的事物。", "primary_collocate": null, "pronunciation": "fǎn kàng", "ipa": "fan˨˩ kʰɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "人民起来反抗不合理的制度。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们反抗老板降低工资。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民反抗不合理的税。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用行动反抗不公平的规定。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奴隶们反抗主人的压迫。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们一起反抗学校的坏规定。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的人民反抗了外国的统治。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们不怕危险，勇敢地反抗压迫。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民们反抗着不合理的收费。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了自由，人们一直在反抗。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反抗了", "label": "体标"}, {"form": "反抗过", "label": "体标"}, {"form": "反抗着", "label": "体标"}], "register": "中性", "sense_fingerprint": "用行动抵抗压迫或不合理的制度和规定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b94b613-bc01-4765-9f44-061a986e4dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92084, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反抗", "is_correct": true, "explanation": "句中“不合理的制度”是被反对的对象，“人民起来反抗”符合语境。"}, {"text": "支持", "is_correct": false, "explanation": "语义：“支持”表示赞成、维护，与“起来”和“不合理”的语境相矛盾。"}, {"text": "抵达", "is_correct": false, "explanation": "配价：“抵达”后接地点，不能接“制度”作宾语。"}, {"text": "歌颂", "is_correct": false, "explanation": "语义：“歌颂”表示赞美，与批评“不合理的制度”的语境相反。"}], "explanations": {"反抗": "句中“不合理的制度”是被反对的对象，“人民起来反抗”符合语境。", "支持": "语义：“支持”表示赞成、维护，与“起来”和“不合理”的语境相矛盾。", "抵达": "配价：“抵达”后接地点，不能接“制度”作宾语。", "歌颂": "语义：“歌颂”表示赞美，与批评“不合理的制度”的语境相反。"}, "sentence_index": 0, "correct_answer": "反抗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们反抗了美味的晚饭。", "explanation": "这里应该用〈享用〉。反抗指对压迫或不合理的事物进行对抗，享受美味的饭菜要用享用。"}, {"text": "他反抗了世界纪录。", "explanation": "这里应该用〈挑战〉。反抗指对压迫或不合理的事物进行对抗，向纪录发起冲击要用挑战。"}, {"text": "大家反抗老人。", "explanation": "这里应该用〈尊重〉。反抗指对压迫或不合理的事物进行对抗，对老人应该表示尊重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92084, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反抗", "is_correct": true, "explanation": "句中“外国的统治”是被对抗的对象，“人民反抗了统治”符合语境。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”表示乐于接受，与人民对外国统治的对抗相反。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”多用于场所、展览，不能接“统治”作宾语。"}, {"text": "提倡", "is_correct": false, "explanation": "语义：“提倡”表示主张推行，与“反抗外国的统治”的意思相反。"}], "explanations": {"反抗": "句中“外国的统治”是被对抗的对象，“人民反抗了统治”符合语境。", "欢迎": "语义：“欢迎”表示乐于接受，与人民对外国统治的对抗相反。", "参观": "搭配：“参观”多用于场所、展览，不能接“统治”作宾语。", "提倡": "语义：“提倡”表示主张推行，与“反抗外国的统治”的意思相反。"}, "sentence_index": 6, "correct_answer": "反抗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他经常反抗自己的错误。", "explanation": "这里应该用〈反省〉。反抗针对压迫或不合理的事物，检查自己的错误要用反省。"}, {"text": "他反抗了对方的说法。", "explanation": "这里应该用〈反驳〉。反抗指对压迫或不合理的事物进行对抗，对别人的说法提出不同意见要用反驳。"}, {"text": "我们反抗老师的帮助。", "explanation": "这里应该用〈感激〉。反抗指对压迫进行对抗，接受别人的帮助并表示谢意要用感激。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92084, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们曾经反抗地很坚决，后来失败了。", "corrected_sentence": "他们曾经反抗得很坚决，后来失败了。", "error_description": "错误：“反抗地很坚决”。正确：“反抗得很坚决”。补语标记应用“得”，不能用“地”，“地”只用于动词前的修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92084, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们正在反抗了不公平的待遇。", "corrected_sentence": "工人们正在反抗不公平的待遇。", "error_description": "错误：“正在反抗了”。正确：“正在反抗”。“正在”表示动作进行，与表示完成的“了”不能同用，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
