INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92085, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "第三个等级。", "primary_collocate": null, "pronunciation": "sān jí", "ipa": "san˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "我通过了汉语考试三级。", "target_word": "三级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学钢琴，今年考过了三级。", "target_word": "三级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏已经玩到三级了。", "target_word": "三级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一级太容易，我想从三级开始学。", "target_word": "三级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书一共分五级，我看的是三级。", "target_word": "三级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的汉语水平是三级，能看简单的书。", "target_word": "三级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛分一级到五级，她拿到了三级。", "target_word": "三级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开始是一级，现在已经升到三级了。", "target_word": "三级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我的画画水平只有三级。", "target_word": "三级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟的游泳考试得了三级。", "target_word": "三级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "三級", "label": "繁体"}], "register": "中性", "sense_fingerprint": "考试、课程或游戏中的第三个等级", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b7baea-ca68-407f-84e5-c669a1b09102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92085, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "三级", "is_correct": true, "explanation": "正确答案。三级（sān jí）指第三个等级。"}, {"text": "三季", "is_correct": false, "explanation": "三季（sān jì）：jì（第四声）与 jí（第二声）声调不同，意思是三个季节。"}, {"text": "散记", "is_correct": false, "explanation": "散记（sǎn jì）：声调不同（sǎn/sān，jì/jí），意思是零散的记录。"}, {"text": "三基", "is_correct": false, "explanation": "三基（sān jī）：jī（第一声）与 jí（第二声）声调不同，意思是基础理论、基本知识、基本技能。"}], "explanations": {"三级": "正确答案。三级（sān jí）指第三个等级。", "三季": "三季（sān jì）：jì（第四声）与 jí（第二声）声调不同，意思是三个季节。", "散记": "散记（sǎn jì）：声调不同（sǎn/sān，jì/jí），意思是零散的记录。", "三基": "三基（sān jī）：jī（第一声）与 jí（第二声）声调不同，意思是基础理论、基本知识、基本技能。"}, "sentence_index": null, "correct_answer": "三级"}, "level_3": {"options": [{"text": "三级", "is_correct": true, "explanation": "正确。「通过了」后面接考试等级，「三级」指第三个等级，符合句意。"}, {"text": "满分", "is_correct": false, "explanation": "搭配：「通过」接考试或测验，不接分数，「通过了满分」不能这样说。"}, {"text": "汉语", "is_correct": false, "explanation": "语义：汉语是语言，不是可以通过的考试或等级，句子不通。"}, {"text": "草稿", "is_correct": false, "explanation": "语义：草稿是未定稿的文字，不是考试或等级，不能「通过」。"}], "explanations": {"三级": "正确。「通过了」后面接考试等级，「三级」指第三个等级，符合句意。", "满分": "搭配：「通过」接考试或测验，不接分数，「通过了满分」不能这样说。", "汉语": "语义：汉语是语言，不是可以通过的考试或等级，句子不通。", "草稿": "语义：草稿是未定稿的文字，不是考试或等级，不能「通过」。"}, "sentence_index": 0, "correct_answer": "三级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在汉语比赛中得了三级奖。", "explanation": "这里应该用〈三等〉。奖项的名次要说“三等奖”，“三级”指等级，不能用于奖项名次。"}, {"text": "我妹妹今年在三级读书。", "explanation": "这里应该用〈三年级〉。学校的年级说“三年级”，“三级”不用于学校年级。"}, {"text": "这座楼的门牌号是三级。", "explanation": "这里应该用〈三号〉。门牌号要说“三号”，“三级”不表示编号。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92085, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "三级", "is_correct": true, "explanation": "正确。「拿到了」后接可以获得的等级，「三级」符合句意。"}, {"text": "比赛", "is_correct": false, "explanation": "语义：比赛是活动，不是可以拿到的等级。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：「拿到」说获得成绩或奖项，不能说体重。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情是情绪，不是可以拿到的等级。"}], "explanations": {"三级": "正确。「拿到了」后接可以获得的等级，「三级」符合句意。", "比赛": "语义：比赛是活动，不是可以拿到的等级。", "体重": "搭配：「拿到」说获得成绩或奖项，不能说体重。", "心情": "语义：心情是情绪，不是可以拿到的等级。"}, "sentence_index": 6, "correct_answer": "三级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "在这次比赛中，他排在三级。", "explanation": "这里应该用〈第三名〉。名次要说“第三名”，“三级”指等级，不表示名次。"}, {"text": "这种花有三级颜色，很漂亮。", "explanation": "这里应该用〈三种〉。颜色的种类要说“三种”，“三级”不表示数量。"}, {"text": "这个价格涨到了原来的三级。", "explanation": "这里应该用〈三倍〉。倍数要说“三倍”，“三级”不表示倍数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92085, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐的英语考试通过着三级，很高兴。", "corrected_sentence": "我姐姐的英语考试通过了三级，很高兴。", "error_description": "错误：「通过着三级」。正确：「通过了三级」。「通过」表示一次性完成的动作，动态助词要用「了」，不用「着」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92085, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的钢琴考试考了过三级。", "corrected_sentence": "她的钢琴考试考过了三级。", "error_description": "错误：「考了过三级」。正确：「考过了三级」。动词后的「过」要紧跟动词，「了」放在「过」后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
