INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92086, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "排在第三位的等级。", "primary_collocate": null, "pronunciation": "sān jí", "ipa": "san˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "一级最好，二级次之，三级排在后面。", "target_word": "三级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些房间分一、二、三级，三级最便宜。", "target_word": "三级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "排在二级后面的就是三级。", "target_word": "三级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水果分三个等级，三级的最便宜。", "target_word": "三级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个职位属于三级，工资比二级低。", "target_word": "三级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今年升了职，从四级升到了三级。", "target_word": "三级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些鸡蛋是三级的，比一级的便宜。", "target_word": "三级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二级的东西卖完了，只剩下三级的。", "target_word": "三级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一级和二级都满了，你只能报三级。", "target_word": "三级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个制度里，三级排在一级和二级之后。", "target_word": "三级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "三級", "label": "繁体"}], "register": "中性", "sense_fingerprint": "等级顺序中排在第三位的一档", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1b7baea-ca68-407f-84e5-c669a1b09102') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92086, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "三级", "is_correct": true, "explanation": "正确答案。三级（sān jí）指排在第三位的一档。"}, {"text": "三季", "is_correct": false, "explanation": "三季（sān jì）：jì（第四声）与 jí（第二声）声调不同，意思是三个季节。"}, {"text": "三几", "is_correct": false, "explanation": "三几（sān jǐ）：jǐ（第三声）与 jí（第二声）声调不同，意思是三四个。"}, {"text": "三基", "is_correct": false, "explanation": "三基（sān jī）：jī（第一声）与 jí（第二声）声调不同，意思是基础理论、基本知识、基本技能。"}], "explanations": {"三级": "正确答案。三级（sān jí）指排在第三位的一档。", "三季": "三季（sān jì）：jì（第四声）与 jí（第二声）声调不同，意思是三个季节。", "三几": "三几（sān jǐ）：jǐ（第三声）与 jí（第二声）声调不同，意思是三四个。", "三基": "三基（sān jī）：jī（第一声）与 jí（第二声）声调不同，意思是基础理论、基本知识、基本技能。"}, "sentence_index": null, "correct_answer": "三级"}, "level_3": {"options": [{"text": "三级", "is_correct": true, "explanation": "正确。前文说「一级最好，二级次之」，「三级」是排在后面的第三档，符合句意。"}, {"text": "满分", "is_correct": false, "explanation": "语义：满分是最高分，不是排在后面的一档，与「一级最好」的次序相矛盾。"}, {"text": "草稿", "is_correct": false, "explanation": "语义：草稿是未定稿的文字，不是可以排序的等级。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：「排在后面」说的是等级或次序，体重不是可以排序的档次。"}], "explanations": {"三级": "正确。前文说「一级最好，二级次之」，「三级」是排在后面的第三档，符合句意。", "满分": "语义：满分是最高分，不是排在后面的一档，与「一级最好」的次序相矛盾。", "草稿": "语义：草稿是未定稿的文字，不是可以排序的等级。", "体重": "搭配：「排在后面」说的是等级或次序，体重不是可以排序的档次。"}, "sentence_index": 0, "correct_answer": "三级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我弟弟已经三级了，每天都在幼儿园玩。", "explanation": "这里应该用〈三岁〉。年龄要说“三岁”，“三级”不表示年龄。"}, {"text": "我们家住在三级，每天要爬楼梯。", "explanation": "这里应该用〈三楼〉。楼层要说“三楼”，“三级”不表示楼层。"}, {"text": "我家有三级卧室，每间都很大。", "explanation": "这里应该用〈三间〉。房间的数量要说“三间”，“三级”不表示数量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EX