INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92086, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "三级", "is_correct": true, "explanation": "正确。「是……的」后接鸡蛋的等级，「三级」符合句意。"}, {"text": "比赛", "is_correct": false, "explanation": "语义：比赛是活动，不是鸡蛋的等级，「这些比赛是……的」不通。"}, {"text": "汉语", "is_correct": false, "explanation": "语义：汉语是语言，不能用来给鸡蛋分等级。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：「是……的，比一级的便宜」是给商品分级的说法，不能用于体温。"}], "explanations": {"三级": "正确。「是……的」后接鸡蛋的等级，「三级」符合句意。", "比赛": "语义：比赛是活动，不是鸡蛋的等级，「这些比赛是……的」不通。", "汉语": "语义：汉语是语言，不能用来给鸡蛋分等级。", "体温": "搭配：「是……的，比一级的便宜」是给商品分级的说法，不能用于体温。"}, "sentence_index": 6, "correct_answer": "三级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他手里拿着三级铅笔，很是得意。", "explanation": "这里应该用〈三支〉。铅笔要用量词“支”，说“三支铅笔”，“三级”不表示数量。"}, {"text": "我在这里住了三级，很快就习惯了。", "explanation": "这里应该用〈三天〉。时间长度要说“住了三天”，“三级”不表示时长。"}, {"text": "我们三级人一起去爬山。", "explanation": "这里应该用〈三个人〉。人数要说“三个人”，“三级”不表示人数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92086, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些橘子被分了成三级，三级的最便宜。", "corrected_sentence": "这些橘子被分成了三级，三级的最便宜。", "error_description": "错误：「分了成三级」。正确：「分成了三级」。「了」应放在动补结构「分成」之后，不能插在动词和补语中间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92086, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年从四级升了到三级。", "corrected_sentence": "他去年从四级升到了三级。", "error_description": "错误：「升了到三级」。正确：「升到了三级」。「了」应放在动补结构「升到」之后，不能插在动词和补语中间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13da2e08-895f-43e9-917f-05cda051874e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
