INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92088, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量词，用于语言或文字的单位。", "primary_collocate": null, "pronunciation": "jù", "ipa": "tɕy˥˩", "syllable_count": 1, "sentences": [{"text": "他对我说了三句话。", "target_word": "句", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这篇文章只有五句。", "target_word": "句", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我只会说一句法语。", "target_word": "句", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她一句话也没说。", "target_word": "句", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请跟我读一句。", "target_word": "句", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这句话我听不懂。", "target_word": "句", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "电话里他只说了两句就挂了。", "target_word": "句", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板的一句话让大家都笑了。", "target_word": "句", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听了你的几句话，心里舒服多了。", "target_word": "句", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌我只记得一句。", "target_word": "句", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "用于数语言、文字的量词，如一句话、两句", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9d6783f-ace1-4265-9d14-fc3a3d5379b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92088, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "句", "is_correct": true, "explanation": "jù（第四声）即“句”，用于数语言、文字。"}, {"text": "去", "is_correct": false, "explanation": "qù 与 jù 声母不同（q/j），意思是离开、去往。"}, {"text": "序", "is_correct": false, "explanation": "xù 与 jù 声母不同（x/j），意思是次序。"}, {"text": "举", "is_correct": false, "explanation": "jǔ（第三声）与 jù（第四声）声调不同，意思是抬起。"}, {"text": "菊", "is_correct": false, "explanation": "jú（第二声）与 jù（第四声）声调不同，意思是菊花。"}, {"text": "拘", "is_correct": false, "explanation": "jū（第一声）与 jù（第四声）声调不同，意思是拘束。"}], "explanations": {"句": "jù（第四声）即“句”，用于数语言、文字。", "去": "qù 与 jù 声母不同（q/j），意思是离开、去往。", "序": "xù 与 jù 声母不同（x/j），意思是次序。", "举": "jǔ（第三声）与 jù（第四声）声调不同，意思是抬起。", "菊": "jú（第二声）与 jù（第四声）声调不同，意思是菊花。", "拘": "jū（第一声）与 jù（第四声）声调不同，意思是拘束。"}, "sentence_index": null, "correct_answer": "句"}, "level_3": {"options": [{"text": "句", "is_correct": true, "explanation": "“句”用于说出的话，“三句话”正确。"}, {"text": "篇", "is_correct": false, "explanation": "语义：“篇”指文章，这里说的是口头的话，“三篇话”不通。"}, {"text": "首", "is_correct": false, "explanation": "搭配：“首”用于诗歌、歌曲，不能说“三首话”。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”用于纸张、桌子等平面的东西，“三张话”不通。"}], "explanations": {"句": "“句”用于说出的话，“三句话”正确。", "篇": "语义：“篇”指文章，这里说的是口头的话，“三篇话”不通。", "首": "搭配：“首”用于诗歌、歌曲，不能说“三首话”。", "张": "搭配：“张”用于纸张、桌子等平面的东西，“三张话”不通。"}, "sentence_index": 0, "correct_answer": "句"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他买了一句水果，装了满满一袋。", "explanation": "这里应该用〈斤〉。“句”不能数水果，称出来的水果要用“斤”。"}, {"text": "爸爸修好了一句自行车。", "explanation": "这里应该用〈辆〉。“句”不能数自行车，自行车要用“辆”。"}, {"text": "他擦了一句窗户，很干净。", "explanation": "这里应该用〈扇〉。“句”不能数窗户，窗户要用“扇”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742aeddd-9d6f-4b00-8821-f90be4d197b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92088, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "句", "is_correct": true, "explanation": "jù（第四声）即“句”，用于数语言、文字。"}, {"text": "续", "is_correct": false, "explanation": "xù 与 jù 声母不同（x/j），意思是继续。"}, {"text": "绪", "is_correct": false, "explanation": "xù 与 jù 声母不同（x/j），意思是情绪、头绪。"}, {"text": "居", "is_correct": false, "explanation": "jū（第一声）与 jù（第四声）声调不同，意思是居住。"}, {"text": "局", "is_correct": false, "explanation": "jú（第二声）与 jù（第四声）声调不同，意思是局面、机构。"}, {"text": "橘", "is_correct": false, "explanation": "jú（第二声）与 jù（第四声）声调不同，意思是橘子。"}], "explanations": {"句": "jù（第四声）即“句”，用于数语言、文字。", "续": "xù 与 jù 声母不同（x/j），意思是继续。", "绪": "xù 与 jù 声母不同（x/j），意思是情绪、头绪。", "居": "jū（第一声）与 jù（第四声）声调不同，意思是居住。", "局": "jú（第二声）与 jù（第四声）声调不同，意思是局面、机构。", "橘": "jú（第二声）与 jù（第四声）声调不同，意思是橘子。"}, "sentence_index": null, "correct_answer": "句"}, "level_3": {"options": [{"text": "句", "is_correct": true, "explanation": "“句”用于说出的话，“说了两句”正确。"}, {"text": "幅", "is_correct": false, "explanation": "语义：“幅”用于画作、照片，不能用来数说出的话。"}, {"text": "台", "is_correct": false, "explanation": "搭配：“台”用于机器、电器，“说了两台”不通。"}, {"text": "副", "is_correct": false, "explanation": "搭配：“副”用于眼镜、扑克、对联，“说了两副”不通。"}], "explanations": {"句": "“句”用于说出的话，“说了两句”正确。", "幅": "语义：“幅”用于画作、照片，不能用来数说出的话。", "台": "搭配：“台”用于机器、电器，“说了两台”不通。", "副": "搭配：“副”用于眼镜、扑克、对联，“说了两副”不通。"}, "sentence_index": 6, "correct_answer": "句"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们买了一句衣服，送给妈妈。", "explanation": "这里应该用〈件〉。“句”不能数衣服，衣服要用“件”。"}, {"text": "这套房子里有一句卧室，很宽敞。", "explanation": "这里应该用〈间〉。“句”不能数卧室，房间要用“间”。"}, {"text": "她吃了一句面包，很饱。", "explanation": "这里应该用〈片〉。“句”不能数面包，切开的面包要用“片”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742aeddd-9d6f-4b00-8821-f90be4d197b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92088, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对我说了一个好话，我一句也没漏掉。", "corrected_sentence": "他对我说了一句好话，我一句也没漏掉。", "error_description": "错误在于量词：“好话”前应该用“句”，不能用“个”。说出的一段话要用“句”来数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742aeddd-9d6f-4b00-8821-f90be4d197b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92088, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我一句也没听漏，她说的每一都很清楚。", "corrected_sentence": "我一句也没听漏，她说的每一句都很清楚。", "error_description": "错误在于量词：“每一”后面要接量词，应说“每一句”，不能漏掉“句”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '742aeddd-9d6f-4b00-8821-f90be4d197b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
