INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92089, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "心里很在乎，认真去做。", "primary_collocate": null, "pronunciation": "shàng xīn", "ipa": "ʂɑŋ˥˩ ɕin˥", "syllable_count": 2, "sentences": [{"text": "他对工作很上心。", "target_word": "上心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈对我的学习特别上心。", "target_word": "上心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事你要上心一点。", "target_word": "上心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师对每个学生都很上心。", "target_word": "上心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做事不上心，总是出错。", "target_word": "上心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子对考试一点也不上心。", "target_word": "上心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你对朋友的事怎么这么上心？", "target_word": "上心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对这份新工作非常上心。", "target_word": "上心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要是上心，就能做好。", "target_word": "上心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸对家里的事从来不上心。", "target_word": "上心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上心了", "label": "体标"}], "register": "口语", "sense_fingerprint": "对某事心里很在乎，认真去做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a182e01-4fd0-41b9-afec-41667e58b233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92089, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上心", "is_correct": true, "explanation": "正确：上心 shàng xīn，意思是在乎、认真去做。"}, {"text": "伤心", "is_correct": false, "explanation": "伤心（shāng xīn）与上心（shàng xīn）第一个音节声调不同，意思是难过。"}, {"text": "善心", "is_correct": false, "explanation": "善心（shàn xīn）与上心（shàng xīn）第一个音节韵母不同（an 与 ang），意思是善良的心。"}, {"text": "上星", "is_correct": false, "explanation": "上星（shàng xīng）与上心（shàng xīn）第二个音节韵母不同（ing 与 in），意思是节目上星、卫星播出。"}], "explanations": {"上心": "正确：上心 shàng xīn，意思是在乎、认真去做。", "伤心": "伤心（shāng xīn）与上心（shàng xīn）第一个音节声调不同，意思是难过。", "善心": "善心（shàn xīn）与上心（shàng xīn）第一个音节韵母不同（an 与 ang），意思是善良的心。", "上星": "上星（shàng xīng）与上心（shàng xīn）第二个音节韵母不同（ing 与 in），意思是节目上星、卫星播出。"}, "sentence_index": null, "correct_answer": "上心"}, "level_3": {"options": [{"text": "上心", "is_correct": true, "explanation": "正确：“上心”表示在乎、认真对待，可与“很”和“对工作”搭配。"}, {"text": "疼爱", "is_correct": false, "explanation": "搭配：“疼爱”的对象是人，如孩子、亲人，不说“对工作很疼爱”。"}, {"text": "同情", "is_correct": false, "explanation": "语义：“同情”是对别人的遭遇表示怜悯，不用来形容对工作的态度。"}, {"text": "体谅", "is_correct": false, "explanation": "搭配：“体谅”指替别人着想，“对工作很体谅”说不通。"}], "explanations": {"上心": "正确：“上心”表示在乎、认真对待，可与“很”和“对工作”搭配。", "疼爱": "搭配：“疼爱”的对象是人，如孩子、亲人，不说“对工作很疼爱”。", "同情": "语义：“同情”是对别人的遭遇表示怜悯，不用来形容对工作的态度。", "体谅": "搭配：“体谅”指替别人着想，“对工作很体谅”说不通。"}, "sentence_index": 0, "correct_answer": "上心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师很上心每个学生的成绩。", "explanation": "这里应该用〈关心〉。上心不直接带宾语，要说“对……上心”；“关心”可以直接带宾语。"}, {"text": "医生很上心病人的病情。", "explanation": "这里应该用〈重视〉。上心后面不接宾语，应说“对病人的病情很上心”；“重视”可直接带宾语。"}, {"text": "妈妈很上心我的身体。", "explanation": "这里应该用〈在乎〉。上心不直接带宾语，应说“对我的身体很上心”；“在乎”可直接带宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '170d71e0-dc2a-4314-bfe2-fb919f6a46ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92089, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上心", "is_correct": true, "explanation": "正确：“上心”表示在乎、认真对待，与“对朋友的事”和“这么”搭配。"}, {"text": "嫉妒", "is_correct": false, "explanation": "语义：“嫉妒”指因别人好而心生不满，用在这里意思不通。"}, {"text": "表扬", "is_correct": false, "explanation": "配价：“表扬”的对象是人或成绩，不能说“对朋友的事怎么这么表扬”。"}, {"text": "伤害", "is_correct": false, "explanation": "语义：“伤害”指使人受损，不能用来形容对朋友的事的态度。"}], "explanations": {"上心": "正确：“上心”表示在乎、认真对待，与“对朋友的事”和“这么”搭配。", "嫉妒": "语义：“嫉妒”指因别人好而心生不满，用在这里意思不通。", "表扬": "配价：“表扬”的对象是人或成绩，不能说“对朋友的事怎么这么表扬”。", "伤害": "语义：“伤害”指使人受损，不能用来形容对朋友的事的态度。"}, "sentence_index": 6, "correct_answer": "上心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶总是上心远方的孙子。", "explanation": "这里应该用〈惦记〉。上心不直接带人作宾语，要说“对……上心”；“惦记”可直接带人。"}, {"text": "园长很上心每个孩子。", "explanation": "这里应该用〈爱护〉。上心不能直接带“每个孩子”作宾语；“爱护”可直接带宾语。"}, {"text": "班长很上心同学的困难。", "explanation": "这里应该用〈体谅〉。上心后面不接宾语，应说“对同学的困难很上心”；“体谅”可直接带宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '170d71e0-dc2a-4314-bfe2-fb919f6a46ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92089, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把身体上心一点。", "corrected_sentence": "我对身体上心一点。", "error_description": "错误：“上心”的对象不能用“把”字句引出。应改用介词“对”，说“我对身体上心一点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '170d71e0-dc2a-4314-bfe2-fb919f6a46ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92089, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对这件事上心很。", "corrected_sentence": "他对这件事上心得很。", "error_description": "错误：状态补语结构缺少“得”。正确应为“上心得很”，“得”连接动词与补语“很”；“上心很”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '170d71e0-dc2a-4314-bfe2-fb919f6a46ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
