INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92091, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "只不过是说事情没有那么多，只有这一点。", "primary_collocate": null, "pronunciation": "zhǐ bú guò", "ipa": "ʈʂɨ˨˩ pu˧˥ kuo˥˩", "syllable_count": 3, "sentences": [{"text": "我只不过说了一句话，他就生气了。", "target_word": "只不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只不过是一件小事，别太担心。", "target_word": "只不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只不过是个孩子，你别怪他。", "target_word": "只不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只不过想问一下，没有别的意思。", "target_word": "只不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天只不过花了十块钱。", "target_word": "只不过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只不过是我的一点小想法。", "target_word": "只不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她只不过迟到了五分钟，老师没说什么。", "target_word": "只不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只不过借了你的笔，你怎么这么着急？", "target_word": "只不过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题只不过有一点难。", "target_word": "只不过", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他只不过跟我开个玩笑。", "target_word": "只不过", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "只不过-副词-只有这一点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2d808-5f98-4557-8046-f4e5641b51ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92091, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "只不过", "is_correct": true, "explanation": "正确：只不过表示仅此而已，说的话很少，与后半句“他就生气了”形成对比。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”修饰形容词或心理动词，不能修饰“说了一句话”这样的动作。"}, {"text": "经常", "is_correct": false, "explanation": "语义：“经常”表示多次重复，与“说了一句话”这种单次动作矛盾。"}, {"text": "总是", "is_correct": false, "explanation": "语义：“总是”表示一直如此，与“说了一句话”这种单次动作矛盾。"}], "explanations": {"只不过": "正确：只不过表示仅此而已，说的话很少，与后半句“他就生气了”形成对比。", "非常": "搭配：“非常”修饰形容词或心理动词，不能修饰“说了一句话”这样的动作。", "经常": "语义：“经常”表示多次重复，与“说了一句话”这种单次动作矛盾。", "总是": "语义：“总是”表示一直如此，与“说了一句话”这种单次动作矛盾。"}, "sentence_index": 0, "correct_answer": "只不过"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的个子很高，只不过篮球打得不好。", "explanation": "这里的“只不过”是连词，表示转折，相当于“但是”，与所教的“仅仅”义项不同。"}, {"text": "只不过你努力学习，就一定能考上。", "explanation": "这里应该用〈只要〉，表示条件。“只不过”表示仅此而已，不能用来引出条件。"}, {"text": "这个方案好是好，只不过太贵了。", "explanation": "这里的“只不过”是连词，表示转折，相当于“但是”，与所教的“仅仅”义项不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ace22b4-9832-4c20-9b66-315f55e68cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92091, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "只不过", "is_correct": true, "explanation": "正确：只不过表示原因很小，与后半句“迟到了”的结果相呼应。"}, {"text": "最", "is_correct": false, "explanation": "搭配：“最”用于最高级或比较，不能说“最迟到了”。"}, {"text": "根本", "is_correct": false, "explanation": "搭配：“根本”通常与否定词连用，不能直接修饰肯定的“迟到了五分钟”。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示一向如此，与“迟到了五分钟”这种具体的一次事件矛盾。"}], "explanations": {"只不过": "正确：只不过表示原因很小，与后半句“迟到了”的结果相呼应。", "最": "搭配：“最”用于最高级或比较，不能说“最迟到了”。", "根本": "搭配：“根本”通常与否定词连用，不能直接修饰肯定的“迟到了五分钟”。", "从来": "语义：“从来”表示一向如此，与“迟到了五分钟”这种具体的一次事件矛盾。"}, "sentence_index": 6, "correct_answer": "只不过"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的东西很好，只不过价格有点贵。", "explanation": "这里的“只不过”是连词，表示转折，相当于“但是”，与所教的“仅仅”义项不同。"}, {"text": "只不过大家一起努力，才能赢。", "explanation": "这里应该用〈只有〉，表示唯一的条件。“只不过”不能用来引出条件。"}, {"text": "这个主意不错，只不过需要更多时间。", "explanation": "这里的“只不过”是连词，表示转折，相当于“但是”，与所教的“仅仅”义项不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ace22b4-9832-4c20-9b66-315f55e68cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92091, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他只不过看着一眼，就走了。", "corrected_sentence": "他只不过看了一眼，就走了。", "error_description": "错误：“看了一眼”的“了”换成了“着”。“着”表示动作持续进行，与“一眼”这种短暂动作搭配不当，应说“看了一眼”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ace22b4-9832-4c20-9b66-315f55e68cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92091, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我只不过买着一本书，你别生气。", "corrected_sentence": "我只不过买了一本书，你别生气。", "error_description": "错误：“买着一本书”用错了体标。“只不过”说的是已经完成的一件小事，要用“了”表示完成，应说“买了一本书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ace22b4-9832-4c20-9b66-315f55e68cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
