INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92093, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92093, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "心里不害怕。", "primary_collocate": null, "pronunciation": "bú pà", "ipa": "pu˧˥ pʰa˥˩", "syllable_count": 2, "sentences": [{"text": "晚上一个人在家，我一点儿也不怕。", "target_word": "不怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别担心，我不怕，你先走吧。", "target_word": "不怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看到大狗一点也不怕，还走过去摸它。", "target_word": "不怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打雷的时候，我抱着妈妈就不怕了。", "target_word": "不怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怕黑吗？我不怕。", "target_word": "不怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说打针不疼，所以弟弟不怕了。", "target_word": "不怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山路很黑，但有朋友在旁边，我就不怕了。", "target_word": "不怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹看到蛇也不怕，还想走近看看。", "target_word": "不怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在身边，孩子们都不怕。", "target_word": "不怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一个人去国外，真的不怕吗？", "target_word": "不怕", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "多单独作谓语，表示面对黑夜、动物、打针等时心里不害怕", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6364b06-5bd6-4d7a-9892-29c9666e0942') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92093, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不怕", "is_correct": true, "explanation": "“不怕”表示心里不害怕，与“一点儿也”搭配，说明一个人在家并不觉得害怕。"}, {"text": "喜欢", "is_correct": false, "explanation": "搭配：“一点儿也”要与否定词连用，“一点儿也喜欢”不成立，也与语境不符。"}, {"text": "需要", "is_correct": false, "explanation": "配价：“需要”要带宾语或小句，“我一点儿也需要”语义不完整。"}, {"text": "讨厌", "is_correct": false, "explanation": "搭配：“一点儿也”要与否定词连用，“一点儿也讨厌”不成立。"}], "explanations": {"不怕": "“不怕”表示心里不害怕，与“一点儿也”搭配，说明一个人在家并不觉得害怕。", "喜欢": "搭配：“一点儿也”要与否定词连用，“一点儿也喜欢”不成立，也与语境不符。", "需要": "配价：“需要”要带宾语或小句，“我一点儿也需要”语义不完整。", "讨厌": "搭配：“一点儿也”要与否定词连用，“一点儿也讨厌”不成立。"}, "sentence_index": 0, "correct_answer": "不怕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "黑漆漆的屋子里，他吓得发抖，连门都不怕进。", "explanation": "这里应该用〈不敢〉。“不怕”表示心里不害怕，与“吓得发抖”矛盾；说不敢进去要用〈不敢〉。"}, {"text": "我一看见蛇就尖叫着往后跑，一点儿也不怕它。", "explanation": "这里应该用〈怕〉。“尖叫着往后跑”表示害怕，与“不怕”矛盾。"}, {"text": "他一听到打针就哭个不停，从来不怕。", "explanation": "这里应该用〈怕〉。“哭个不停”表示害怕，与“不怕”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92093, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不怕", "is_correct": true, "explanation": "“不怕”表示心里不害怕，与“有朋友在旁边”呼应，说明有人陪着就不害怕了。"}, {"text": "迷路", "is_correct": false, "explanation": "语义：有朋友在旁边，“我就迷路了”与语境相矛盾。"}, {"text": "逃跑", "is_correct": false, "explanation": "语义：有朋友陪着，“我就逃跑了”与语境相矛盾，逃跑的动机也不成立。"}, {"text": "逃之夭夭", "is_correct": false, "explanation": "语域：“逃之夭夭”是书面化的成语，与这句口语化的叙述不协调；语义上也与“有朋友在旁边”相矛盾。"}], "explanations": {"不怕": "“不怕”表示心里不害怕，与“有朋友在旁边”呼应，说明有人陪着就不害怕了。", "迷路": "语义：有朋友在旁边，“我就迷路了”与语境相矛盾。", "逃跑": "语义：有朋友陪着，“我就逃跑了”与语境相矛盾，逃跑的动机也不成立。", "逃之夭夭": "语域：“逃之夭夭”是书面化的成语，与这句口语化的叙述不协调；语义上也与“有朋友在旁边”相矛盾。"}, "sentence_index": 6, "correct_answer": "不怕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我借了朋友的钱，见到他有点不怕。", "explanation": "这里应该用〈不好意思〉。「不怕」表示不畏惧，而「欠钱」的歉疚语境要用〈不好意思〉，表示心里有顾虑。"}, {"text": "妹妹见到狗就躲到妈妈身后，一点儿也不怕。", "explanation": "这里应该用〈怕〉。“躲到妈妈身后”表示害怕，与“不怕”矛盾。"}, {"text": "他一看见黑乎乎的山洞就腿软，一点儿也不怕。", "explanation": "这里应该用〈怕〉。“腿软”表示害怕，与“不怕”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92093, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜里一个人走路，他一点儿也不不怕。", "corrected_sentence": "夜里一个人走路，他一点儿也不怕。", "error_description": "多了一个“不”，形成双重否定“不不怕”。应为“一点儿也不怕”，只保留一个“不”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92093, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋里有灯，有朋友陪着，我就不怕着。", "corrected_sentence": "屋里有灯，有朋友陪着，我就不怕了。", "error_description": "“了”误用为“着”。“着”表示动作或状态的持续，不能放在“不怕”后面表示情况的出现或变化；应为“不怕了”，用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
