INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92094, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不畏惧；不担心。", "primary_collocate": null, "pronunciation": "bú pà", "ipa": "pu˧˥ pʰa˥˩", "syllable_count": 2, "sentences": [{"text": "他不怕困难，一直努力学习。", "target_word": "不怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要你认真，就不怕考试。", "target_word": "不怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不怕累，只想把工作做好。", "target_word": "不怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王不怕冷，冬天也穿短裤。", "target_word": "不怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不怕下雨，因为带了雨伞。", "target_word": "不怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不怕别人说什么，只做自己的事。", "target_word": "不怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，不怕学得慢，就怕不学。", "target_word": "不怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸不怕辛苦，每天很早就去上班。", "target_word": "不怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不怕迟到吗？快点走吧。", "target_word": "不怕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不怕花钱，只要东西好。", "target_word": "不怕", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "后面带困难、辛苦、天气、结果等宾语，表示不畏惧、不担心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6364b06-5bd6-4d7a-9892-29c9666e0942') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92094, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不怕", "is_correct": true, "explanation": "“不怕”表示不畏惧，与后文“一直努力学习”相呼应，说明他面对困难仍然坚持。"}, {"text": "躲避", "is_correct": false, "explanation": "语义：“躲避困难”与“一直努力学习”的态度相矛盾，句意不通。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”与后文“一直努力学习”相矛盾，句意不通。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：“逃避困难”与“一直努力学习”的态度相矛盾，句意不通。"}], "explanations": {"不怕": "“不怕”表示不畏惧，与后文“一直努力学习”相呼应，说明他面对困难仍然坚持。", "躲避": "语义：“躲避困难”与“一直努力学习”的态度相矛盾，句意不通。", "放弃": "语义：“放弃”与后文“一直努力学习”相矛盾，句意不通。", "逃避": "语义：“逃避困难”与“一直努力学习”的态度相矛盾，句意不通。"}, "sentence_index": 0, "correct_answer": "不怕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一想到要上台讲话就腿软，根本不怕站上去。", "explanation": "这里应该用〈不敢〉。“腿软”表示害怕，与“不怕”矛盾。"}, {"text": "他一见到陌生人就躲到门后，从来不怕和别人说话。", "explanation": "这里应该用〈不敢〉。“躲到门后”表示害怕，与“不怕”矛盾。"}, {"text": "他听到雷声就发抖，连门都不怕出去。", "explanation": "这里应该用〈不敢〉。“不怕”表示不畏惧，与“发抖”的语境矛盾；说不敢出门要用〈不敢〉，两者意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92094, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不怕", "is_correct": true, "explanation": "“不怕”表示不畏惧，与后文“就怕不学”形成对照，说明学得慢不要紧。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：“逃避学得慢”与“就怕不学”的态度相反，句意不通。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：后半句“就怕不学”说明学得慢不要紧，“讨厌学得慢”与这种宽容的态度不符。"}, {"text": "嫌弃", "is_correct": false, "explanation": "语义：后半句“就怕不学”说明学得慢不要紧，“嫌弃学得慢”与这种态度相反。"}], "explanations": {"不怕": "“不怕”表示不畏惧，与后文“就怕不学”形成对照，说明学得慢不要紧。", "逃避": "语义：“逃避学得慢”与“就怕不学”的态度相反，句意不通。", "讨厌": "语义：后半句“就怕不学”说明学得慢不要紧，“讨厌学得慢”与这种宽容的态度不符。", "嫌弃": "语义：后半句“就怕不学”说明学得慢不要紧，“嫌弃学得慢”与这种态度相反。"}, "sentence_index": 6, "correct_answer": "不怕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一听到要去外地就心慌，根本不怕走那么远的路。", "explanation": "这里应该用〈不敢〉。“心慌”表示害怕，与“不怕”矛盾。"}, {"text": "我把他的书弄丢了，见到他总有点不怕。", "explanation": "这里应该用〈不好意思〉。「不怕」表示不畏惧，而「弄丢了书」的歉疚语境要用〈不好意思〉，表示心里有顾虑。"}, {"text": "他一看到高处就脸色发白，连楼梯都不怕走。", "explanation": "这里应该用〈不敢〉。“脸色发白”表示害怕，与“不怕”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92094, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她不怕了辛苦，每天都练习。", "corrected_sentence": "她不怕辛苦，每天都练习。", "error_description": "“了”用错了。“不怕辛苦”是动词带宾语，表示一贯的态度，中间不能插入“了”，应删去“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92094, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一点儿也不不怕困难，还笑着说没关系。", "corrected_sentence": "他一点儿也不怕困难，还笑着说没关系。", "error_description": "多了一个“不”，形成“不不怕”的双重否定，句意混乱。应为“一点儿也不怕”，只保留一个“不”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
