INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92095, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "只当是把这件事看成另一件事。", "primary_collocate": null, "pronunciation": "zhǐ dàng", "ipa": "ʈʂɻ̩˨˩˦ tɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他说的话，你只当是玩笑吧。", "target_word": "只当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行，我只当是出去放松。", "target_word": "只当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她送的东西，你只当是个纪念吧。", "target_word": "只当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只当是一场梦，别再想了。", "target_word": "只当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他批评我，我只当是帮助我。", "target_word": "只当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这点钱，只当是请朋友吃饭了。", "target_word": "只当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那件事过去了，你只当是个教训。", "target_word": "只当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟的哭声，妈妈只当是撒娇。", "target_word": "只当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些累活，他只当是锻炼身体。", "target_word": "只当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只当是帮你一个小忙，不用谢。", "target_word": "只当", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "只当是：把一件事当作另一件事来看", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68b6fea3-2699-4510-9ab1-0d36748570eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92095, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打扫", "is_correct": false, "explanation": "语义：「打扫」是清扫地方，不能接「是玩笑」这样的判断。"}, {"text": "只当", "is_correct": true, "explanation": "「只当是」表示姑且把这件事看作另一件事，与「是玩笑」相符。"}, {"text": "看重", "is_correct": false, "explanation": "搭配：「看重」的对象是事情的价值或人，不接「是玩笑」这样的判断句。"}, {"text": "证明", "is_correct": false, "explanation": "语义：「证明」是断定事实的依据，与「只当是」这种姑且的看法不合。"}], "explanations": {"打扫": "语义：「打扫」是清扫地方，不能接「是玩笑」这样的判断。", "只当": "「只当是」表示姑且把这件事看作另一件事，与「是玩笑」相符。", "看重": "搭配：「看重」的对象是事情的价值或人，不接「是玩笑」这样的判断句。", "证明": "语义：「证明」是断定事实的依据，与「只当是」这种姑且的看法不合。"}, "sentence_index": 0, "correct_answer": "只当"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "服务员，我只当一杯咖啡。", "explanation": "这里应该用〈要〉。点东西用「要」，「只当」表示姑且看作，不能表示点餐。"}, {"text": "我昨天只当了一本新书。", "explanation": "这里应该用〈买〉。「只当」不表示购买，也不接具体物品。"}, {"text": "他只当得很快，第一个到学校。", "explanation": "这里应该用〈跑〉。「只当」不是动作动词，不能带「得很快」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92095, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "忘掉", "is_correct": false, "explanation": "语义：「忘掉」表示不再记得，与「是个教训」的判断不合，且不能接判断句。"}, {"text": "只当", "is_correct": true, "explanation": "「只当是」表示姑且把那件事看作一个教训，与「那件事过去了」的语境相符。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：「洗澡」是不及物动作，不能接「是个教训」。"}, {"text": "感受", "is_correct": false, "explanation": "语义：「感受」指体会到的感觉，不能用来判断一件事是什么。"}], "explanations": {"忘掉": "语义：「忘掉」表示不再记得，与「是个教训」的判断不合，且不能接判断句。", "只当": "「只当是」表示姑且把那件事看作一个教训，与「那件事过去了」的语境相符。", "洗澡": "语义：「洗澡」是不及物动作，不能接「是个教训」。", "感受": "语义：「感受」指体会到的感觉，不能用来判断一件事是什么。"}, "sentence_index": 6, "correct_answer": "只当"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房只当饭。", "explanation": "这里应该用〈做〉。「只当」表示姑且看作，不能表示做饭。"}, {"text": "这个问题太难，我只当不出来。", "explanation": "这里应该用〈想〉。「只当」不能带「不出来」这样的补语。"}, {"text": "他把门只当上了。", "explanation": "这里应该用〈关〉。「只当」不能表示关门这样的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92095, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事，你只当了是玩笑吧。", "corrected_sentence": "这件事，你只当是玩笑吧。", "error_description": "错误形式「只当了是」，正确形式「只当是」。「只当」后面不能直接加「了」表示动作完成，这里应去掉「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92095, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那次失败过去了，你只当了是个经验。", "corrected_sentence": "那次失败过去了，你只当是个经验。", "error_description": "错误形式「只当了是」，正确形式「只当是」。「只当」后面不能直接加「了」，这里应去掉「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
