INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92096, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "权当；姑且把某事看作另一种情况。", "primary_collocate": null, "pronunciation": "zhǐ dàng", "ipa": "ʈʂɻ̩˨˩˦ tɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "你只当我今天没来过。", "target_word": "只当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这事你只当没听见，好不好？", "target_word": "只当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话，你只当耳边风。", "target_word": "只当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家只当没这回事，继续工作。", "target_word": "只当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不喜欢，就只当我没问。", "target_word": "只当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考砸了，只当没考过。", "target_word": "只当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的唠叨，我只当没听到。", "target_word": "只当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今晚的事，大家只当没发生。", "target_word": "只当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你只当我是个路人，别客气。", "target_word": "只当", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次的事，你只当我没提过，好不好？", "target_word": "只当", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "只当：姑且当作没有发生或另一种情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68b6fea3-2699-4510-9ab1-0d36748570eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92096, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打扫", "is_correct": false, "explanation": "语义：「打扫」是清扫地方，不能接「我今天没来过」。"}, {"text": "只当", "is_correct": true, "explanation": "「只当」表示姑且当作没有发生，与「我今天没来过」的语境相符。"}, {"text": "解释", "is_correct": false, "explanation": "配价：「解释」要说明原因或道理，不直接接「我今天没来过」这样的事实句。"}, {"text": "宣布", "is_correct": false, "explanation": "语义：「宣布」是公开正式地表态，与「只当」私下姑且处理的意思不合。"}], "explanations": {"打扫": "语义：「打扫」是清扫地方，不能接「我今天没来过」。", "只当": "「只当」表示姑且当作没有发生，与「我今天没来过」的语境相符。", "解释": "配价：「解释」要说明原因或道理，不直接接「我今天没来过」这样的事实句。", "宣布": "语义：「宣布」是公开正式地表态，与「只当」私下姑且处理的意思不合。"}, "sentence_index": 0, "correct_answer": "只当"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "服务员，我只当一碗面条。", "explanation": "这里应该用〈要〉。点餐用「要」，「只当」表示姑且看作，不能表示点餐。"}, {"text": "我只当他的生日。", "explanation": "这里应该用〈忘记〉。「只当」后面要接「没…」或「是…」一类情况，不能单带名词表示遗忘。"}, {"text": "他只当得很快，第一个到家。", "explanation": "这里应该用〈跑〉。「只当」不是动作动词，不能带「得很快」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92096, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反驳", "is_correct": false, "explanation": "语义：「反驳」要针对对方的观点，「妈妈的唠叨」后接「没听到」不构成反驳。"}, {"text": "只当", "is_correct": true, "explanation": "「只当」表示姑且当作没有听到，与「妈妈的唠叨，我没听到」的语境相符。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：「洗澡」是不及物动作，不能接「没听到」。"}, {"text": "拒绝", "is_correct": false, "explanation": "配价：「拒绝」要求对象是请求或建议，不接「没听到」这样的状态。"}], "explanations": {"反驳": "语义：「反驳」要针对对方的观点，「妈妈的唠叨」后接「没听到」不构成反驳。", "只当": "「只当」表示姑且当作没有听到，与「妈妈的唠叨，我没听到」的语境相符。", "洗澡": "语义：「洗澡」是不及物动作，不能接「没听到」。", "拒绝": "配价：「拒绝」要求对象是请求或建议，不接「没听到」这样的状态。"}, "sentence_index": 6, "correct_answer": "只当"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房只当饭。", "explanation": "这里应该用〈做〉。「只当」表示姑且看作，不能表示做饭。"}, {"text": "他把门只当上了。", "explanation": "这里应该用〈关〉。「只当」不能表示关门这样的动作。"}, {"text": "这个问题太难，我只当不出来。", "explanation": "这里应该用〈想〉。「只当」不能带「不出来」这样的补语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92096, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次的事，你只当了没看见。", "corrected_sentence": "这次的事，你只当没看见。", "error_description": "错误形式「只当了没看见」，正确形式「只当没看见」。「只当」后面不能直接加「了」，这里应去掉「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92096, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那次的误会，你只当着没听说。", "corrected_sentence": "那次的误会，你只当没听说。", "error_description": "错误：「只当」后加「着」；正确：去掉「着」。「只当」表示姑且看作，后面不能加「着」表示持续状态。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
