INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92097, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "没有小心看着。", "primary_collocate": null, "pronunciation": "bú zhù yì", "ipa": "pu˧˥ ʈʂu˥˩ i˥˩", "syllable_count": 3, "sentences": [{"text": "他走路不注意，撞到了树。", "target_word": "不注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过马路不注意，很危险。", "target_word": "不注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不注意，手碰到了火。", "target_word": "不注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车不注意，会出事故。", "target_word": "不注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不注意脚下，会摔跤的。", "target_word": "不注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看手机不注意，走进了水坑。", "target_word": "不注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一不注意，杯子就掉了。", "target_word": "不注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做饭时不注意，把手烫了。", "target_word": "不注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不注意前面的车，差点撞上。", "target_word": "不注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上楼梯不注意，容易摔倒。", "target_word": "不注意", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "做事或走路时没有留神看着，结果出事或出错", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20ba2caa-c9bc-48ff-8965-0af456cf76bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92097, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不注意", "is_correct": true, "explanation": "正确：“不注意”表示走路时没看着，结果撞到了树。"}, {"text": "小心", "is_correct": false, "explanation": "语义：“小心”表示留神，“走路小心，撞到了树”自相矛盾。"}, {"text": "留神", "is_correct": false, "explanation": "语义：“留神”表示注意，与“撞到了树”的结果矛盾。"}, {"text": "注视", "is_correct": false, "explanation": "搭配：“注视”要看着某个对象，不说走路注视。"}], "explanations": {"不注意": "正确：“不注意”表示走路时没看着，结果撞到了树。", "小心": "语义：“小心”表示留神，“走路小心，撞到了树”自相矛盾。", "留神": "语义：“留神”表示注意，与“撞到了树”的结果矛盾。", "注视": "搭配：“注视”要看着某个对象，不说走路注视。"}, "sentence_index": 0, "correct_answer": "不注意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他不注意地仔细检查了每一道题。", "explanation": "“不注意”指没小心看着，与“仔细检查”的做法相矛盾，不能作方式状语。"}, {"text": "他不注意地把每个细节都记了下来。", "explanation": "“不注意”指没小心看着，与“把每个细节都记下来”的做法相矛盾，不能作方式状语。"}, {"text": "她不注意地反复确认了每一步。", "explanation": "“不注意”指没小心看着，与“反复确认”的做法相矛盾，不能作方式状语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92097, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不注意", "is_correct": true, "explanation": "正确：“不注意”表示一时没看着，杯子就掉了。"}, {"text": "当心", "is_correct": false, "explanation": "语义：“当心”表示留神，与“杯子就掉了”的结果矛盾。"}, {"text": "提防", "is_correct": false, "explanation": "配价：“提防”要带明确的对象，这里没有宾语，句子不成立。"}, {"text": "留神", "is_correct": false, "explanation": "语义：“留神”表示注意，与“杯子就掉了”的结果矛盾。"}], "explanations": {"不注意": "正确：“不注意”表示一时没看着，杯子就掉了。", "当心": "语义：“当心”表示留神，与“杯子就掉了”的结果矛盾。", "提防": "配价：“提防”要带明确的对象，这里没有宾语，句子不成立。", "留神": "语义：“留神”表示注意，与“杯子就掉了”的结果矛盾。"}, "sentence_index": 6, "correct_answer": "不注意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他不注意地认真参加了比赛。", "explanation": "“不注意”指没小心看着，与“认真”的做法相矛盾，不能作方式状语。"}, {"text": "妈妈不注意地精心做了晚饭。", "explanation": "“不注意”指没小心看着，与“精心”的做法相矛盾，不能作方式状语。"}, {"text": "他不注意地仔细核对了账目。", "explanation": "“不注意”指没小心看着，与“仔细核对”的做法相矛盾，不能作方式状语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92097, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "过马路时他被不注意，差点被车撞了。", "corrected_sentence": "过马路时他不注意，差点被车撞了。", "error_description": "错误：“不注意”不能用于“被”字句，“被不注意”不成立。正确是“过马路时他不注意，差点被车撞了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92097, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他骑车时一不不注意，撞到了路边的石头。", "corrected_sentence": "他骑车时一不注意，撞到了路边的石头。", "error_description": "错误：“不注意”前多写了一个“不”，成了“不不注意”。“一不注意”只用一个“不”，正确是“一不注意”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
