INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92098, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "没有留心；没有注意。", "primary_collocate": null, "pronunciation": "bú zhù yì", "ipa": "pu˧˥ ʈʂu˥˩ i˥˩", "syllable_count": 3, "sentences": [{"text": "他一直不注意身体，所以病了。", "target_word": "不注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人不注意饮食，容易发胖。", "target_word": "不注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不注意卫生，房间很脏。", "target_word": "不注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上课时我不注意老师说的话。", "target_word": "不注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不注意细节，作业就会错。", "target_word": "不注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不注意时间，常常迟到。", "target_word": "不注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不注意周围的声音，没听见电话响。", "target_word": "不注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不注意坐姿，眼睛会不好。", "target_word": "不注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不注意安全，工地上很危险。", "target_word": "不注意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些人不注意礼貌，让大家不高兴。", "target_word": "不注意", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "对某事、某物不留心、不重视，后面常带身体、卫生、细节等宾语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20ba2caa-c9bc-48ff-8965-0af456cf76bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92098, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不注意", "is_correct": true, "explanation": "正确：“不注意”表示不留心、不重视身体，与“所以病了”的因果相合。"}, {"text": "锻炼", "is_correct": false, "explanation": "语义：“锻炼身体”是积极做法，与“所以病了”的因果相反。"}, {"text": "照顾", "is_correct": false, "explanation": "语义：“照顾身体”是保护身体，与“所以病了”的结果矛盾。"}, {"text": "关照", "is_correct": false, "explanation": "搭配：“关照”多用于对人，不说关照身体。"}], "explanations": {"不注意": "正确：“不注意”表示不留心、不重视身体，与“所以病了”的因果相合。", "锻炼": "语义：“锻炼身体”是积极做法，与“所以病了”的因果相反。", "照顾": "语义：“照顾身体”是保护身体，与“所以病了”的结果矛盾。", "关照": "搭配：“关照”多用于对人，不说关照身体。"}, "sentence_index": 0, "correct_answer": "不注意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他不注意地反复斟酌这件事。", "explanation": "“不注意”指没有留心，与“反复斟酌”的做法相矛盾，不能作方式状语。"}, {"text": "她不注意地逐字核对了合同。", "explanation": "“不注意”指没有留心，与“逐字核对”的做法相矛盾，不能作方式状语。"}, {"text": "他不注意地反复检查那份文件。", "explanation": "“不注意”指没有留心，与“反复检查”的做法相矛盾，不能作方式状语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92098, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不注意", "is_correct": true, "explanation": "正确：“不注意”表示不留心，与“没听见电话响”的结果相合。"}, {"text": "留意", "is_correct": false, "explanation": "语义：“留意”表示注意，与“没听见电话响”矛盾。"}, {"text": "注视", "is_correct": false, "explanation": "搭配：“注视”指看着某物，不说注视声音。"}, {"text": "警惕", "is_correct": false, "explanation": "语义：“警惕”表示高度留神，与“没听见电话响”相矛盾。"}], "explanations": {"不注意": "正确：“不注意”表示不留心，与“没听见电话响”的结果相合。", "留意": "语义：“留意”表示注意，与“没听见电话响”矛盾。", "注视": "搭配：“注视”指看着某物，不说注视声音。", "警惕": "语义：“警惕”表示高度留神，与“没听见电话响”相矛盾。"}, "sentence_index": 6, "correct_answer": "不注意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他不注意地反复核对了每一笔账。", "explanation": "“不注意”指没有留心，与“反复核对”的做法相矛盾，不能作方式状语。"}, {"text": "老师不注意地一字一句地批改了作业。", "explanation": "“不注意”指没有留心，与“一字一句”的做法相矛盾，不能作方式状语。"}, {"text": "老板不注意地逐条检查了每份报告。", "explanation": "“不注意”指没有留心，与“逐条检查”的做法相矛盾，不能作方式状语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92098, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "上课时他不不注意老师讲的题目，所以作业都错了。", "corrected_sentence": "上课时他不注意老师讲的题目，所以作业都错了。", "error_description": "错误：“不注意”里多写了一个“不”。“不注意”只用一个否定词“不”，正确是“不注意老师讲的题目”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92098, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "开会时他把不注意周围的同事，显得很冷淡。", "corrected_sentence": "开会时他不注意周围的同事，显得很冷淡。", "error_description": "错误：“不注意”前多加了“把”，“把”字句不能这样用。正确是“不注意周围的同事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
