INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92100, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个国家的首都。", "primary_collocate": null, "pronunciation": "guó dū", "ipa": "kwo˧˥ tu˥", "syllable_count": 2, "sentences": [{"text": "西安曾经是中国古代的国都。", "target_word": "国都", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家的国都是哪个城市？", "target_word": "国都", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他去国都参加了国际会议。", "target_word": "国都", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国都里有许多大使馆。", "target_word": "国都", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "从这里到国都要坐三个小时的车。", "target_word": "国都", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家把国都从海边搬到了山里。", "target_word": "国都", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "唐朝的国都在长安，那里非常繁荣。", "target_word": "国都", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的家在国都，却在小城工作。", "target_word": "国都", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国都的天气比别的城市冷。", "target_word": "国都", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师问我们：“法国的国都在哪里？”", "target_word": "国都", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "國都", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "国都：名词，一个国家的首都", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62980f86-a355-48b6-b578-ee1687d5ac53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92100, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "国都", "is_correct": true, "explanation": "正确：国都指一个国家的首都，读作 guó dū（国为第二声，都为第一声）。"}, {"text": "国度", "is_correct": false, "explanation": "国度（guó dù）与国都只有第二个音节声调不同，意思是国家、领域。"}, {"text": "过度", "is_correct": false, "explanation": "过度（guò dù）与国都两个音节的声调都不同，意思是超过适当的限度。"}, {"text": "过渡", "is_correct": false, "explanation": "过渡（guò dù）与国都读音相近，只是声调不同，意思是从一个阶段转到另一个阶段。"}], "explanations": {"国都": "正确：国都指一个国家的首都，读作 guó dū（国为第二声，都为第一声）。", "国度": "国度（guó dù）与国都只有第二个音节声调不同，意思是国家、领域。", "过度": "过度（guò dù）与国都两个音节的声调都不同，意思是超过适当的限度。", "过渡": "过渡（guò dù）与国都读音相近，只是声调不同，意思是从一个阶段转到另一个阶段。"}, "sentence_index": null, "correct_answer": "国都"}, "level_3": {"options": [{"text": "国都", "is_correct": true, "explanation": "正确：西安曾是中国古代的首都，即国都。"}, {"text": "国家", "is_correct": false, "explanation": "语义：西安是城市，不是国家，“中国古代的国家”指的不是城市，说法不通。"}, {"text": "国王", "is_correct": false, "explanation": "搭配：“中国古代的…”作“是”的宾语，此处需要表示城市的名词，“国王”指人，不能搭配。"}, {"text": "宫殿", "is_correct": false, "explanation": "语义：宫殿是建筑，西安是城市，不能说西安是宫殿。"}], "explanations": {"国都": "正确：西安曾是中国古代的首都，即国都。", "国家": "语义：西安是城市，不是国家，“中国古代的国家”指的不是城市，说法不通。", "国王": "搭配：“中国古代的…”作“是”的宾语，此处需要表示城市的名词，“国王”指人，不能搭配。", "宫殿": "语义：宫殿是建筑，西安是城市，不能说西安是宫殿。"}, "sentence_index": 0, "correct_answer": "国都"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "韩国是一个小国都。", "explanation": "这里应该用〈国家〉。国都指首都，是城市，不能用来指整个国家。"}, {"text": "成都是四川省的国都。", "explanation": "这里应该用〈省会〉。国都指全国的首都，四川省的首府应说“省会”，不能用“国都”。"}, {"text": "拉萨是西藏的国都。", "explanation": "这里应该用〈首府〉。国都指全国的首都，西藏自治区的首府应说“首府”，不能用“国都”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dbd2967-c06a-4705-ac9f-18a26b80dd14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92100, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国都", "is_correct": true, "explanation": "正确：唐朝的首都在长安，即国都。"}, {"text": "国情", "is_correct": false, "explanation": "语义：国情是抽象的国家基本状况，不是可以位于某地的实体，句子说不通。"}, {"text": "国策", "is_correct": false, "explanation": "语义：国策是抽象的国家政策，不是可以位于某地的实体，句子说不通。"}, {"text": "国体", "is_correct": false, "explanation": "语义：国体指国家的政治制度，是抽象概念，不能位于某个城市，句子说不通。"}], "explanations": {"国都": "正确：唐朝的首都在长安，即国都。", "国情": "语义：国情是抽象的国家基本状况，不是可以位于某地的实体，句子说不通。", "国策": "语义：国策是抽象的国家政策，不是可以位于某地的实体，句子说不通。", "国体": "语义：国体指国家的政治制度，是抽象概念，不能位于某个城市，句子说不通。"}, "sentence_index": 6, "correct_answer": "国都"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "国都说了很多话。", "explanation": "这里应该用〈老师〉。国都是地方，不能说话，句中的主语应是人。"}, {"text": "他每月的国都很高。", "explanation": "这里应该用〈工资〉。国都指首都，不能用来指收入。"}, {"text": "她的国都很好。", "explanation": "这里应该用〈成绩〉。国都指首都，不能用来指学习成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dbd2967-c06a-4705-ac9f-18a26b80dd14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92100, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去过一本国都，那里的博物馆很有名。", "corrected_sentence": "他去过一座国都，那里的博物馆很有名。", "error_description": "错误：“一本国都”；正确：“一座国都”。国都是城市，量词应用“座”，“本”只用于书。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dbd2967-c06a-4705-ac9f-18a26b80dd14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92100, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "法国的国都有巴黎。", "corrected_sentence": "法国的国都是巴黎。", "error_description": "错误：“国都”后用了“有”，应为“是”。判断句“A是B”表示两者等同，“法国的国都是巴黎”中不能用“有”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dbd2967-c06a-4705-ac9f-18a26b80dd14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
