INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92101, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "客人走的时候，主人说的客气话。", "primary_collocate": null, "pronunciation": "bú sòng", "ipa": "pu˧˥ sʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "客人起身告辞，爷爷客气地说了句“不送”。", "target_word": "不送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人走出院门，老张在屋里喊：“不送啦，慢走！”", "target_word": "不送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老李站在门里，对着客人说：“慢走，不送！”", "target_word": "不送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人都走到门外了，他才说了声不送。", "target_word": "不送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你走吧，我就不送了，路上注意安全。", "target_word": "不送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人刚出门，姐姐探出头来说：“不送了，路上小心！”", "target_word": "不送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边说“不送”，一边向客人点头。", "target_word": "不送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面太冷了，我就不送你们了。", "target_word": "不送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈对客人说了声“不送”，就回厨房了。", "target_word": "不送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人刚迈出门，主人就说：“不送，再见！”", "target_word": "不送", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "礼貌用语", "sense_fingerprint": "客人告辞时主人说的客气话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c8724db-93b5-4991-96c7-55399deeca21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92101, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不送", "is_correct": true, "explanation": "正确。“不送”是主人送客时说的客气话，与“客人起身告辞”的语境相符。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”与客人告辞、主人客套的语境完全无关，句子不通。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”与客人告辞的语境完全无关，句子不通。"}, {"text": "吃饭", "is_correct": false, "explanation": "搭配：“吃饭”不是告辞时的客套话，与“说了句”的语境不搭配。"}], "explanations": {"不送": "正确。“不送”是主人送客时说的客气话，与“客人起身告辞”的语境相符。", "考试": "语义：“考试”与客人告辞、主人客套的语境完全无关，句子不通。", "下雨": "语义：“下雨”与客人告辞的语境完全无关，句子不通。", "吃饭": "搭配：“吃饭”不是告辞时的客套话，与“说了句”的语境不搭配。"}, "sentence_index": 0, "correct_answer": "不送"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "您不送，路上注意安全。", "explanation": "这里应该用〈慢走〉。客人离开时主人说“慢走”是祝福，“不送”是客套话，接“路上注意安全”不通。"}, {"text": "同学们都来车站不送，我很感动。", "explanation": "这里应该用〈送行〉。送行指到场送别；“不送”是主人不再远送的客套话，不能用来说同学到了车站却不送。"}, {"text": "客人敲门，主人打开门说：“不送，快请进！”", "explanation": "这里应该用〈欢迎〉。客人刚到，应表示欢迎；“不送”只在客人告辞时说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b39e582-744c-4c39-a343-7e0484b564a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92101, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不送", "is_correct": true, "explanation": "正确。“他一边说“不送”，一边向客人点头”，符合主人送客的动作。"}, {"text": "上班", "is_correct": false, "explanation": "语义：“上班”与向客人点头的送客情境不符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与客人告辞时说的客套话不符。"}, {"text": "散席", "is_correct": false, "explanation": "搭配：“散席”是宴席结束时用的，与送客时说的话和点头的动作不搭配。"}], "explanations": {"不送": "正确。“他一边说“不送”，一边向客人点头”，符合主人送客的动作。", "上班": "语义：“上班”与向客人点头的送客情境不符。", "睡觉": "语义：“睡觉”与客人告辞时说的客套话不符。", "散席": "搭配：“散席”是宴席结束时用的，与送客时说的话和点头的动作不搭配。"}, "sentence_index": 6, "correct_answer": "不送"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我出门前对房东说：“不送。”", "explanation": "这里是要离开的人对房东说，把“不送”当成了告辞者的话，应改用〈再见〉。"}, {"text": "客人刚进门，主人就说：“不送。”", "explanation": "这里是客人刚进门，把“不送”当成了迎客的招呼，应改用〈请进〉。"}, {"text": "饭馆还没上菜，老板就说：“不送。”", "explanation": "这里没有客人离开，把“不送”当成了开场的招呼，应改用〈欢迎光临〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b39e582-744c-4c39-a343-7e0484b564a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92101, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "外婆站在门口，客气地说了句“不送过”。", "corrected_sentence": "外婆站在门口，客气地说了句“不送”。", "error_description": "错误：“不送”后面加了“过”。“过”表示经历，“不送过”不成立；这里是客人告辞时的客套话，应说“不送”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b39e582-744c-4c39-a343-7e0484b564a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92101, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "舅舅在门口喊：“慢走，不送着啊！”", "corrected_sentence": "舅舅在门口喊：“慢走，不送啊！”", "error_description": "错误：“不送”后面加了“着”。“着”表示持续的状态，“不送着”说不通；这里应说“不送啊”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b39e582-744c-4c39-a343-7e0484b564a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
