INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92105, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "报导是把新发生的事写出来或说出来，让大家知道。", "primary_collocate": null, "pronunciation": "bào dǎo", "ipa": "pau˥˩ tau˨˩˦", "syllable_count": 2, "sentences": [{"text": "记者在现场报导了这次比赛。", "target_word": "报导", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电视台正在报导这场大雨。", "target_word": "报导", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "各大报纸都报导过这件事。", "target_word": "报导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家报社最先报导了比赛的结果。", "target_word": "报导", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者要把真实情况报导出来。", "target_word": "报导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上没有报导这次事故的原因。", "target_word": "报导", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新闻里报导，明天北京有大雪。", "target_word": "报导", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电台每天早上都报导天气情况。", "target_word": "报导", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者采访了很多人，然后写文章报导这件事。", "target_word": "报导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小城的变化，当地报纸一直在报导。", "target_word": "报导", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "报导了", "label": "体标"}, {"form": "报导过", "label": "体标"}, {"form": "报导着", "label": "体标"}, {"form": "報導", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词：记者或媒体把新发生的事写出来或说出来告诉大家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f82317-b64b-4c72-a0db-f7ebe4e148f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92105, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "报导", "is_correct": true, "explanation": "报导：动词，指记者把新发生的事写出来或说出来告诉大家，此句指记者在现场报道这次比赛。"}, {"text": "隐瞒", "is_correct": false, "explanation": "语义：“隐瞒”指有意不让人知道，与记者现场报道的职责正好相反。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”只接食物，不能说“吃比赛”。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：“撕”接纸张等具体物体，不接比赛这类事件。"}], "explanations": {"报导": "报导：动词，指记者把新发生的事写出来或说出来告诉大家，此句指记者在现场报道这次比赛。", "隐瞒": "语义：“隐瞒”指有意不让人知道，与记者现场报道的职责正好相反。", "吃": "搭配：“吃”只接食物，不能说“吃比赛”。", "撕": "搭配：“撕”接纸张等具体物体，不接比赛这类事件。"}, "sentence_index": 0, "correct_answer": "报导"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在班会上报导了暑假的计划。", "explanation": "这里应该用〈报告〉。报导是媒体把新闻告诉公众，在班会上向大家说明计划要用“报告”。"}, {"text": "班主任报导了这张桌子。", "explanation": "这里应该用〈擦〉。报导的对象须是新发生的事，桌子不是事件，应说“擦”。"}, {"text": "小明每天都报导他的作业。", "explanation": "这里应该用〈交〉。报导只用于把新闻告诉公众，作业要“交”给老师，不能说“报导”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92105, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "报导", "is_correct": true, "explanation": "报导：动词，指新闻媒体把新发生的事告诉大家，此句指新闻里播报明天北京的天气。"}, {"text": "推迟", "is_correct": false, "explanation": "配价：“推迟”需要带宾语，如“推迟比赛”，不能单独带一个小句。"}, {"text": "嘱咐", "is_correct": false, "explanation": "语义：“嘱咐”是对某人叮嘱，新闻不是叮嘱的对象，与句意不合。"}, {"text": "报名", "is_correct": false, "explanation": "搭配：“报名”指登记参加活动，不能用来指新闻播报天气。"}], "explanations": {"报导": "报导：动词，指新闻媒体把新发生的事告诉大家，此句指新闻里播报明天北京的天气。", "推迟": "配价：“推迟”需要带宾语，如“推迟比赛”，不能单独带一个小句。", "嘱咐": "语义：“嘱咐”是对某人叮嘱，新闻不是叮嘱的对象，与句意不合。", "报名": "搭配：“报名”指登记参加活动，不能用来指新闻播报天气。"}, "sentence_index": 6, "correct_answer": "报导"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师在课堂上报导了一个有趣的故事。", "explanation": "这里应该用〈讲〉。报导是媒体向公众发布新闻，在课堂上给学生讲故事要用“讲”。"}, {"text": "老师报导了这道题的解法。", "explanation": "这里应该用〈解释〉。报导不用于向学生说明题目的解法。"}, {"text": "爷爷给我们报导了他小时候的故事。", "explanation": "这里应该用〈讲述〉。报导指发布新闻，家人之间讲述童年往事要用“讲述”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92105, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "电视台正在报导了这场足球比赛。", "corrected_sentence": "电视台正在报导这场足球比赛。", "error_description": "错误：“正在”表示动作进行中，“报导”之后不能再加表示完成的“了”。正确：“电视台正在报导这场足球比赛”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92105, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每天晚上电台都报导了股市行情。", "corrected_sentence": "每天晚上电台都报导股市行情。", "error_description": "错误：“报导”前有表示习惯的“每天”，不能加表示完成的“了”。正确：“每天晚上电台都报导股市行情”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
