INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92106, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "报纸、广播、电视上刊出的一篇新闻稿，即向公众报道新闻的文字。", "primary_collocate": null, "pronunciation": "bào dǎo", "ipa": "pau˥˩ tau˨˩˦", "syllable_count": 2, "sentences": [{"text": "这篇报导写得很清楚。", "target_word": "报导", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我今天看了一篇关于大熊猫的报导。", "target_word": "报导", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这则报导让很多人很吃惊。", "target_word": "报导", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "报纸上有一条关于天气的报导。", "target_word": "报导", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把这篇报导读了两遍。", "target_word": "报导", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者写的报导登在今天的报纸上。", "target_word": "报导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上这篇报导，记者写得很详细。", "target_word": "报导", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "关于这次比赛的报导，电视和报纸上都有。", "target_word": "报导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条报导说，明年地铁会开到海边。", "target_word": "报导", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在网上找到了几篇有关这件事的报导。", "target_word": "报导", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一篇报导", "label": "量词"}, {"form": "一则报导", "label": "量词"}, {"form": "新闻报导", "label": "复合"}, {"form": "報導", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：报纸、广播、电视上刊出的一篇新闻稿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f82317-b64b-4c72-a0db-f7ebe4e148f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92106, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "报导", "is_correct": true, "explanation": "报导：名词，指报纸、广播、电视上刊出的一篇新闻稿，此句指这篇新闻稿写得清楚。"}, {"text": "比赛", "is_correct": false, "explanation": "搭配：量词“篇”只用于文章类，比赛不能用“篇”计量，也不能“写得很清楚”。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“房子”的量词是“座”或“栋”，不用“篇”，房子也不能“写得很清楚”。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，不是可以“写得很清楚”的文字。"}], "explanations": {"报导": "报导：名词，指报纸、广播、电视上刊出的一篇新闻稿，此句指这篇新闻稿写得清楚。", "比赛": "搭配：量词“篇”只用于文章类，比赛不能用“篇”计量，也不能“写得很清楚”。", "房子": "搭配：“房子”的量词是“座”或“栋”，不用“篇”，房子也不能“写得很清楚”。", "蛋糕": "语义：蛋糕是食物，不是可以“写得很清楚”的文字。"}, "sentence_index": 0, "correct_answer": "报导"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师布置了一篇读书报导。", "explanation": "这里应该用〈报告〉。报导是媒体发布的新闻稿，学生交的读书心得要用“报告”。"}, {"text": "我收到了一篇生日报导。", "explanation": "这里应该用〈贺卡〉。报导是新闻稿，生日的祝福要用“贺卡”，不能说“报导”。"}, {"text": "这个报导的味道很甜。", "explanation": "这里应该用〈蛋糕〉。报导是新闻稿，不能用“甜”形容它的味道；甜味属于食物，应说“这个蛋糕的味道很甜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92106, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "报导", "is_correct": true, "explanation": "报导：名词，指报纸上刊出的一篇新闻稿，此句指记者写的这篇新闻稿很详细。"}, {"text": "节目", "is_correct": false, "explanation": "语义：“节目”是广播、电视的播出内容，报纸上不播节目，也不能“写得详细”。"}, {"text": "照片", "is_correct": false, "explanation": "搭配：“写”用于文字，不能用于照片，照片也不用量词“篇”。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“课本”的量词是“本”，不用“篇”，也不是报纸上的新闻稿。"}], "explanations": {"报导": "报导：名词，指报纸上刊出的一篇新闻稿，此句指记者写的这篇新闻稿很详细。", "节目": "语义：“节目”是广播、电视的播出内容，报纸上不播节目，也不能“写得详细”。", "照片": "搭配：“写”用于文字，不能用于照片，照片也不用量词“篇”。", "课本": "搭配：“课本”的量词是“本”，不用“篇”，也不是报纸上的新闻稿。"}, "sentence_index": 6, "correct_answer": "报导"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一个好报导。", "explanation": "这里应该用〈人〉。报导指新闻稿，不能用来指人；说某人是好人，要用“人”。"}, {"text": "这个报导睡着了。", "explanation": "这里应该用〈小猫〉。报导是文字，不会睡觉；“睡着”只用于人或动物。"}, {"text": "他每天早上都喝一篇报导。", "explanation": "这里应该用〈牛奶〉。报导是文章，不能喝；早上喝的应是牛奶之类的饮品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92106, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只报导的标题很吸引人。", "corrected_sentence": "这篇报导的标题很吸引人。", "error_description": "错误：“报导”是文章，量词应用“篇”，不能用“只”。正确：“这篇报导的标题很吸引人。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92106, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些报导们的内容都很真实。", "corrected_sentence": "这些报导的内容都很真实。", "error_description": "错误：“报导”是指事物的名词，后面不能加“们”表示复数。正确：“这些报导的内容都很真实”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
