INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92107, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "第二个等级。", "primary_collocate": null, "pronunciation": "èr jí", "ipa": "ɚ˥˩ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "这个考试分三个等级，我通过了二级。", "target_word": "二级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的普通话水平是二级。", "target_word": "二级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次的普通话考试，他拿到了二级。", "target_word": "二级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的游泳考试，我女儿过了二级。", "target_word": "二级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一级最高，二级比一级低一点。", "target_word": "二级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的英语证书是二级。", "target_word": "二级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的画画班已经上到二级了。", "target_word": "二级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校的游泳课从一级到二级。", "target_word": "二级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试我考了二级，明年想考三级。", "target_word": "二级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的钢琴已经考到二级了。", "target_word": "二级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "二級", "label": "繁体"}, {"form": "二级公路", "label": "复合"}, {"form": "二级市场", "label": "复合"}], "register": "中性", "sense_fingerprint": "按顺序排列的第二个等级", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '501e030f-9419-4045-ab4d-0d12862286c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92107, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "二级", "is_correct": true, "explanation": "正确：“通过了”后接考试等级，句中指第二个等级。"}, {"text": "证书", "is_correct": false, "explanation": "搭配：“通过”的对象是考试或测验，证书是考过后拿到的，不说通过证书。"}, {"text": "同学", "is_correct": false, "explanation": "语义：“通过”用于考核过关，不能用于人，“同学”不是可以被通过的对象。"}, {"text": "学校", "is_correct": false, "explanation": "语义：“通过”指考核过关，“学校”不是考核对象，句意不通。"}], "explanations": {"二级": "正确：“通过了”后接考试等级，句中指第二个等级。", "证书": "搭配：“通过”的对象是考试或测验，证书是考过后拿到的，不说通过证书。", "同学": "语义：“通过”用于考核过关，不能用于人，“同学”不是可以被通过的对象。", "学校": "语义：“通过”指考核过关，“学校”不是考核对象，句意不通。"}, "sentence_index": 0, "correct_answer": "二级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在作文比赛中拿到了二级奖。", "explanation": "这里应该用〈二等〉。奖项的名次要说“二等奖”，“二级”只表示等级，不用作奖项名次。"}, {"text": "他在比赛里拿了二级。", "explanation": "这里应该用〈第二名〉。比赛名次说“第二名”，“二级”表示等级，不表示名次。"}, {"text": "他今年上二级，是小学生。", "explanation": "这里应该用〈二年级〉。学校的年级要说“二年级”，“二级”表示等级，不表示年级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92107, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "二级", "is_correct": true, "explanation": "正确：“上到”后接年级或等级，句中指画画班的第二个等级。"}, {"text": "证书", "is_correct": false, "explanation": "搭配：“上到”用于年级、等级或课程，不说上到证书。"}, {"text": "老师", "is_correct": false, "explanation": "语义：“上到”指学习进阶，人不能被“上到”，“老师”与句意不符。"}, {"text": "游泳池", "is_correct": false, "explanation": "语义：“游泳池”是场所，不是可以上到的阶段，句意不通。"}], "explanations": {"二级": "正确：“上到”后接年级或等级，句中指画画班的第二个等级。", "证书": "搭配：“上到”用于年级、等级或课程，不说上到证书。", "老师": "语义：“上到”指学习进阶，人不能被“上到”，“老师”与句意不符。", "游泳池": "语义：“游泳池”是场所，不是可以上到的阶段，句意不通。"}, "sentence_index": 6, "correct_answer": "二级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次游泳比赛，她得了二级。", "explanation": "这里应该用〈亚军〉。比赛名次说“亚军”，“二级”表示等级，不用于名次。"}, {"text": "他在班里排二级，成绩很好。", "explanation": "这里应该用〈第二位〉。排名要说“排第二位”，“二级”只表示等级，不能用来表示名次。"}, {"text": "我家住在二级，窗户朝南。", "explanation": "这里应该用〈二楼〉。楼层要说“二楼”，“二级”表示等级，不表示楼层。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92107, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我女儿的画画考在二级了。", "corrected_sentence": "我女儿的画画考到二级了。", "error_description": "补语错误：表示考试达到某一等级要用补语“到”，应说“考到二级了”，不说“考在二级了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92107, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他已经考着二级了。", "corrected_sentence": "他已经考过二级了。", "error_description": "体标错误：表示已经有过的考试经历要用“过”，应说“考过二级了”，不说“考着二级了”；“着”表示持续状态，不用于此。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
