INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92108, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "排在第二位的等级。", "primary_collocate": null, "pronunciation": "èr jí", "ipa": "ɚ˥˩ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "这些大米按质量分三级，这批属于二级。", "target_word": "二级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一级太难了，我想先学二级。", "target_word": "二级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水果分三级，这个是二级。", "target_word": "二级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年我们班有五个人通过了二级。", "target_word": "二级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震警报已经从三级升到二级了。", "target_word": "二级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩在二级，离最高级不远。", "target_word": "二级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，我的中文已经是二级了。", "target_word": "二级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "等一级的名额满了，才轮到二级。", "target_word": "二级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说二级考试比一级难多了。", "target_word": "二级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游泳池只给二级的学生用。", "target_word": "二级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "二級", "label": "繁体"}, {"form": "二级公路", "label": "复合"}, {"form": "二级市场", "label": "复合"}], "register": "中性", "sense_fingerprint": "排在第二位的等级", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '501e030f-9419-4045-ab4d-0d12862286c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92108, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "二级", "is_correct": true, "explanation": "正确：“属于”后接等级，句中指这批大米属于第二等级。"}, {"text": "质量", "is_correct": false, "explanation": "语义：“属于”后接类别，“质量”是性质而不是类别，句意不通。"}, {"text": "大学", "is_correct": false, "explanation": "语义：大米按等级分类的语境下，“大学”与句意无关，这批大米不属于大学。"}, {"text": "产地", "is_correct": false, "explanation": "搭配：“属于”后接等级或类别，“产地”不能表示这批大米的等级归属。"}], "explanations": {"二级": "正确：“属于”后接等级，句中指这批大米属于第二等级。", "质量": "语义：“属于”后接类别，“质量”是性质而不是类别，句意不通。", "大学": "语义：大米按等级分类的语境下，“大学”与句意无关，这批大米不属于大学。", "产地": "搭配：“属于”后接等级或类别，“产地”不能表示这批大米的等级归属。"}, "sentence_index": 0, "correct_answer": "二级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在比赛中排在二级，离冠军只差一点。", "explanation": "这里应该用〈第二位〉。名次要说“排在第二位”，“二级”表示等级，不表示名次。"}, {"text": "他的作品拿到了二级奖，很开心。", "explanation": "这里应该用〈二等〉。奖项的名次要说“二等奖”，不用“二级奖”。"}, {"text": "妹妹今年上二级，还是小学生。", "explanation": "这里应该用〈二年级〉。学校的年级要说“二年级”，“二级”表示等级，不表示年级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92108, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "二级", "is_correct": true, "explanation": "正确：“已经是”后接等级，句中指中文水平的第二等级。"}, {"text": "证书", "is_correct": false, "explanation": "搭配：“是”后接水平或等级，不说“我的中文已经是证书了”。"}, {"text": "老师", "is_correct": false, "explanation": "语义：“我的中文”指语言水平，不能说成“老师”，句意不通。"}, {"text": "学校", "is_correct": false, "explanation": "语义：“我的中文”指语言水平，不能说成“学校”，句意不通。"}], "explanations": {"二级": "正确：“已经是”后接等级，句中指中文水平的第二等级。", "证书": "搭配：“是”后接水平或等级，不说“我的中文已经是证书了”。", "老师": "语义：“我的中文”指语言水平，不能说成“老师”，句意不通。", "学校": "语义：“我的中文”指语言水平，不能说成“学校”，句意不通。"}, "sentence_index": 6, "correct_answer": "二级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次跑步比赛，她得了二级。", "explanation": "这里应该用〈亚军〉。比赛名次说“亚军”，“二级”表示等级，不用于名次。"}, {"text": "他在班里排名是二级。", "explanation": "这里应该用〈第二〉。排名要说“第二”，“二级”只表示等级。"}, {"text": "我家住在二级，窗户朝南。", "explanation": "这里应该用〈二楼〉。楼层要说“二楼”，“二级”表示等级，不表示楼层。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92108, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这批草莓是一只二级。", "corrected_sentence": "这批草莓是二级。", "error_description": "量词错误：“二级”是等级，不能用“只”修饰，应说“这批草莓是二级”，不说“是一只二级”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92108, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她去年就考着二级了。", "corrected_sentence": "她去年就考过二级了。", "error_description": "体标错误：表示已有的考试经历要用“过”，应说“考过二级了”；“着”表示持续，不能用于此。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4f7b231-1e3b-4b87-9e66-fc48c2d15079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
