INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92111, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "天使是故事里长着翅膀、心很好的神仙，样子像人。", "primary_collocate": null, "pronunciation": "tiān shǐ", "ipa": "tʰi̯ɛn˥ ʂɻ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "故事里的天使长着一对白翅膀。", "target_word": "天使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图画书上有一个天使。", "target_word": "天使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天使在天上飞，还帮助好人。", "target_word": "天使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹画了一个天使，翅膀很大。", "target_word": "天使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事里的天使心很好。", "target_word": "天使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都喜欢故事里的天使。", "target_word": "天使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上，天使飞到小女孩的窗前。", "target_word": "天使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "圣诞树上挂着一个天使。", "target_word": "天使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里的天使送给小男孩一朵花。", "target_word": "天使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，那个天使的翅膀是金色的。", "target_word": "天使", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "小天使", "label": "复合"}], "register": "通用", "sense_fingerprint": "故事里长翅膀、心地善良、像人的神仙", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b94b613-bc01-4765-9f44-061a986e4dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92111, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头没有翅膀，不会“长着一对白翅膀”。"}, {"text": "天使", "is_correct": true, "explanation": "正确：故事里的小人长着翅膀，符合句意。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：“长着翅膀”的主语须是有生命的生物，河流不能“长”翅膀。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不是生物，不会长翅膀。"}], "explanations": {"石头": "语义：石头没有翅膀，不会“长着一对白翅膀”。", "天使": "正确：故事里的小人长着翅膀，符合句意。", "河流": "搭配：“长着翅膀”的主语须是有生命的生物，河流不能“长”翅膀。", "桌子": "语义：桌子不是生物，不会长翅膀。"}, "sentence_index": 0, "correct_answer": "天使"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "道士画了一道符，想请来一位没有翅膀的天使。", "explanation": "这里应该用〈神仙〉。天使须长着翅膀，此处说“没有翅膀”，与其定义不符。"}, {"text": "故事里的天使很坏，总是欺负小孩。", "explanation": "这里应该用〈魔鬼〉。天使心很好，欺负小孩的坏角色要用魔鬼。"}, {"text": "寺庙里供着一位天使，他没有翅膀，手里拿着念珠。", "explanation": "这里应该用〈菩萨〉。天使须长着翅膀，此处说“没有翅膀”，与其定义不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92111, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "汽车", "is_correct": false, "explanation": "语义：汽车不会飞，不能飞到窗前。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会飞，与“飞到窗前”冲突。"}, {"text": "天使", "is_correct": true, "explanation": "正确：故事里的天使会飞，符合句意。"}, {"text": "河水", "is_correct": false, "explanation": "搭配：“飞”的主语须能飞行，河水不能“飞到”窗前。"}], "explanations": {"汽车": "语义：汽车不会飞，不能飞到窗前。", "石头": "语义：石头不会飞，与“飞到窗前”冲突。", "天使": "正确：故事里的天使会飞，符合句意。", "河水": "搭配：“飞”的主语须能飞行，河水不能“飞到”窗前。"}, "sentence_index": 6, "correct_answer": "天使"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "故事里有一个天使，长着长长的尾巴，在水里游。", "explanation": "这里应该用〈人鱼〉。天使长着翅膀会飞，在水里游、有尾巴的是人鱼。"}, {"text": "东海里住着一位天使，他没有翅膀，却能在海底游泳。", "explanation": "这里应该用〈人鱼〉。天使须长着翅膀，此处说“没有翅膀”，与其定义不符。"}, {"text": "村里的老人说，村后的老树下住着一位天使，她没有翅膀，专门保佑孩子。", "explanation": "这里应该用〈狐仙〉。天使须长着翅膀，此处说“没有翅膀”，与其定义不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92111, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那条天使住在云朵上面。", "corrected_sentence": "那个天使住在云朵上面。", "error_description": "错误：“天使”作量词搭配应用“个”（或“位”），“条”用于细长的东西。错误形式“那条天使”，正确形式“那个天使”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92111, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一条天使从天上飞下来。", "corrected_sentence": "一位天使从天上飞下来。", "error_description": "“天使”作量词搭配应用“位”（或“个”），“条”用于细长的东西。错误形式“一条天使”，正确形式“一位天使”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92112, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "老师", "is_correct": false, "explanation": "与“天使”没有反义关系，“老师”指教书育人的人。"}, {"text": "魔鬼", "is_correct": true, "explanation": "反义：魔鬼与天使相对，指凶恶残忍的人或邪恶的神灵。"}, {"text": "石头", "is_correct": false, "explanation": "与“天使”没有反义关系，石头只是普通的自然物。"}, {"text": "花园", "is_correct": false, "explanation": "与“天使”没有反义关系，花园是一个地方。"}], "correct_answer": "魔鬼", "explanations": {"老师": "与“天使”没有反义关系，“老师”指教书育人的人。", "魔鬼": "反义：魔鬼与天使相对，指凶恶残忍的人或邪恶的神灵。", "石头": "与“天使”没有反义关系，石头只是普通的自然物。", "花园": "与“天使”没有反义关系，花园是一个地方。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92112, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "河流", "is_correct": false, "explanation": "与“天使”没有反义关系，河流是自然景物。"}, {"text": "恶魔", "is_correct": true, "explanation": "反义：恶魔与天使相对，指凶恶残忍的人。"}, {"text": "窗户", "is_correct": false, "explanation": "与“天使”没有反义关系，窗户是建筑部件。"}, {"text": "钢笔", "is_correct": false, "explanation": "与“天使”没有反义关系，钢笔是书写工具。"}], "correct_answer": "恶魔", "explanations": {"河流": "与“天使”没有反义关系，河流是自然景物。", "恶魔": "反义：恶魔与天使相对，指凶恶残忍的人。", "窗户": "与“天使”没有反义关系，窗户是建筑部件。", "钢笔": "与“天使”没有反义关系，钢笔是书写工具。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92112, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "宗教和神话中传达神意的使者，常被描绘成长有翅膀的善良形象；也比喻美好善良的人。", "primary_collocate": null, "pronunciation": "tiān shǐ", "ipa": "tʰi̯ɛn˥ ʂɻ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "在很多宗教里，天使是神的使者。", "target_word": "天使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "圣经里的天使给她带来了好消息。", "target_word": "天使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画家把天使画成长着翅膀的样子。", "target_word": "天使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士像天使一样照顾着病人。", "target_word": "天使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是我们家的天使，大家都爱她。", "target_word": "天使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位医生是病人心中的天使。", "target_word": "天使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教堂的墙上画着很多天使。", "target_word": "天使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在困难的时候，他是我的天使。", "target_word": "天使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，天使会保护好人。", "target_word": "天使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个女孩心地善良，大家叫她天使。", "target_word": "天使", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "天使们", "label": "复数"}], "register": "通用", "sense_fingerprint": "宗教中神的使者；比喻善良美好的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b94b613-bc01-4765-9f44-061a986e4dc9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92112, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "神", "is_correct": false, "explanation": "语义：“神”本身是派遣使者的主，“神的使者”不能指神自己。"}, {"text": "教堂", "is_correct": false, "explanation": "语义：教堂是建筑，不是神的使者。"}, {"text": "天使", "is_correct": true, "explanation": "正确：天使是宗教中传达神意的使者，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“是……的使者”要求主语是人或灵，石头不能担任。"}], "explanations": {"神": "语义：“神”本身是派遣使者的主，“神的使者”不能指神自己。", "教堂": "语义：教堂是建筑，不是神的使者。", "天使": "正确：天使是宗教中传达神意的使者，符合句意。", "石头": "搭配：“是……的使者”要求主语是人或灵，石头不能担任。"}, "sentence_index": 0, "correct_answer": "天使"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天使掌管着生死簿，决定人的寿命。", "explanation": "这里应该用〈阎王〉。生死簿、寿命是中国民间的说法，天使属西方宗教，此处不这么用。"}, {"text": "他心肠很坏，常常害人，大家都叫他天使。", "explanation": "这里应该用〈恶魔〉。天使比喻善良的人，坏心肠、害人的人要叫恶魔。"}, {"text": "天使是一种蔬菜，可以炒着吃。", "explanation": "这里应该用〈白菜〉。天使是神的使者，不是蔬菜，“炒着吃”应接蔬菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92112, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饺子", "is_correct": false, "explanation": "语义：饺子不是教堂墙上常见的画作内容，与“教堂”的语境冲突。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不宜画在教堂的墙上，与“教堂”的语境冲突。"}, {"text": "天使", "is_correct": true, "explanation": "正确：教堂墙上常画天使，符合句意。"}, {"text": "超市", "is_correct": false, "explanation": "搭配：“画着很多”后面多接人物或图案，超市是场所，不宜这样用。"}], "explanations": {"饺子": "语义：饺子不是教堂墙上常见的画作内容，与“教堂”的语境冲突。", "汽车": "语义：汽车不宜画在教堂的墙上，与“教堂”的语境冲突。", "天使": "正确：教堂墙上常画天使，符合句意。", "超市": "搭配：“画着很多”后面多接人物或图案，超市是场所，不宜这样用。"}, "sentence_index": 6, "correct_answer": "天使"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个人又凶又坏，真是个天使。", "explanation": "这里应该用〈魔鬼〉。天使比喻善良美好的人，又凶又坏的人要说魔鬼。"}, {"text": "花果山上的天使是一只猴子，喜欢吃桃子。", "explanation": "这里应该用〈猴王〉。天使是神的使者，此处描写的是猴子。"}, {"text": "中国古代神话里，天使是一块大石头，掌管着人间的雨水。", "explanation": "这里应该用〈雨师〉。雨师掌管雨水，而天使是神的使者，不是石头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92112, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家都称她为一条天使。", "corrected_sentence": "大家都称她为一位天使。", "error_description": "“天使”作量词搭配应用“位”（或“个”），“条”用于细长的东西。错误形式“一条天使”，正确形式“一位天使”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92112, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在我心里，他是一条善良的天使。", "corrected_sentence": "在我心里，他是一位善良的天使。", "error_description": "“天使”作量词搭配应用“位”（或“个”），“条”用于细长的东西。错误形式“一条善良的天使”，正确形式“一位善良的天使”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8611fb52-b29d-4fcb-9290-183077bad01f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
