INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92113, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "后设是讲这件事本身的事。", "primary_collocate": null, "pronunciation": "hòu shè", "ipa": "xou˥˩ ʂɤ˥˩", "syllable_count": 2, "sentences": [{"text": "这部电影很后设，讲的是拍电影的故事。", "target_word": "后设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写的这本小说很后设。", "target_word": "后设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的写法很后设。", "target_word": "后设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这是一种后设的写法。", "target_word": "后设", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我喜欢看后设的电影。", "target_word": "后设", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个故事很后设，作者自己也在故事里。", "target_word": "后设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用后设的方式讲了这个故事。", "target_word": "后设", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这出戏有很多后设的地方。", "target_word": "后设", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "演员对着观众说话，这样的演法很后设。", "target_word": "后设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种故事写得很后设，我第一次看到。", "target_word": "后设", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "後設", "label": "繁体"}], "register": "书面", "sense_fingerprint": "后设：作品或事情讲的是它自己本身，如后设电影、后设小说", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91424016-136b-4dbb-8616-3939a22b04a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92113, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "后视", "is_correct": false, "explanation": "后视（hòushì）与后设（hòu shè）第二音节韵母不同（ì/è），意思是向后看，如后视镜。"}, {"text": "厚实", "is_correct": false, "explanation": "厚实（hòushí）与后设（hòu shè）第二音节韵母不同（í/è），意思是厚而结实。"}, {"text": "喉舌", "is_correct": false, "explanation": "喉舌（hóushé）两个音节声调都与后设（hòu shè）不同，意思是发声器官，也比喻代人说话的人。"}, {"text": "后设", "is_correct": true, "explanation": "后设：作品或事情讲的是它自己本身，正确答案。"}], "explanations": {"后视": "后视（hòushì）与后设（hòu shè）第二音节韵母不同（ì/è），意思是向后看，如后视镜。", "厚实": "厚实（hòushí）与后设（hòu shè）第二音节韵母不同（í/è），意思是厚而结实。", "喉舌": "喉舌（hóushé）两个音节声调都与后设（hòu shè）不同，意思是发声器官，也比喻代人说话的人。", "后设": "后设：作品或事情讲的是它自己本身，正确答案。"}, "sentence_index": null, "correct_answer": "后设"}, "level_3": {"options": [{"text": "后设", "is_correct": true, "explanation": "正确：后设指作品讲的是它自己，与“讲的是拍电影的故事”相符。"}, {"text": "高", "is_correct": false, "explanation": "体貌：“高”形容人或物体的高度，不能用来形容一部电影。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”是味觉，电影没有咸淡，不能这样形容。"}, {"text": "饿", "is_correct": false, "explanation": "语义：“饿”形容人的饥饿感，不能用来形容一部电影。"}], "explanations": {"后设": "正确：后设指作品讲的是它自己，与“讲的是拍电影的故事”相符。", "高": "体貌：“高”形容人或物体的高度，不能用来形容一部电影。", "咸": "语义：“咸”是味觉，电影没有咸淡，不能这样形容。", "饿": "语义：“饿”形容人的饥饿感，不能用来形容一部电影。"}, "sentence_index": 0, "correct_answer": "后设"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市的建筑很后设。", "explanation": "这里应该用〈后现代〉。后设指作品或事情讲的是它自己，建筑不能这样形容；〈后现代〉才用于形容建筑风格。"}, {"text": "这家店的装修很后设。", "explanation": "这里应该用〈前卫〉。后设不用于形容店铺装修，〈前卫〉指新颖超前的风格。"}, {"text": "这件衣服很后设。", "explanation": "这里应该用〈复古〉。后设只形容讲自身的作品或事情，不能形容衣服的风格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b2bf2e-59d7-411a-9869-74a291039784') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92113, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "后事", "is_correct": false, "explanation": "后事（hòushì）与后设（hòu shè）第二音节韵母不同（ì/è），意思是身后的事务。"}, {"text": "后世", "is_correct": false, "explanation": "后世（hòushì）与后设（hòu shè）第二音节韵母不同（ì/è），意思是后代、将来的时代。"}, {"text": "后市", "is_correct": false, "explanation": "后市（hòushì）与后设（hòu shè）第二音节韵母不同（ì/è），意思是今后的市场走势。"}, {"text": "后设", "is_correct": true, "explanation": "后设：作品或事情讲的是它自己本身，正确答案。"}], "explanations": {"后事": "后事（hòushì）与后设（hòu shè）第二音节韵母不同（ì/è），意思是身后的事务。", "后世": "后世（hòushì）与后设（hòu shè）第二音节韵母不同（ì/è），意思是后代、将来的时代。", "后市": "后市（hòushì）与后设（hòu shè）第二音节韵母不同（ì/è），意思是今后的市场走势。", "后设": "后设：作品或事情讲的是它自己本身，正确答案。"}, "sentence_index": null, "correct_answer": "后设"}, "level_3": {"options": [{"text": "后设", "is_correct": true, "explanation": "正确：后设修饰“方式”，指用讲作品自身的方式讲故事，与句意相符。"}, {"text": "圆", "is_correct": false, "explanation": "体貌：“圆”指物体的形状，不能用来修饰“方式”。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”形容人或动物的体形，不能用来修饰“方式”。"}, {"text": "湿", "is_correct": false, "explanation": "语义：“湿”指含有水分，用来修饰“方式”说不通。"}], "explanations": {"后设": "正确：后设修饰“方式”，指用讲作品自身的方式讲故事，与句意相符。", "圆": "体貌：“圆”指物体的形状，不能用来修饰“方式”。", "胖": "体貌：“胖”形容人或动物的体形，不能用来修饰“方式”。", "湿": "语义：“湿”指含有水分，用来修饰“方式”说不通。"}, "sentence_index": 6, "correct_answer": "后设"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他后设地跑了一圈。", "explanation": "这里应该用〈飞快〉。后设指讲作品或事情自身，不能修饰跑步；〈飞快〉才描写跑的速度。"}, {"text": "她后设地唱了一首歌。", "explanation": "这里应该用〈大声〉。后设指讲作品或事情自身，不能修饰唱歌；〈大声〉才描写唱的方式。"}, {"text": "这个孩子很后设，总爱吃糖。", "explanation": "这里应该用〈馋〉。后设指讲作品或事情自身，不能形容孩子的性格；〈馋〉指爱吃，正合“总爱吃糖”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b2bf2e-59d7-411a-9869-74a291039784') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92113, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "作者用后设地手法来写这个故事。", "corrected_sentence": "作者用后设的手法来写这个故事。", "error_description": "“后设”修饰名词“手法”时应用“的”，写成“地”是错误的（“地”用于修饰动词）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b2bf2e-59d7-411a-9869-74a291039784') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
