INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92114, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指对事物自身进行再一层说明的，如后设语言。", "primary_collocate": null, "pronunciation": "hòu shè", "ipa": "xou˥˩ ʂɤ˥˩", "syllable_count": 2, "sentences": [{"text": "这句话很后设，它在谈论这句话本身。", "target_word": "后设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师从后设的角度解释这个词。", "target_word": "后设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这门课讲的是后设的思考。", "target_word": "后设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对自己的想法做了后设的思考。", "target_word": "后设", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "想一想自己怎么想，这种想法很后设。", "target_word": "后设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一个后设的问题，在问问题本身。", "target_word": "后设", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对这份分析做了后设的检查。", "target_word": "后设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里有一段后设的说明。", "target_word": "后设", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用中文讲中文语法，这就很后设了。", "target_word": "后设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从后设的角度看这件事。", "target_word": "后设", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "後設", "label": "繁体"}], "register": "书面", "sense_fingerprint": "后设：对事物自身再作一层说明的，如后设语言、后设认知", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91424016-136b-4dbb-8616-3939a22b04a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
