INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92114, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份报告用后设地方式来写。", "corrected_sentence": "这份报告用后设的方式来写。", "error_description": "“后设”修饰名词“方式”时应用“的”，写成“地”是错误的（“地”用于修饰动词）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b2bf2e-59d7-411a-9869-74a291039784') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
