INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92115, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人的脾气和品德。", "primary_collocate": null, "pronunciation": "rén gé", "ipa": "ʐən˧˥ kɤ˧˥", "syllable_count": 2, "sentences": [{"text": "他人格很好，大家都愿意和他做朋友。", "target_word": "人格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师人格高尚，学生们都很敬佩他。", "target_word": "人格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看一个人，要看他的人格，不只看他有没有钱。", "target_word": "人格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的人格魅力让大家都喜欢她。", "target_word": "人格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很欣赏他的人格，他善良又诚实。", "target_word": "人格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷一生诚实，他的人格影响了全家人。", "target_word": "人格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好老师的人格对学生有很大影响。", "target_word": "人格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的人格怎么样，朋友们最清楚。", "target_word": "人格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人人格不好，经常骗别人。", "target_word": "人格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做人要有好人格，才会受人尊敬。", "target_word": "人格", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人格魅力", "label": "复合词"}, {"form": "人格尊严", "label": "复合词"}], "register": "书面", "sense_fingerprint": "指一个人的为人、品德和性情，常说人格高尚、人格魅力、人格好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6364b06-5bd6-4d7a-9892-29c9666e0942') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92115, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人格", "is_correct": true, "explanation": "“人格”指一个人的为人与品德，“很好”评价的正是这一点，句意通顺。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“很好”不用于评价身高，不能说身高很好。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人的属性，“他天气很好”句意不通。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不是人的品德或为人，“他书包很好”句意不通。"}], "explanations": {"人格": "“人格”指一个人的为人与品德，“很好”评价的正是这一点，句意通顺。", "身高": "搭配：“很好”不用于评价身高，不能说身高很好。", "天气": "语义：天气不是人的属性，“他天气很好”句意不通。", "书包": "语义：书包不是人的品德或为人，“他书包很好”句意不通。"}, "sentence_index": 0, "correct_answer": "人格"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这箱书的人格很重，我一个人搬不动。", "explanation": "这里应该用〈重量〉。“人格”只指人的性格和品质，说物体的轻重要用〈重量〉。"}, {"text": "这套房子的人格很大，住了一家五口。", "explanation": "这里应该用〈面积〉。「人格」只指人的脾气和品德，说房子的大小要用〈面积〉。"}, {"text": "这台电脑的人格很好，运行得很快。", "explanation": "这里应该用〈性能〉。「人格」只指人的脾气和品德，说机器好不好用要用〈性能〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92115, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人格", "is_correct": true, "explanation": "“人格”指老师的为人与品德，能够对学生产生影响，句意通顺。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟不是老师的品质，不能对学生产生“很大影响”。"}, {"text": "粉笔", "is_correct": false, "explanation": "语义：粉笔是教具，不是老师的品质，句意不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“好老师的”修饰的应是品德或为人，不能修饰体重。"}], "explanations": {"人格": "“人格”指老师的为人与品德，能够对学生产生影响，句意通顺。", "闹钟": "语义：闹钟不是老师的品质，不能对学生产生“很大影响”。", "粉笔": "语义：粉笔是教具，不是老师的品质，句意不通。", "体重": "搭配：“好老师的”修饰的应是品德或为人，不能修饰体重。"}, "sentence_index": 6, "correct_answer": "人格"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在公司的人格是部门经理。", "explanation": "这里应该用〈身份〉。人格指品德与为人，说一个人的职务、角色要用〈身份〉。"}, {"text": "这件衣服的人格很贵，我买不起。", "explanation": "这里应该用〈价格〉。人格只指人的品德与为人，不能用来说衣服的贵贱。"}, {"text": "这位歌手的人格很响，很多人都认识他。", "explanation": "这里应该用〈名气〉。「人格」只指人的脾气和品德，说一个人有名气要用〈名气〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92115, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位长辈人格影响了很多年轻人。", "corrected_sentence": "这位长辈的人格影响了很多年轻人。", "error_description": "漏掉了“的”。应为“长辈的人格”，定语“长辈”与中心词“人格”之间需要“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92115, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村里的人都很敬佩奶奶人格。", "corrected_sentence": "村里的人都很敬佩奶奶的人格。", "error_description": "漏掉了“的”。“奶奶”是“人格”的定语，作宾语时中间需要“的”，应为“奶奶的人格”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
