INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92116, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "个人稳定的性格、品质和尊严的总和。", "primary_collocate": null, "pronunciation": "rén gé", "ipa": "ʐən˧˥ kɤ˧˥", "syllable_count": 2, "sentences": [{"text": "我们应该尊重每个人的人格。", "target_word": "人格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话伤害了我的人格。", "target_word": "人格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律保护公民的人格尊严。", "target_word": "人格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不能因为别人穷，就不尊重他的人格。", "target_word": "人格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板当着大家骂人，是对员工人格的不尊重。", "target_word": "人格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子也有自己的人格，父母要尊重他。", "target_word": "人格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样做是在侮辱他的人格。", "target_word": "人格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人格平等，是每个人都应有的权利。", "target_word": "人格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她努力工作，保持着自己独立的人格。", "target_word": "人格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他宁可不要钱，也不愿失去人格。", "target_word": "人格", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人格尊严", "label": "复合词"}, {"form": "人格魅力", "label": "复合词"}], "register": "书面", "sense_fingerprint": "强调个人的尊严和独立，常说尊重人格、侮辱人格、人格平等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b6364b06-5bd6-4d7a-9892-29c9666e0942') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92116, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人格", "is_correct": true, "explanation": "“人格”指个人的品德与尊严，“尊重”针对的正是人格，句意通顺。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“尊重”的对象是人或人的权利、感受，不能说尊重价格。"}, {"text": "温度", "is_correct": false, "explanation": "语义：人的温度不是可以被“尊重”的对象，“尊重每个人的温度”语义不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：人的颜色不是可以被“尊重”的对象，句意不通。"}], "explanations": {"人格": "“人格”指个人的品德与尊严，“尊重”针对的正是人格，句意通顺。", "价格": "搭配：“尊重”的对象是人或人的权利、感受，不能说尊重价格。", "温度": "语义：人的温度不是可以被“尊重”的对象，“尊重每个人的温度”语义不通。", "颜色": "语义：人的颜色不是可以被“尊重”的对象，句意不通。"}, "sentence_index": 0, "correct_answer": "人格"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条河的人格很深，船很难过去。", "explanation": "这里应该用〈深度〉。「人格」只指人的性格、品质和尊严，说河的深浅要用〈深度〉。"}, {"text": "他的人格很高兴，大家都笑了。", "explanation": "这里应该用〈心情〉。「人格」指稳定的性格与品质，说一时的高兴要用〈心情〉。"}, {"text": "他对这件事的人格很认真，大家都佩服他。", "explanation": "这里应该用〈态度〉。「人格」指性格与品质，说对事情的看法和做法要用〈态度〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92116, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人格", "is_correct": true, "explanation": "“人格”是人的品德与尊严，“侮辱”针对的正是这一点，句意通顺。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能被“侮辱”，“侮辱他的天气”句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是可以被“侮辱”的对象，句意荒谬。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子不是可以被“侮辱”的对象，句意荒谬。"}], "explanations": {"人格": "“人格”是人的品德与尊严，“侮辱”针对的正是这一点，句意通顺。", "天气": "语义：天气不能被“侮辱”，“侮辱他的天气”句意不通。", "颜色": "语义：颜色不是可以被“侮辱”的对象，句意荒谬。", "影子": "语义：影子不是可以被“侮辱”的对象，句意荒谬。"}, "sentence_index": 6, "correct_answer": "人格"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的人格是学生，每天要上课。", "explanation": "这里应该用〈身份〉。人格指人的品德和尊严，说一个人的社会角色要用〈身份〉。"}, {"text": "这套邮票的人格很高，收藏家都想买。", "explanation": "这里应该用〈价值〉。人格只指人的品德和尊严，不能用来说物品的高低。"}, {"text": "这家公司的人格很大，大家都想进去。", "explanation": "这里应该用〈规模〉。「人格」只指人的性格与品质，说公司的大小要用〈规模〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92116, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师应该尊重每个学生人格。", "corrected_sentence": "老师应该尊重每个学生的人格。", "error_description": "漏掉了“的”。“每个学生人格”应为“每个学生的人格”，“的”用来连接定语“每个学生”和中心词“人格”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92116, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位校长有一只高尚的人格，学生都很敬佩。", "corrected_sentence": "这位校长有一种高尚的人格，学生都很敬佩。", "error_description": "量词用错：“人格”应用“种”，“只”多用于动物等，不用于抽象的人格。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '799d03a2-8908-4561-85af-468aaefa8264') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
