INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92117, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "得令是接到了命令。", "primary_collocate": null, "pronunciation": "dé lìng", "ipa": "tɤ˧˥ liŋ˥˩", "syllable_count": 2, "sentences": [{"text": "得令以后，士兵马上出发了。", "target_word": "得令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将军一声令下，他得令就走。", "target_word": "得令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队长得令，带着大家向山上跑去。", "target_word": "得令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚一得令，就骑马出了城。", "target_word": "得令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "得令后，警察很快到了现场。", "target_word": "得令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部队得令，连夜向北边出发。", "target_word": "得令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他得令以后一句话也没说。", "target_word": "得令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船长得令，马上让船靠了岸。", "target_word": "得令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一得令，消防员就上了车。", "target_word": "得令", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老将军说：“得令！我这就去办。”", "target_word": "得令", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "动词：接到上级的命令，多见于军队、官府等场合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552319c8-d678-4547-b1ce-dbccda73abfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92117, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "得令", "is_correct": true, "explanation": "dé lìng，接到上级的命令，正确答案。"}, {"text": "得病", "is_correct": false, "explanation": "bìng（第四声）与 lìng 声母不同，得病意思是患病，不是接到命令。"}, {"text": "得名", "is_correct": false, "explanation": "míng（第二声）与 lìng 声母和声调都不同，得名意思是获得名声。"}, {"text": "得力", "is_correct": false, "explanation": "dé lì，与 dé lìng 只差韵尾 -n / -ng，意思是能干、起作用，不是接到命令。"}], "explanations": {"得令": "dé lìng，接到上级的命令，正确答案。", "得病": "bìng（第四声）与 lìng 声母不同，得病意思是患病，不是接到命令。", "得名": "míng（第二声）与 lìng 声母和声调都不同，得名意思是获得名声。", "得力": "dé lì，与 dé lìng 只差韵尾 -n / -ng，意思是能干、起作用，不是接到命令。"}, "sentence_index": null, "correct_answer": "得令"}, "level_3": {"options": [{"text": "得令", "is_correct": true, "explanation": "接到命令，与后句“士兵马上出发了”相符。"}, {"text": "受伤", "is_correct": false, "explanation": "语义：受伤之后很难马上出发，与后句“马上出发了”矛盾。"}, {"text": "卧床", "is_correct": false, "explanation": "语义：卧床不起之后，士兵不可能马上出发，与后句矛盾。"}, {"text": "退伍", "is_correct": false, "explanation": "语义：退伍意味着离开部队，与“士兵马上出发”矛盾。"}], "explanations": {"得令": "接到命令，与后句“士兵马上出发了”相符。", "受伤": "语义：受伤之后很难马上出发，与后句“马上出发了”矛盾。", "卧床": "语义：卧床不起之后，士兵不可能马上出发，与后句矛盾。", "退伍": "语义：退伍意味着离开部队，与“士兵马上出发”矛盾。"}, "sentence_index": 0, "correct_answer": "得令"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在比赛中得令了。", "explanation": "这里应该用〈得分〉。“得令”指接到上级的命令，不能用于比赛中得分。"}, {"text": "皇帝得令处死了那位大臣。", "explanation": "这里应该用〈下令〉。得令是接受上级的命令，皇帝是发令的人，不能说“得令”。"}, {"text": "我自己得令，决定明天早点睡。", "explanation": "这里应该用〈自行安排〉。“得令”必须是从上级接到命令，自己给自己定的事不能说得令。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f98bd86-ea85-4cd9-9ac2-9b979a6f3ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92117, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "得令", "is_correct": true, "explanation": "接到命令，与“一句话也没说”的情境相符。"}, {"text": "桌子", "is_correct": false, "explanation": "词性：“桌子”是名词，不能作谓语放在“他……以后”中。"}, {"text": "非常", "is_correct": false, "explanation": "词性：“非常”是程度副词，不能单独作谓语。"}, {"text": "已经", "is_correct": false, "explanation": "词性：“已经”是副词，后面必须接动词，不能直接接“以后”。"}], "explanations": {"得令": "接到命令，与“一句话也没说”的情境相符。", "桌子": "词性：“桌子”是名词，不能作谓语放在“他……以后”中。", "非常": "词性：“非常”是程度副词，不能单独作谓语。", "已经": "词性：“已经”是副词，后面必须接动词，不能直接接“以后”。"}, "sentence_index": 6, "correct_answer": "得令"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块石头得令，滚下了山坡。", "explanation": "这里应该用〈掉落〉。“得令”只指人接到上级的命令，石头不能得令。"}, {"text": "这件衣服得令，穿在身上很合适。", "explanation": "这里应该用〈合身〉。“得令”只指人接到上级的命令，衣服不能得令。"}, {"text": "雨水得令，洒满了大地。", "explanation": "这里应该用〈降落〉。“得令”只指人接到上级的命令，雨水不能得令。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f98bd86-ea85-4cd9-9ac2-9b979a6f3ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92117, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "队长把得令后，立刻带队出发了。", "corrected_sentence": "队长得令后，立刻带队出发了。", "error_description": "“得令”是不及物动词，不能放在“把”字句的动词位置；应说“队长得令后”，去掉“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f98bd86-ea85-4cd9-9ac2-9b979a6f3ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92117, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "士兵被得令，马上出发了。", "corrected_sentence": "士兵得令，马上出发了。", "error_description": "“得令”是不及物动词，不能用“被”字句，应说“士兵得令”，去掉“被”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f98bd86-ea85-4cd9-9ac2-9b979a6f3ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
