INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92119, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "好起来是原来不好，慢慢变好了。", "primary_collocate": null, "pronunciation": "hǎo qǐ lái", "ipa": "xɑʊ˨˩ tɕʰi˨˩ laɪ˨˦", "syllable_count": 3, "sentences": [{"text": "妈妈的病慢慢好起来了。", "target_word": "好起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃了药，他的身体好起来了。", "target_word": "好起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了音乐，我的心情好起来了。", "target_word": "好起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的胃口好起来，能吃很多饭。", "target_word": "好起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡了一觉，我的头疼好起来了。", "target_word": "好起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的腿好起来，又能散步了。", "target_word": "好起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的感冒好起来了。", "target_word": "好起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住了一个月医院，他才好起来。", "target_word": "好起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到好消息，他的脸色好起来了。", "target_word": "好起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的咳嗽慢慢好起来了。", "target_word": "好起来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "好起来了", "label": "体标"}], "register": "中性", "sense_fingerprint": "好起来：人的身体、心情原来不好，慢慢恢复", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68b6fea3-2699-4510-9ab1-0d36748570eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92119, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好起来", "is_correct": true, "explanation": "正确：“好起来”表示身体由差变好，此处指妈妈的病逐渐好转。"}, {"text": "下起来", "is_correct": false, "explanation": "搭配：“下起来”只用于雨、雪，不能用于病。"}, {"text": "变胖", "is_correct": false, "explanation": "语义：“变胖”指体形变胖，与病情无关，句子不通。"}, {"text": "长大", "is_correct": false, "explanation": "语义：“长大”指人或事物成长，病不能长大。"}], "explanations": {"好起来": "正确：“好起来”表示身体由差变好，此处指妈妈的病逐渐好转。", "下起来": "搭配：“下起来”只用于雨、雪，不能用于病。", "变胖": "语义：“变胖”指体形变胖，与病情无关，句子不通。", "长大": "语义：“长大”指人或事物成长，病不能长大。"}, "sentence_index": 0, "correct_answer": "好起来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的心情一直很好，今天又好起来了。", "explanation": "这里应该用〈保持〉。“好起来”预设原来不好，心情一直很好时不能用。"}, {"text": "我的新手机好起来了。", "explanation": "这里应该用〈升级〉。“好起来”预设原来不好，新手机没有由差变好的前提，功能提升应说“升级”。"}, {"text": "这杯水好起来了，很凉。", "explanation": "这里应该用〈变凉〉。“好起来”说状况由差变好，水的温度变化不是好坏的变化，应说“变凉了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92119, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好起来", "is_correct": true, "explanation": "正确：“好起来”表示身体由差变好，与“孩子的感冒”的语境一致。"}, {"text": "站起来", "is_correct": false, "explanation": "语义：“站起来”指人起身，感冒不能站起来。"}, {"text": "亮起来", "is_correct": false, "explanation": "语义：“亮起来”指灯光发亮，与感冒无关。"}, {"text": "叫起来", "is_correct": false, "explanation": "搭配：“叫起来”指发出声音，不能用来说病情好转。"}], "explanations": {"好起来": "正确：“好起来”表示身体由差变好，与“孩子的感冒”的语境一致。", "站起来": "语义：“站起来”指人起身，感冒不能站起来。", "亮起来": "语义：“亮起来”指灯光发亮，与感冒无关。", "叫起来": "搭配：“叫起来”指发出声音，不能用来说病情好转。"}, "sentence_index": 6, "correct_answer": "好起来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的知识增长了，这些知识也好起来了。", "explanation": "这里应该用〈丰富〉。“好起来”说状况由差变好，知识增多应说“丰富”，不能用“好起来”。"}, {"text": "他的工作一直很顺利，这次又好起来了。", "explanation": "这里应该用〈保持〉。工作一直顺利，没有由差变好的前提，应说“保持顺利”。"}, {"text": "他这一年的身高好起来了。", "explanation": "这里应该用〈长高〉。身高增长是数量变化，“好起来”不能用于身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92119, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的感冒好起来慢慢了。", "corrected_sentence": "他的感冒慢慢好起来了。", "error_description": "错误形式「好起来慢慢了」，正确形式「慢慢好起来了」。副词“慢慢”要放在“好起来”前面，不能放在后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
