INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92120, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "由差变好，向好的方向发展。", "primary_collocate": null, "pronunciation": "hǎo qǐ lái", "ipa": "xɑʊ˨˩ tɕʰi˨˩ laɪ˨˦", "syllable_count": 3, "sentences": [{"text": "经济会慢慢好起来的。", "target_word": "好起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要努力，生活就会好起来。", "target_word": "好起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天天气就会好起来。", "target_word": "好起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩终于好起来了。", "target_word": "好起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的环境好起来了。", "target_word": "好起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的关系慢慢好起来了。", "target_word": "好起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的生意好起来，大家都高兴。", "target_word": "好起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别担心，一切都会好起来。", "target_word": "好起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家的情况一天天好起来。", "target_word": "好起来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新政策让农村的日子好起来了。", "target_word": "好起来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "好起来了", "label": "体标"}], "register": "中性", "sense_fingerprint": "好起来：形势、环境、事情由差变好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68b6fea3-2699-4510-9ab1-0d36748570eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92120, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好起来", "is_correct": true, "explanation": "正确：“好起来”表示由差变好，此处指经济向好的方向发展。"}, {"text": "哭起来", "is_correct": false, "explanation": "语义：“哭起来”指哭泣，不能用于经济。"}, {"text": "下起来", "is_correct": false, "explanation": "搭配：“下起来”只用于雨、雪，不能用于经济。"}, {"text": "吵起来", "is_correct": false, "explanation": "语义：“吵起来”指争吵，不能用来说经济由差变好。"}], "explanations": {"好起来": "正确：“好起来”表示由差变好，此处指经济向好的方向发展。", "哭起来": "语义：“哭起来”指哭泣，不能用于经济。", "下起来": "搭配：“下起来”只用于雨、雪，不能用于经济。", "吵起来": "语义：“吵起来”指争吵，不能用来说经济由差变好。"}, "sentence_index": 0, "correct_answer": "好起来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的成绩一直很好，这学期又好起来了。", "explanation": "这里应该用〈保持〉。“好起来”预设原来不好，成绩一直很好时应说“保持”，不说“好起来”。"}, {"text": "他把门好起来了。", "explanation": "这里应该用〈关上〉。“好起来”说情况由差变好，不能带宾语，也不能表示关门这个动作。"}, {"text": "我家的房子一直很干净，今天又好起来了。", "explanation": "这里应该用〈保持〉。房子一直干净，不存在由差变好的前提，应说“保持干净”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92120, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好起来", "is_correct": true, "explanation": "正确：“好起来”表示由差变好，与“大家都高兴”的语境一致。"}, {"text": "停下来", "is_correct": false, "explanation": "语义：“停下来”指停止，生意停下来与“大家都高兴”的语境相反。"}, {"text": "哭起来", "is_correct": false, "explanation": "语义：“哭起来”指哭泣，不能用来形容生意。"}, {"text": "胖起来", "is_correct": false, "explanation": "体貌：“胖起来”形容人或动物的体形变胖，不能用于生意。"}], "explanations": {"好起来": "正确：“好起来”表示由差变好，与“大家都高兴”的语境一致。", "停下来": "语义：“停下来”指停止，生意停下来与“大家都高兴”的语境相反。", "哭起来": "语义：“哭起来”指哭泣，不能用来形容生意。", "胖起来": "体貌：“胖起来”形容人或动物的体形变胖，不能用于生意。"}, "sentence_index": 6, "correct_answer": "好起来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的钥匙终于好起来了。", "explanation": "这里应该用〈找到〉。“好起来”说情况由差变好，丢失的钥匙找回应说“找到”，不能用于钥匙。"}, {"text": "我们学校一直很好，今年又好起来了。", "explanation": "这里应该用〈保持〉。“好起来”预设原来不好，学校一直很好时应说“保持”。"}, {"text": "这次考试好起来了。", "explanation": "这里应该用〈通过〉。“好起来”说情况由差变好，考试的结果是及格与否，应说“通过”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92120, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天气终于好起来好了。", "corrected_sentence": "天气终于好起来了。", "error_description": "错误形式「好起来好了」，正确形式「好起来了」。「好起来」已表示由差变好，后面再加「好」是多余成分，应去掉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
