INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92121, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "被选出来做某件事的人。", "primary_collocate": null, "pronunciation": "rén xuǎn", "ipa": "ʐən˧˥ ɕɥɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "经理的人选已经定下来了。", "target_word": "人选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁是班长最合适的人选？", "target_word": "人选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校正在找合适的人选。", "target_word": "人选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛的人选，老师还没决定。", "target_word": "人选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是大家心里最好的人选。", "target_word": "人选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司选出了三个人选。", "target_word": "人选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王年轻又努力，是这个工作的好人选。", "target_word": "人选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议代表的人选，由同学们投票决定。", "target_word": "人选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想不出比她更合适的人选了。", "target_word": "人选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队长的人选有两位，你支持哪一位？", "target_word": "人选", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位人选", "label": "量词"}], "register": "中性", "sense_fingerprint": "被选出来做某事的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c8724db-93b5-4991-96c7-55399deeca21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92121, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "搭配：“定下来”不能和“身高”搭配，身高不能被决定。"}, {"text": "人选", "is_correct": true, "explanation": "人选指被选出来担任某职务的人，与“经理的……定下来了”相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，不能是经理的人选。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指滋味或气味，不能被定为经理的人选。"}], "explanations": {"身高": "搭配：“定下来”不能和“身高”搭配，身高不能被决定。", "人选": "人选指被选出来担任某职务的人，与“经理的……定下来了”相符。", "颜色": "语义：“颜色”指色彩，不能是经理的人选。", "味道": "语义：“味道”指滋味或气味，不能被定为经理的人选。"}, "sentence_index": 0, "correct_answer": "人选"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是历史上最著名的人选。", "explanation": "这里应该用〈人物〉。人选指被选出来做某事的人，不指有名气的历史人物。"}, {"text": "这次比赛的人选是星期五。", "explanation": "这里应该用〈日期〉。人选指被选出来做事的人，不指时间。"}, {"text": "这台电脑是这次比赛的人选，老师还没决定。", "explanation": "这里误把〈人选〉用于物品。人选只指被选出来做事的人，不指电脑，应改用〈候选方案〉之类的说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b39e582-744c-4c39-a343-7e0484b564a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92121, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "钟表", "is_correct": false, "explanation": "搭配：“年轻又努力”只能形容人，不能形容钟表。"}, {"text": "人选", "is_correct": true, "explanation": "人选指被选出来担任某项工作的人，与“年轻又努力”的小王相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人，不能指小王这样的人选。"}, {"text": "外套", "is_correct": false, "explanation": "语义：外套是衣物，不能是小王这样的人选。"}], "explanations": {"钟表": "搭配：“年轻又努力”只能形容人，不能形容钟表。", "人选": "人选指被选出来担任某项工作的人，与“年轻又努力”的小王相符。", "天气": "语义：天气不是人，不能指小王这样的人选。", "外套": "语义：外套是衣物，不能是小王这样的人选。"}, "sentence_index": 6, "correct_answer": "人选"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次旅行的人选是一座海边的小城。", "explanation": "这里应该用〈目的地〉。人选指被选出来做某事的人，不指地方。"}, {"text": "这个计划是我们班的最佳人选。", "explanation": "这里误把〈人选〉用于计划。人选只指被选出来做事的人，计划是物，应改用〈方案〉。"}, {"text": "我们班有五十个人选，每个人都来上课。", "explanation": "这里应该用〈学生〉。人选指被选出来做事的人，不指全班所有的学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b39e582-744c-4c39-a343-7e0484b564a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92121, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "校方已经选出了三本人选。", "corrected_sentence": "校方已经选出了三位人选。", "error_description": "错误：“三本人选”，正确：“三位人选”。人用量词“位”，“本”用于书册，不能用于人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b39e582-744c-4c39-a343-7e0484b564a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92121, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班有一本人选参加比赛。", "corrected_sentence": "我们班有一位人选参加比赛。", "error_description": "错误：“一本人选”，正确：“一位人选”。人用量词“位”，“本”用于书册，不能用于人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b39e582-744c-4c39-a343-7e0484b564a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
