INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92123, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从业是去做一份工作。", "primary_collocate": null, "pronunciation": "cóng yè", "ipa": "tsʰʊŋ˧˥ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "他大学毕业后，在银行从业十年了。", "target_word": "从业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从业以后，每天都很忙。", "target_word": "从业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥在医院从业，是一名医生。", "target_word": "从业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚毕业，想在大城市从业。", "target_word": "从业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在学校从业二十年，教过很多学生。", "target_word": "从业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸年轻时在工厂从业，后来开了小店。", "target_word": "从业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从业的第一年，每个月只有两千块。", "target_word": "从业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想在哪个城市从业？", "target_word": "从业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她回国后，在一家小公司从业。", "target_word": "从业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他离开家乡，到上海从业。", "target_word": "从业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "从业了", "label": "体标"}, {"form": "从业过", "label": "体标"}, {"form": "從業", "label": "繁体"}], "register": "书面", "sense_fingerprint": "去某个地方做一份工作，常说在某处从业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c28bc5d3-0d63-4ade-a3fe-6947abe42ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92123, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "从业", "is_correct": true, "explanation": "正确答案：cóng yè，指从事某种职业。"}, {"text": "同业", "is_correct": false, "explanation": "tóng 与 cóng 声母不同（t 与 c），意思是同一行业。"}, {"text": "葱叶", "is_correct": false, "explanation": "cōng（第一声）与 cóng（第二声）声调不同，意思是葱的叶子。"}, {"text": "从医", "is_correct": false, "explanation": "yī（第一声）与 yè（第四声）韵母和声调都不同，意思是从事医疗工作。"}], "explanations": {"从业": "正确答案：cóng yè，指从事某种职业。", "同业": "tóng 与 cóng 声母不同（t 与 c），意思是同一行业。", "葱叶": "cōng（第一声）与 cóng（第二声）声调不同，意思是葱的叶子。", "从医": "yī（第一声）与 yè（第四声）韵母和声调都不同，意思是从事医疗工作。"}, "sentence_index": null, "correct_answer": "从业"}, "level_3": {"options": [{"text": "从业", "is_correct": true, "explanation": "正确答案：“从业”指从事某种职业，与“在银行”搭配，表示在银行工作十年。"}, {"text": "读书", "is_correct": false, "explanation": "语义：“读书”指求学，银行不是学校，与“在银行”不合。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”指身体不适，不能表示在银行的工作时间。"}, {"text": "任教", "is_correct": false, "explanation": "配价：“任教”需要学校这类机构作场所，不能用在“银行”后面。"}], "explanations": {"从业": "正确答案：“从业”指从事某种职业，与“在银行”搭配，表示在银行工作十年。", "读书": "语义：“读书”指求学，银行不是学校，与“在银行”不合。", "生病": "语义：“生病”指身体不适，不能表示在银行的工作时间。", "任教": "配价：“任教”需要学校这类机构作场所，不能用在“银行”后面。"}, "sentence_index": 0, "correct_answer": "从业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在家里从业，每天做饭、打扫卫生。", "explanation": "“从业”指从事有报酬的职业，做家务不属于职业，这里不能用。"}, {"text": "我在大学从业，每天上课学习。", "explanation": "“从业”指以工作谋生，上课学习是学生的事，不能说从业。"}, {"text": "下班后，他还要从业两个小时。", "explanation": "这里应该用〈工作〉。从业指长期从事某种职业，不能用来说一段时间的工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92123, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "从业", "is_correct": true, "explanation": "正确答案：“从业的第一年”指刚开始工作的那一年，与每月两千块的工资相符。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”是身体状况，不指工作的时期，与每月两千块的收入语境不合。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与每月两千块的收入无关，不能指工作的时期。"}, {"text": "逛街", "is_correct": false, "explanation": "语义：“逛街”是休闲活动，不是有收入的职业，与这一句不合。"}], "explanations": {"从业": "正确答案：“从业的第一年”指刚开始工作的那一年，与每月两千块的工资相符。", "生病": "语义：“生病”是身体状况，不指工作的时期，与每月两千块的收入语境不合。", "睡觉": "语义：“睡觉”与每月两千块的收入无关，不能指工作的时期。", "逛街": "语义：“逛街”是休闲活动，不是有收入的职业，与这一句不合。"}, "sentence_index": 6, "correct_answer": "从业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "每天早上八点从业，晚上十点才下班。", "explanation": "这里应该用〈上班〉。从业指长期从事某种职业，说的是职业身份，不用来描述每天上下班的具体时间。"}, {"text": "这台机器人已经在工厂从业三年了。", "explanation": "这里把“从业”用成了机器运转的意思，但从业指人长期从事某种职业，机器不能从业。"}, {"text": "他从业了十分钟，就回家吃饭了。", "explanation": "这里应该用〈工作〉。从业指长期从事某种职业，不能用来说只持续十分钟的工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92123, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她医院从业多年，很有经验。", "corrected_sentence": "她在医院从业多年，很有经验。", "error_description": "错误：“医院从业多年”；正确：“在医院从业多年”。表示地点的“在医院”要用介词“在”引出，不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92123, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她希望能一直从业一下。", "corrected_sentence": "她希望能一直从业下去。", "error_description": "错误：“一直……一下”语义矛盾：“一下”表示短时，与“一直”的持续义相反；正确：“一直从业下去”，“下去”表示持续。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
