INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92124, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从事某种职业或行业。", "primary_collocate": null, "pronunciation": "cóng yè", "ipa": "tsʰʊŋ˧˥ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "她从业于教育行业已经很多年了。", "target_word": "从业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从业二十多年，一直做同一行。", "target_word": "从业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生必须有证书才能从业。", "target_word": "从业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个行业从业，要有耐心。", "target_word": "从业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在法律行业从业多年。", "target_word": "从业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想从业于餐饮行业。", "target_word": "从业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从业期间，从来没有出过错。", "target_word": "从业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人想在这一行从业，要先学习。", "target_word": "从业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在金融行业从业十年了。", "target_word": "从业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从业前，他先参加了一次考试。", "target_word": "从业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "从业了", "label": "体标"}, {"form": "从业过", "label": "体标"}, {"form": "從業", "label": "繁体"}], "register": "书面", "sense_fingerprint": "从事某种职业或行业，常与行业、资格、年数搭配", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c28bc5d3-0d63-4ade-a3fe-6947abe42ec1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92124, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "从业", "is_correct": true, "explanation": "正确答案：cóng yè，指从事某种职业或行业。"}, {"text": "同业", "is_correct": false, "explanation": "tóng 与 cóng 声母不同（t 与 c），意思是同一行业。"}, {"text": "葱叶", "is_correct": false, "explanation": "cōng（第一声）与 cóng（第二声）声调不同，意思是葱的叶子。"}, {"text": "从医", "is_correct": false, "explanation": "yī（第一声）与 yè（第四声）韵母和声调都不同，意思是从事医疗工作。"}], "explanations": {"从业": "正确答案：cóng yè，指从事某种职业或行业。", "同业": "tóng 与 cóng 声母不同（t 与 c），意思是同一行业。", "葱叶": "cōng（第一声）与 cóng（第二声）声调不同，意思是葱的叶子。", "从医": "yī（第一声）与 yè（第四声）韵母和声调都不同，意思是从事医疗工作。"}, "sentence_index": null, "correct_answer": "从业"}, "level_3": {"options": [{"text": "从业", "is_correct": true, "explanation": "正确答案：“从业于”指在某个行业工作，与“教育行业”搭配。"}, {"text": "出差", "is_correct": false, "explanation": "语义：“出差”指因公到外地办事，不能表示长期在某行业工作。"}, {"text": "读书", "is_correct": false, "explanation": "语义：“读书”指求学，与“教育行业”的工作语境不合。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与“教育行业”毫无关系，不能这样说。"}], "explanations": {"从业": "正确答案：“从业于”指在某个行业工作，与“教育行业”搭配。", "出差": "语义：“出差”指因公到外地办事，不能表示长期在某行业工作。", "读书": "语义：“读书”指求学，与“教育行业”的工作语境不合。", "睡觉": "语义：“睡觉”与“教育行业”毫无关系，不能这样说。"}, "sentence_index": 0, "correct_answer": "从业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "暑假他去餐厅从业，每天端盘子。", "explanation": "这里应该用〈打工〉。从业指长期从事某种职业，短期的暑假工不能说从业。"}, {"text": "我在大学里从业，每天上课写作业。", "explanation": "这里说的是学习，不是工作。“从业”指长期从事某种职业，上课写作业属于学生的事，不能用来说从业。"}, {"text": "她在家里从业，每天做饭洗衣。", "explanation": "“从业”指从事有报酬的职业，做家务不属于这种职业，这里不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92124, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "从业", "is_correct": true, "explanation": "正确答案：“从业期间”指做这份职业的时间段，与后面的“出错”相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”不是工作状态，与“从来没有出过错”的工作表现不合。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”是身体状态，不能与“从来没有出过错”的工作表现搭配。"}, {"text": "逛街", "is_correct": false, "explanation": "语义：“逛街”是休闲活动，不是工作的时间段，与这句不合。"}], "explanations": {"从业": "正确答案：“从业期间”指做这份职业的时间段，与后面的“出错”相符。", "睡觉": "语义：“睡觉”不是工作状态，与“从来没有出过错”的工作表现不合。", "生病": "语义：“生病”是身体状态，不能与“从来没有出过错”的工作表现搭配。", "逛街": "语义：“逛街”是休闲活动，不是工作的时间段，与这句不合。"}, "sentence_index": 6, "correct_answer": "从业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在书店从业一晚，第二天就辞职了。", "explanation": "这里应该用〈打工〉。从业指长期从事某种职业，只做一晚不能说从业。"}, {"text": "这辆汽车已经在城里从业两年了。", "explanation": "这里把“从业”用成了车辆在城里营运的意思，但从业指人长期从事某种职业，车辆不能从业。"}, {"text": "午休后，他又从业了一个小时。", "explanation": "这里应该用〈工作〉。从业指长期从事某种职业，不能用来说一段时间的工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92124, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她一家小公司从业多年，还是很认真。", "corrected_sentence": "她在一家小公司从业多年，还是很认真。", "error_description": "错误：“一家小公司从业”；正确：“在一家小公司从业”。表示地点的“在一家小公司”要用介词“在”引出，不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92124, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她决心一直从业一下，不轻易转行。", "corrected_sentence": "她决心一直从业下去，不轻易转行。", "error_description": "错误：“一直……一下”语义矛盾：“一下”表示短时，与“一直”的持续义相反；正确：“一直……下去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '746b15bb-2605-4638-8073-050cf52324a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
