INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92126, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "依靠制导系统飞向并击毁目标的飞行武器。", "primary_collocate": null, "pronunciation": "dǎo dàn", "ipa": "taʊ˨˩˦ tan˥˩", "syllable_count": 2, "sentences": [{"text": "导弹击毁了远处的目标。", "target_word": "导弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队用导弹打下了敌人的飞机。", "target_word": "导弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导弹靠制导系统飞向目标。", "target_word": "导弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天他们试射了一枚新导弹。", "target_word": "导弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导弹发射后很快就找到了目标。", "target_word": "导弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种导弹能击毁一艘大船。", "target_word": "导弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "技术人员在检查导弹的制导系统。", "target_word": "导弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家买了一批新的导弹。", "target_word": "导弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导弹在空中改变了方向。", "target_word": "导弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们成功发射了导弹。", "target_word": "导弹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "枚", "label": "量词"}, {"form": "颗", "label": "量词"}, {"form": "洲际导弹", "label": "复合词"}, {"form": "巡航导弹", "label": "复合词"}], "register": "中性", "sense_fingerprint": "靠制导系统飞向并击毁目标的飞行武器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88a2d808-5f98-4557-8046-f4e5641b51ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92126, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "导弹", "is_correct": true, "explanation": "导弹靠制导系统飞向目标并击毁它，符合“击毁了远处的目标”。"}, {"text": "风", "is_correct": false, "explanation": "语义：风是自然现象，不能击毁目标，句子说的是有攻击能力的武器。"}, {"text": "狗", "is_correct": false, "explanation": "配价：“击毁”要求能施加毁坏力的主语，狗不能击毁远处的目标。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨是降水，不会击毁目标，与句子的意思不符。"}], "explanations": {"导弹": "导弹靠制导系统飞向目标并击毁它，符合“击毁了远处的目标”。", "风": "语义：风是自然现象，不能击毁目标，句子说的是有攻击能力的武器。", "狗": "配价：“击毁”要求能施加毁坏力的主语，狗不能击毁远处的目标。", "雨": "语义：雨是降水，不会击毁目标，与句子的意思不符。"}, "sentence_index": 0, "correct_answer": "导弹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "军队买了两张导弹。", "explanation": "这里应该用〈枚〉或〈颗〉。导弹不用“张”计数，“张”多用于纸张、平面物品。"}, {"text": "我每天用导弹给花浇水。", "explanation": "这里应该用〈水壶〉。浇花要用盛水的器具，导弹不能用来浇水。"}, {"text": "导弹在铁轨上飞驰。", "explanation": "这里应该用〈火车〉。“飞驰”和“铁轨”搭配的是火车，导弹不走铁轨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ace22b4-9832-4c20-9b66-315f55e68cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92126, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "导弹", "is_correct": true, "explanation": "导弹需要制导系统来控制飞行方向，符合“检查导弹的制导系统”。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：制导系统用于导弹等飞行武器，冰箱不需要制导系统。"}, {"text": "电梯", "is_correct": false, "explanation": "搭配：“制导”指引导飞行方向，电梯靠轨道升降，不说“制导系统”。"}, {"text": "书", "is_correct": false, "explanation": "语义：书没有制导系统，句子说的是需要制导控制的设备。"}], "explanations": {"导弹": "导弹需要制导系统来控制飞行方向，符合“检查导弹的制导系统”。", "冰箱": "搭配：制导系统用于导弹等飞行武器，冰箱不需要制导系统。", "电梯": "搭配：“制导”指引导飞行方向，电梯靠轨道升降，不说“制导系统”。", "书": "语义：书没有制导系统，句子说的是需要制导控制的设备。"}, "sentence_index": 6, "correct_answer": "导弹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "院子里种着一棵导弹。", "explanation": "这里应该用〈枚〉或〈颗〉。导弹不用“棵”计数，“棵”用于树木、植物。"}, {"text": "导弹在马路上行驶了一个小时。", "explanation": "这里应该用〈汽车〉。“行驶”用于汽车等车辆，导弹不在马路上行驶。"}, {"text": "导弹在草地上吃草。", "explanation": "这里应该用〈牛〉。“吃草”是牛等动物的行为，导弹不吃草。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ace22b4-9832-4c20-9b66-315f55e68cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92126, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们用一只导弹击毁了那艘敌舰。", "corrected_sentence": "他们用一枚导弹击毁了那艘敌舰。", "error_description": "错误：“只”不能用于导弹，应改为“枚”或“颗”，应说“一枚导弹”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ace22b4-9832-4c20-9b66-315f55e68cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92126, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在靶场成功发射了一枚的导弹。", "corrected_sentence": "他们在靶场成功发射了一枚导弹。", "error_description": "错误：数量短语「一枚」后面不能加「的」，应说「一枚导弹」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ace22b4-9832-4c20-9b66-315f55e68cf7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
