INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92128, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对企业的生产经营活动进行计划、组织和协调的工作。", "primary_collocate": null, "pronunciation": "qǐ yè guǎn lǐ", "ipa": "tɕʰi˨˩˦ je˥˩ kwan˨˩˦ li˨˩˦", "syllable_count": 4, "sentences": [{"text": "企业管理包括计划、组织和协调。", "target_word": "企业管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她负责公司的企业管理工作。", "target_word": "企业管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现代企业管理需要用电脑。", "target_word": "企业管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理把企业管理分成了几个部分。", "target_word": "企业管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的企业管理能让工人更有效率。", "target_word": "企业管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位教授研究企业管理已经十年了。", "target_word": "企业管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "企业管理要先做好生产计划。", "target_word": "企业管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们公司的企业管理做得很规范。", "target_word": "企业管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "企业管理让各个部门配合得更好。", "target_word": "企业管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校开了一门企业管理课。", "target_word": "企业管理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "企業管理", "label": "繁体"}], "register": "书面", "sense_fingerprint": "对企业生产经营进行计划、组织和协调的工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c8724db-93b5-4991-96c7-55399deeca21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92128, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "企业管理", "is_correct": true, "explanation": "正确：“企业管理包括计划、组织和协调”，主语指的正是这类工作。"}, {"text": "企业", "is_correct": false, "explanation": "语义：企业是经营的组织，不是计划、组织和协调的工作，不能作“包括”的主语。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是天空的状况，不包括计划和协调的工作。"}, {"text": "老板", "is_correct": false, "explanation": "搭配：“包括”后面接的是工作内容，“老板”是人，不能和它搭配。"}], "explanations": {"企业管理": "正确：“企业管理包括计划、组织和协调”，主语指的正是这类工作。", "企业": "语义：企业是经营的组织，不是计划、组织和协调的工作，不能作“包括”的主语。", "天气": "语义：天气是天空的状况，不包括计划和协调的工作。", "老板": "搭配：“包括”后面接的是工作内容，“老板”是人，不能和它搭配。"}, "sentence_index": 0, "correct_answer": "企业管理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "企业管理正在门口等你。", "explanation": "这里应该用〈经理〉。企业管理指计划、组织和协调的工作，不是人，不能在门口等人。"}, {"text": "经理把企业管理装进了箱子。", "explanation": "这里应该用〈资料〉。企业管理是工作和办法，不是能装进箱子的东西。"}, {"text": "经理是一位很好的企业管理。", "explanation": "这里应该用〈管理者〉。企业管理指工作，不指人，指人要说管理者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b39e582-744c-4c39-a343-7e0484b564a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92128, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "企业管理", "is_correct": true, "explanation": "正确：“企业管理要先做好生产计划”，主语是这类工作，符合语境。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：午饭是一顿饭，不能做生产计划，这里说不通。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是文学作品，不能用来做生产计划。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“做好生产计划”只能由企业或工厂来做，不能和“考试”搭配。"}], "explanations": {"企业管理": "正确：“企业管理要先做好生产计划”，主语是这类工作，符合语境。", "午饭": "语义：午饭是一顿饭，不能做生产计划，这里说不通。", "小说": "语义：小说是文学作品，不能用来做生产计划。", "考试": "搭配：“做好生产计划”只能由企业或工厂来做，不能和“考试”搭配。"}, "sentence_index": 6, "correct_answer": "企业管理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校负责学生的企业管理。", "explanation": "这里应该用〈教育〉。企业管理指企业的生产经营工作，培养学生要说教育。"}, {"text": "他们公司引进了一只企业管理。", "explanation": "这里应该用〈套〉。企业管理指一整套办法和工作，计量时用“套”；用“只”（指单个物品或动物）把它当成实物，是错的。"}, {"text": "企业管理在城市的北边。", "explanation": "这里应该用〈企业〉。企业是实体，可以位于某地；企业管理是工作，不能说在某个地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b39e582-744c-4c39-a343-7e0484b564a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92128, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂的企业管理做很有效。", "corrected_sentence": "这家工厂的企业管理做得很有效。", "error_description": "漏了“得”：“做”后面带程度补语要用“得”，应说“做得很有效”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b39e582-744c-4c39-a343-7e0484b564a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92128, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要好企业管理。", "corrected_sentence": "我们要做好企业管理。", "error_description": "漏了“做”：“好”是“做”的结果补语，“做”不能省，应说“做好企业管理”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b39e582-744c-4c39-a343-7e0484b564a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
