INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92129, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "征求是去问大家，请大家说想法。", "primary_collocate": null, "pronunciation": "zhēng qiú", "ipa": "ʈʂɤŋ˥ tɕʰjoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "老师征求大家的意见。", "target_word": "征求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会前，经理征求了同事的想法。", "target_word": "征求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校想征求家长的看法。", "target_word": "征求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先征求一下大家的意见吧。", "target_word": "征求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班长正在征求同学们的建议。", "target_word": "征求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司征求过员工的意见。", "target_word": "征求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有征求我的想法，就决定了。", "target_word": "征求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么不先征求妈妈的意见？", "target_word": "征求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府在网上征求市民的建议。", "target_word": "征求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生征求病人的意见后，才开始治疗。", "target_word": "征求", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "征求了", "label": "体标"}, {"form": "征求过", "label": "体标"}, {"form": "征求意见", "label": "复合"}], "register": "书面", "sense_fingerprint": "征求:问大家，请大家说想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e2be088-64c2-41e3-84d8-6c7e9081f3dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92129, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "征求", "is_correct": true, "explanation": "征求：去问大家、请大家说想法，与“老师……大家的意见”相符。"}, {"text": "偷", "is_correct": false, "explanation": "搭配：“偷”多用于财物，意见不能被偷。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮品，不能用于意见。"}, {"text": "驱赶", "is_correct": false, "explanation": "语义：“驱赶”指赶走人或动物，不能用于意见。"}], "explanations": {"征求": "征求：去问大家、请大家说想法，与“老师……大家的意见”相符。", "偷": "搭配：“偷”多用于财物，意见不能被偷。", "喝": "搭配：“喝”的对象是饮品，不能用于意见。", "驱赶": "语义：“驱赶”指赶走人或动物，不能用于意见。"}, "sentence_index": 0, "correct_answer": "征求"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想向医生征求一个数学问题。", "explanation": "这里应该用〈请教〉。征求是问大家的意见、看法，问知识或问题要用请教，不能说“征求一个问题”。"}, {"text": "政府征求了农民的粮食。", "explanation": "这里应该用〈征收〉。征求是询问意见，政府向农民收取粮食、税款要用征收。"}, {"text": "他终于征求到一个女朋友。", "explanation": "这里应该用〈追求〉。追求指努力争取爱情或理想，征求是询问意见，不能用来争取人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b4369c-9c0e-4855-8132-776cb5e3243d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92129, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "征求", "is_correct": true, "explanation": "征求：问我的想法，与“没有……就决定了”的语境相符。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”用于擦拭物体表面，想法不能被擦。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”的对象是食物或身体部位，想法不能被咬。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”用于搬运实物，想法不能被搬。"}], "explanations": {"征求": "征求：问我的想法，与“没有……就决定了”的语境相符。", "擦": "搭配：“擦”用于擦拭物体表面，想法不能被擦。", "咬": "搭配：“咬”的对象是食物或身体部位，想法不能被咬。", "搬": "搭配：“搬”用于搬运实物，想法不能被搬。"}, "sentence_index": 6, "correct_answer": "征求"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个青年被征求入伍了。", "explanation": "这里应该用〈征召〉。征召指国家召集人员入伍，征求是询问意见，不能用于入伍。"}, {"text": "公司正在征求新员工。", "explanation": "这里应该用〈招聘〉。招聘指招收员工，征求的对象是意见和看法，不能用于人。"}, {"text": "研究人员征求了当地的水质。", "explanation": "这里应该用〈调查〉。调查指查看事实情况，征求的对象是意见，不能用于水质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b4369c-9c0e-4855-8132-776cb5e3243d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92129, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们先征求家长的意见一下吧。", "corrected_sentence": "我们先征求家长的意见吧。", "error_description": "多出了“一下”。“征求一下”可以说，但“一下”不能放在宾语“意见”之后，应说“征求家长的意见吧”，不说“征求家长的意见一下吧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b4369c-9c0e-4855-8132-776cb5e3243d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92129, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师征求过学生的看法过。", "corrected_sentence": "老师征求过学生的看法。", "error_description": "多出了一个“过”。体标“过”只用一次，应说“征求过学生的看法”，不说“征求过学生的看法过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6b4369c-9c0e-4855-8132-776cb5e3243d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
