INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92132, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "相差很小，接近；也表示大致、几乎。", "primary_collocate": null, "pronunciation": "chà bu duō", "ipa": "ʈʂʰa˥˩ pu tuo˥", "syllable_count": 3, "sentences": [{"text": "我和哥哥差不多高。", "target_word": "差不多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家离学校差不多两公里。", "target_word": "差不多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在差不多十点了。", "target_word": "差不多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作业差不多写完了，我再检查一下。", "target_word": "差不多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个孩子的年纪差不多。", "target_word": "差不多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个箱子差不多满了。", "target_word": "差不多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我走了差不多一个小时。", "target_word": "差不多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们差不多同时到了学校。", "target_word": "差不多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来的人差不多都是学生。", "target_word": "差不多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和我的体重差不多。", "target_word": "差不多", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "差不多：相差很小，接近；大致、几乎", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6fc0c8a-a2f4-4258-9b79-7225f30965f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92132, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "差不多", "is_correct": true, "explanation": "“差不多”表示相差很小，与后面的“高”搭配，说明两人身高接近。"}, {"text": "相同", "is_correct": false, "explanation": "搭配：“相同”不能直接修饰“高”，要说“一样高”。"}, {"text": "矮", "is_correct": false, "explanation": "语义：“矮”与后面的“高”意思相反，“我和哥哥矮高”说不通。"}, {"text": "悬殊", "is_correct": false, "explanation": "搭配：“悬殊”指差距很大，不能用来说身高接近。"}], "explanations": {"差不多": "“差不多”表示相差很小，与后面的“高”搭配，说明两人身高接近。", "相同": "搭配：“相同”不能直接修饰“高”，要说“一样高”。", "矮": "语义：“矮”与后面的“高”意思相反，“我和哥哥矮高”说不通。", "悬殊": "搭配：“悬殊”指差距很大，不能用来说身高接近。"}, "sentence_index": 0, "correct_answer": "差不多"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的成绩和我差不多，我却比他低了二十多分。", "explanation": "这里“差不多”取“相差很小、接近”的义项，但后句说低了二十多分，相差很大，与“差不多”矛盾。"}, {"text": "他们俩的收入差不多，他一年的钱却是我的十倍。", "explanation": "这里“差不多”取“相差很小、接近”的义项，但后句说对方是十倍，相差很大，前后矛盾。"}, {"text": "这次旅行我们的钱差不多花完了，却还剩下一大笔钱。", "explanation": "这里“差不多”取“几乎”的义项，说钱几乎花完了，但后句说还剩一大笔钱，与之矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e507a47d-ed7e-4f68-bb16-befd85161867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92132, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "差不多", "is_correct": true, "explanation": "“差不多”表示大约的时长，与“一个小时”搭配，符合语境。"}, {"text": "却", "is_correct": false, "explanation": "语法：“却”是转折副词，不能放在“了”与数量短语“一个小时”之间，句子不通。"}, {"text": "竟", "is_correct": false, "explanation": "语义：“竟”表示出乎意料，句中没有这层意思。"}, {"text": "是", "is_correct": false, "explanation": "语法：“是”不能放在“走了”与数量短语之间，句子不通。"}], "explanations": {"差不多": "“差不多”表示大约的时长，与“一个小时”搭配，符合语境。", "却": "语法：“却”是转折副词，不能放在“了”与数量短语“一个小时”之间，句子不通。", "竟": "语义：“竟”表示出乎意料，句中没有这层意思。", "是": "语法：“是”不能放在“走了”与数量短语之间，句子不通。"}, "sentence_index": 6, "correct_answer": "差不多"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个箱子差不多空着，里面已经装满了东西。", "explanation": "这里“差不多”取“几乎”的义项，说箱子几乎空着，后句却说装满了，前后矛盾。"}, {"text": "我走了差不多一个小时，才走了五分钟。", "explanation": "这里“差不多”取“大致”的义项，说接近一个小时，后句说只走了五分钟，与之矛盾。"}, {"text": "现在差不多中午了，窗外却是半夜。", "explanation": "这里“差不多”取“大致”的义项，说接近中午，后句说是半夜，时间上前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e507a47d-ed7e-4f68-bb16-befd85161867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92132, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我和弟弟差不多了高。", "corrected_sentence": "我和弟弟差不多高。", "error_description": "错误：“差不多”后面多加了“了”。正确：“差不多高”，表示身高接近，“了”不能加在“差不多”与“高”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e507a47d-ed7e-4f68-bb16-befd85161867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92132, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们干了很差不多一天的活。", "corrected_sentence": "他们干了差不多一天的活。", "error_description": "错误：“很”放在了“差不多”前面。正确：“差不多”前不能加程度副词“很”，直接说“干了差不多一天的活”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e507a47d-ed7e-4f68-bb16-befd85161867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
