INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92135, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "心理学是研究人心里想什么的学问。", "primary_collocate": null, "pronunciation": "xīn lǐ xué", "ipa": "ɕin˥ li˨˩˦ ɕɥe˧˥", "syllable_count": 3, "sentences": [{"text": "想知道人为什么哭，可以看看心理学。", "target_word": "心理学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我借了一本讲心理学的书。", "target_word": "心理学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "心理学是一门有意思的学问。", "target_word": "心理学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友说，学心理学能看懂别人的心。", "target_word": "心理学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我妈妈最近在自学心理学。", "target_word": "心理学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他读了很多心理学方面的书。", "target_word": "心理学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "心理学告诉我们，人需要朋友。", "target_word": "心理学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个电视节目讲的是生活中的心理学。", "target_word": "心理学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想考心理学的研究生。", "target_word": "心理学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听了心理学的课，我才知道自己怎么想。", "target_word": "心理学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "心理學", "label": "繁体"}, {"form": "心理学家", "label": "复合"}, {"form": "社会心理学", "label": "复合"}], "register": "中性", "sense_fingerprint": "心理学：研究人心里怎么想的学问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91424016-136b-4dbb-8616-3939a22b04a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92135, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地图", "is_correct": false, "explanation": "语义：“地图”指示方向和位置，不能用来了解人为什么哭。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：“食谱”讲做菜的方法，与人为什么哭无关。"}, {"text": "心理学", "is_correct": true, "explanation": "心理学研究人心里怎么想，可以帮助了解人为什么哭。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：“钢琴”是乐器，不是可供查阅的资料，无法帮助了解人为什么哭。"}], "explanations": {"地图": "语义：“地图”指示方向和位置，不能用来了解人为什么哭。", "食谱": "语义：“食谱”讲做菜的方法，与人为什么哭无关。", "心理学": "心理学研究人心里怎么想，可以帮助了解人为什么哭。", "钢琴": "语义：“钢琴”是乐器，不是可供查阅的资料，无法帮助了解人为什么哭。"}, "sentence_index": 0, "correct_answer": "心理学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听到这个消息，我心理学一下子沉了下来。", "explanation": "这里应该用〈心里〉。表示内心感受要用“心里”，“心理学”是学科，不能指心里的感觉。"}, {"text": "他的心理学很稳重。", "explanation": "这里应该用〈性格〉。“性格”指人稳定的个性特点，可以说“性格稳重”；“心理学”是学科名称，不能用来形容人的性格。"}, {"text": "他的心理学很难猜。", "explanation": "这里应该用〈心思〉。“心思”指一个人的想法，“心理学”是学科，不能说它难猜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b2bf2e-59d7-411a-9869-74a291039784') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92135, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：“天气”是自然现象，不是学问，不能告诉我们人需要朋友。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”是做饭的地方，不能告诉我们人需要什么。"}, {"text": "心理学", "is_correct": true, "explanation": "心理学研究人的心理，可以告诉我们人需要朋友。"}, {"text": "钥匙", "is_correct": false, "explanation": "搭配：“告诉我们”的主语须是书、学问或理论，“钥匙”不能这样搭配。"}], "explanations": {"天气": "语义：“天气”是自然现象，不是学问，不能告诉我们人需要朋友。", "厨房": "语义：“厨房”是做饭的地方，不能告诉我们人需要什么。", "心理学": "心理学研究人的心理，可以告诉我们人需要朋友。", "钥匙": "搭配：“告诉我们”的主语须是书、学问或理论，“钥匙”不能这样搭配。"}, "sentence_index": 6, "correct_answer": "心理学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的心理学很平静。", "explanation": "这里应该用〈心境〉。“心境”指内心的状态，“心理学”是学科，不能说它平静。"}, {"text": "他对我的心理学很冷淡。", "explanation": "这里应该用〈态度〉。“态度”指人对人或事的看法和表现，可以说“态度冷淡”；“心理学”是学科名称，不能用来形容人对别人的态度。"}, {"text": "她今天心理学很愉快。", "explanation": "这里应该用〈心情〉。“心情”指情绪状态，“心理学”是学科，不能描述心情愉快。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b2bf2e-59d7-411a-9869-74a291039784') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92135, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我最近上了一本心理学课。", "corrected_sentence": "我最近上了一门心理学课。", "error_description": "量词错误：“心理学课”是课程，应用量词“门”，不能用“本”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b2bf2e-59d7-411a-9869-74a291039784') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92135, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她学了一本心理学。", "corrected_sentence": "她学了一门心理学。", "error_description": "量词错误：“心理学”是学科，应用量词“门”，不能用“本”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b2bf2e-59d7-411a-9869-74a291039784') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
