INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92136, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "研究人的心理现象及其规律的科学。", "primary_collocate": null, "pronunciation": "xīn lǐ xué", "ipa": "ɕin˥ li˨˩˦ ɕɥe˧˥", "syllable_count": 3, "sentences": [{"text": "她在大学学心理学。", "target_word": "心理学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "心理学研究人的心理活动。", "target_word": "心理学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我对心理学很感兴趣。", "target_word": "心理学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本心理学的书很有意思。", "target_word": "心理学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她哥哥读的是心理学。", "target_word": "心理学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位教授教心理学已经二十年了。", "target_word": "心理学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "心理学可以解释人为什么会紧张。", "target_word": "心理学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟下个学期要上心理学课。", "target_word": "心理学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学了心理学以后，我更懂孩子了。", "target_word": "心理学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做老师要懂一点心理学。", "target_word": "心理学", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "心理學", "label": "繁体"}, {"form": "心理学家", "label": "复合"}, {"form": "社会心理学", "label": "复合"}], "register": "中性", "sense_fingerprint": "心理学：研究人的心理现象及其规律的科学学科", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91424016-136b-4dbb-8616-3939a22b04a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92136, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "语义：“学”的对象须是学问或技能，“空气”不是可以学习的东西。"}, {"text": "心理学", "is_correct": true, "explanation": "心理学是研究心理现象及其规律的学科，可以在大学里学习。"}, {"text": "柜子", "is_correct": false, "explanation": "语义：“柜子”是家具，不是学科，不能作“学”的宾语。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“学”不与“窗户”这类具体物件搭配作宾语，应说“学做窗户”之类的具体技能。"}], "explanations": {"空气": "语义：“学”的对象须是学问或技能，“空气”不是可以学习的东西。", "心理学": "心理学是研究心理现象及其规律的学科，可以在大学里学习。", "柜子": "语义：“柜子”是家具，不是学科，不能作“学”的宾语。", "窗户": "搭配：“学”不与“窗户”这类具体物件搭配作宾语，应说“学做窗户”之类的具体技能。"}, "sentence_index": 0, "correct_answer": "心理学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他最近心理学很不好。", "explanation": "这里应该用〈心理〉。心理指人的精神状态，“心理学”是学科名称，不能用来描述心情或精神状态。"}, {"text": "我心理学很难过。", "explanation": "这里应该用〈心里〉。表示内心感受要用“心里”，“心理学”是学科，不能说“心理学很难过”。"}, {"text": "他的心理学一直很积极。", "explanation": "这里应该用〈心态〉。“心态”指人对事情的看法和心理状态，可以说“心态积极”；“心理学”是学科名称，不能用来形容人的心态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b2bf2e-59d7-411a-9869-74a291039784') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92136, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "柠檬", "is_correct": false, "explanation": "语义：“柠檬”是水果，不是学问，无法解释人为什么紧张。"}, {"text": "心理学", "is_correct": true, "explanation": "心理学研究人的心理活动，可以解释人为什么会紧张。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：“钥匙”是开门的工具，不能用来解释心理现象。"}, {"text": "音乐", "is_correct": false, "explanation": "搭配：“解释”的主语须是学科或理论，“音乐”是艺术形式，不能这样搭配。"}], "explanations": {"柠檬": "语义：“柠檬”是水果，不是学问，无法解释人为什么紧张。", "心理学": "心理学研究人的心理活动，可以解释人为什么会紧张。", "钥匙": "语义：“钥匙”是开门的工具，不能用来解释心理现象。", "音乐": "搭配：“解释”的主语须是学科或理论，“音乐”是艺术形式，不能这样搭配。"}, "sentence_index": 6, "correct_answer": "心理学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她今天心理学很愉快。", "explanation": "这里应该用〈心情〉。“心情”指情绪状态，“心理学”是学科，不能描述心情愉快。"}, {"text": "她的心理学很开朗。", "explanation": "这里应该用〈性格〉。“性格”指人稳定的个性特点，可以说“性格开朗”；“心理学”是学科名称，不能用来形容人的性格。"}, {"text": "这次考试后，他的心理学很不稳定。", "explanation": "这里应该用〈情绪〉。“情绪”指人的情感状态，“心理学”是学科，不能说它不稳定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b2bf2e-59d7-411a-9869-74a291039784') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92136, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "心理学是一本很有用的学问。", "corrected_sentence": "心理学是一门很有用的学问。", "error_description": "量词错误：“心理学”是学科、学问，应用量词“门”，不能用“本”（“本”用于书籍）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b2bf2e-59d7-411a-9869-74a291039784') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92136, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她下学期选了一本心理学课。", "corrected_sentence": "她下学期选了一门心理学课。", "error_description": "量词错误：“心理学课”是课程，应用量词“门”，不能用“本”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b2bf2e-59d7-411a-9869-74a291039784') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
