INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92140, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "占据；占用。", "primary_collocate": null, "pronunciation": "zhàn qù", "ipa": "ʈʂan˥˩ tɕʰy˥˩", "syllable_count": 2, "sentences": [{"text": "大树占去了整个院子。", "target_word": "占去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的行李占去了两个座位。", "target_word": "占去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那辆车占去了我的停车位。", "target_word": "占去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的书占去了整张桌子。", "target_word": "占去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾占去了走廊，大家过不去。", "target_word": "占去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架占去了半面墙。", "target_word": "占去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人占去了三个人的位子。", "target_word": "占去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高楼占去了河边的好地方。", "target_word": "占去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂占去了村子里的大片地。", "target_word": "占去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视占去了客厅的中间。", "target_word": "占去", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "占去了", "label": "体标"}], "register": "中性", "sense_fingerprint": "占去：占据、占用某个位置或地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6fc0c8a-a2f4-4258-9b79-7225f30965f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92140, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "占去", "is_correct": true, "explanation": "“占去”表示占据院子的空间，与“整个院子”搭配，符合语境。"}, {"text": "冲洗", "is_correct": false, "explanation": "语义：“冲洗”需要人作主语，“大树”无法实施这一动作，句子不通。"}, {"text": "赠送", "is_correct": false, "explanation": "语义：“赠送”表示送给别人，与“大树占据院子”的意思不符。"}, {"text": "存放", "is_correct": false, "explanation": "语义：“存放”表示把东西放在某处保存，与“占据整个院子”的意思不合。"}], "explanations": {"占去": "“占去”表示占据院子的空间，与“整个院子”搭配，符合语境。", "冲洗": "语义：“冲洗”需要人作主语，“大树”无法实施这一动作，句子不通。", "赠送": "语义：“赠送”表示送给别人，与“大树占据院子”的意思不符。", "存放": "语义：“存放”表示把东西放在某处保存，与“占据整个院子”的意思不合。"}, "sentence_index": 0, "correct_answer": "占去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的书占去了整张桌子，桌子上却还空着一大半。", "explanation": "这里“占去”取“占据”的义项，后句说桌上还空着一大半，与“占去了整张桌子”矛盾。"}, {"text": "垃圾占去了走廊，走廊上却一件东西也没有。", "explanation": "这里“占去”取“占据”的义项，后句说走廊上一件东西也没有，与之矛盾。"}, {"text": "那辆车占去了我的停车位，我的车位却还空着。", "explanation": "这里“占去”取“占据”的义项，后句说车位还空着，与“占去了车位”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e507a47d-ed7e-4f68-bb16-befd85161867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92140, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "占去", "is_correct": true, "explanation": "“占去”表示占据位子，与“三个人的位子”搭配，说明一个人占了三个人的位置。"}, {"text": "浇灌", "is_correct": false, "explanation": "搭配：“浇灌”用于植物或田地，不能与“位子”搭配。"}, {"text": "阅读", "is_correct": false, "explanation": "语义：“阅读”的对象是文字材料，不能说“阅读位子”。"}, {"text": "挥霍", "is_correct": false, "explanation": "搭配：“挥霍”指浪费钱财，不能用于“位子”。"}], "explanations": {"占去": "“占去”表示占据位子，与“三个人的位子”搭配，说明一个人占了三个人的位置。", "浇灌": "搭配：“浇灌”用于植物或田地，不能与“位子”搭配。", "阅读": "语义：“阅读”的对象是文字材料，不能说“阅读位子”。", "挥霍": "搭配：“挥霍”指浪费钱财，不能用于“位子”。"}, "sentence_index": 6, "correct_answer": "占去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工厂占去了村子里的大片地，村里的田地却一块也没有少。", "explanation": "这里“占去”取“占据”的义项，后句说田地一块也没少，与“占去了大片地”矛盾。"}, {"text": "他的行李占去了两个座位，可是两个座位都是空的。", "explanation": "这里“占去”取“占据”的义项，后句说座位是空的，与“占去了两个座位”矛盾。"}, {"text": "大树占去了整个院子，院子里却连一棵树也没有。", "explanation": "这里“占去”取“占据”的义项，后句说院子里没有树，与“大树占去了整个院子”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e507a47d-ed7e-4f68-bb16-befd85161867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92140, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会议室占去在走廊的一半。", "corrected_sentence": "会议室占去了走廊的一半。", "error_description": "错误：“占去”后面加了“在”。正确：“占去了走廊的一半”，“在”不能放在“占去”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e507a47d-ed7e-4f68-bb16-befd85161867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92140, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "客厅的沙发占去了了一半的地方。", "corrected_sentence": "客厅的沙发占去了一半的地方。", "error_description": "错误：“了”重复出现在“占去”后面。正确：“占去了一半的地方”，只用一个“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e507a47d-ed7e-4f68-bb16-befd85161867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
