INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92141, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "性行是一个人的性格和做事的样子。", "primary_collocate": null, "pronunciation": "xìng xíng", "ipa": "ɕiŋ˥˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他性行急躁，做事总是匆匆忙忙。", "target_word": "性行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从他的性行可以看出，他是个认真的人。", "target_word": "性行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的性行常常受家人影响。", "target_word": "性行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他性行随和，跟谁都能说得来。", "target_word": "性行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个人性行古怪，大家都不爱和他来往。", "target_word": "性行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板喜欢性行稳重的年轻人。", "target_word": "性行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们先看看这个人的性行，再决定要不要合作。", "target_word": "性行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他性行耿直，遇事从不绕弯子。", "target_word": "性行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王性行勤快，一早就开始打扫。", "target_word": "性行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过这件事，大家更了解他的性行了。", "target_word": "性行", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "一个人的性格和做事的作风", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbb1089a-7f0e-4a1d-9b64-4094ab18e718') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92141, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "性行", "is_correct": true, "explanation": "性行（xìng xíng）指人的性格和做事的样子，正是这里要辨认的词。"}, {"text": "行星", "is_correct": false, "explanation": "行星（xíng xīng）两个音节的声调都与性行（xìng xíng）不同，意思是绕恒星运行的天体。"}, {"text": "星形", "is_correct": false, "explanation": "星形（xīng xíng）第一音节 xīng（第一声）与 xìng（第四声）声调不同，意思是星星的形状。"}, {"text": "星型", "is_correct": false, "explanation": "星型（xīng xíng）第一音节 xīng（第一声）与 xìng（第四声）声调不同，意思是星状的类型。"}, {"text": "新型", "is_correct": false, "explanation": "新型（xīn xíng）第一音节 xīn 与 xìng 韵尾不同（-n 与 -ng），声调也不同，意思是新的类型。"}, {"text": "心形", "is_correct": false, "explanation": "心形（xīn xíng）第一音节 xīn 与 xìng 韵尾不同（-n 与 -ng），声调也不同，意思是心脏的形状。"}], "explanations": {"性行": "性行（xìng xíng）指人的性格和做事的样子，正是这里要辨认的词。", "行星": "行星（xíng xīng）两个音节的声调都与性行（xìng xíng）不同，意思是绕恒星运行的天体。", "星形": "星形（xīng xíng）第一音节 xīng（第一声）与 xìng（第四声）声调不同，意思是星星的形状。", "星型": "星型（xīng xíng）第一音节 xīng（第一声）与 xìng（第四声）声调不同，意思是星状的类型。", "新型": "新型（xīn xíng）第一音节 xīn 与 xìng 韵尾不同（-n 与 -ng），声调也不同，意思是新的类型。", "心形": "心形（xīn xíng）第一音节 xīn 与 xìng 韵尾不同（-n 与 -ng），声调也不同，意思是心脏的形状。"}, "sentence_index": null, "correct_answer": "性行"}, "level_3": {"options": [{"text": "性行", "is_correct": true, "explanation": "正确：“性行”指人的性情和做事的样子，与“急躁、做事匆匆忙忙”相符。"}, {"text": "字迹", "is_correct": false, "explanation": "搭配：“急躁”不能形容字迹，字迹只说工整或潦草。"}, {"text": "身材", "is_correct": false, "explanation": "语义：身材指体形，与一个人性情急不急躁无关。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“急躁”不能修饰体重，体重只说轻重。"}], "explanations": {"性行": "正确：“性行”指人的性情和做事的样子，与“急躁、做事匆匆忙忙”相符。", "字迹": "搭配：“急躁”不能形容字迹，字迹只说工整或潦草。", "身材": "语义：身材指体形，与一个人性情急不急躁无关。", "体重": "搭配：“急躁”不能修饰体重，体重只说轻重。"}, "sentence_index": 0, "correct_answer": "性行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种药的性行很温和。", "explanation": "这里应该用〈性质〉。性行只用于人，说药物的特点要用〈性质〉。"}, {"text": "我每天晚上十点睡觉，这是我的性行。", "explanation": "这里应该用〈习惯〉。性行指人的性情和做事的样子，日常作息要用〈习惯〉。"}, {"text": "这台电脑的性行很好，运行得特别快。", "explanation": "这里应该用〈性能〉。性行指人的性格和做事的样子，说机器的运行能力要用〈性能〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0276bb3d-0a3e-470f-9a6d-d191d79e25a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92141, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "性行", "is_correct": true, "explanation": "正确：“性行”指人的性情和做事的样子，正适合用来判断这个人是否可靠、值不值得合作。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“看”不能用于声音，了解声音应说“听”。"}, {"text": "嗓门", "is_correct": false, "explanation": "搭配：嗓门只说大小，不能用“看”来了解。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温指身体的冷热，与是否合作无关，不能作为判断依据。"}], "explanations": {"性行": "正确：“性行”指人的性情和做事的样子，正适合用来判断这个人是否可靠、值不值得合作。", "声音": "搭配：“看”不能用于声音，了解声音应说“听”。", "嗓门": "搭配：嗓门只说大小，不能用“看”来了解。", "体温": "语义：体温指身体的冷热，与是否合作无关，不能作为判断依据。"}, "sentence_index": 6, "correct_answer": "性行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部小说的性行很幽默。", "explanation": "这里应该用〈风格〉。性行只用于人，说小说的写法要用〈风格〉。"}, {"text": "这个方案的性行很简单，容易执行。", "explanation": "这里应该用〈特点〉。性行只用于人，说方案的特点要用〈特点〉。"}, {"text": "这座城市的性行很开放。", "explanation": "这里应该用〈性格〉。性行只用于人，说城市的个性要用〈性格〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0276bb3d-0a3e-470f-9a6d-d191d79e25a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
