INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92142, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "性行", "is_correct": true, "explanation": "性行（xìng xíng）指人的性情和品行，正是这里要辨认的词。"}, {"text": "行星", "is_correct": false, "explanation": "行星（xíng xīng）两个音节的声调都与性行（xìng xíng）不同，意思是绕恒星运行的天体。"}, {"text": "星形", "is_correct": false, "explanation": "星形（xīng xíng）第一音节 xīng（第一声）与 xìng（第四声）声调不同，意思是星星的形状。"}, {"text": "星型", "is_correct": false, "explanation": "星型（xīng xíng）第一音节 xīng（第一声）与 xìng（第四声）声调不同，意思是星状的类型。"}, {"text": "新型", "is_correct": false, "explanation": "新型（xīn xíng）第一音节 xīn 与 xìng 韵尾不同（-n 与 -ng），声调也不同，意思是新的类型。"}, {"text": "心形", "is_correct": false, "explanation": "心形（xīn xíng）第一音节 xīn 与 xìng 韵尾不同（-n 与 -ng），声调也不同，意思是心脏的形状。"}], "explanations": {"性行": "性行（xìng xíng）指人的性情和品行，正是这里要辨认的词。", "行星": "行星（xíng xīng）两个音节的声调都与性行（xìng xíng）不同，意思是绕恒星运行的天体。", "星形": "星形（xīng xíng）第一音节 xīng（第一声）与 xìng（第四声）声调不同，意思是星星的形状。", "星型": "星型（xīng xíng）第一音节 xīng（第一声）与 xìng（第四声）声调不同，意思是星状的类型。", "新型": "新型（xīn xíng）第一音节 xīn 与 xìng 韵尾不同（-n 与 -ng），声调也不同，意思是新的类型。", "心形": "心形（xīn xíng）第一音节 xīn 与 xìng 韵尾不同（-n 与 -ng），声调也不同，意思是心脏的形状。"}, "sentence_index": null, "correct_answer": "性行"}, "level_3": {"options": [{"text": "性行", "is_correct": true, "explanation": "正确：“性行”指人的性情和品行，与“温和、从来不跟人吵架”相符。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高指身体的高矮，与人的性情无关，不能用“温和”来形容。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“温和”不能修饰体重，体重只说轻重。"}, {"text": "视力", "is_correct": false, "explanation": "搭配：视力只说好坏、强弱，不能用“温和”描述。"}], "explanations": {"性行": "正确：“性行”指人的性情和品行，与“温和、从来不跟人吵架”相符。", "身高": "语义：身高指身体的高矮，与人的性情无关，不能用“温和”来形容。", "体重": "搭配：“温和”不能修饰体重，体重只说轻重。", "视力": "搭配：视力只说好坏、强弱，不能用“温和”描述。"}, "sentence_index": 0, "correct_answer": "性行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种材料的性行很稳定。", "explanation": "这里应该用〈性质〉。性行只用于人的性情和品行，说材料的特点要用〈性质〉。"}, {"text": "我的性行是每天早上七点起床。", "explanation": "这里应该用〈习惯〉。性行指人的性情和品行，说日常作息的规律要用〈习惯〉。"}, {"text": "这座桥的性行很坚固。", "explanation": "这里应该用〈结构〉。性行只用于人的性情和品行，说桥的牢固程度要用〈结构〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0276bb3d-0a3e-470f-9a6d-d191d79e25a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92142, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "性行", "is_correct": true, "explanation": "正确：“性行”指人的性情和品行，与“安静、不喜欢热闹”相符。"}, {"text": "字迹", "is_correct": false, "explanation": "搭配：“安静”不能形容字迹，字迹只说工整或潦草。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温指身体的冷热，与一个人是否安静、是否爱热闹无关。"}, {"text": "身材", "is_correct": false, "explanation": "语义：身材指体形，不能用“安静”来描述。"}], "explanations": {"性行": "正确：“性行”指人的性情和品行，与“安静、不喜欢热闹”相符。", "字迹": "搭配：“安静”不能形容字迹，字迹只说工整或潦草。", "体温": "语义：体温指身体的冷热，与一个人是否安静、是否爱热闹无关。", "身材": "语义：身材指体形，不能用“安静”来描述。"}, "sentence_index": 6, "correct_answer": "性行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试他的性行很好。", "explanation": "这里应该用〈表现〉。性行指人长期的性情和品行，一次考试中的表现要用〈表现〉。"}, {"text": "这篇文章的性行很幽默。", "explanation": "这里应该用〈风格〉。性行只用于人，说文章的写法要用〈风格〉。"}, {"text": "这座城市的性行很开放。", "explanation": "这里应该用〈性格〉。性行只用于人，说城市的个性要用〈性格〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0276bb3d-0a3e-470f-9a6d-d191d79e25a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92142, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这个人很性行温和，所以人缘很好。", "corrected_sentence": "他这个人性行温和，所以人缘很好。", "error_description": "词性错误。“性行”是名词，不能受“很”修饰，“很”应去掉，直接说“性行温和”。错误形式：很性行温和；正确形式：性行温和。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0276bb3d-0a3e-470f-9a6d-d191d79e25a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92142, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他这几年变得很性行温和了。", "corrected_sentence": "他这几年变得性行温和了。", "error_description": "词性错误。“性行”是名词，不能受“很”修饰，“很”应去掉，直接说“性行温和”。错误形式：很性行温和；正确形式：性行温和。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0276bb3d-0a3e-470f-9a6d-d191d79e25a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
