INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92143, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "引用是把别人说过的话拿来用。", "primary_collocate": null, "pronunciation": "yǐn yòng", "ipa": "in˨˩ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "写文章时，可以引用名人的话。", "target_word": "引用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在发言里引用了老师说的一句话。", "target_word": "引用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "引用别人的话，要说明是谁说的。", "target_word": "引用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她常常引用妈妈的话来教孩子。", "target_word": "引用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这句话是我从书上引用的。", "target_word": "引用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "演讲时他引用过爷爷的一句老话。", "target_word": "引用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，引用别人的话要加引号。", "target_word": "引用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你为什么总是引用同一个人的话？", "target_word": "引用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他开会时引用了经理昨天说的话。", "target_word": "引用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明在作文里引用了妈妈的话。", "target_word": "引用", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "引用了", "label": "体标"}, {"form": "引用过", "label": "体标"}], "register": "书面语", "sense_fingerprint": "引用：动词，把别人说过的话拿来用在自己的话或文章里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62980f86-a355-48b6-b578-ee1687d5ac53') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92143, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "引用", "is_correct": true, "explanation": "引用：援引名人的话作为文章的依据，符合句意。"}, {"text": "演唱", "is_correct": false, "explanation": "搭配：“演唱”的对象是歌曲，不能说演唱名人的话。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”指吃东西，不能表示援引，“吃名人的话”句意不通。"}, {"text": "煮", "is_correct": false, "explanation": "配价：“煮”需要食物作宾语，不能煮话语。"}], "explanations": {"引用": "引用：援引名人的话作为文章的依据，符合句意。", "演唱": "搭配：“演唱”的对象是歌曲，不能说演唱名人的话。", "吃": "搭配：“吃”指吃东西，不能表示援引，“吃名人的话”句意不通。", "煮": "配价：“煮”需要食物作宾语，不能煮话语。"}, "sentence_index": 0, "correct_answer": "引用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她常常引用妈妈的皮包来教孩子。", "explanation": "这里把〈引用〉当成了“拿来用”的泛用义；引用只针对话语、文字或事例，实物不能被援引。"}, {"text": "她常常引用妈妈的椅子来教孩子。", "explanation": "这里把〈引用〉当成了“拿来用”的泛用义；引用只针对话语、文字或事例，实物不能被援引。"}, {"text": "她常常引用妈妈的脾气来教孩子。", "explanation": "这里把〈引用〉当成了“拿来用”的泛用义；引用只针对话语、文字或事例，性格或情绪这类状态不能被援引。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dbd2967-c06a-4705-ac9f-18a26b80dd14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92143, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "引用", "is_correct": true, "explanation": "引用：把别人说过的话拿来用，老师说的是引用别人的话要加引号，符合句意。"}, {"text": "原谅", "is_correct": false, "explanation": "配价：“原谅”需要一个人作宾语，不能原谅别人的话。"}, {"text": "熟悉", "is_correct": false, "explanation": "语义：“熟悉”指了解某事物，与“要加引号”的句意不符，不能用来说明引用的要求。"}, {"text": "微笑", "is_correct": false, "explanation": "搭配：“微笑”是不及物动作，不能带“别人的话”作宾语。"}], "explanations": {"引用": "引用：把别人说过的话拿来用，老师说的是引用别人的话要加引号，符合句意。", "原谅": "配价：“原谅”需要一个人作宾语，不能原谅别人的话。", "熟悉": "语义：“熟悉”指了解某事物，与“要加引号”的句意不符，不能用来说明引用的要求。", "微笑": "搭配：“微笑”是不及物动作，不能带“别人的话”作宾语。"}, "sentence_index": 6, "correct_answer": "引用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小明在作文里引用了妈妈的鞋子。", "explanation": "这里把〈引用〉误用为“随便拿来用”的泛用义；引用只针对话语、文字或事例，实物不能被援引。"}, {"text": "小明在作文里引用了妈妈的心跳。", "explanation": "这里把〈引用〉误用为“提到、说起”的泛用义；引用只针对话语、文字或事例，生理现象不能被援引。"}, {"text": "小明在作文里引用了妈妈的汽车。", "explanation": "这里把〈引用〉误用为“随便拿来用”的泛用义；引用只针对话语、文字或事例，交通工具不能被援引。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dbd2967-c06a-4705-ac9f-18a26b80dd14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92143, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天在作文里引用着老师的一句话。", "corrected_sentence": "他昨天在作文里引用了老师的一句话。", "error_description": "错误：“昨天”表示动作已经完成，应用体标“了”；“着”表示动作或状态持续，不能用在这里。应说“引用了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dbd2967-c06a-4705-ac9f-18a26b80dd14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92143, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经引用着这句名言。", "corrected_sentence": "他曾经引用过这句名言。", "error_description": "错误：表示曾经发生过的经历应用体标“过”；“着”表示动作持续进行的状态，与“曾经”矛盾。正确应说“引用过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9dbd2967-c06a-4705-ac9f-18a26b80dd14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
