INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92145, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "看着大门，保护大家安全的人。", "primary_collocate": null, "pronunciation": "bǎo ān", "ipa": "pau˨˩˦ an˥", "syllable_count": 2, "sentences": [{"text": "小区门口有一位保安。", "target_word": "保安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保安站在大门口。", "target_word": "保安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保安叔叔帮我找到了钥匙。", "target_word": "保安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上保安会在楼下走一走。", "target_word": "保安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给保安看了我的卡。", "target_word": "保安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保安问我找谁。", "target_word": "保安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校的保安很热情。", "target_word": "保安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保安正坐在门口看报纸。", "target_word": "保安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保安替我把门打开了。", "target_word": "保安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店的保安在门口站着。", "target_word": "保安", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "保安员", "label": "复合"}], "register": "中性", "sense_fingerprint": "守在大门口、保护大家安全的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a182e01-4fd0-41b9-afec-41667e58b233') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92145, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保安", "is_correct": true, "explanation": "正确：“保安”指看门、保护安全的人，与“小区门口有一位”搭配。"}, {"text": "皇帝", "is_correct": false, "explanation": "语义：皇帝是古代的君主，不会在小区门口值守。"}, {"text": "海盗", "is_correct": false, "explanation": "语义：海盗是在海上抢东西的人，不会在小区门口。"}, {"text": "老爷", "is_correct": false, "explanation": "语域：“老爷”是旧时的称呼，不用于说现代小区的守门人。"}], "explanations": {"保安": "正确：“保安”指看门、保护安全的人，与“小区门口有一位”搭配。", "皇帝": "语义：皇帝是古代的君主，不会在小区门口值守。", "海盗": "语义：海盗是在海上抢东西的人，不会在小区门口。", "老爷": "语域：“老爷”是旧时的称呼，不用于说现代小区的守门人。"}, "sentence_index": 0, "correct_answer": "保安"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "保安负责调查这起案件。", "explanation": "这里应该用〈警察〉。保安负责看门、巡逻，不负责侦查案件；侦查是警察的职责。"}, {"text": "我们学校有一只保安。", "explanation": "这里量词不对。“只”用于动物，指人应该用〈位〉或〈名〉。"}, {"text": "保安每天负责开车接送孩子。", "explanation": "这里应该用〈司机〉。保安的工作是看门和巡逻，不负责开车接送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '170d71e0-dc2a-4314-bfe2-fb919f6a46ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92145, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保安", "is_correct": true, "explanation": "正确：“保安”指看门、保护安全的人，与“我们学校的”和“很热情”搭配。"}, {"text": "猎人", "is_correct": false, "explanation": "语义：猎人在山林里打猎，学校里不会有猎人当保安。"}, {"text": "海盗", "is_correct": false, "explanation": "语义：海盗是海上劫掠者，与学校的门卫工作无关。"}, {"text": "王爷", "is_correct": false, "explanation": "语域：“王爷”是古代的称谓，现代学校里不这样说，口语中说“保安”。"}], "explanations": {"保安": "正确：“保安”指看门、保护安全的人，与“我们学校的”和“很热情”搭配。", "猎人": "语义：猎人在山林里打猎，学校里不会有猎人当保安。", "海盗": "语义：海盗是海上劫掠者，与学校的门卫工作无关。", "王爷": "语域：“王爷”是古代的称谓，现代学校里不这样说，口语中说“保安”。"}, "sentence_index": 6, "correct_answer": "保安"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "保安每天打扫办公楼。", "explanation": "这里应该用〈清洁工〉。保安的职责是看门、巡逻，打扫卫生是清洁工的工作。"}, {"text": "这家商店请了一台保安。", "explanation": "这里量词不对。“台”用于机器，指人应该用〈位〉或〈名〉。"}, {"text": "保安给客人端菜。", "explanation": "这里应该用〈服务员〉。保安负责看守，端菜是服务员的工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '170d71e0-dc2a-4314-bfe2-fb919f6a46ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92145, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一位保安们正在门口值班。", "corrected_sentence": "一位保安正在门口值班。", "error_description": "错误：数量词“一位”修饰的名词后面不能再加“们”。正确应为“一位保安正在门口值班”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '170d71e0-dc2a-4314-bfe2-fb919f6a46ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92145, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "门口站着一条保安。", "corrected_sentence": "门口站着一位保安。", "error_description": "错误：量词“条”用于狗、鱼等，不用于人。保安是人，应该用“位”或“名”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '170d71e0-dc2a-4314-bfe2-fb919f6a46ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
