INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92147, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "恐慌是很怕，心里很乱。", "primary_collocate": null, "pronunciation": "kǒng huāng", "ipa": "kʰʊŋ˨˩ xuaŋ˥", "syllable_count": 2, "sentences": [{"text": "听到地震的消息，大家都很恐慌。", "target_word": "恐慌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人在黑夜里，心里很恐慌。", "target_word": "恐慌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试快开始了，她突然恐慌起来。", "target_word": "恐慌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子找不到妈妈，十分恐慌。", "target_word": "恐慌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到水一直往上涨，大家都恐慌了。", "target_word": "恐慌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的声音听起来很恐慌。", "target_word": "恐慌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别恐慌，医生马上就来。", "target_word": "恐慌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "半夜听到奇怪的声音，我有点恐慌。", "target_word": "恐慌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人丢了钱包，恐慌地到处找。", "target_word": "恐慌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车突然停了，乘客们都很恐慌。", "target_word": "恐慌", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "恐慌了", "label": "完成体"}], "register": "中性", "sense_fingerprint": "很害怕、心里很乱的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '106b6cc5-ef4e-4494-9883-9314d895a3e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92147, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "恐慌", "is_correct": true, "explanation": "正确答案。恐慌：很怕，心里很乱，与听到地震消息后的反应相符。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”表示愉快，与听到地震消息后的反应相反。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：“漂亮”说外貌，不能形容人听到地震消息后的心理状态。"}, {"text": "健康", "is_correct": false, "explanation": "语义：“健康”说身体状况，与地震消息中人的心理反应不符。"}], "explanations": {"恐慌": "正确答案。恐慌：很怕，心里很乱，与听到地震消息后的反应相符。", "高兴": "语义：“高兴”表示愉快，与听到地震消息后的反应相反。", "漂亮": "语义：“漂亮”说外貌，不能形容人听到地震消息后的心理状态。", "健康": "语义：“健康”说身体状况，与地震消息中人的心理反应不符。"}, "sentence_index": 0, "correct_answer": "恐慌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他恐慌地夸奖了我的作业。", "explanation": "这里应该用〈欣赏〉。恐慌表示害怕、心乱，与夸奖时的赞赏心情相反，这里应说欣赏。"}, {"text": "我恐慌地喜欢这首歌。", "explanation": "这里应改用〈深深〉。恐慌表示害怕、心乱，与喜欢的心情相反，不能用来修饰喜欢。"}, {"text": "我恐慌地享受着假期。", "explanation": "这里应该用〈放松〉。恐慌表示害怕、心乱，享受假期应当放松，恐慌与之相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92147, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "恐慌", "is_correct": true, "explanation": "正确答案。恐慌：害怕、心乱，与“别……，医生马上就来”的语境相符。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：“漂亮”说外貌，不能用于劝人“别……”时指的心理状态。"}, {"text": "精彩", "is_correct": false, "explanation": "语义：“精彩”形容表演、比赛等，不能形容人的心理状态。"}, {"text": "富裕", "is_correct": false, "explanation": "语义：“富裕”说经济条件，与“别……”的安慰语气不符。"}], "explanations": {"恐慌": "正确答案。恐慌：害怕、心乱，与“别……，医生马上就来”的语境相符。", "漂亮": "语义：“漂亮”说外貌，不能用于劝人“别……”时指的心理状态。", "精彩": "语义：“精彩”形容表演、比赛等，不能形容人的心理状态。", "富裕": "语义：“富裕”说经济条件，与“别……”的安慰语气不符。"}, "sentence_index": 6, "correct_answer": "恐慌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子收到礼物，恐慌地笑了。", "explanation": "这里应该用〈高兴〉。恐慌表示害怕、心乱，收到礼物不会恐慌。"}, {"text": "他赢了比赛，恐慌地扬起了头。", "explanation": "这里应该用〈得意〉。赢了比赛应当得意，恐慌与此语境矛盾。"}, {"text": "妈妈说没事，我终于恐慌了。", "explanation": "这里应该用〈安心〉。妈妈说没事，我应当安心，恐慌与语境相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92147, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子听到哭声，突然恐慌起。", "corrected_sentence": "孩子听到哭声，突然恐慌起来。", "error_description": "错误：“恐慌起”；正确：“恐慌起来”。“起来”作趋向补语，不能省略成“起”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92147, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一晚上都恐慌的坐不住。", "corrected_sentence": "他一晚上都恐慌得坐不住。", "error_description": "错误：“恐慌的坐不住”；正确：“恐慌得坐不住”。引出程度补语要用“得”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '456f9d03-c410-4729-b2ab-6bb56bf95261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
