INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92149, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "抵达是走到了要去的地方。", "primary_collocate": null, "pronunciation": "dǐ dá", "ipa": "ti˨˩˦ ta˧˥", "syllable_count": 2, "sentences": [{"text": "我们下午三点抵达了北京。", "target_word": "抵达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车明天早上抵达上海。", "target_word": "抵达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走了一天，终于抵达山顶。", "target_word": "抵达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你抵达宾馆后，请给我打电话。", "target_word": "抵达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机已经抵达机场了。", "target_word": "抵达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们坐车抵达了学校。", "target_word": "抵达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们走了很久才抵达那个小村子。", "target_word": "抵达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一次抵达这个城市，什么都不认识。", "target_word": "抵达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人们都抵达了饭店。", "target_word": "抵达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他骑车两个小时就抵达了海边。", "target_word": "抵达", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抵达了", "label": "完成体"}, {"form": "抵达过", "label": "经历体"}], "register": "书面语", "sense_fingerprint": "走到要去的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68b6fea3-2699-4510-9ab1-0d36748570eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92149, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "抵达", "is_correct": true, "explanation": "正确：抵达（dǐ dá）指走到了要去的地方。"}, {"text": "地大", "is_correct": false, "explanation": "dì（第四声）与 dǐ（第三声）声调不同，“地大”意思是地域广阔，与“抵达”意思不同。"}, {"text": "滴答", "is_correct": false, "explanation": "dī（第一声）与 dǐ（第三声）声调不同，“滴答”是象声词，指钟表的声音。"}, {"text": "抵挡", "is_correct": false, "explanation": "dǐ dǎng 与 dǐ dá 第二个音节不同（dǎng 有鼻音韵尾、第三声）。“抵挡”意思是挡住、抵抗，与“抵达”意思不同。"}], "explanations": {"抵达": "正确：抵达（dǐ dá）指走到了要去的地方。", "地大": "dì（第四声）与 dǐ（第三声）声调不同，“地大”意思是地域广阔，与“抵达”意思不同。", "滴答": "dī（第一声）与 dǐ（第三声）声调不同，“滴答”是象声词，指钟表的声音。", "抵挡": "dǐ dǎng 与 dǐ dá 第二个音节不同（dǎng 有鼻音韵尾、第三声）。“抵挡”意思是挡住、抵抗，与“抵达”意思不同。"}, "sentence_index": null, "correct_answer": "抵达"}, "level_3": {"options": [{"text": "抵达", "is_correct": true, "explanation": "正确：“抵达”表示到达，可以说“抵达了北京”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象是歌曲，不能说“唱了北京”。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，“北京”是地点，不能搭配。"}, {"text": "挖", "is_correct": false, "explanation": "语义：“挖”指掘土，“挖了北京”不能表示到达某地。"}], "explanations": {"抵达": "正确：“抵达”表示到达，可以说“抵达了北京”。", "唱": "语义：“唱”的对象是歌曲，不能说“唱了北京”。", "吃": "搭配：“吃”的对象是食物，“北京”是地点，不能搭配。", "挖": "语义：“挖”指掘土，“挖了北京”不能表示到达某地。"}, "sentence_index": 0, "correct_answer": "抵达"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在城门口抵达了敌人。", "explanation": "这里应该用〈抵抗〉。“抵达”指到达某个地点，“敌人”不是地点，不能用“抵达”。"}, {"text": "他把房子抵达了银行。", "explanation": "这里应该用〈抵押〉。“把房子抵押给银行”指以房子作担保借钱，“抵达”表示到达，意思不符。"}, {"text": "他终于抵达了那道难题。", "explanation": "这里应该用〈解决〉。“抵达”指到达地点，“难题”不是地点，应说“解决难题”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92149, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抵达", "is_correct": true, "explanation": "正确：“抵达”表示经过长时间走到目的地，与“走了很久”相符。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指燃烧，不能表示到达某个村子，与句中语境不符。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”指抛掷，不能用来表示到达村子。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”的对象多是食物或动物，不能搭配“村子”。"}], "explanations": {"抵达": "正确：“抵达”表示经过长时间走到目的地，与“走了很久”相符。", "烧": "语义：“烧”指燃烧，不能表示到达某个村子，与句中语境不符。", "扔": "语义：“扔”指抛掷，不能用来表示到达村子。", "咬": "搭配：“咬”的对象多是食物或动物，不能搭配“村子”。"}, "sentence_index": 6, "correct_answer": "抵达"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去银行抵达了手续。", "explanation": "这里应该用〈办理〉。“手续”是要办的事，应说“办理手续”，“抵达”只能用于到达地点。"}, {"text": "他抵达了生病的朋友。", "explanation": "这里应该用〈看望〉。“抵达”的对象是地点，“生病的朋友”是人，应说“看望”。"}, {"text": "他在路上抵达了老师。", "explanation": "这里应该用〈遇到〉。“抵达”表示到达地点，“老师”是人，不能作“抵达”的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92149, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们明天中午抵达了北京。", "corrected_sentence": "我们明天中午抵达北京。", "error_description": "错误：“抵达了”；正确：“抵达”。“明天中午”指将来，将来的动作一般不用“了”表示完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92149, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们走了三天，终于抵达在海边。", "corrected_sentence": "他们走了三天，终于抵达海边。", "error_description": "错误：“抵达在”；正确：“抵达”。“抵达”后直接接地点，不能加介词“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
