INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92150, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "到达；到了目的地。", "primary_collocate": null, "pronunciation": "dǐ dá", "ipa": "ti˨˩˦ ta˧˥", "syllable_count": 2, "sentences": [{"text": "船在晚上抵达了港口。", "target_word": "抵达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们明天中午抵达目的地。", "target_word": "抵达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机准时抵达了成都。", "target_word": "抵达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你抵达以后，请给我发短信。", "target_word": "抵达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们坐了十小时的车，抵达了西安。", "target_word": "抵达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥昨天抵达了广州。", "target_word": "抵达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师抵达会场的时候，大家都已经坐好了。", "target_word": "抵达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队员们抵达车站时，天已经黑了。", "target_word": "抵达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她下午五点抵达了这个小城。", "target_word": "抵达", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们平安抵达了家乡。", "target_word": "抵达", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抵达了", "label": "完成体"}, {"form": "抵达过", "label": "经历体"}], "register": "书面语", "sense_fingerprint": "到达目的地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68b6fea3-2699-4510-9ab1-0d36748570eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92150, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "抵达", "is_correct": true, "explanation": "正确：抵达（dǐ dá）指到了要去的地方。"}, {"text": "地大", "is_correct": false, "explanation": "dì（第四声）与 dǐ（第三声）声调不同，“地大”意思是地域广阔，与“抵达”意思不同。"}, {"text": "滴答", "is_correct": false, "explanation": "dī（第一声）与 dǐ（第三声）声调不同，“滴答”是象声词，指钟表的声音。"}, {"text": "抵挡", "is_correct": false, "explanation": "dǐ dǎng 与 dǐ dá 第二个音节不同（dǎng 有鼻音韵尾、第三声）。“抵挡”意思是挡住、抵抗，与“抵达”意思不同。"}], "explanations": {"抵达": "正确：抵达（dǐ dá）指到了要去的地方。", "地大": "dì（第四声）与 dǐ（第三声）声调不同，“地大”意思是地域广阔，与“抵达”意思不同。", "滴答": "dī（第一声）与 dǐ（第三声）声调不同，“滴答”是象声词，指钟表的声音。", "抵挡": "dǐ dǎng 与 dǐ dá 第二个音节不同（dǎng 有鼻音韵尾、第三声）。“抵挡”意思是挡住、抵抗，与“抵达”意思不同。"}, "sentence_index": null, "correct_answer": "抵达"}, "level_3": {"options": [{"text": "抵达", "is_correct": true, "explanation": "正确：“抵达”表示船到达港口，可以说“抵达了港口”。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”指擦拭，“擦了港口”不能表示船到达。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，“港口”是地点，不能搭配。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮品，“港口”不能作“喝”的对象。"}], "explanations": {"抵达": "正确：“抵达”表示船到达港口，可以说“抵达了港口”。", "擦": "语义：“擦”指擦拭，“擦了港口”不能表示船到达。", "吃": "搭配：“吃”的对象是食物，“港口”是地点，不能搭配。", "喝": "搭配：“喝”的对象是饮品，“港口”不能作“喝”的对象。"}, "sentence_index": 0, "correct_answer": "抵达"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校抵达了一场比赛。", "explanation": "这里应该用〈举办〉。“抵达”指到达地点，“比赛”是活动，学校不能“抵达”比赛。"}, {"text": "他抵达了这个建议。", "explanation": "这里应该用〈接受〉。“抵达”指到达某地，“建议”不是地点，应说“接受建议”。"}, {"text": "他抵达了那件衣服。", "explanation": "这里应该用〈穿〉。“抵达”指到达地点，“衣服”不是地点，应说“穿衣服”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92150, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抵达", "is_correct": true, "explanation": "正确：“抵达”表示老师到达会场，与后面“大家都已经坐好了”相符。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：“拆除”指拆掉建筑，与“大家都已经坐好了”的语境相矛盾。"}, {"text": "砸", "is_correct": false, "explanation": "语义：“砸”指敲打破坏，与会场里有序就座的情境不符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能搭配“会场”。"}], "explanations": {"抵达": "正确：“抵达”表示老师到达会场，与后面“大家都已经坐好了”相符。", "拆除": "语义：“拆除”指拆掉建筑，与“大家都已经坐好了”的语境相矛盾。", "砸": "语义：“砸”指敲打破坏，与会场里有序就座的情境不符。", "唱": "搭配：“唱”的对象是歌曲，不能搭配“会场”。"}, "sentence_index": 6, "correct_answer": "抵达"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家抵达了客人。", "explanation": "这里应该用〈欢迎〉。“抵达”的对象是地点，“客人”是人，应说“欢迎客人”。"}, {"text": "他抵达了生病的父母。", "explanation": "这里应该用〈照顾〉。“照顾”的对象是人，“抵达”的对象是地点，不能搭配“父母”。"}, {"text": "他抵达了考试。", "explanation": "这里应该用〈通过〉。“抵达”表示到达地点，“考试”不是地点，应说“通过考试”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92150, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们明天下午抵达到机场。", "corrected_sentence": "他们明天下午抵达机场。", "error_description": "错误：多加了“到”；正确：“抵达”本身已含“到”的意思，后面直接接地点。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92150, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她上个月抵达了过伦敦。", "corrected_sentence": "她上个月抵达过伦敦。", "error_description": "错误：“了过”重复；正确：“抵达过”。“过”表示经历，已能表达曾经发生的动作，不能再加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
