INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92151, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "心里很相信，一定要做到的想法。", "primary_collocate": null, "pronunciation": "xìn niàn", "ipa": "ɕin˥˩ njɛn˥˩", "syllable_count": 2, "sentences": [{"text": "他有一个信念，一定要考上大学。", "target_word": "信念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "靠着这个信念，她每天坚持练习。", "target_word": "信念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的信念是，明年一定要学会游泳。", "target_word": "信念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心里有信念，所以再累也不放弃。", "target_word": "信念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的信念是让每个孩子都学会读书。", "target_word": "信念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她没有放弃自己的信念，终于做到了。", "target_word": "信念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸常说，有信念的人才能成功。", "target_word": "信念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个信念让他走过了最难的日子。", "target_word": "信念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们带着同一个信念来到这个城市。", "target_word": "信念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想做好这件事，先要有坚定的信念。", "target_word": "信念", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "心里相信并一定要做到的想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a8fa994-3fd8-45ac-8f40-a9acd11355a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92151, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信念", "is_correct": true, "explanation": "“信念”指心里很相信、一定要做到的想法，与“一定要考上大学”的决心相合。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指性情，不是“一定要考上大学”这种目标或打算。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指外形，不能用来指“一定要考上大学”的决心。"}, {"text": "玩笑", "is_correct": false, "explanation": "语义：“玩笑”是逗乐的话，不能表示“一定要考上大学”这种坚定的想法。"}], "explanations": {"信念": "“信念”指心里很相信、一定要做到的想法，与“一定要考上大学”的决心相合。", "脾气": "语义：“脾气”指性情，不是“一定要考上大学”这种目标或打算。", "身材": "体貌：“身材”指外形，不能用来指“一定要考上大学”的决心。", "玩笑": "语义：“玩笑”是逗乐的话，不能表示“一定要考上大学”这种坚定的想法。"}, "sentence_index": 0, "correct_answer": "信念"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今天突然有个信念，想去爬山。", "explanation": "这里应该用〈念头〉。信念指长期坚定、一定要做到的想法，不用于一时冒出的念头。"}, {"text": "他向母亲许下了信念，一定要考上大学。", "explanation": "这里应该用〈诺言〉。许下的是诺言，信念是心里坚定的想法，不能向别人许下。"}, {"text": "他养成了每天锻炼的信念。", "explanation": "这里应该用〈习惯〉。养成的是习惯，信念是坚信的想法，不能养成一种日常行为。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92151, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信念", "is_correct": true, "explanation": "“信念”指心里坚信、一定要做到的想法，“有信念的人”指有坚定追求的人，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能用“有……的人”来修饰，与“才能成功”也没有逻辑联系。"}, {"text": "小说", "is_correct": false, "explanation": "语义：“小说”是文学作品，不是人靠它就能成功的东西。"}, {"text": "电话", "is_correct": false, "explanation": "语义：“电话”是通信工具，“有电话的人才能成功”没有道理。"}], "explanations": {"信念": "“信念”指心里坚信、一定要做到的想法，“有信念的人”指有坚定追求的人，符合句意。", "天气": "搭配：“天气”不能用“有……的人”来修饰，与“才能成功”也没有逻辑联系。", "小说": "语义：“小说”是文学作品，不是人靠它就能成功的东西。", "电话": "语义：“电话”是通信工具，“有电话的人才能成功”没有道理。"}, "sentence_index": 6, "correct_answer": "信念"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的信念跑得很快。", "explanation": "这里应该用〈脚步〉。“跑得很快”形容动作或脚步的速度，信念是心里的想法，没有快慢。"}, {"text": "他的信念是打篮球，从来不换。", "explanation": "这里应该用〈爱好〉。信念指坚信不疑的想法，不用来说一般的兴趣。"}, {"text": "这个信念很难解决。", "explanation": "这里应该用〈问题〉。信念是心里的想法，不能“解决”，“解决”适用于问题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92151, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他心里有一本信念，想要成为医生。", "corrected_sentence": "他心里有一种信念，想要成为医生。", "error_description": "量词错误：“信念”应该用量词“种”或“个”，不能用“本”。“本”用于书籍，这里应改为“一种信念”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92151, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一直把自己信念放在心里，没有忘记。", "corrected_sentence": "他一直把自己的信念放在心里，没有忘记。", "error_description": "修饰语错误：“自己”修饰“信念”时要加“的”，应写作“自己的信念”，不能说“自己信念”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
