INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92152, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92152, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "坚信不疑的想法和意志。", "primary_collocate": null, "pronunciation": "xìn niàn", "ipa": "ɕin˥˩ njɛn˥˩", "syllable_count": 2, "sentences": [{"text": "他的信念非常坚定，谁也改变不了。", "target_word": "信念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生的信念是，每个病人都能好起来。", "target_word": "信念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即使很难，她也没有丢掉信念。", "target_word": "信念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对他来说，信念比钱更重要。", "target_word": "信念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人用一生守住了自己的信念。", "target_word": "信念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家的信念让这支队伍越来越强。", "target_word": "信念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他相信好人有好报，这是他的信念。", "target_word": "信念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有信念的人，遇到困难就会害怕。", "target_word": "信念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这个信念从不怀疑，一直坚持下去。", "target_word": "信念", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王的信念一直没有变，他要当老师。", "target_word": "信念", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "坚信不疑的想法和意志", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a8fa994-3fd8-45ac-8f40-a9acd11355a6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92152, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "信念", "is_correct": true, "explanation": "“信念”指坚信不疑的想法和意志，可以用“非常坚定”来形容，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”没有“坚定”的意思，不能用“非常坚定”形容。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“坚定”用于人的意志或立场，不修饰“桌子”。"}, {"text": "发型", "is_correct": false, "explanation": "体貌：“发型”指外形，不能用“坚定”来形容。"}], "explanations": {"信念": "“信念”指坚信不疑的想法和意志，可以用“非常坚定”来形容，符合句意。", "天气": "语义：“天气”没有“坚定”的意思，不能用“非常坚定”形容。", "桌子": "搭配：“坚定”用于人的意志或立场，不修饰“桌子”。", "发型": "体貌：“发型”指外形，不能用“坚定”来形容。"}, "sentence_index": 0, "correct_answer": "信念"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的信念是打篮球，从来不改变。", "explanation": "这里应该用〈爱好〉。信念指坚信不疑的想法，不用来说一般的兴趣。"}, {"text": "他当众许下了信念，承诺一定会做到。", "explanation": "这里应该用〈诺言〉。许下的是诺言，信念是心里坚定的想法，不能当众许下。"}, {"text": "他的信念走得很快。", "explanation": "这里应该用〈脚步〉。“走得很快”形容人行走的速度，信念是心里的想法，不能说快慢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92152, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "信念", "is_correct": true, "explanation": "“信念”指坚信不疑的想法和意志，“这是他的信念”指这是他坚持的想法，符合句意。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：“汽车”是交通工具，与“相信好人有好报”的内容没有关系。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指外形，不能用来指一个人相信的道理。"}, {"text": "鞋", "is_correct": false, "explanation": "语义：“鞋”是穿的东西，不能用来指“相信好人有好报”这种想法。"}], "explanations": {"信念": "“信念”指坚信不疑的想法和意志，“这是他的信念”指这是他坚持的想法，符合句意。", "汽车": "语义：“汽车”是交通工具，与“相信好人有好报”的内容没有关系。", "身材": "体貌：“身材”指外形，不能用来指一个人相信的道理。", "鞋": "语义：“鞋”是穿的东西，不能用来指“相信好人有好报”这种想法。"}, "sentence_index": 6, "correct_answer": "信念"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他养成了每天早起的信念。", "explanation": "这里应该用〈习惯〉。养成的是习惯，信念是坚信不疑的想法，不能养成一种日常行为。"}, {"text": "这个信念很难解决，大家想了很久。", "explanation": "这里应该用〈问题〉。“解决”的对象是问题，信念是坚信不疑的想法，不能“解决”。"}, {"text": "他今天信念很好，吃了两碗饭。", "explanation": "这里应该用〈胃口〉。“胃口好”说的是食欲，信念是心里坚定的想法，不能用来形容吃饭的欲望。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92152, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的心里有一张信念，非常坚定。", "corrected_sentence": "她的心里有一种信念，非常坚定。", "error_description": "量词错误：“信念”应该用“种”或“个”，“张”用于纸张、桌子等平面物品，不能修饰“信念”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92152, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把自己信念丢掉了，所以很后悔。", "corrected_sentence": "他把自己的信念丢掉了，所以很后悔。", "error_description": "修饰语错误：“自己”修饰“信念”时要加“的”，应写作“自己的信念”，不能说“自己信念”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa38d876-7073-4a29-9493-f473535f7feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
