INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92154, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容年代久远，历史长。", "primary_collocate": null, "pronunciation": "yōu jiǔ", "ipa": "joʊ˥ tɕjoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这座寺庙年代悠久。", "target_word": "悠久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一座年代悠久的古塔。", "target_word": "悠久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中华文化历史悠久。", "target_word": "悠久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家博物馆里有很多年代悠久的东西。", "target_word": "悠久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "西安是一座历史悠久的城市。", "target_word": "悠久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条老街的历史十分悠久。", "target_word": "悠久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的家乡有一座历史悠久的古镇。", "target_word": "悠久", "complexity_tier": "T3", "furigana": "tā de jiā xiāng yǒu yí zuò lì shǐ yōu jiǔ de gǔ zhèn", "sentence_source": "generated"}, {"text": "这座古庙有着悠久的历史，香火很旺。", "target_word": "悠久", "complexity_tier": "T3", "furigana": "zhè zuò gǔ miào yǒu zhe yōu jiǔ de lì shǐ, xiāng huǒ hěn wàng", "sentence_source": "generated"}, {"text": "那个民族有着悠久的文化。", "target_word": "悠久", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节是一个历史悠久的节日。", "target_word": "悠久", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "年代悠久", "label": "复合"}], "register": "书面", "sense_fingerprint": "形容事物的年代久远、历史很长，如文化、古迹", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28a127e4-6f10-4f8a-b8d9-beff9815793c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92154, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "悠久", "is_correct": true, "explanation": "悠久描述“年代”，指年代久远，与寺庙的古老相符。"}, {"text": "短暂", "is_correct": false, "explanation": "语义：“短暂”说时间很短，与“寺庙年代”的古老语境矛盾。"}, {"text": "新鲜", "is_correct": false, "explanation": "搭配：“新鲜”不修饰“年代”，只用于食物、空气等。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”描写形体，不能用来修饰“年代”。"}], "explanations": {"悠久": "悠久描述“年代”，指年代久远，与寺庙的古老相符。", "短暂": "语义：“短暂”说时间很短，与“寺庙年代”的古老语境矛盾。", "新鲜": "搭配：“新鲜”不修饰“年代”，只用于食物、空气等。", "高大": "搭配：“高大”描写形体，不能用来修饰“年代”。"}, "sentence_index": 0, "correct_answer": "悠久"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的耐心很悠久。", "explanation": "这里应该用〈持久〉。悠久只说历史、传统等年代久远，耐心的延续要用持久。"}, {"text": "我们在街上遇见了悠久的朋友。", "explanation": "这里应该用〈久违〉。悠久说的是年代久远，许久未见的朋友要用久违。"}, {"text": "我的表弟很悠久。", "explanation": "这里应该用〈年轻〉。悠久用于历史、传统的年代，不用来说人的年龄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3ebdeb5-e7f4-4049-b6ee-561b9731ae5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92154, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "悠久", "is_correct": true, "explanation": "悠久描述“历史”，表示年代久远，与“古镇”相符。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”形容水或眼神，不能修饰“历史”。"}, {"text": "狭窄", "is_correct": false, "explanation": "语义：“狭窄”指空间窄小，与“历史”的时间含义不合。"}, {"text": "浓烈", "is_correct": false, "explanation": "搭配：“浓烈”多形容味道或感情，不用于修饰“历史”。"}], "explanations": {"悠久": "悠久描述“历史”，表示年代久远，与“古镇”相符。", "清澈": "搭配：“清澈”形容水或眼神，不能修饰“历史”。", "狭窄": "语义：“狭窄”指空间窄小，与“历史”的时间含义不合。", "浓烈": "搭配：“浓烈”多形容味道或感情，不用于修饰“历史”。"}, "sentence_index": 6, "correct_answer": "悠久"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们的相遇很悠久。", "explanation": "这里应该用〈短暂〉。悠久强调年代久远，相遇只是片刻，要用短暂。"}, {"text": "这里的空气很悠久。", "explanation": "这里应该用〈新鲜〉。悠久形容历史、传统的年代，空气的清新要用新鲜。"}, {"text": "那个孩子还很悠久。", "explanation": "这里应该用〈年幼〉。悠久说的是年代，不能用来形容孩子年纪小，要用年幼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3ebdeb5-e7f4-4049-b6ee-561b9731ae5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92154, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一座历史悠久了的古殿。", "corrected_sentence": "这是一座历史悠久的古殿。", "error_description": "错误：“悠久”后多加了“了”。“悠久”是形容词，修饰名词时后面直接用“的”。正确：“这是一座历史悠久的古殿。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3ebdeb5-e7f4-4049-b6ee-561b9731ae5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92154, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座古塔的年代悠久得。", "corrected_sentence": "这座古塔的年代悠久得很。", "error_description": "错误：“悠久得”是带补语的结构，“得”后缺少补语“很”，应写作“悠久得很”。正确：“这座古塔的年代悠久得很。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3ebdeb5-e7f4-4049-b6ee-561b9731ae5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
