INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92155, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "考是老师出题，让你回答，看你会不会。", "primary_collocate": null, "pronunciation": "kǎo", "ipa": "kʰau˨˩˦", "syllable_count": 1, "sentences": [{"text": "老师考我们今天学的词。", "target_word": "考", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈考了我三个汉字。", "target_word": "考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师想考我们，看谁记得住。", "target_word": "考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师出了一道难题考大家。", "target_word": "考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他常用有意思的问题考学生。", "target_word": "考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸拿一本书考我会不会读。", "target_word": "考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师突然考我一个问题，我答不上来。", "target_word": "考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "课上老师常常考我们生词。", "target_word": "考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友故意考我，问我这个字怎么读。", "target_word": "考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师考了我们三个问题，大家都答对了。", "target_word": "考", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "考了", "label": "体标"}, {"form": "考过", "label": "体标"}, {"form": "考一考", "label": "重叠"}], "register": "口语", "sense_fingerprint": "动词：出题让别人回答，看对方会不会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f82317-b64b-4c72-a0db-f7ebe4e148f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92155, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "考", "is_correct": true, "explanation": "正确。“考”读 kǎo（第三声），意思是出题考人。"}, {"text": "好", "is_correct": false, "explanation": "声母不同：“好”读 hǎo，声母 h 与 k 不同，意思是好。"}, {"text": "靠", "is_correct": false, "explanation": "声调不同：“靠”读 kào（第四声），与 kǎo（第三声）只差声调，意思是靠近。"}, {"text": "老", "is_correct": false, "explanation": "声母不同：“老”读 lǎo，声母 l 与 k 不同，意思是年纪大。"}, {"text": "跑", "is_correct": false, "explanation": "声母不同：“跑”读 pǎo，声母 p 与 k 不同，意思是奔跑。"}], "explanations": {"考": "正确。“考”读 kǎo（第三声），意思是出题考人。", "好": "声母不同：“好”读 hǎo，声母 h 与 k 不同，意思是好。", "靠": "声调不同：“靠”读 kào（第四声），与 kǎo（第三声）只差声调，意思是靠近。", "老": "声母不同：“老”读 lǎo，声母 l 与 k 不同，意思是年纪大。", "跑": "声母不同：“跑”读 pǎo，声母 p 与 k 不同，意思是奔跑。"}, "sentence_index": null, "correct_answer": "考"}, "level_3": {"options": [{"text": "考", "is_correct": true, "explanation": "正确。“老师考我们今天学的词”指老师出题让学生回答。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能带“今天学的词”作宾语，“吃词”不成立。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”与“学的词”无关，“老师洗我们学的词”说不通。"}, {"text": "戒", "is_correct": false, "explanation": "语义：“戒”指戒除，不能用于“学的词”，句子意思不通。"}], "explanations": {"考": "正确。“老师考我们今天学的词”指老师出题让学生回答。", "吃": "搭配：“吃”不能带“今天学的词”作宾语，“吃词”不成立。", "洗": "语义：“洗”与“学的词”无关，“老师洗我们学的词”说不通。", "戒": "语义：“戒”指戒除，不能用于“学的词”，句子意思不通。"}, "sentence_index": 0, "correct_answer": "考"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工厂要考这批产品。", "explanation": "这里应该用〈检验〉。“考”用于出题考人，不用于检验产品。"}, {"text": "护士要考我的体温。", "explanation": "这里应该用〈测量〉。“考”用于出题考人，不用于测量体温。"}, {"text": "厨师要考这锅汤的咸淡。", "explanation": "这里应该用〈尝〉。“考”用于出题考人，不用于尝汤的味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92155, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "考", "is_correct": true, "explanation": "正确。“考”读 kǎo（第三声），意思是出题考人。"}, {"text": "保", "is_correct": false, "explanation": "声母不同：“保”读 bǎo，声母 b 与 k 不同，意思是保护。"}, {"text": "早", "is_correct": false, "explanation": "声母不同：“早”读 zǎo，声母 z 与 k 不同，意思是早晨。"}, {"text": "咬", "is_correct": false, "explanation": "声母不同：“咬”读 yǎo，声母 y 与 k 不同，意思是用牙齿咬。"}, {"text": "稿", "is_correct": false, "explanation": "声母不同：“稿”读 gǎo，声母 g 与 k 不同，意思是稿子。"}], "explanations": {"考": "正确。“考”读 kǎo（第三声），意思是出题考人。", "保": "声母不同：“保”读 bǎo，声母 b 与 k 不同，意思是保护。", "早": "声母不同：“早”读 zǎo，声母 z 与 k 不同，意思是早晨。", "咬": "声母不同：“咬”读 yǎo，声母 y 与 k 不同，意思是用牙齿咬。", "稿": "声母不同：“稿”读 gǎo，声母 g 与 k 不同，意思是稿子。"}, "sentence_index": null, "correct_answer": "考"}, "level_3": {"options": [{"text": "考", "is_correct": true, "explanation": "正确。“老师突然考我一个问题”指老师出题让我回答。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”不能用来指出题，“老师突然唱我一个问题”说不通。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”不能带“问题”作宾语，搭配不当。"}, {"text": "穿", "is_correct": false, "explanation": "语义：“穿”指穿戴，与“问题”和“答不上来”的语境不符。"}], "explanations": {"考": "正确。“老师突然考我一个问题”指老师出题让我回答。", "唱": "语义：“唱”不能用来指出题，“老师突然唱我一个问题”说不通。", "喝": "搭配：“喝”不能带“问题”作宾语，搭配不当。", "穿": "语义：“穿”指穿戴，与“问题”和“答不上来”的语境不符。"}, "sentence_index": 6, "correct_answer": "考"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在考那辆车的油耗。", "explanation": "这里应该用〈测试〉。“考”指出题让人回答，不用于测试汽车的油耗。"}, {"text": "警察在考这件案子。", "explanation": "这里应该用〈调查〉。“考”指出题让人回答，不用于调查案件。"}, {"text": "这次大雨考了我们的房子。", "explanation": "这里应该用〈考验〉。“考”指出题让人回答，不用于大雨对房子的考验。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92155, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师昨天考着我们三个汉字。", "corrected_sentence": "老师昨天考了我们三个汉字。", "error_description": "体标错误：“着”表示动作持续进行，与“昨天”已完成的事件不合，应把“着”改为“了”。正确：“老师昨天考了我们三个汉字”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92155, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师以前考了过我们三个汉字。", "corrected_sentence": "老师以前考过我们三个汉字。", "error_description": "体标重复：“考过”已含体标“过”，不能再加“了”，说“考了过”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
