INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92156, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "参加考试，接受他人出题对自己的知识或能力进行检查。", "primary_collocate": null, "pronunciation": "kǎo", "ipa": "kʰau˨˩˦", "syllable_count": 1, "sentences": [{"text": "我明天上午要考数学，现在很紧张。", "target_word": "考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次英语，他考了九十分。", "target_word": "考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她想考上北京的大学。", "target_word": "考", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟今年要考驾照。", "target_word": "考", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这次我没考好，成绩很差。", "target_word": "考", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你们考完以后可以回家。", "target_word": "考", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他为了考大学，每天都学三个小时。", "target_word": "考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们都在教室里考汉语，没有人说话。", "target_word": "考", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我哥哥去年考过一次，没有通过。", "target_word": "考", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他考得很好，老师笑了。", "target_word": "考", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "考了", "label": "体标"}, {"form": "考过", "label": "体标"}, {"form": "考一考", "label": "重叠"}], "register": "口语", "sense_fingerprint": "动词：参加考试（作为应试者），接受他人出题检查自己的知识或能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9f82317-b64b-4c72-a0db-f7ebe4e148f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92156, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "考", "is_correct": true, "explanation": "正确。“考”读 kǎo（第三声），意思是参加考试。"}, {"text": "好", "is_correct": false, "explanation": "声母不同：“好”读 hǎo，声母 h 与 k 不同，意思是好。"}, {"text": "靠", "is_correct": false, "explanation": "声调不同：“靠”读 kào（第四声），与 kǎo（第三声）只差声调，意思是靠近。"}, {"text": "老", "is_correct": false, "explanation": "声母不同：“老”读 lǎo，声母 l 与 k 不同，意思是年纪大。"}, {"text": "跑", "is_correct": false, "explanation": "声母不同：“跑”读 pǎo，声母 p 与 k 不同，意思是奔跑。"}], "explanations": {"考": "正确。“考”读 kǎo（第三声），意思是参加考试。", "好": "声母不同：“好”读 hǎo，声母 h 与 k 不同，意思是好。", "靠": "声调不同：“靠”读 kào（第四声），与 kǎo（第三声）只差声调，意思是靠近。", "老": "声母不同：“老”读 lǎo，声母 l 与 k 不同，意思是年纪大。", "跑": "声母不同：“跑”读 pǎo，声母 p 与 k 不同，意思是奔跑。"}, "sentence_index": null, "correct_answer": "考"}, "level_3": {"options": [{"text": "考", "is_correct": true, "explanation": "正确。“考数学”指参加数学考试，与“现在很紧张”的语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“数学”搭配，“要吃数学”说不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能带“数学”作宾语，句子不成立。"}, {"text": "戒", "is_correct": false, "explanation": "语义：“戒”指戒除，与“数学”无关，句子意思不通。"}], "explanations": {"考": "正确。“考数学”指参加数学考试，与“现在很紧张”的语境相符。", "吃": "搭配：“吃”不能与“数学”搭配，“要吃数学”说不通。", "洗": "搭配：“洗”不能带“数学”作宾语，句子不成立。", "戒": "语义：“戒”指戒除，与“数学”无关，句子意思不通。"}, "sentence_index": 0, "correct_answer": "考"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "护士要考我的体温。", "explanation": "这里应该用〈测量〉。“考”指参加考试或出题考人，不用于测量体温。"}, {"text": "医生要考我的眼睛。", "explanation": "这里应该用〈检查〉。“考”指参加考试或出题考人，不用于检查身体器官。"}, {"text": "工厂要考这批产品。", "explanation": "这里应该用〈检验〉。“考”用于人参加考试，不用于检验产品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92156, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "考", "is_correct": true, "explanation": "正确。“考”读 kǎo（第三声），意思是参加考试。"}, {"text": "保", "is_correct": false, "explanation": "声母不同：“保”读 bǎo，声母 b 与 k 不同，意思是保护。"}, {"text": "早", "is_correct": false, "explanation": "声母不同：“早”读 zǎo，声母 z 与 k 不同，意思是早晨。"}, {"text": "咬", "is_correct": false, "explanation": "声母不同：“咬”读 yǎo，声母 y 与 k 不同，意思是用牙齿咬。"}, {"text": "稿", "is_correct": false, "explanation": "声母不同：“稿”读 gǎo，声母 g 与 k 不同，意思是稿子。"}], "explanations": {"考": "正确。“考”读 kǎo（第三声），意思是参加考试。", "保": "声母不同：“保”读 bǎo，声母 b 与 k 不同，意思是保护。", "早": "声母不同：“早”读 zǎo，声母 z 与 k 不同，意思是早晨。", "咬": "声母不同：“咬”读 yǎo，声母 y 与 k 不同，意思是用牙齿咬。", "稿": "声母不同：“稿”读 gǎo，声母 g 与 k 不同，意思是稿子。"}, "sentence_index": null, "correct_answer": "考"}, "level_3": {"options": [{"text": "考", "is_correct": true, "explanation": "正确。“为了考大学”指为了参加大学入学考试。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”与“大学”不相关，“为了唱大学”说不通。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”不能带“大学”作宾语，搭配不当。"}, {"text": "穿", "is_correct": false, "explanation": "语义：“穿”指穿戴，“为了穿大学”没有意义。"}], "explanations": {"考": "正确。“为了考大学”指为了参加大学入学考试。", "唱": "语义：“唱”与“大学”不相关，“为了唱大学”说不通。", "喝": "搭配：“喝”不能带“大学”作宾语，搭配不当。", "穿": "语义：“穿”指穿戴，“为了穿大学”没有意义。"}, "sentence_index": 6, "correct_answer": "考"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位律师在考这份合同。", "explanation": "这里应该用〈审查〉。“考”指出题考人或参加考试，不用于审查合同。"}, {"text": "科学家在考这种新药的效果。", "explanation": "这里应该用〈评估〉。“考”指出题考人或参加考试，不用于评估药物的效果。"}, {"text": "这场大风考了我们的帐篷。", "explanation": "这里应该用〈考验〉。“考”指出题考人或参加考试，不用于大风对帐篷的考验。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92156, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐考很好，全班都知道了。", "corrected_sentence": "我姐姐考得很好，全班都知道了。", "error_description": "补语标记错误：“考”后接状态补语“很好”时必须加“得”，不能直接说“考很好”。正确：“我姐姐考得很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92156, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我哥哥去年考着一次驾照。", "corrected_sentence": "我哥哥去年考了一次驾照。", "error_description": "体标错误：“着”表示动作持续进行，与“去年”已完成的事件不合，应把“着”改为“了”。正确：“我哥哥去年考了一次驾照”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1862e300-81c9-4209-8179-774d3c82f4a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
