INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92157, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在一个地方不走。", "primary_collocate": null, "pronunciation": "tíng liú", "ipa": "tʰiŋ˧˥ ljoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "我在北京只停留了两天。", "target_word": "停留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在公园门口停留了十分钟。", "target_word": "停留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在门口停留了一会儿。", "target_word": "停留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客们在桥上停留，拍了很多照片。", "target_word": "停留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只猫在窗台上停留了很久，一动不动。", "target_word": "停留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在花店前停留了很久。", "target_word": "停留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要在路中间停留。", "target_word": "停留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在海边停留了一个下午。", "target_word": "停留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只在这个城市停留过一次。", "target_word": "停留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟在树上停留了一下，就飞走了。", "target_word": "停留", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "停留了", "label": "体标（了）"}, {"form": "停留过", "label": "体标（过）"}, {"form": "停留着", "label": "体标（着）"}], "register": "中性", "sense_fingerprint": "人或物在某地待着不离开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab3b97-f3d7-4c95-a0b9-3d6f706e958c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92157, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "停留", "is_correct": true, "explanation": "正确：“停留”指在某地待着不走，与“只……了两天”的时长搭配，句意通顺。"}, {"text": "生产", "is_correct": false, "explanation": "搭配：“生产”的主语是工厂或产品，人在北京待两天不能说生产。"}, {"text": "出发", "is_correct": false, "explanation": "语义：“出发”表示动身启程，不是待在一个地方，与“只……了两天”的句意不合。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：“毕业”是一次性完成的事件，不能持续两天，与“停留”的时长义不合。"}], "explanations": {"停留": "正确：“停留”指在某地待着不走，与“只……了两天”的时长搭配，句意通顺。", "生产": "搭配：“生产”的主语是工厂或产品，人在北京待两天不能说生产。", "出发": "语义：“出发”表示动身启程，不是待在一个地方，与“只……了两天”的句意不合。", "毕业": "语义：“毕业”是一次性完成的事件，不能持续两天，与“停留”的时长义不合。"}, "sentence_index": 0, "correct_answer": "停留"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说话时停留了一下。", "explanation": "这里应该用〈停顿〉。说话中间的短暂中断用停顿，停留是在某处待着不走。"}, {"text": "球员因为受伤停留了三场比赛。", "explanation": "这里应该用〈停赛〉。因受伤或处罚而不能参赛应说停赛，停留表示待在某处不走，不能表示停止参赛。"}, {"text": "他听到声音，停留了脚步。", "explanation": "这里应该用〈停下〉。说停下脚步，不说停留脚步。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac21c432-ba06-4bde-be5a-b3bcdaf2db26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92157, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "停留", "is_correct": true, "explanation": "正确：“停留”指在某处待着、不往前走，与“请不要”和“在路中间”搭配，句意通顺。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”需要水，路中间没有水，句子不通。"}, {"text": "繁殖", "is_correct": false, "explanation": "语义：“繁殖”指生物增加后代，与“请不要”的提醒语境不合。"}, {"text": "栖息", "is_correct": false, "explanation": "搭配：“栖息”的主体是鸟兽，不用于人在路中间待着。"}], "explanations": {"停留": "正确：“停留”指在某处待着、不往前走，与“请不要”和“在路中间”搭配，句意通顺。", "游泳": "语义：“游泳”需要水，路中间没有水，句子不通。", "繁殖": "语义：“繁殖”指生物增加后代，与“请不要”的提醒语境不合。", "栖息": "搭配：“栖息”的主体是鸟兽，不用于人在路中间待着。"}, "sentence_index": 6, "correct_answer": "停留"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工厂突然停留了生产。", "explanation": "这里应该用〈停止〉。停留指待在某处，不能表示生产中止。"}, {"text": "会议停留了十分钟。", "explanation": "这里应该用〈暂停〉。会议暂时中断应说暂停，停留不表示中断进行。"}, {"text": "风终于停留了。", "explanation": "这里应该用〈停歇〉。风停止时用停歇，不说停留。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac21c432-ba06-4bde-be5a-b3bcdaf2db26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92157, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在上海只停留着一天。", "corrected_sentence": "我在上海只停留了一天。", "error_description": "错误：“停留”描述的是已经完成的一次停留，应用“了”，不能用“着”。“着”表示持续的状态，与“只……一天”的已完成时长不合。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac21c432-ba06-4bde-be5a-b3bcdaf2db26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92157, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在湖边停留着一个上午。", "corrected_sentence": "我们在湖边停留了一个上午。", "error_description": "错误：后面有表示已完成时长的“一个上午”，“停留”后应用“了”，不能用“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac21c432-ba06-4bde-be5a-b3bcdaf2db26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
