INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92159, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "态势是事情现在的样子和往哪走。", "primary_collocate": null, "pronunciation": "tài shì", "ipa": "tʰai˥˩ ʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "他们公司现在的态势不错。", "target_word": "态势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁都看得出，比赛的态势变了。", "target_word": "态势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座城市的人口增长态势明显。", "target_word": "态势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要看清眼前的态势再决定。", "target_word": "态势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理介绍了市场的新态势。", "target_word": "态势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "目前的态势对我们很不利。", "target_word": "态势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河水上涨的态势很快停住了。", "target_word": "态势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球队这几场的态势越来越好。", "target_word": "态势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说病情有好转的态势。", "target_word": "态势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新店开张后，生意有了一种好的态势。", "target_word": "态势", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "態勢", "label": "繁体"}, {"form": "一种态势", "label": "量词"}, {"form": "发展态势", "label": "复合"}, {"form": "上升态势", "label": "复合"}], "register": "书面", "sense_fingerprint": "态势：事情眼下的样子和接下来的走向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91424016-136b-4dbb-8616-3939a22b04a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92159, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大事", "is_correct": false, "explanation": "大事（dàshì）与态势（tài shì）声母不同（d/t），意思是重大的事情。"}, {"text": "太史", "is_correct": false, "explanation": "太史（tài shǐ）与态势（tài shì）仅第二音节声调不同，指古代史官，意思无关。"}, {"text": "台式", "is_correct": false, "explanation": "台式（tái shì）第一音节声调不同（á/à），意思是台湾式样，如台式电脑。"}, {"text": "态势", "is_correct": true, "explanation": "态势：事情现在的样子和往哪走，正确答案。"}], "explanations": {"大事": "大事（dàshì）与态势（tài shì）声母不同（d/t），意思是重大的事情。", "太史": "太史（tài shǐ）与态势（tài shì）仅第二音节声调不同，指古代史官，意思无关。", "台式": "台式（tái shì）第一音节声调不同（á/à），意思是台湾式样，如台式电脑。", "态势": "态势：事情现在的样子和往哪走，正确答案。"}, "sentence_index": null, "correct_answer": "态势"}, "level_3": {"options": [{"text": "态势", "is_correct": true, "explanation": "正确：态势指事情现在的样子和走向，与“不错”相符。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”指人或动物的重量，不能用来说公司的状况。"}, {"text": "音量", "is_correct": false, "explanation": "语义：“音量”指声音的大小，不能用来形容公司的状况。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的高矮，不能用来形容公司的状况。"}], "explanations": {"态势": "正确：态势指事情现在的样子和走向，与“不错”相符。", "体重": "体貌：“体重”指人或动物的重量，不能用来说公司的状况。", "音量": "语义：“音量”指声音的大小，不能用来形容公司的状况。", "身高": "体貌：“身高”指人的高矮，不能用来形容公司的状况。"}, "sentence_index": 0, "correct_answer": "态势"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要听清这首歌的态势再唱。", "explanation": "这里应该用〈旋律〉。态势指事情的状况和走向，歌曲的好听与否要说旋律。"}, {"text": "我们要先尝一尝这道菜的态势再决定。", "explanation": "这里应该用〈口味〉。态势指状况和走向，菜的滋味要说口味。"}, {"text": "我们要看清这件衣服的态势再决定。", "explanation": "这里应该用〈外形〉。态势不用于形容衣服的外形，要说外形。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b2bf2e-59d7-411a-9869-74a291039784') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92159, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "态势", "is_correct": true, "explanation": "正确：态势指事情的状况和走向，与“河水上涨”的趋势相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，河水上涨不能用颜色来说明。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的高矮，不能用来形容河水的变化。"}, {"text": "性格", "is_correct": false, "explanation": "搭配：“性格”不能与“河水上涨”搭配。"}], "explanations": {"态势": "正确：态势指事情的状况和走向，与“河水上涨”的趋势相符。", "颜色": "语义：“颜色”指色彩，河水上涨不能用颜色来说明。", "身高": "体貌：“身高”指人的高矮，不能用来形容河水的变化。", "性格": "搭配：“性格”不能与“河水上涨”搭配。"}, "sentence_index": 6, "correct_answer": "态势"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新店开张后，生意有了一条好的态势。", "explanation": "这里应该用〈种〉。态势的量词是“种”，“条”用于细长的东西。"}, {"text": "新店开张后，生意有了一朵好的态势。", "explanation": "这里应该用〈种〉。“朵”用于花朵等，不能用来数态势。"}, {"text": "新店开张后，生意有了一根好的态势。", "explanation": "这里应该用〈种〉。“根”用于细长的物体，不能用来数态势。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b2bf2e-59d7-411a-9869-74a291039784') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92159, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条态势很难改变。", "corrected_sentence": "这种态势很难改变。", "error_description": "“态势”的量词应为“种”，“条”用于细长的东西，不能用来数态势，应说“这种态势”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b2bf2e-59d7-411a-9869-74a291039784') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
