INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92160, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物所呈现的状态和发展趋势。", "primary_collocate": null, "pronunciation": "tài shì", "ipa": "tʰai˥˩ ʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "今年经济的发展态势很好。", "target_word": "态势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司呈现出上升的态势。", "target_word": "态势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛的态势对我们很有利。", "target_word": "态势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房价上涨的态势还会继续吗？", "target_word": "态势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市场保持着稳定的态势。", "target_word": "态势", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "疫情的发展态势让大家很担心。", "target_word": "态势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在是对方占上风的态势。", "target_word": "态势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "从数据看，销售有下降的态势。", "target_word": "态势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家分析了今年的竞争态势。", "target_word": "态势", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种态势一时很难改变。", "target_word": "态势", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "態勢", "label": "繁体"}, {"form": "一种态势", "label": "量词"}, {"form": "发展态势", "label": "复合"}, {"form": "上升态势", "label": "复合"}], "register": "书面", "sense_fingerprint": "态势：事物呈现出的状态和发展趋势，如上升态势、发展态势", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91424016-136b-4dbb-8616-3939a22b04a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt