INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92160, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大事", "is_correct": false, "explanation": "大事（dàshì）与态势（tài shì）声母不同（d/t），意思是重大的事情。"}, {"text": "太史", "is_correct": false, "explanation": "太史（tài shǐ）与态势（tài shì）仅第二音节声调不同，指古代史官，意思无关。"}, {"text": "台式", "is_correct": false, "explanation": "台式（tái shì）第一音节声调不同（á/à），意思是台湾式样，如台式电脑。"}, {"text": "态势", "is_correct": true, "explanation": "态势：事物所呈现的状态和发展趋势，正确答案。"}], "explanations": {"大事": "大事（dàshì）与态势（tài shì）声母不同（d/t），意思是重大的事情。", "太史": "太史（tài shǐ）与态势（tài shì）仅第二音节声调不同，指古代史官，意思无关。", "台式": "台式（tái shì）第一音节声调不同（á/à），意思是台湾式样，如台式电脑。", "态势": "态势：事物所呈现的状态和发展趋势，正确答案。"}, "sentence_index": null, "correct_answer": "态势"}, "level_3": {"options": [{"text": "态势", "is_correct": true, "explanation": "正确：态势指经济的发展状态与趋势，与“很好”相符。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，不能用来形容经济的发展。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，不能说经济的发展有颜色。"}, {"text": "气味", "is_correct": false, "explanation": "语义：“气味”指气息，不能用来形容经济的发展。"}], "explanations": {"态势": "正确：态势指经济的发展状态与趋势，与“很好”相符。", "身材": "体貌：“身材”指人的体形，不能用来形容经济的发展。", "颜色": "语义：“颜色”指色彩，不能说经济的发展有颜色。", "气味": "语义：“气味”指气息，不能用来形容经济的发展。"}, "sentence_index": 0, "correct_answer": "态势"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的态势很挺拔。", "explanation": "这里应该用〈姿态〉。态势指事物的状况和走向，人的身体姿势要说姿态。"}, {"text": "他目前的态势很困难。", "explanation": "这里应该用〈处境〉。态势用于事物的发展走向，个人的境遇要说处境。"}, {"text": "这首歌的态势很动听。", "explanation": "这里应该用〈旋律〉。态势指状况和走向，歌曲好听与否要说旋律。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b2bf2e-59d7-411a-9869-74a291039784') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92160, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "态势", "is_correct": true, "explanation": "正确：态势指事物的状况和走向，与“占上风”的局面相符。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的高矮，不能用来指“占上风”的状况。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指滋味，不能用来形容“占上风”的局面。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：“歌曲”指歌，与“占上风”的局面毫无关系，说不通。"}], "explanations": {"态势": "正确：态势指事物的状况和走向，与“占上风”的局面相符。", "身高": "体貌：“身高”指人的高矮，不能用来指“占上风”的状况。", "味道": "语义：“味道”指滋味，不能用来形容“占上风”的局面。", "歌曲": "语义：“歌曲”指歌，与“占上风”的局面毫无关系，说不通。"}, "sentence_index": 6, "correct_answer": "态势"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这一只态势一时很难改变。", "explanation": "这里应该用〈种〉。态势的量词是“种”，“只”用于动物等，不能用来数态势。"}, {"text": "这一条态势一时很难改变。", "explanation": "这里应该用〈种〉。“条”用于细长的东西，不能用来数态势。"}, {"text": "这一块态势一时很难改变。", "explanation": "这里应该用〈种〉。“块”用于成块的东西，不能用来数态势。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b2bf2e-59d7-411a-9869-74a291039784') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92160, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个行业呈现出一条下降的态势。", "corrected_sentence": "这个行业呈现出一种下降的态势。", "error_description": "“态势”的量词应为“种”。“条”用于细长的东西，不能用来数态势，应说“一种态势”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b2bf2e-59d7-411a-9869-74a291039784') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92160, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "股市呈现出一块回升的态势。", "corrected_sentence": "股市呈现出一种回升的态势。", "error_description": "量词错误：“态势”的量词应为“种”，“块”用于成块的东西，不能用来数态势。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b2bf2e-59d7-411a-9869-74a291039784') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92161, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最后", "is_correct": true, "explanation": "「最初」指开始的时候，「最后」指结束的时候，二者在这一义项上构成反义。"}, {"text": "复杂", "is_correct": false, "explanation": "「复杂」形容事情繁多或难懂，与「最初」的时间意义没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "「清楚」形容明白、分明，与「最初」没有反义或近义关系。"}, {"text": "重要", "is_correct": false, "explanation": "「重要」形容作用大、价值高，与「最初」的时间意义无关。"}], "correct_answer": "最后", "explanations": {"最后": "「最初」指开始的时候，「最后」指结束的时候，二者在这一义项上构成反义。", "复杂": "「复杂」形容事情繁多或难懂，与「最初」的时间意义没有反义关系。", "清楚": "「清楚」形容明白、分明，与「最初」没有反义或近义关系。", "重要": "「重要」形容作用大、价值高，与「最初」的时间意义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92161, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最后", "is_correct": true, "explanation": "「最初」指开始的时候，「最后」指结束的时候，二者在这一义项上构成反义。"}, {"text": "巨大", "is_correct": false, "explanation": "「巨大」形容规模或程度很大，与「最初」的时间意义没有反义关系。"}, {"text": "轻松", "is_correct": false, "explanation": "「轻松」形容不费力或心情放松，与「最初」没有反义或近义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "「热闹」形容场面喧闹、人多，与「最初」的时间意义无关。"}], "correct_answer": "最后", "explanations": {"最后": "「最初」指开始的时候，「最后」指结束的时候，二者在这一义项上构成反义。", "巨大": "「巨大」形容规模或程度很大，与「最初」的时间意义没有反义关系。", "轻松": "「轻松」形容不费力或心情放松，与「最初」没有反义或近义关系。", "热闹": "「热闹」形容场面喧闹、人多，与「最初」的时间意义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92161, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "最初是最早的时候。", "primary_collocate": null, "pronunciation": "zuì chū", "ipa": "tsweɪ˥˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "最初，我一句汉语也不会说。", "target_word": "最初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市最初很小。", "target_word": "最初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最初的计划是去海边玩。", "target_word": "最初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最初他不太喜欢这个工作。", "target_word": "最初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最初的梦想是当老师。", "target_word": "最初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最初的几天，她每天都哭。", "target_word": "最初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店最初只卖面包。", "target_word": "最初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最初我们都不认识。", "target_word": "最初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他还记得最初见到她的样子。", "target_word": "最初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最初学汉字的时候觉得很难。", "target_word": "最初", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "最初的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "最早的时候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68b6fea3-2699-4510-9ab1-0d36748570eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92161, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "终于", "is_correct": false, "explanation": "语义：「终于」表示经过努力或一段时间后达到结果，而「一句汉语也不会说」是持续的否定状态，二者不搭。"}, {"text": "最初", "is_correct": true, "explanation": "「最初」指开始的阶段，与后面「一句汉语也不会说」描述的起始状态相符。"}, {"text": "随后", "is_correct": false, "explanation": "语域：「随后」是书面语，表示紧接在前面的事情之后。这句话前面没有可承接的事，口语中这样开头不自然。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：「偶尔」表示有时发生，而「一句汉语也不会说」说的是全面的情况，二者矛盾。"}], "explanations": {"终于": "语义：「终于」表示经过努力或一段时间后达到结果，而「一句汉语也不会说」是持续的否定状态，二者不搭。", "最初": "「最初」指开始的阶段，与后面「一句汉语也不会说」描述的起始状态相符。", "随后": "语域：「随后」是书面语，表示紧接在前面的事情之后。这句话前面没有可承接的事，口语中这样开头不自然。", "偶尔": "语义：「偶尔」表示有时发生，而「一句汉语也不会说」说的是全面的情况，二者矛盾。"}, "sentence_index": 0, "correct_answer": "最初"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我现在最初在学汉语。", "explanation": "这里应该用〈正在〉。「正在」表示现在进行中的动作，「最初」只指过去的早期阶段，不能与「现在」连用表示进行。"}, {"text": "我们找了很久，最初找到了钥匙。", "explanation": "这里应该用〈最后〉。「最后」表示经过较长过程后的结果，「最初」只指开始的阶段，与「找了很久」不搭配。"}, {"text": "他找了两年工作，最初找到了好工作。", "explanation": "这里应该用〈最终〉。「最终」表示经过一段过程后的结果，「最初」只指开头，与「找了两年」之后的结果不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92161, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "立刻", "is_correct": false, "explanation": "语义：「立刻」强调紧接着马上发生，不能描述一段时间内的经营状态。"}, {"text": "最初", "is_correct": true, "explanation": "「最初」指开始的阶段，与「只卖面包」所说的开业时的经营范围相符。"}, {"text": "再三", "is_correct": false, "explanation": "搭配：「再三」表示多次反复，多用于请求或考虑，不说「再三只卖面包」。"}, {"text": "当场", "is_correct": false, "explanation": "语义：「当场」指就在当时当地发生的事，不用来描述长期的经营范围。"}], "explanations": {"立刻": "语义：「立刻」强调紧接着马上发生，不能描述一段时间内的经营状态。", "最初": "「最初」指开始的阶段，与「只卖面包」所说的开业时的经营范围相符。", "再三": "搭配：「再三」表示多次反复，多用于请求或考虑，不说「再三只卖面包」。", "当场": "语义：「当场」指就在当时当地发生的事，不用来描述长期的经营范围。"}, "sentence_index": 6, "correct_answer": "最初"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我学了三年，最初觉得汉字不难了。", "explanation": "这里应该用〈终于〉。「终于」表示经过一段过程后出现的变化，「最初」指开始的阶段，与「学了三年」之后的感受不符。"}, {"text": "直到三年后，我最初学会了汉字。", "explanation": "这里应该用〈后来〉。「后来」指较晚的时间，「最初」指开始的阶段，与「直到三年后」搭配不当。"}, {"text": "我花了三年最初学会写汉字。", "explanation": "这里应该用〈才〉。「才」表示经过一段时间后才实现，「最初」只指开头，与「花了三年」搭配不当。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92161, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我还记得他最初样子。", "corrected_sentence": "我还记得他最初的样子。", "error_description": "错误形式「最初样子」，正确形式「最初的样子」。「最初」修饰「样子」这类名词作定语时要加「的」，与定语形式「最初的」保持一致。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92161, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他最初地没有听懂我的话。", "corrected_sentence": "他最初没有听懂我的话。", "error_description": "错误形式「最初地没有听懂」，正确形式「最初没有听懂」。「最初」作状语修饰否定短语时不加「地」，直接放在「没有」前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92162, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "简单", "is_correct": false, "explanation": "「简单」形容不复杂，与「最初」的时间意义没有反义关系。"}, {"text": "最后", "is_correct": true, "explanation": "「最初」指开始的时候，「最后」指结束的时候，二者在这一义项上构成反义。"}, {"text": "普通", "is_correct": false, "explanation": "「普通」形容平常、不特别，与「最初」没有反义或近义关系。"}, {"text": "明显", "is_correct": false, "explanation": "「明显」形容容易看出，与「最初」的时间意义无关。"}], "correct_answer": "最后", "explanations": {"简单": "「简单」形容不复杂，与「最初」的时间意义没有反义关系。", "最后": "「最初」指开始的时候，「最后」指结束的时候，二者在这一义项上构成反义。", "普通": "「普通」形容平常、不特别，与「最初」没有反义或近义关系。", "明显": "「明显」形容容易看出，与「最初」的时间意义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92162, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "陌生", "is_correct": false, "explanation": "「陌生」形容不熟悉，与「最初」的时间意义没有反义关系。"}, {"text": "深刻", "is_correct": false, "explanation": "「深刻」形容印象或道理深入，与「最初」没有反义或近义关系。"}, {"text": "最后", "is_correct": true, "explanation": "「最初」指开始的时候，「最后」指结束的时候，二者在这一义项上构成反义。"}, {"text": "活泼", "is_correct": false, "explanation": "「活泼」形容性格或动作生动，与「最初」的时间意义无关。"}], "correct_answer": "最后", "explanations": {"陌生": "「陌生」形容不熟悉，与「最初」的时间意义没有反义关系。", "深刻": "「深刻」形容印象或道理深入，与「最初」没有反义或近义关系。", "最后": "「最初」指开始的时候，「最后」指结束的时候，二者在这一义项上构成反义。", "活泼": "「活泼」形容性格或动作生动，与「最初」的时间意义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92162, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "最开始的时候；起初。", "primary_collocate": null, "pronunciation": "zuì chū", "ipa": "tsweɪ˥˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "最初我以为这件事很容易。", "target_word": "最初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最初的价格比现在便宜很多。", "target_word": "最初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路最初是一条小河。", "target_word": "最初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最初，大家都不同意他的意见。", "target_word": "最初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最初到北京时，我住在朋友家。", "target_word": "最初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机最初只能打电话。", "target_word": "最初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她最初的工作在一家小公司。", "target_word": "最初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最初那几年，他们过得很辛苦。", "target_word": "最初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想起了最初的那一天。", "target_word": "最初", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最初她很怕狗，后来喜欢了。", "target_word": "最初", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "最初的", "label": "定语形式"}], "register": "中性", "sense_fingerprint": "最开始；起初", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68b6fea3-2699-4510-9ab1-0d36748570eb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92162, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当然", "is_correct": false, "explanation": "语义：「当然」表示理所当然，而「以为」表示当时的主观判断，二者意思不搭。"}, {"text": "最初", "is_correct": true, "explanation": "「最初」指开始的时候，与「我以为这件事很容易」所说的当时想法相符。"}, {"text": "终究", "is_correct": false, "explanation": "语义：「终究」表示经过一段过程后得出的最终结论，用来说开始时的想法不合适。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：「偶尔」表示有时候，与「以为」所说的一次判断不合。"}], "explanations": {"当然": "语义：「当然」表示理所当然，而「以为」表示当时的主观判断，二者意思不搭。", "最初": "「最初」指开始的时候，与「我以为这件事很容易」所说的当时想法相符。", "终究": "语义：「终究」表示经过一段过程后得出的最终结论，用来说开始时的想法不合适。", "偶尔": "语义：「偶尔」表示有时候，与「以为」所说的一次判断不合。"}, "sentence_index": 0, "correct_answer": "最初"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他现在最初在写论文。", "explanation": "这里应该用〈正在〉。「正在」表示现在进行中的动作，「最初」只指过去的早期阶段，不能与「现在」连用表示进行。"}, {"text": "这场比赛踢了很久，我们最初赢了。", "explanation": "这里应该用〈最后〉。「最后」表示经过较长过程后的结局，「最初」只指开始的阶段，与「踢了很久」不搭配。"}, {"text": "他学了三年，最初考上了大学。", "explanation": "这里应该用〈最终〉。「最终」表示经过一段过程后的结果，「最初」只指开头，与「学了三年」之后的结果不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92162, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大型", "is_correct": false, "explanation": "语义：「大型」指规模很大，与「一家小公司」矛盾，不能修饰这份工作所在的单位。"}, {"text": "最初", "is_correct": true, "explanation": "「最初」指第一份工作，与「在一家小公司」的起始情况相符。"}, {"text": "跨国", "is_correct": false, "explanation": "语义：「跨国」指业务横跨多个国家，与「一家小公司」的规模不合。"}, {"text": "首席", "is_correct": false, "explanation": "搭配：「首席」一般修饰「执行官」「设计师」等职位，不直接修饰「工作」。"}], "explanations": {"大型": "语义：「大型」指规模很大，与「一家小公司」矛盾，不能修饰这份工作所在的单位。", "最初": "「最初」指第一份工作，与「在一家小公司」的起始情况相符。", "跨国": "语义：「跨国」指业务横跨多个国家，与「一家小公司」的规模不合。", "首席": "搭配：「首席」一般修饰「执行官」「设计师」等职位，不直接修饰「工作」。"}, "sentence_index": 6, "correct_answer": "最初"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我学了三年最初学会游泳。", "explanation": "这里应该用〈才〉。「才」表示经过一段时间后才实现，「最初」只指开头，与「学了三年」搭配不当。"}, {"text": "他考了三次，最初才考上了大学。", "explanation": "这里应该用〈最后〉。「最后」表示经过多次努力后的结局，「最初」只指开始的阶段，与「考了三次」的过程不符。"}, {"text": "我等了他两个小时，他最初来了。", "explanation": "这里应该用〈终于〉。「终于」表示等了很久以后才出现结果，「最初」只指开始的阶段，与「等了两个小时」不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92162, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是我最初看法。", "corrected_sentence": "这是我最初的看法。", "error_description": "错误形式「最初看法」，正确形式「最初的看法」。「最初」用在名词前作定语时要加「的」，与定语形式「最初的」保持一致。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92162, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她最初地没有答应我的请求。", "corrected_sentence": "她最初没有答应我的请求。", "error_description": "错误形式「最初地没有答应」，正确形式「最初没有答应」。「最初」作状语修饰否定短语时不加「地」，直接放在「没有」前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '249ca11e-639b-4131-b929-040624b45621') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
