INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92163, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "受了伤的人，和不在了的人。", "primary_collocate": null, "pronunciation": "shāng wáng", "ipa": "ʂɑŋ˥ wɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这次地震的伤亡已经超过了一百人。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次地震的伤亡大多是老人和孩子。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火灾中的伤亡名单已经出来了。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者问政府有多少伤亡。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察正在统计这次车祸的伤亡。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争让两边都有很多伤亡。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院正在照顾这次车祸的伤亡。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场车祸的伤亡数字还没有确定。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次火灾的伤亡都是附近的居民。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府给伤亡家庭送去了钱。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "傷亡", "label": "繁体"}], "register": "书面", "sense_fingerprint": "事故或灾难中受伤和死亡的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c8724db-93b5-4991-96c7-55399deeca21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92163, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伤亡", "is_correct": true, "explanation": "正确：伤亡指受伤和死亡的人，可以说“超过了一百人”。"}, {"text": "灾情", "is_correct": false, "explanation": "语义：灾情指灾害的状况，不是人，不能用人数来说“超过了一百人”。"}, {"text": "财产", "is_correct": false, "explanation": "语义：财产是钱和物，不能用人数计算，“超过了一百人”说不通。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“面积”用平方米、公顷等计量，不和“超过了一百人”搭配。"}], "explanations": {"伤亡": "正确：伤亡指受伤和死亡的人，可以说“超过了一百人”。", "灾情": "语义：灾情指灾害的状况，不是人，不能用人数来说“超过了一百人”。", "财产": "语义：财产是钱和物，不能用人数计算，“超过了一百人”说不通。", "面积": "搭配：“面积”用平方米、公顷等计量，不和“超过了一百人”搭配。"}, "sentence_index": 0, "correct_answer": "伤亡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次洪水的伤亡是十万元。", "explanation": "这里应该用〈损失〉。伤亡只指受伤和死亡的人，钱财上的减少要说损失。"}, {"text": "这辆卡车的伤亡很严重。", "explanation": "这里应该用〈损坏〉。伤亡只用于人，车辆受到破坏要说损坏。"}, {"text": "这次事故的伤亡是两百万元。", "explanation": "这里应该用〈赔偿〉。伤亡指人的受伤和死亡，赔给受害者的钱要说赔偿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b39e582-744c-4c39-a343-7e0484b564a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92163, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伤亡", "is_correct": true, "explanation": "正确：伤亡指受伤和死亡的人，医院可以照顾车祸中的伤亡。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是天空的状况，不是人，医院不能“照顾天气”。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是身体的重量，不是人，不能说“照顾车祸的体重”。"}, {"text": "产量", "is_correct": false, "explanation": "语义：产量指生产出来的数量，不是人，不能被医院照顾。"}], "explanations": {"伤亡": "正确：伤亡指受伤和死亡的人，医院可以照顾车祸中的伤亡。", "天气": "语义：天气是天空的状况，不是人，医院不能“照顾天气”。", "体重": "语义：体重是身体的重量，不是人，不能说“照顾车祸的体重”。", "产量": "语义：产量指生产出来的数量，不是人，不能被医院照顾。"}, "sentence_index": 6, "correct_answer": "伤亡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的左手受到了伤亡。", "explanation": "这里应该用〈损伤〉。伤亡指人群或事件中的伤亡，不用于身体的某一个部位，手的伤要说损伤。"}, {"text": "他的伤亡很重，医生让他住院。", "explanation": "这里应该用〈伤势〉。伤亡不用来形容一个人受伤的程度，描述伤情要说伤势。"}, {"text": "他的感情受到了伤亡。", "explanation": "这里应该用〈伤害〉。伤亡只指受伤和死亡，不用于感情，感情受到的损害要说伤害。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b39e582-744c-4c39-a343-7e0484b564a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92163, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场洪水的一个伤亡已经超过了八十人。", "corrected_sentence": "这场洪水的伤亡已经超过了八十人。", "error_description": "错误：“伤亡”前面加了量词“一个”。伤亡不能用“个”来计量，应直接说“这场洪水的伤亡”，或用“伤亡人数”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b39e582-744c-4c39-a343-7e0484b564a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92163, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那场战争的伤亡得很惨重。", "corrected_sentence": "那场战争的伤亡很惨重。", "error_description": "错误：“伤亡”后面加了“得”。伤亡是名词，不能带程度补语，应直接说“伤亡很惨重”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b39e582-744c-4c39-a343-7e0484b564a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
