INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92164, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "受伤和死亡；也指受伤和死亡的人。", "primary_collocate": null, "pronunciation": "shāng wáng", "ipa": "ʂɑŋ˥ wɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这次事故没有造成伤亡。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震造成了很大的伤亡。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂很注意安全，怕有伤亡。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争会带来大量伤亡。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨来了，政府怕出现伤亡。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场火灾幸好没有伤亡。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想办法减少伤亡。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机开得很慢，所以没有伤亡。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻说这次大火的伤亡不大。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了避免伤亡，大家都离开了山下的村子。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "傷亡", "label": "繁体"}], "register": "书面", "sense_fingerprint": "事故或战争中受伤和死亡的情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c8724db-93b5-4991-96c7-55399deeca21') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92164, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伤亡", "is_correct": true, "explanation": "正确：“造成伤亡”是固定说法，伤亡指受伤和死亡的情况。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字是称呼，不是事故造成的后果，不能说“造成名字”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是天空的状况，不是事故的后果，不能说“造成天气”。"}, {"text": "节日", "is_correct": false, "explanation": "语义：节日是固定的日子，不会因为事故而产生，不能说“造成节日”。"}], "explanations": {"伤亡": "正确：“造成伤亡”是固定说法，伤亡指受伤和死亡的情况。", "名字": "语义：名字是称呼，不是事故造成的后果，不能说“造成名字”。", "天气": "语义：天气是天空的状况，不是事故的后果，不能说“造成天气”。", "节日": "语义：节日是固定的日子，不会因为事故而产生，不能说“造成节日”。"}, "sentence_index": 0, "correct_answer": "伤亡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场战争夺走了很多伤亡。", "explanation": "这里应该用〈生命〉。“夺走”接的是生命，伤亡是情况，不能被夺走。"}, {"text": "这次事故给环境带来了很大的伤亡。", "explanation": "这里应该用〈伤害〉。伤亡只指人的受伤和死亡，对环境的损害要说伤害。"}, {"text": "他们在伤亡途中被抓住了。", "explanation": "这里应该用〈逃亡〉。伤亡指受伤和死亡，没有逃走的意思，“逃亡途中”要说逃亡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b39e582-744c-4c39-a343-7e0484b564a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92164, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伤亡", "is_correct": true, "explanation": "正确：“减少伤亡”是固定说法，伤亡指受伤和死亡的情况。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不是可以“减少”的数量或程度，“减少名字”句意不通。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是人的长度，不能用“减少”来说，这里说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是视觉上的属性，不能用“减少”来说。"}], "explanations": {"伤亡": "正确：“减少伤亡”是固定说法，伤亡指受伤和死亡的情况。", "名字": "语义：名字不是可以“减少”的数量或程度，“减少名字”句意不通。", "身高": "语义：身高是人的长度，不能用“减少”来说，这里说不通。", "颜色": "语义：颜色是视觉上的属性，不能用“减少”来说。"}, "sentence_index": 6, "correct_answer": "伤亡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次撞击造成了机器的伤亡。", "explanation": "这里应该用〈损伤〉。伤亡指人的受伤和死亡，机器的毁坏要说损伤。"}, {"text": "他的伤亡很重，需要住院。", "explanation": "这里应该用〈伤势〉。伤亡不用来形容一个人受伤的程度，描述伤情要说伤势。"}, {"text": "这场火灾烧毁了很多伤亡。", "explanation": "这里应该用〈财产〉。伤亡只指人的受伤和死亡，烧毁的是财产。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b39e582-744c-4c39-a343-7e0484b564a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92164, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场大雨没有造成一座伤亡。", "corrected_sentence": "这场大雨没有造成伤亡。", "error_description": "错误：“伤亡”前面加了量词“一座”。“座”用于山、楼房等大型固定物，不能用来计量伤亡，应直接说“没有造成伤亡”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b39e582-744c-4c39-a343-7e0484b564a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92164, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场火灾造成了很多头伤亡。", "corrected_sentence": "这场火灾造成了很多伤亡。", "error_description": "错误：“伤亡”前面加了量词“头”。“头”用于牲畜等动物，不能用来计量伤亡，应直接说“造成了很多伤亡”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b39e582-744c-4c39-a343-7e0484b564a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
