INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92165, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "应手是用起来很顺手。", "primary_collocate": null, "pronunciation": "yìng shǒu", "ipa": "iŋ⁵¹ ʂoʊ²¹⁴", "syllable_count": 2, "sentences": [{"text": "这个新鼠标很应手。", "target_word": "应手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的画笔不太应手。", "target_word": "应手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把伞又轻又应手。", "target_word": "应手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做饭时，应手的锅最重要。", "target_word": "应手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找了一把应手的扳手。", "target_word": "应手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台相机用着很应手。", "target_word": "应手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她觉得这套工具特别应手。", "target_word": "应手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把勺子大小合适，拿着很应手。", "target_word": "应手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们都爱用这种应手的锤子。", "target_word": "应手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支笔写起来应手，我天天带着。", "target_word": "应手", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "應手", "label": "繁体"}], "register": "书面", "sense_fingerprint": "用起来很顺手", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552319c8-d678-4547-b1ce-dbccda73abfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92165, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "应手", "is_correct": true, "explanation": "用起来顺手，与“新鼠标”的语境相符。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：“温柔”形容人的性情，不能用来形容鼠标。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”形容人或动物的体形，鼠标不能说胖。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”形容食物的味道，鼠标不能说咸。"}], "explanations": {"应手": "用起来顺手，与“新鼠标”的语境相符。", "温柔": "语义：“温柔”形容人的性情，不能用来形容鼠标。", "胖": "体貌：“胖”形容人或动物的体形，鼠标不能说胖。", "咸": "语义：“咸”形容食物的味道，鼠标不能说咸。"}, "sentence_index": 0, "correct_answer": "应手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家商店很应手，东西很多。", "explanation": "这里应该用〈方便〉。“应手”只形容用起来顺手的工具，商店不能说应手。"}, {"text": "这个孩子很应手，很听话。", "explanation": "“应手”只形容工具，不能用来形容人。"}, {"text": "这场比赛很应手。", "explanation": "这里应该用〈顺利〉。“应手”只形容用起来顺手的工具，比赛不能说应手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f98bd86-ea85-4cd9-9ac2-9b979a6f3ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
