INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92166, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "顺手；得心应手。", "primary_collocate": null, "pronunciation": "yìng shǒu", "ipa": "iŋ⁵¹ ʂoʊ²¹⁴", "syllable_count": 2, "sentences": [{"text": "这把刀很应手。", "target_word": "应手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支笔用起来很应手。", "target_word": "应手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他换了一把新锤子，觉得特别应手。", "target_word": "应手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师傅的工具都很应手。", "target_word": "应手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双筷子拿在手里非常应手。", "target_word": "应手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用惯了这个键盘，所以觉得应手。", "target_word": "应手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把剪刀大小合适，用着很应手。", "target_word": "应手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木工说这种锯子最应手。", "target_word": "应手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工具不应手，活儿就做不好。", "target_word": "应手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用的那把小刀又轻又应手。", "target_word": "应手", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "應手", "label": "繁体"}], "register": "书面", "sense_fingerprint": "工具用起来顺手、得心应手", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552319c8-d678-4547-b1ce-dbccda73abfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDE