INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92167, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "荣誉是做了好事，大家夸你、给你的光彩。", "primary_collocate": null, "pronunciation": "róng yù", "ipa": "ʐʊŋ˧˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "他常帮助别人，得到了大家给的荣誉。", "target_word": "荣誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李救了落水的孩子，得到了大家给的荣誉。", "target_word": "荣誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做了很多好事，应该得到这份荣誉。", "target_word": "荣誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都夸他，这份荣誉让他很高兴。", "target_word": "荣誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他捡到钱包交给警察，得到了一份荣誉。", "target_word": "荣誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了班级的荣誉，我们每天都练习。", "target_word": "荣誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师当着大家夸我，我觉得这是很大的荣誉。", "target_word": "荣誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做了好事，从不炫耀自己的荣誉。", "target_word": "荣誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，做好事不是为了荣誉。", "target_word": "荣誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶年轻时得到过很多荣誉，她一直很自豪。", "target_word": "荣誉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "项", "label": "量词"}, {"form": "榮譽", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做了好事后别人夸奖、给予的光彩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79e0a565-ff65-4751-a7de-98805f80eb54') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92167, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "荣誉", "is_correct": true, "explanation": "正确。荣誉指做了好事后得到的称赞与光彩，与“帮助别人”的语境相合。"}, {"text": "债务", "is_correct": false, "explanation": "搭配：“债务”是欠下的钱，不能说“大家给的债务”。"}, {"text": "罚单", "is_correct": false, "explanation": "语义：“罚单”是对违规行为的处罚，与“帮助别人”的好事正相反。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：“垃圾”是废弃物，不能作为得到的称赞，与句意冲突。"}], "explanations": {"荣誉": "正确。荣誉指做了好事后得到的称赞与光彩，与“帮助别人”的语境相合。", "债务": "搭配：“债务”是欠下的钱，不能说“大家给的债务”。", "罚单": "语义：“罚单”是对违规行为的处罚，与“帮助别人”的好事正相反。", "垃圾": "语义：“垃圾”是废弃物，不能作为得到的称赞，与句意冲突。"}, "sentence_index": 0, "correct_answer": "荣誉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每个月都领到荣誉，用来交房租。", "explanation": "这里应该用〈工资〉。荣誉是他人给予的称赞与光彩，不是钱，不能领取后用来交房租。"}, {"text": "他把荣誉装进了书包。", "explanation": "这里应该用〈奖状〉。荣誉是他人给予的称赞与光彩，是抽象的，不能装进书包；书包里装的是实物奖状。"}, {"text": "他拿到了荣誉，学费全免。", "explanation": "这里应该用〈奖学金〉。荣誉是精神上的光彩，不能免学费；奖学金才有金钱上的实际作用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92167, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "荣誉", "is_correct": true, "explanation": "正确。句中的“夸我”和“很大的”都指向受称赞的荣誉。"}, {"text": "错误", "is_correct": false, "explanation": "语义：“错误”指做得不对，与“老师当着大家夸我”的受表扬语境相反，句意不通。"}, {"text": "污点", "is_correct": false, "explanation": "搭配：“污点”常说“留下污点”或“洗掉污点”，与受表扬的语境不搭。"}, {"text": "伤害", "is_correct": false, "explanation": "语义：“伤害”指损害，与老师当众夸奖的语境相反。"}], "explanations": {"荣誉": "正确。句中的“夸我”和“很大的”都指向受称赞的荣誉。", "错误": "语义：“错误”指做得不对，与“老师当着大家夸我”的受表扬语境相反，句意不通。", "污点": "搭配：“污点”常说“留下污点”或“洗掉污点”，与受表扬的语境不搭。", "伤害": "语义：“伤害”指损害，与老师当众夸奖的语境相反。"}, "sentence_index": 6, "correct_answer": "荣誉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把荣誉存进了银行。", "explanation": "这里应该用〈奖金〉。荣誉不是钱，不能存进银行。"}, {"text": "他拿到荣誉，把它吃掉了。", "explanation": "这里应该用〈食物〉。荣誉是抽象的称赞，不是可以吃的东西，不能“吃掉”。"}, {"text": "他买了一件荣誉衣服，很贵。", "explanation": "这里应该用〈名牌〉。荣誉不是商品，不能用来修饰“衣服”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92167, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只荣誉属于我们全班。", "corrected_sentence": "这份荣誉属于我们全班。", "error_description": "错误：量词用了“只”。“只”用于动物等，荣誉要用“份”或“项”。正确：“这份荣誉属于我们全班。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92167, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他荣誉让他很骄傲。", "corrected_sentence": "他的荣誉让他很骄傲。", "error_description": "错误：“荣誉”前漏了“的”，“他的荣誉”是领属结构，不能省略。正确：“他的荣誉让他很骄傲。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
