INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92168, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "因成绩或贡献而得到的公认的称赞和尊敬。", "primary_collocate": null, "pronunciation": "róng yù", "ipa": "ʐʊŋ˧˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "这位科学家因为重大贡献，获得了国家荣誉。", "target_word": "荣誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这份荣誉送给了全体队员。", "target_word": "荣誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "获得金牌是运动员最大的荣誉。", "target_word": "荣誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她为学校赢得了很高的荣誉。", "target_word": "荣誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这枚奖章代表国家给他的荣誉。", "target_word": "荣誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成绩一直很好，学校给了他很高的荣誉。", "target_word": "荣誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她多年的付出，让她获得了全国的荣誉。", "target_word": "荣誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "能代表国家比赛，对他来说是一种荣誉。", "target_word": "荣誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "荣誉不是金钱能买到的。", "target_word": "荣誉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一生有很多荣誉，却一直很谦虚。", "target_word": "荣誉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "项", "label": "量词"}, {"form": "榮譽", "label": "繁体"}], "register": "书面", "sense_fingerprint": "因成绩或贡献而获得的公认称赞与尊敬", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '79e0a565-ff65-4751-a7de-98805f80eb54') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92168, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "荣誉", "is_correct": true, "explanation": "正确。荣誉指因贡献而获得的公认称赞与尊敬，与“重大贡献”相合。"}, {"text": "罚款", "is_correct": false, "explanation": "语义：“罚款”是因违规而被处罚的钱，与“重大贡献”的语境相反。"}, {"text": "债务", "is_correct": false, "explanation": "搭配：“债务”是欠下的钱，不能说“获得了国家债务”。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：“垃圾”是废弃物，与“重大贡献”的语境相反，不能作为获得的东西。"}], "explanations": {"荣誉": "正确。荣誉指因贡献而获得的公认称赞与尊敬，与“重大贡献”相合。", "罚款": "语义：“罚款”是因违规而被处罚的钱，与“重大贡献”的语境相反。", "债务": "搭配：“债务”是欠下的钱，不能说“获得了国家债务”。", "垃圾": "语义：“垃圾”是废弃物，与“重大贡献”的语境相反，不能作为获得的东西。"}, "sentence_index": 0, "correct_answer": "荣誉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她骑着荣誉去学校。", "explanation": "这里应该用〈自行车〉。荣誉是抽象的称赞与尊敬，不是交通工具，不能“骑”。"}, {"text": "她每个月领荣誉，用来还房贷。", "explanation": "这里应该用〈工资〉。荣誉是称赞与尊敬，不是钱，不能按月领取用来还贷。"}, {"text": "春节时，爷爷给我发了一份荣誉。", "explanation": "这里应该用〈红包〉。荣誉不是金钱，不能像红包一样发给别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92168, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "荣誉", "is_correct": true, "explanation": "正确。“多年的付出”与“获得了全国的”都指向褒义的荣誉。"}, {"text": "伤痕", "is_correct": false, "explanation": "语义：“伤痕”指受伤后留下的痕迹，与“多年的付出”的褒义语境相反。"}, {"text": "疾病", "is_correct": false, "explanation": "搭配：“疾病”常说“患上”或“得了”，不说“获得了全国的”。"}, {"text": "灾难", "is_correct": false, "explanation": "语义：“灾难”指严重的祸害，与“获得全国的”的褒义语境相反。"}], "explanations": {"荣誉": "正确。“多年的付出”与“获得了全国的”都指向褒义的荣誉。", "伤痕": "语义：“伤痕”指受伤后留下的痕迹，与“多年的付出”的褒义语境相反。", "疾病": "搭配：“疾病”常说“患上”或“得了”，不说“获得了全国的”。", "灾难": "语义：“灾难”指严重的祸害，与“获得全国的”的褒义语境相反。"}, "sentence_index": 6, "correct_answer": "荣誉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一生欠了很多荣誉，却一直很谦虚。", "explanation": "这里应该用〈债务〉。荣誉是得到的称赞，不能说“欠”。"}, {"text": "他犯了很多荣誉，所以被判了刑。", "explanation": "这里应该用〈罪行〉。“荣誉”是褒义的称赞，不能用“犯”，表示犯下的错误应用〈罪行〉。"}, {"text": "他一生患了很多荣誉，却一直很健康。", "explanation": "这里应该用〈疾病〉。荣誉不是病，不能“患”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92168, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她为学校争取到了一只荣誉。", "corrected_sentence": "她为学校争取到了一份荣誉。", "error_description": "错误：量词用了“只”。“只”用于动物等，荣誉要用“份”或“项”。正确：“她为学校争取到了一份荣誉。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92168, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她为班级争取到了很的高荣誉。", "corrected_sentence": "她为班级争取到了很高的荣誉。", "error_description": "错误：“的”位置不对，应放在“很高”之后、“荣誉”之前。正确：“很高的荣誉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5c73d88-f480-4317-959d-72abd06699d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92169, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收", "is_correct": true, "explanation": "正确：“收”指收取费用，“免”指不收、不用付，二者意思相反（如“门票免了”与“门票要收钱”）。"}, {"text": "吃", "is_correct": false, "explanation": "“吃”与“免”没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "“写”与“免”没有反义关系。"}, {"text": "跑", "is_correct": false, "explanation": "“跑”与“免”没有反义关系。"}], "correct_answer": "收", "explanations": {"收": "正确：“收”指收取费用，“免”指不收、不用付，二者意思相反（如“门票免了”与“门票要收钱”）。", "吃": "“吃”与“免”没有反义关系。", "写": "“写”与“免”没有反义关系。", "跑": "“跑”与“免”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92169, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收", "is_correct": true, "explanation": "正确：“收”指收取费用，“免”指不收、不用付，二者意思相反（如“房租免了”与“房租照收”）。"}, {"text": "唱", "is_correct": false, "explanation": "“唱”与“免”没有反义关系。"}, {"text": "洗", "is_correct": false, "explanation": "“洗”与“免”没有反义关系。"}, {"text": "玩", "is_correct": false, "explanation": "“玩”与“免”没有反义关系。"}], "correct_answer": "收", "explanations": {"收": "正确：“收”指收取费用，“免”指不收、不用付，二者意思相反（如“房租免了”与“房租照收”）。", "唱": "“唱”与“免”没有反义关系。", "洗": "“洗”与“免”没有反义关系。", "玩": "“玩”与“免”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92169, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不用做，不用给。", "primary_collocate": null, "pronunciation": "miǎn", "ipa": "mjɛn˨˩˦", "syllable_count": 1, "sentences": [{"text": "这次作业可以免了。", "target_word": "免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生生病了，作业免了。", "target_word": "免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不到一米二，车费可以免。", "target_word": "免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板说这顿饭的钱免了。", "target_word": "免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有会员卡，停车费能免吗？", "target_word": "免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天下雨，早操免了。", "target_word": "免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人看病，挂号费全免。", "target_word": "免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你是学生，门票可以免。", "target_word": "免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说大家太忙，作文免了。", "target_word": "免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是老朋友，房租这个月免了。", "target_word": "免", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "免了", "label": "完成体"}], "register": "中性", "sense_fingerprint": "本来要交、要付或要做的事，这次不用交、不用付、不用做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20ba2caa-c9bc-48ff-8965-0af456cf76bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92169, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "免", "is_correct": true, "explanation": "正确：免 miǎn，表示不用付、不用交、不用做。"}, {"text": "面", "is_correct": false, "explanation": "miàn（第四声）与 miǎn（第三声）声调不同，意思是面条、面粉。"}, {"text": "棉", "is_correct": false, "explanation": "mián（第二声）与 miǎn（第三声）声调不同，意思是棉花。"}, {"text": "秒", "is_correct": false, "explanation": "miǎo 与 miǎn 韵母不同（-ǎo 与 -ǎn），意思是秒。"}, {"text": "脸", "is_correct": false, "explanation": "liǎn 与 miǎn 声母不同（l 与 m），意思是脸。"}], "explanations": {"免": "正确：免 miǎn，表示不用付、不用交、不用做。", "面": "miàn（第四声）与 miǎn（第三声）声调不同，意思是面条、面粉。", "棉": "mián（第二声）与 miǎn（第三声）声调不同，意思是棉花。", "秒": "miǎo 与 miǎn 韵母不同（-ǎo 与 -ǎn），意思是秒。", "脸": "liǎn 与 miǎn 声母不同（l 与 m），意思是脸。"}, "sentence_index": null, "correct_answer": "免"}, "level_3": {"options": [{"text": "免", "is_correct": true, "explanation": "正确：“免”表示不用交、不用做，“这次作业可以免了”语义通顺。"}, {"text": "罚", "is_correct": false, "explanation": "语义：“罚”是处罚的意思，“作业可以罚了”与“可以”所表示的许可不合。"}, {"text": "骂", "is_correct": false, "explanation": "语义：“骂”表示责骂，与作业无关，句子不通。"}, {"text": "杀", "is_correct": false, "explanation": "搭配：“杀”不跟“作业”搭配，不说杀作业。"}], "explanations": {"免": "正确：“免”表示不用交、不用做，“这次作业可以免了”语义通顺。", "罚": "语义：“罚”是处罚的意思，“作业可以罚了”与“可以”所表示的许可不合。", "骂": "语义：“骂”表示责骂，与作业无关，句子不通。", "杀": "搭配：“杀”不跟“作业”搭配，不说杀作业。"}, "sentence_index": 0, "correct_answer": "免"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "门票免了，可是入口处还是要收三十块。", "explanation": "这里“免”表示不用付，与后文“还是要收钱”相矛盾，不能用。"}, {"text": "作业免了，老师却要求我们全部交上去。", "explanation": "这里“免”表示不用做，与后文“要求全部交上去”相矛盾，不能用。"}, {"text": "车费免了，司机还是要求我们照常付钱。", "explanation": "这里“免”表示不用付，与后文“照常付钱”相矛盾，不能用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92169, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "免", "is_correct": true, "explanation": "正确：免 miǎn，表示不用付、不用交、不用做。"}, {"text": "眠", "is_correct": false, "explanation": "mián（第二声）与 miǎn（第三声）声调不同，意思是睡觉。"}, {"text": "绵", "is_correct": false, "explanation": "mián（第二声）与 miǎn（第三声）声调不同，意思是柔软、连续。"}, {"text": "扁", "is_correct": false, "explanation": "biǎn 与 miǎn 声母不同（b 与 m），意思是扁平。"}], "explanations": {"免": "正确：免 miǎn，表示不用付、不用交、不用做。", "眠": "mián（第二声）与 miǎn（第三声）声调不同，意思是睡觉。", "绵": "mián（第二声）与 miǎn（第三声）声调不同，意思是柔软、连续。", "扁": "biǎn 与 miǎn 声母不同（b 与 m），意思是扁平。"}, "sentence_index": null, "correct_answer": "免"}, "level_3": {"options": [{"text": "免", "is_correct": true, "explanation": "正确：“免”表示不用交，“挂号费全免”语义通顺。"}, {"text": "卖", "is_correct": false, "explanation": "语义：“卖”与挂号费无关，“挂号费全卖”句子不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不跟“费”搭配，不说唱挂号费。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”与挂号费无关，句子不通。"}], "explanations": {"免": "正确：“免”表示不用交，“挂号费全免”语义通顺。", "卖": "语义：“卖”与挂号费无关，“挂号费全卖”句子不通。", "唱": "搭配：“唱”不跟“费”搭配，不说唱挂号费。", "洗": "语义：“洗”与挂号费无关，句子不通。"}, "sentence_index": 6, "correct_answer": "免"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们一定要免事故。", "explanation": "这里应该用〈避免〉。“免”单用时不能直接以“事故”为宾语表示躲开，要说“避免”。"}, {"text": "这个社区的健身房对老人免开放。", "explanation": "这里应该用〈免费〉。“免”不能修饰“开放”表示不收钱，要说“免费开放”。"}, {"text": "妈妈免了我的手机。", "explanation": "这里应该用〈没收〉。“免”表示不用交、不用做，不能用来指把物品拿走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92169, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师说明天的测验可以了免。", "corrected_sentence": "老师说明天的测验可以免了。", "error_description": "错误：完成体的“了”放在了动词“免”之前。正确是“免了”，“了”要放在动词后面，应说“可以免了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92169, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这学期的校服费可以把免了。", "corrected_sentence": "这学期的校服费可以免了。", "error_description": "错误：在“免”前多加了“把”，“把”字句不能这样用。正确说法是“可以免了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
