INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92170, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "免除；不必。", "primary_collocate": null, "pronunciation": "miǎn", "ipa": "mjɛn˨˩˦", "syllable_count": 1, "sentences": [{"text": "这个问题太简单了，解释就免了。", "target_word": "免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间不多，客气话就免了。", "target_word": "免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "您请留步，送就免了吧。", "target_word": "免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都认识，介绍就免了吧。", "target_word": "免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气这么冷，晨跑就免了吧。", "target_word": "免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些道理我都懂，讲就免了吧。", "target_word": "免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人太客气了，礼物就免了。", "target_word": "免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工地危险，参观就免了吧。", "target_word": "免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这么忙，来接我就免了。", "target_word": "免", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有钱，借钱的事就免了吧。", "target_word": "免", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "免了", "label": "完成体"}], "register": "中性", "sense_fingerprint": "把某个动作或客套放在前面，后接“就免了（吧）”，表示不必做，多用于客气推辞", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20ba2caa-c9bc-48ff-8965-0af456cf76bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92170, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "免", "is_correct": true, "explanation": "正确：免 miǎn，后接动词时表示不必做某事。"}, {"text": "面", "is_correct": false, "explanation": "miàn（第四声）与 miǎn（第三声）声调不同，意思是面条、面粉。"}, {"text": "棉", "is_correct": false, "explanation": "mián（第二声）与 miǎn（第三声）声调不同，意思是棉花。"}, {"text": "秒", "is_correct": false, "explanation": "miǎo 与 miǎn 韵母不同（-ǎo 与 -ǎn），意思是秒。"}, {"text": "脸", "is_correct": false, "explanation": "liǎn 与 miǎn 声母不同（l 与 m），意思是脸。"}], "explanations": {"免": "正确：免 miǎn，后接动词时表示不必做某事。", "面": "miàn（第四声）与 miǎn（第三声）声调不同，意思是面条、面粉。", "棉": "mián（第二声）与 miǎn（第三声）声调不同，意思是棉花。", "秒": "miǎo 与 miǎn 韵母不同（-ǎo 与 -ǎn），意思是秒。", "脸": "liǎn 与 miǎn 声母不同（l 与 m），意思是脸。"}, "sentence_index": null, "correct_answer": "免"}, "level_3": {"options": [{"text": "免", "is_correct": true, "explanation": "正确：“免”表示不必做，“解释就免了”与“问题太简单”的语境相合。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不跟“解释”搭配，“解释就唱了”不成立。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”不跟“解释”搭配，“解释就喝了”不成立。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”与解释无关，句子不通。"}], "explanations": {"免": "正确：“免”表示不必做，“解释就免了”与“问题太简单”的语境相合。", "唱": "搭配：“唱”不跟“解释”搭配，“解释就唱了”不成立。", "喝": "搭配：“喝”不跟“解释”搭配，“解释就喝了”不成立。", "踢": "语义：“踢”与解释无关，句子不通。"}, "sentence_index": 0, "correct_answer": "免"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个系统能让机器免故障。", "explanation": "这里应该用〈避免〉。“免”不能直接以“故障”为宾语表示躲开，要说“避免”。"}, {"text": "为了安全，我们要免浪费水。", "explanation": "这里应该用〈避免〉。“免”不能直接以“浪费”为宾语表示躲开，要说“避免”。"}, {"text": "这个方法能让你免痛苦。", "explanation": "这里应该用〈消除〉。“免”不能直接以“痛苦”为宾语表示去掉，要说“消除”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version 