INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92170, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "免", "is_correct": true, "explanation": "正确：免 miǎn，后接动词时表示不必做某事。"}, {"text": "眠", "is_correct": false, "explanation": "mián（第二声）与 miǎn（第三声）声调不同，意思是睡觉。"}, {"text": "绵", "is_correct": false, "explanation": "mián（第二声）与 miǎn（第三声）声调不同，意思是柔软、连续。"}, {"text": "扁", "is_correct": false, "explanation": "biǎn 与 miǎn 声母不同（b 与 m），意思是扁平。"}], "explanations": {"免": "正确：免 miǎn，后接动词时表示不必做某事。", "眠": "mián（第二声）与 miǎn（第三声）声调不同，意思是睡觉。", "绵": "mián（第二声）与 miǎn（第三声）声调不同，意思是柔软、连续。", "扁": "biǎn 与 miǎn 声母不同（b 与 m），意思是扁平。"}, "sentence_index": null, "correct_answer": "免"}, "level_3": {"options": [{"text": "免", "is_correct": true, "explanation": "正确：“免”表示不必做，“礼物就免了”与“客人太客气”的语境相合。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能带“礼物”作宾语，不说唱礼物。"}, {"text": "讲", "is_correct": false, "explanation": "语义：讲礼物与“客人太客气”的语境不合，句子不通。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”与礼物无关，句子不通。"}], "explanations": {"免": "正确：“免”表示不必做，“礼物就免了”与“客人太客气”的语境相合。", "唱": "搭配：“唱”不能带“礼物”作宾语，不说唱礼物。", "讲": "语义：讲礼物与“客人太客气”的语境不合，句子不通。", "吃": "语义：“吃”与礼物无关，句子不通。"}, "sentence_index": 6, "correct_answer": "免"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师免了我的手机。", "explanation": "这里应该用〈没收〉。“免”表示不用交、不用做，不能用来指把物品拿走。"}, {"text": "老板免了我的工资。", "explanation": "这里应该用〈扣〉。“免”表示不用交、不用做，不能用于“工资”这类收入，克扣工资要说“扣”。"}, {"text": "他免了我的座位。", "explanation": "这里应该用〈抢〉。“免”表示不用做，不能用来指把座位拿走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92170, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这么晚了，接送就免吧了。", "corrected_sentence": "这么晚了，接送就免了吧。", "error_description": "错误：“了”与“吧”的位置颠倒。正确是“就免了吧”，“了”跟在动词后，“吧”放在句末。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92170, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天气不好，出去玩就免过吧。", "corrected_sentence": "天气不好，出去玩就免了吧。", "error_description": "错误：“免”后面用了“过”，“过”表示经历，不能与“就……吧”组合。正确是“就免了吧”，“了”表示变化。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13d98004-63d6-4d01-91d5-99745a852991') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
