INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92171, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "应用程序是手机或电脑里能做事的小软件。", "primary_collocate": null, "pronunciation": "yìng yòng chéng xù", "ipa": "iŋ⁵¹ jʊŋ⁵¹ ʈʂʰɤŋ³⁵ ɕy⁵¹", "syllable_count": 4, "sentences": [{"text": "我手机里有很多应用程序。", "target_word": "应用程序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个应用程序可以免费下载。", "target_word": "应用程序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在做一个新的应用程序。", "target_word": "应用程序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你用哪个应用程序看书？", "target_word": "应用程序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个应用程序帮我学汉语。", "target_word": "应用程序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把不用的应用程序删了。", "target_word": "应用程序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个应用程序每天提醒我喝水。", "target_word": "应用程序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑里的应用程序太多，所以很慢。", "target_word": "应用程序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她下载了一个应用程序，用来看地图。", "target_word": "应用程序", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们喜欢这个画画的应用程序。", "target_word": "应用程序", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "應用程序", "label": "繁体"}], "register": "中性", "sense_fingerprint": "手机或电脑里的小软件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '552319c8-d678-4547-b1ce-dbccda73abfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92171, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "花园", "is_correct": false, "explanation": "语义：花园是可以走进去的地方，装不进手机里。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：饺子是食物，不能存放在手机里。"}, {"text": "石头", "is_correct": false, "explanation": "体貌：石头体积大、有实体，装不进手机里。"}, {"text": "应用程序", "is_correct": true, "explanation": "应用程序：指手机里能做事的小软件，符合句意。"}], "explanations": {"花园": "语义：花园是可以走进去的地方，装不进手机里。", "饺子": "语义：饺子是食物，不能存放在手机里。", "石头": "体貌：石头体积大、有实体，装不进手机里。", "应用程序": "应用程序：指手机里能做事的小软件，符合句意。"}, "sentence_index": 0, "correct_answer": "应用程序"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我手机里有一把应用程序。", "explanation": "这里量词用错。“把”用于有柄的器具，不用于应用程序，应该用“个”或“款”。"}, {"text": "这件事要严格按照应用程序来办。", "explanation": "这里用的是“程序”（办事步骤）的意思。应用程序本义是软件，不指办事的步骤。"}, {"text": "妈妈给我推荐了一台应用程序。", "explanation": "这里量词用错。“台”用于机器、仪器，应用程序是软件，应该用“个”或“款”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f98bd86-ea85-4cd9-9ac2-9b979a6f3ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92171, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沙发", "is_correct": false, "explanation": "配价：“提醒”需要能发出提示的施事，沙发不能提醒人喝水。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是遮雨的用品，不能每天提醒人喝水。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：冰块会融化，不能主动提醒人喝水。"}, {"text": "应用程序", "is_correct": true, "explanation": "应用程序：可以定时提醒的小软件，符合句意。"}], "explanations": {"沙发": "配价：“提醒”需要能发出提示的施事，沙发不能提醒人喝水。", "雨伞": "语义：雨伞是遮雨的用品，不能每天提醒人喝水。", "冰块": "语义：冰块会融化，不能主动提醒人喝水。", "应用程序": "应用程序：可以定时提醒的小软件，符合句意。"}, "sentence_index": 6, "correct_answer": "应用程序"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们喜欢喝这个画画的应用程序。", "explanation": "这里应该用“饮料”。应用程序是软件，不能喝。"}, {"text": "孩子们喜欢穿这个画画的应用程序。", "explanation": "这里应该用“衣服”。应用程序是软件，不能穿。"}, {"text": "孩子们喜欢这把画画的应用程序。", "explanation": "这里量词用错。“把”用于有柄的器具，应用程序是软件，应该用“个”或“款”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f98bd86-ea85-4cd9-9ac2-9b979a6f3ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92171, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天在手机上装了一把应用程序。", "corrected_sentence": "我昨天在手机上装了一个应用程序。", "error_description": "量词错误：应为“一个”（或“一款”），不应为“一把”。“把”用于有柄的器具，应用程序不是器具。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f98bd86-ea85-4cd9-9ac2-9b979a6f3ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92171, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们在平板上玩了一本应用程序。", "corrected_sentence": "孩子们在平板上玩了一个应用程序。", "error_description": "量词错误：应为“一个”（或“一款”），不应为“一本”。“本”用于书籍、册子，应用程序不是书。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f98bd86-ea85-4cd9-9ac2-9b979a6f3ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
