INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92175, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为很多人做的好事，不是为了自己赚钱。", "primary_collocate": null, "pronunciation": "gōng yì", "ipa": "kʊŋ˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "他每个周末都做公益。", "target_word": "公益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司常常做公益活动。", "target_word": "公益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢参加学校的公益活动。", "target_word": "公益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李把工资的一部分用在公益上。", "target_word": "公益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公益项目帮助了很多孩子。", "target_word": "公益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司每年都做公益。", "target_word": "公益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学生去山区做公益，教孩子读书。", "target_word": "公益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位歌手一直热心公益。", "target_word": "公益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不赚钱，只是想为公益出一份力。", "target_word": "公益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末的公益演出不收钱。", "target_word": "公益", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "公益活动", "label": "复合"}, {"form": "公益事业", "label": "复合"}, {"form": "公益性", "label": "派生"}], "register": "中性", "sense_fingerprint": "不为赚钱、帮助他人的公益事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab3b97-f3d7-4c95-a0b9-3d6f706e958c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92175, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "公益", "is_correct": true, "explanation": "公益（gōng yì）：为很多人做的、不为赚钱的好事，是本词的读音。"}, {"text": "工业", "is_correct": false, "explanation": "工业（gōngyè）：第二音节韵母不同（ie 与 i），读音只差一个韵母，意思是工业。"}, {"text": "公寓", "is_correct": false, "explanation": "公寓（gōngyù）：第二音节韵母不同（ü 与 i），意思是住宅楼房。"}, {"text": "功绩", "is_correct": false, "explanation": "功绩（gōngjì）：第二音节声母不同（j 与 y），意思是功劳和成绩。"}, {"text": "忠义", "is_correct": false, "explanation": "忠义（zhōngyì）：第一音节声母不同（zh 与 g），意思是忠诚和正义。"}], "explanations": {"公益": "公益（gōng yì）：为很多人做的、不为赚钱的好事，是本词的读音。", "工业": "工业（gōngyè）：第二音节韵母不同（ie 与 i），读音只差一个韵母，意思是工业。", "公寓": "公寓（gōngyù）：第二音节韵母不同（ü 与 i），意思是住宅楼房。", "功绩": "功绩（gōngjì）：第二音节声母不同（j 与 y），意思是功劳和成绩。", "忠义": "忠义（zhōngyì）：第一音节声母不同（zh 与 g），意思是忠诚和正义。"}, "sentence_index": null, "correct_answer": "公益"}, "level_3": {"options": [{"text": "公益", "is_correct": true, "explanation": "公益：为大众做的不赚钱的好事，能与“做”搭配，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是自然存在的东西，不能被“做”，“做空气”说不通。"}, {"text": "公园", "is_correct": false, "explanation": "搭配：“做”不接“公园”，公园是建成的场所，不说“做公园”。"}, {"text": "历史", "is_correct": false, "explanation": "搭配：“做历史”不是常用说法，历史要说“创造”或“书写”。"}], "explanations": {"公益": "公益：为大众做的不赚钱的好事，能与“做”搭配，符合句意。", "空气": "语义：空气是自然存在的东西，不能被“做”，“做空气”说不通。", "公园": "搭配：“做”不接“公园”，公园是建成的场所，不说“做公园”。", "历史": "搭配：“做历史”不是常用说法，历史要说“创造”或“书写”。"}, "sentence_index": 0, "correct_answer": "公益"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个公益车站每天都很挤。", "explanation": "这里应该用〈公共〉。“公共”指人人可以使用的，如公共车站；“公益”指为大众做的不赚钱的好事，不用来修饰场所。"}, {"text": "他在公交车上很讲公益，主动给老人让座。", "explanation": "这里应该用〈公德〉。“讲公德”是固定说法，指遵守社会公共道德；“公益”指为大众做的好事，不说“讲公益”。"}, {"text": "他用公益买了一辆新车。", "explanation": "这里应该用〈钱〉。“公益”指为大众做的不赚钱的好事，不是钱，不能用来购物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac21c432-ba06-4bde-be5a-b3bcdaf2db26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92175, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "公益", "is_correct": true, "explanation": "公益（gōng yì）：为很多人做的、不为赚钱的好事，是本词的读音。"}, {"text": "刚毅", "is_correct": false, "explanation": "刚毅（gāngyì）：第一音节韵母不同（ang 与 ong），意思是坚强果断。"}, {"text": "通译", "is_correct": false, "explanation": "通译（tōngyì）：第一音节声母不同（t 与 g），意思是翻译人员。"}, {"text": "公印", "is_correct": false, "explanation": "公印（gōngyìn）：第二音节比 yì 多了韵尾 n，意思是公章。"}], "explanations": {"公益": "公益（gōng yì）：为很多人做的、不为赚钱的好事，是本词的读音。", "刚毅": "刚毅（gāngyì）：第一音节韵母不同（ang 与 ong），意思是坚强果断。", "通译": "通译（tōngyì）：第一音节声母不同（t 与 g），意思是翻译人员。", "公印": "公印（gōngyìn）：第二音节比 yì 多了韵尾 n，意思是公章。"}, "sentence_index": null, "correct_answer": "公益"}, "level_3": {"options": [{"text": "公益", "is_correct": true, "explanation": "公益：为大众做的不赚钱的好事，符合句中的活动和“教孩子读书”的语境。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，不能被“做”，句子说的是大学生去山区的活动。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：“做”不接“河流”，河流是自然存在的，不说“做河流”。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空是自然景象，不能被“做”，与“教孩子读书”的语境也对不上。"}], "explanations": {"公益": "公益：为大众做的不赚钱的好事，符合句中的活动和“教孩子读书”的语境。", "太阳": "语义：太阳是天体，不能被“做”，句子说的是大学生去山区的活动。", "河流": "搭配：“做”不接“河流”，河流是自然存在的，不说“做河流”。", "天空": "语义：天空是自然景象，不能被“做”，与“教孩子读书”的语境也对不上。"}, "sentence_index": 6, "correct_answer": "公益"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每个月都去养老院当公益，帮老人打扫房间。", "explanation": "这里应该用〈做〉。“公益”是名词，不能说“当公益”，要说“做公益”。"}, {"text": "他每天坐公益去上班。", "explanation": "这里应该用〈公交车〉。“公益”指为大众做的不赚钱的好事，不是交通工具，不能“坐”。"}, {"text": "我们班捐了一笔公益，帮助山区的孩子。", "explanation": "这里应该用〈钱〉。“公益”指为大众做的好事，不是钱，不能“捐一笔公益”，应说“捐了一笔钱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac21c432-ba06-4bde-be5a-b3bcdaf2db26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92175, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每个星期六都公益。", "corrected_sentence": "他每个星期六都做公益。", "error_description": "错误：“公益”是名词，不能直接作谓语，前面要加动词“做”，应说“做公益”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac21c432-ba06-4bde-be5a-b3bcdaf2db26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92175, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个活动的公益很强。", "corrected_sentence": "这个活动的公益性很强。", "error_description": "词形错误：“公益很强”不通顺，表示公益性质的程度要加“性”，应说“公益性很强”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac21c432-ba06-4bde-be5a-b3bcdaf2db26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
