INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92176, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "社会公共的利益。", "primary_collocate": null, "pronunciation": "gōng yì", "ipa": "kʊŋ˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "这条路是为了公益才修的。", "target_word": "公益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "个人的事不能影响公益。", "target_word": "公益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府要保护公益。", "target_word": "公益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把公益放在第一位。", "target_word": "公益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了公益，这个小区要搬走。", "target_word": "公益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司不能为了赚钱而伤害公益。", "target_word": "公益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律的目的之一是维护公益。", "target_word": "公益", "complexity_tier": "T3", "furigana": "fǎ lǜ de mù dì zhī yī shì wéi hù gōng yì.", "sentence_source": "generated"}, {"text": "这件事关系到大家的公益。", "target_word": "公益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了公益，放弃了自己的利益。", "target_word": "公益", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "个人的利益要服从公益。", "target_word": "公益", "complexity_tier": "T3", "furigana": "gè rén de lì yì yào fú cóng gōng yì.", "sentence_source": "generated"}], "morphological_forms": [{"form": "公益性", "label": "派生"}, {"form": "公益事业", "label": "复合"}], "register": "中性", "sense_fingerprint": "与个人利益相对的社会公共利益", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ecab3b97-f3d7-4c95-a0b9-3d6f706e958c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92176, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "公益", "is_correct": true, "explanation": "公益（gōng yì）：社会公共的利益，是本词的读音。"}, {"text": "工业", "is_correct": false, "explanation": "工业（gōngyè）：第二音节韵母不同（ie 与 i），读音只差一个韵母，意思是工业。"}, {"text": "公寓", "is_correct": false, "explanation": "公寓（gōngyù）：第二音节韵母不同（ü 与 i），意思是住宅楼房。"}, {"text": "功绩", "is_correct": false, "explanation": "功绩（gōngjì）：第二音节声母不同（j 与 y），意思是功劳和成绩。"}, {"text": "忠义", "is_correct": false, "explanation": "忠义（zhōngyì）：第一音节声母不同（zh 与 g），意思是忠诚和正义。"}], "explanations": {"公益": "公益（gōng yì）：社会公共的利益，是本词的读音。", "工业": "工业（gōngyè）：第二音节韵母不同（ie 与 i），读音只差一个韵母，意思是工业。", "公寓": "公寓（gōngyù）：第二音节韵母不同（ü 与 i），意思是住宅楼房。", "功绩": "功绩（gōngjì）：第二音节声母不同（j 与 y），意思是功劳和成绩。", "忠义": "忠义（zhōngyì）：第一音节声母不同（zh 与 g），意思是忠诚和正义。"}, "sentence_index": null, "correct_answer": "公益"}, "level_3": {"options": [{"text": "公益", "is_correct": true, "explanation": "公益：社会公共的利益，符合“为了……才修的”的句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能作为修路的目的，句意不通。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，不能作为修路的目的，句意不通。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语义：“玩意儿”指东西，不能作为修路的目的；它又是口语词，与书面的“为了……才修的”也不合。"}], "explanations": {"公益": "公益：社会公共的利益，符合“为了……才修的”的句意。", "天气": "语义：天气是自然现象，不能作为修路的目的，句意不通。", "太阳": "语义：太阳是天体，不能作为修路的目的，句意不通。", "玩意儿": "语义：“玩意儿”指东西，不能作为修路的目的；它又是口语词，与书面的“为了……才修的”也不合。"}, "sentence_index": 0, "correct_answer": "公益"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府要加强公益卫生管理。", "explanation": "这里应该用〈公共〉。“公共卫生”是固定说法；“公益”指社会公共的利益，不用来修饰“卫生”。"}, {"text": "他为了自己的公益，不管别人死活。", "explanation": "这里应该用〈利益〉。“公益”指社会公共的利益，不能说“自己的公益”，说个人的好处要用〈利益〉。"}, {"text": "他把公益装进书包里带回家。", "explanation": "这里应该用〈书〉。“公益”指社会公共的利益，是抽象概念，不能装进书包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac21c432-ba06-4bde-be5a-b3bcdaf2db26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92176, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "公益", "is_correct": true, "explanation": "公益（gōng yì）：社会公共的利益，是本词的读音。"}, {"text": "刚毅", "is_correct": false, "explanation": "刚毅（gāngyì）：第一音节韵母不同（ang 与 ong），意思是坚强果断。"}, {"text": "通译", "is_correct": false, "explanation": "通译（tōngyì）：第一音节声母不同（t 与 g），意思是翻译人员。"}, {"text": "公印", "is_correct": false, "explanation": "公印（gōngyìn）：第二音节比 yì 多了韵尾 n，意思是公章。"}], "explanations": {"公益": "公益（gōng yì）：社会公共的利益，是本词的读音。", "刚毅": "刚毅（gāngyì）：第一音节韵母不同（ang 与 ong），意思是坚强果断。", "通译": "通译（tōngyì）：第一音节声母不同（t 与 g），意思是翻译人员。", "公印": "公印（gōngyìn）：第二音节比 yì 多了韵尾 n，意思是公章。"}, "sentence_index": null, "correct_answer": "公益"}, "level_3": {"options": [{"text": "公益", "is_correct": true, "explanation": "公益：社会公共的利益，符合“法律的目的”的句意。"}, {"text": "笑话", "is_correct": false, "explanation": "语义：笑话不能被“维护”，这句话讲的是法律的目的，句意不通。"}, {"text": "草坪", "is_correct": false, "explanation": "搭配：“维护草坪”可以说，但句子讲法律的目的，“维护”要接抽象的对象。"}, {"text": "老鼠", "is_correct": false, "explanation": "语义：老鼠不是法律要维护的对象，句意不通。"}], "explanations": {"公益": "公益：社会公共的利益，符合“法律的目的”的句意。", "笑话": "语义：笑话不能被“维护”，这句话讲的是法律的目的，句意不通。", "草坪": "搭配：“维护草坪”可以说，但句子讲法律的目的，“维护”要接抽象的对象。", "老鼠": "语义：老鼠不是法律要维护的对象，句意不通。"}, "sentence_index": 6, "correct_answer": "公益"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天只想着给公益打工，却要求拿高额工资。", "explanation": "这里应该用〈单位〉。“公益”指社会公共利益，不是可以雇人、发工资的机构，句中的用法与其含义相矛盾。"}, {"text": "他为了私人的公益，把公司的钱都挪走了。", "explanation": "这里应该用〈利益〉。“公益”指社会公共的利益，不能说“私人的公益”，个人的好处要说“私人的利益”。"}, {"text": "他每天早上都喝一杯公益。", "explanation": "这里应该用〈牛奶〉。“公益”是抽象概念，不能喝；“一杯”后应接可以喝的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac21c432-ba06-4bde-be5a-b3bcdaf2db26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92176, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项工程的公益很强。", "corrected_sentence": "这项工程的公益性很强。", "error_description": "词形错误：“公益很强”不通顺，表示公益性质的程度要加“性”，应说“公益性很强”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac21c432-ba06-4bde-be5a-b3bcdaf2db26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92176, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她为了公益，牺牲了自己的公益。", "corrected_sentence": "她为了公益，牺牲了自己的利益。", "error_description": "用词错误：“公益”是社会公共的利益，不能说“自己的公益”，个人的好处应说“自己的利益”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ac21c432-ba06-4bde-be5a-b3bcdaf2db26') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
