INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92177, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "战区是打仗的那一大片地方。", "primary_collocate": null, "pronunciation": "zhàn qū", "ipa": "tʂan⁵¹ tɕʰy⁵⁵", "syllable_count": 2, "sentences": [{"text": "打仗的时候，战区里到处是炮火声。", "target_word": "战区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战区很大，有山，有河，也有城市。", "target_word": "战区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子都坏了，战区里没有一个安全的家。", "target_word": "战区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸在战区工作，我们很担心他。", "target_word": "战区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战区的孩子不能去学校上课。", "target_word": "战区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们要经过战区，路上非常危险。", "target_word": "战区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战区里没有水，也没有电。", "target_word": "战区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红十字会把药送进了战区。", "target_word": "战区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争结束后，战区的人开始重建家园。", "target_word": "战区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说战区已经停火了。", "target_word": "战区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "战区司令", "label": "复合"}], "register": "通用", "sense_fingerprint": "正在打仗的一大片地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e27c0865-ac13-463b-bae0-85a44d455076') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92177, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "战区", "is_correct": true, "explanation": "正确：战区是打仗的地区，那里到处是炮火声。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱里不会到处是炮火声，句子说的是战斗发生的地方。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包里不会到处是炮火声，句子说的是战斗发生的地方。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“里到处是……声”要求前面是能容纳声音的场所，“天气”不是场所，不搭配。"}], "explanations": {"战区": "正确：战区是打仗的地区，那里到处是炮火声。", "冰箱": "语义：冰箱里不会到处是炮火声，句子说的是战斗发生的地方。", "书包": "语义：书包里不会到处是炮火声，句子说的是战斗发生的地方。", "天气": "搭配：“里到处是……声”要求前面是能容纳声音的场所，“天气”不是场所，不搭配。"}, "sentence_index": 0, "correct_answer": "战区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们去战区旅游。", "explanation": "这里应该用〈景点〉。战区是打仗的地区，不能用来旅游。"}, {"text": "我今天去战区理发。", "explanation": "这里应该用〈理发店〉。战区是打仗的地区，不是理发的地方。"}, {"text": "我买了一个战区送给妈妈。", "explanation": "这里应该用〈蛋糕〉。战区是地区，不是可以买来送人的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92177, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "战区", "is_correct": true, "explanation": "正确：战区里生活条件很差，所以没有水也没有电。"}, {"text": "信箱", "is_correct": false, "explanation": "语义：信箱不是人居住的地方，句子说的是生活条件很差的地区。"}, {"text": "字典", "is_correct": false, "explanation": "语义：字典里没有人居住，也谈不上有没有水和电。"}, {"text": "午饭", "is_correct": false, "explanation": "搭配：“里”前的地点要能容纳人群，“午饭”不是地点，不搭配。"}], "explanations": {"战区": "正确：战区里生活条件很差，所以没有水也没有电。", "信箱": "语义：信箱不是人居住的地方，句子说的是生活条件很差的地区。", "字典": "语义：字典里没有人居住，也谈不上有没有水和电。", "午饭": "搭配：“里”前的地点要能容纳人群，“午饭”不是地点，不搭配。"}, "sentence_index": 6, "correct_answer": "战区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们昨天看了一场战区。", "explanation": "这里应该用〈比赛〉。战区是地区，不是可以观看的活动，“看了一场”后要接比赛、演出之类。"}, {"text": "我把战区放进书包里了。", "explanation": "这里应该用〈课本〉。战区是很大的地区，不是可以放进书包的东西。"}, {"text": "我每天坐战区去上班。", "explanation": "这里应该用〈公交车〉。战区是打仗的地区，不是可以坐的交通工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92177, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "士兵们封锁了一只战区。", "corrected_sentence": "士兵们封锁了一个战区。", "error_description": "量词错误：“战区”的量词是“个”，“只”多用于动物或成对的东西，不能用来数“战区”。应说“一个战区”，不能说“一只战区”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92177, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们进入着战区。", "corrected_sentence": "他们进入过战区。", "error_description": "体标错误：表示曾经经历某事时要用“过”，“着”表示动作的持续状态。“进入”是瞬时动词，不能与“着”搭配。应说“进入过战区”，不能说“进入着战区”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
