INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92178, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "发生战争的区域；军队划分的作战区域。", "primary_collocate": null, "pronunciation": "zhàn qū", "ipa": "tʂan⁵¹ tɕʰy⁵⁵", "syllable_count": 2, "sentences": [{"text": "战区里的人们需要食物和药。", "target_word": "战区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者进入战区，报道当地的情况。", "target_word": "战区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队把这个国家分成了五个战区。", "target_word": "战区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多孩子离开战区，去了别的国家。", "target_word": "战区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生冒着危险，在战区里救人。", "target_word": "战区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战区的司令正在开会。", "target_word": "战区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "联合国要求各方保护战区的平民。", "target_word": "战区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战区的天气很冷，士兵们很辛苦。", "target_word": "战区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个战区的部队今天开始训练。", "target_word": "战区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们坐车离开战区，来到安全的地方。", "target_word": "战区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "战区司令", "label": "复合"}], "register": "书面", "sense_fingerprint": "发生战争的地区；军队划分的作战区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e27c0865-ac13-463b-bae0-85a44d455076') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92178, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "战区", "is_correct": true, "explanation": "正确：战区是发生战争的区域，那里的人需要食物和药。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空里不会有需要食物和药的人群，这种说法不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱里不会有人群，句子说的是需要救助的地区。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“里”前的地点要能容纳人群，“课本”不是能容纳人的地方，不搭配。"}], "explanations": {"战区": "正确：战区是发生战争的区域，那里的人需要食物和药。", "天空": "语义：天空里不会有需要食物和药的人群，这种说法不通。", "冰箱": "语义：冰箱里不会有人群，句子说的是需要救助的地区。", "课本": "搭配：“里”前的地点要能容纳人群，“课本”不是能容纳人的地方，不搭配。"}, "sentence_index": 0, "correct_answer": "战区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个战区每天都很热闹。", "explanation": "这里应该用〈商业区〉。战区指发生战争或军队作战的区域，不能用来形容热闹的地方。"}, {"text": "我们周末去战区逛街。", "explanation": "这里应该用〈商场〉。战区是打仗的地区，不能去那里逛街购物。"}, {"text": "我昨天去了一个战区看电影。", "explanation": "这里应该用〈影院〉。战区是打仗的地方，不能去那里看电影。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92178, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "战区", "is_correct": true, "explanation": "正确：战区是发生战争、平民需要保护的地区，句子要的正是这个意思。"}, {"text": "宇宙", "is_correct": false, "explanation": "语义：宇宙不是需要各方保护平民的地方，句子指的是战争地区。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮上没有平民，句子指的是有战争的地区。"}, {"text": "咖啡", "is_correct": false, "explanation": "搭配：“保护……的平民”修饰的应是地区或群体，“咖啡”不是能住人的地方，不搭配。"}], "explanations": {"战区": "正确：战区是发生战争、平民需要保护的地区，句子要的正是这个意思。", "宇宙": "语义：宇宙不是需要各方保护平民的地方，句子指的是战争地区。", "月亮": "语义：月亮上没有平民，句子指的是有战争的地区。", "咖啡": "搭配：“保护……的平民”修饰的应是地区或群体，“咖啡”不是能住人的地方，不搭配。"}, "sentence_index": 6, "correct_answer": "战区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们暑假去战区旅游。", "explanation": "这里应该用〈景区〉。战区是战争地区，不适合旅游。"}, {"text": "我们昨天打了一场战区。", "explanation": "这里应该用〈战争〉。战区是地区，不是一场战斗，“打一场”后要接战斗或战争。"}, {"text": "孩子们每天都去战区玩耍。", "explanation": "这里应该用〈游乐场〉。战区是战争地区，不是孩子玩耍的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92178, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "士兵们封锁了一只战区。", "corrected_sentence": "士兵们封锁了一个战区。", "error_description": "量词错误：“战区”的量词是“个”，“只”多用于动物或成对的东西，不能用来数“战区”。应说“一个战区”，不能说“一只战区”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4d568a2-c0bd-4840-b127-be0c1f8e0aa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
